window.MOVIE_CATALOG={"source":"Movies: based on true story — catalogue of films based on real events","built":"2026-09-02","count":501,"films":[{"imdb_id":"tt0108052","title":"Schindler's List","title_uk":"Список Шиндлера","year":1993,"rating":9,"votes":1600974,"genres":["Biography","Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Голокост","who_what":"Німецький промисловець Оскар Шиндлер урятував близько 1100 польських євреїв на своїх фабриках.","basis":"реальна історія","note":"Кілька епізодів драматизовано — зокрема сцену з душовою в Аушвіці та мотиви навернення Шиндлера.","thriller_flag":false,"decade":"1990-ті","desc":"Судетський німець і член НСДАП Оскар Шиндлер (1908–1974) на емальовій фабриці в Кракові, а згодом у чеському Брненці врятував близько 1100 євреїв, підкуповуючи есесівців і вигадуючи для робітників фіктивні спеціальності. Стівен Спілберг знімав чорно-білою камерою в самому Кракові за романом Томаса Кеніллі; Рейф Файнз грає коменданта Плашува Амона Ґета, страченого 1946 року. Сім «Оскарів», зокрема за найкращий фільм і режисуру."},{"imdb_id":"tt0109830","title":"Forrest Gump","title_uk":"Форрест Ґамп","year":1994,"rating":8.8,"votes":2530836,"genres":["Comedy","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"США від сегрегації 1950-х через В'єтнам і Вотерґейт до епідемії СНІДу.","basis":"реальне тло, вигадані герої","note":"Історичні епізоди подані вибірково й спрощено, а кадри з політиками — цифрова містифікація.","thriller_flag":false,"decade":"1990-ті","desc":"Роберт Земекіс проводить вигаданого алабамця крізь тридцять років американської історії, вмонтовуючи його в справжню хроніку поруч із Кеннеді, Ніксоном і Ленноном. Форрест, Дженні й лейтенант Ден вигадані Вінстоном Ґрумом. Шість «Оскарів», зокрема за фільм, режисуру і роль Тома Генкса. Фільм став найкасовішим у прокаті США 1994 року."},{"imdb_id":"tt0099685","title":"GoodFellas","title_uk":"Славні хлопці","year":1990,"rating":8.7,"votes":1410440,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Історія Генрі Гілла — рядового учасника бруклінської мафіозної команди, який у 1980 році став свідком обвинувачення.","basis":"реальна історія","note":"Прізвища більшості реальних мафіозі змінено: Джиммі Берк став Конвеєм, Пол Варіо — Полі Сісеро.","thriller_flag":false,"decade":"1990-ті","desc":"Генрі Гілл (1943–2012) майже тридцять років працював на бруклінську команду родини Луккезе, брав участь у пограбуванні Lufthansa в аеропорту Кеннеді 11 грудня 1978 року, а потім пішов у програму захисту свідків. Мартін Скорсезе екранізував репортажну книжку Ніколаса Піледжі «Wiseguy» і зробив із неї хроніку буденності гангстера: гроші, кокаїн, зради, страх. Джо Пеші отримав «Оскар» за роль Томмі."},{"imdb_id":"tt15964372","title":"Aparajito","title_uk":"Апараджіто","year":2022,"rating":8.7,"votes":5629,"genres":["Biography","Drama","Family","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"бенгальська","theme":"Музика та мистецтво","who_what":"Як Сатьяджіт Рей без грошей і досвіду знімав свій дебют «Пісня дороги», що змінив індійське кіно.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Кінець 1940-х: рекламний художник із Калькутти, закоханий у неореалізм, вирішує екранізувати роман Бібгутібгушана Бондопаддгая — без грошей, без акторів і без жодного знятого кадру за плечима. Анік Датта відтворює п'ять років, за які постала «Пісня дороги», з паузами в зйомках і порятунком коштом уряду Західної Бенгалії. Знято чорно-білим, із педантичною реконструкцією майданчиків Рея; Джіту Камаль вражаюче на нього схожий. Формально це не байопік: імена змінено, режисера звати Апараджіто Рей."},{"imdb_id":"tt23849204","title":"12th Fail","title_uk":"Провал у 12-му класі","year":2023,"rating":8.7,"votes":176110,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Манодж Кумар Шарма з бідної родини стає офіцером індійської поліції.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Манодж Кумар Шарма із села в Чамбальській долині провалив дванадцятий клас, бо на іспиті вперше не дали списувати, — а через кілька років і кілька невдалих спроб склав іспит UPSC і став офіцером поліції. Відгу Вінод Чопра знімав переважно на реальних локаціях у делійському Мукерджі-Нагарі, кварталі підготовчих курсів, із непрофесійними виконавцями в епізодах. Вікрант Массі грає без пафосу; в основі — документальна книжка Анурага Патхака."},{"imdb_id":"tt0116860","title":"Lepa sela lepo gore","title_uk":"Гарні села гарно горять","year":1996,"rating":8.6,"votes":19174,"genres":["Drama","History","War"],"country":"Югославія (Сербія)","country_main":"Югославія (Сербія)","region":"Європа","language":"серб.","theme":"Війна","who_what":"Реальний епізод Боснійської війни: сербські бійці, замкнені в дорожньому тунелі в оточенні.","basis":"натхненний реальними подіями","note":"Каркасом став реальний епізод у тунелі; персонажі, їхні біографії та дружба — вигадані.","thriller_flag":false,"decade":"1990-ті","desc":"1992 року група сербських бійців кілька днів просиділа замкненою в дорожньому тунелі у східній Боснії в оточенні боснійських сил — про цей випадок написав журналіст Ваня Булич, і з його репортажу виріс фільм. Срджан Драгоєвич додав до нього передвоєнну дружбу серба й мусульманина, які тепер опинилися по різні боки. Чорний гумор і рвана хронологія зробили стрічку найвідомішим антивоєнним фільмом регіону. Драган Бєлоґрлич і Нікола Койо в головних ролях."},{"imdb_id":"tt0118799","title":"Life Is Beautiful","title_uk":"Життя прекрасне","year":1997,"rating":8.6,"votes":821631,"genres":["Comedy","Drama","Romance"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Голокост","who_what":"Расові закони фашистської Італії та депортація євреїв до нацистського табору 1944 року.","basis":"реальне тло, вигадані герої","note":"Табір і його порядки стилізовані; частина критиків і вцілілих закидала фільму надмірну умовність.","thriller_flag":false,"decade":"1990-ті","desc":"Роберто Беніньї грає книгаря Ґвідо, який у таборі переконує сина, що все довкола — лише гра з призом у вигляді танка. Родина Орефіче вигадана, а сам табір навмисно умовний, без прив'язки до конкретного місця. Три «Оскари», зокрема за найкращу чоловічу роль і найкращий іншомовний фільм."},{"imdb_id":"tt0120815","title":"Saving Private Ryan","title_uk":"Врятувати рядового Раяна","year":1998,"rating":8.6,"votes":1659568,"genres":["Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Висадка в Нормандії 6 червня 1944 року і бої перших тижнів після неї.","basis":"реальне тло, вигадані герої","note":"Поштовхом стала історія братів Ніланд, але фабула й персонажі вигадані.","thriller_flag":false,"decade":"1990-ті","desc":"Двадцятихвилинний штурм сектора «Омаха» на початку фільму вважають найточнішою реконструкцією Дня Д у кіно. Загін капітана Міллера, який шукає рядового Раяна, повністю вигаданий, хоча правило про останнього сина в родині справді існувало. Спілберг отримав «Оскар» за режисуру, Януш Камінський — за операторську роботу. Ця відкривальна сцена на роки задала стандарт зображення бою в кіно."},{"imdb_id":"tt0317248","title":"City of God","title_uk":"Місто Бога","year":2002,"rating":8.6,"votes":879671,"genres":["Crime","Drama"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"португ.","theme":"Кримінал","who_what":"Зростання наркобанд у ріо-де-жанейрській фавелі Сідаді-ді-Деус у 1960–80-х роках.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Паулу Лінс виріс у ріо-де-жанейрському районі Сідаді-ді-Деус і зібрав історії реальних сусідів у роман, який Фернанду Мейреллеш і Катія Лунд перенесли на екран. Три десятиліття, від 1960-х до 1980-х, показано очима Ракети, підлітка з фотоапаратом, поки поруч росте банда Малюка Зе. Більшість ролей зіграли непрофесійні актори з фавел, відібрані через театральну майстерню. Чотири номінації на «Оскар», зокрема за режисуру, сценарій і монтаж."},{"imdb_id":"tt10189514","title":"Soorarai Pottru","title_uk":"Сураарай Потру","year":2020,"rating":8.6,"votes":132651,"genres":["Action","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Автобіографія","who_what":"Історія підприємця Г. Р. Гопінатха, який заснував першу індійську лоукост-авіакомпанію Air Deccan, щоб зробити авіапереліт доступним простим людям.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"За мемуарами «Simply Fly» відставного капітана Ґ. Р. Ґопінатха, який 2003 року запустив Air Deccan і вперше зробив квиток на літак дешевшим за поїзд. Судга Конґара переносить героя на ім'я Маара (Суря) у тамільське село, додає дружину-пекарку й перетворює бізнес-історію на боротьбу з монополістом, чиновниками та кастовою зверхністю. Національні кінопремії Індії за найкращий фільм, найкращу чоловічу і найкращу жіночу ролі."},{"imdb_id":"tt15097216","title":"Jai Bhim","title_uk":"Джай Бгім","year":2021,"rating":8.6,"votes":235896,"genres":["Crime","Drama","History","Mystery"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Суд і журналістика","who_what":"Адвокат Чандру бореться за плем'я іруларів; в основі — реальна справа 1993 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"1993 рік, Тамілнад: чоловіка з племені іруларів Раджаканну забирають у поліцію за крадіжку, якої не було, а потім кажуть дружині, що він утік. Вагітна Сенґені йде до адвоката Чандру — реальної людини, згодом судді Високого суду Мадраса, — і той подає habeas corpus. Ґнанавел показує не так суд, як механіку зникнення: людей без виборчих карток і протоколи, куди можна вписати будь-що. Суря продюсував фільм і зіграв Чандру."},{"imdb_id":"tt9263550","title":"Rocketry: The Nambi Effect","title_uk":"Ракетник: Ефект Намбі","year":2022,"rating":8.6,"votes":62529,"genres":["Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"англ., тамільська","theme":"Наука і технології","who_what":"Учений ISRO Намбі Нараянан, безпідставно звинувачений у шпигунстві 1994 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Намбі Нараянан керував розробкою рідинних двигунів ISRO і привіз до Індії французьку технологію, з якої виріс двигун Vikas, — аж поки 1994 року його не заарештували за звинуваченням у передачі секретів. CBI визнало справу сфабрикованою, а 2018-го Верховний суд присудив ученому компенсацію. Р. Мадгаван зняв фільм і сам зіграв Нараянана в усіх вікових шарах. Оповідь оформлена як телеінтерв'ю, яке в гінді-версії веде Шах Рух Хан, а в тамільській — Суря."},{"imdb_id":"tt0255289","title":"Kaalapani","title_uk":"Чорні води","year":1996,"rating":8.5,"votes":5066,"genres":["Action","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Політика та історія","who_what":"Каральна тюрма «Селлулар» на Андаманських островах для індійських політв'язнів.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Молодого лікаря Ґовардхана несправедливо засуджують за участь у теракті й відправляють за «чорні води» — до тюрми, де в'язнів запрягають у млин замість волів. Ґовардхан вигаданий, натомість сама тюрма, її наглядач Баррі й голодування в'язнів 1930-х історичні. Прійадаршан зняв один із найдорожчих малаяламських фільмів; три Національні премії."},{"imdb_id":"tt0172495","title":"Gladiator","title_uk":"Гладіатор","year":2000,"rating":8.5,"votes":1878622,"genres":["Action","Adventure","Drama"],"country":"США / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Рим кінця II століття: смерть Марка Аврелія і правління Коммода.","basis":"реальне тло, вигадані герої","note":"Обставини смерті Коммода та ідея повернення республіки — вигадка сценаристів.","thriller_flag":false,"decade":"2000-ті","desc":"Полководець Максимус, вигаданий персонаж, після вбивства імператора стає рабом і повертається до Рима гладіатором. Марк Аврелій, Коммод і Луцилла реальні, але Коммода задушив атлет у лазні, а не боєць на арені, і жодної реставрації республіки він не планував. П'ять «Оскарів», зокрема за фільм і за роль Рассела Кроу."},{"imdb_id":"tt0253474","title":"The Pianist","title_uk":"Піаніст","year":2002,"rating":8.5,"votes":1022058,"genres":["Biography","Drama","Music","War"],"country":"Польща/Франція/Німеччина/Велика Британія","country_main":"Польща","region":"Європа","language":"англ./нім.","theme":"Голокост","who_what":"Польський піаніст Владислав Шпільман, який вижив у Варшавському гетто.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Владислав Шпільман, піаніст Польського радіо, пережив ліквідацію Варшавського гетто й до січня 1945-го переховувався в руїнах міста. Роман Поланський, який дитиною втік із краківського гетто, знімає без підйому: камера не відходить від Шпільмана й показує рівно те, що бачить він. Едрієн Броуді отримав «Оскар» за цю роль, фільм — Золоту пальмову гілку та ще дві статуетки. Німецький офіцер Вільм Гозенфельд, який його врятував, — реальна постать."},{"imdb_id":"tt1675434","title":"The Intouchables","title_uk":"1+1 (Недоторканні)","year":2011,"rating":8.5,"votes":1039156,"genres":["Comedy","Drama"],"country":"Франція","country_main":"Франція","region":"Європа","language":"фр.","theme":"Соціальна драма","who_what":"Дружба паралізованого аристократа Філіппа Поццо ді Борґо та його доглядальника Абделя Селлу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Філіпп Поццо ді Борґо, спадкоємець виноробного дому, після аварії на параплані лишився паралізованим від шиї, а доглядальником узяв Абделя Селлу, який щойно вийшов із в'язниці. Олів'є Накаш та Ерік Толедано зробили з цього комедію про двох людей, яким удвох легше, ніж окремо: Франсуа Клюзе і Омар Сі, що отримав «Сезар». У Франції фільм подивилися понад 19 мільйонів глядачів. Головна вільність: Селлу — алжирець, а в кіно сенегалець, і за це стрічку дорікали."},{"imdb_id":"tt1853728","title":"Django Unchained","title_uk":"Джанґо вільний","year":2012,"rating":8.5,"votes":1910559,"genres":["Drama","Western"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Рабовласницький Південь США за два роки до Громадянської війни, 1858–1859.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Тарантіно показує систему рабства: аукціони, ловців утікачів із псами, «мандінго»-бої, побутову ієрархію серед невільників і роль домашньої прислуги. Джанґо, доктор Кінг Шульц і Келвін Кенді вигадані, як і весь сюжет визволення Брумгільди. Два «Оскари» — Тарантіно за сценарій і Крістоф Вальц за роль. Інститут рабства відтворено, конкретних задокументованих подій у фільмі немає."},{"imdb_id":"tt10811166","title":"The Kashmir Files","title_uk":"Кашмірські файли","year":2022,"rating":8.5,"votes":579687,"genres":["Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Вигнання і вбивства кашмірських пандитів на початку 1990-х років у Джамму і Кашмірі.","basis":"натхненний реальними подіями","note":"Фільм звинувачують у пропагандистському викривленні: масштаби й обставини подій 1990 року подано з істотними перебільшеннями, історики та журналісти вказували на маніпуляції фактами й розпалювання ворожнечі.","thriller_flag":false,"decade":"2020-ті","desc":"На початку 1990-х із Кашмірської долини під погрозами бойовиків виїхали десятки тисяч індуїстів-пандитів; були вбивства, захоплені будинки, роки в наметових таборах. Вівек Аґніготрі будує фільм на свідченнях переселенців і на лінії студента, який дізнається правду про загибель рідних. Картина зібрала величезну касу в Індії і водночас стала однією з найсуперечливіших: історики й журналісти закидали їй перебільшені цифри та антимусульманську риторику, а голова журі фестивалю в Ґоа Надав Лапід назвав її пропагандою."},{"imdb_id":"tt20850406","title":"Sita Ramam","title_uk":"«Сіта Рамам»","year":2022,"rating":8.5,"votes":85386,"genres":["Action","Drama","History","Musical","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"телугу","theme":"Війна","who_what":"Індійсько-пакистанська війна 1965 року й ситуація в Кашмірі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Ханну Раґхавапуді знімає епістолярний роман про лейтенанта індійської армії на кашмірському кордоні напередодні війни 1965-го. Сирота Рам отримує листи від незнайомої Сіти, а через двадцять років пакистанська студентка Аафрін мусить доставити його останній лист. У ролях Дульквер Салман і Мріналі Тхакур; фільм несподівано став хітом і в Індії, і в Пакистані. Війна, лінія припинення вогню й політичний фон реальні, всі герої — ні."},{"imdb_id":"tt0119385","title":"Iruvar","title_uk":"Двоє","year":1997,"rating":8.4,"votes":9048,"genres":["Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Політика та історія","who_what":"Дружба і політичне суперництво тамільських лідерів М. Г. Рамачандрана та М. Карунанідхі.","basis":"натхненний реальними подіями","note":"Імена змінено, прототипи офіційно не визнані, окремі епізоди скомпоновано.","thriller_flag":false,"decade":"1990-ті","desc":"Мані Ратнам показав, як від 1950-х кіноактор і сценарист піднялися до керма штату Тамілнаду: Анандан списаний з М. Г. Рамачандрана, Таміжчелван — з М. Карунанідхі, а Кальпана — з Дж. Джаялаліти. Фільм простежує зрощення дравідійської політики з кіноіндустрією від знімальних майданчиків до виборів. Дебют Айшварії Рай, операторська робота Сантоша Сівана. Карунанідхі і Джаялаліта заперечували зв'язок стрічки зі своїм життям."},{"imdb_id":"tt0346336","title":"The Best of Youth","title_uk":"Найкращі роки молодості","year":2003,"rating":8.4,"votes":28715,"genres":["Drama","History","Romance"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Політика та історія","who_what":"Італія 1966—2000: повінь у Флоренції, «свинцеві роки», мафіозні вбивства, реформа психіатрії.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Брати Нікола і Маттео Каратті обирають різні шляхи — психіатрію і поліцію — і разом із ними глядач проходить тридцять чотири роки італійської історії. Родина вигадана, натомість закриття божевілень за законом Базальї, «Червоні бригади» і вибухи 1990-х подані як пережите зсередини. Шестигодинний телефільм став кінострічкою і взяв приз «Особливий погляд» у Каннах."},{"imdb_id":"tt0400234","title":"Black Friday","title_uk":"Чорна п'ятниця","year":2004,"rating":8.4,"votes":26483,"genres":["Action","Crime","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Серія терактів у Бомбеї 12 березня 1993 року і подальше розслідування; за книгою Хусейна Зайді.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"12 березня 1993 року в Бомбеї за дві години прогриміли тринадцять вибухів. Анураг Кашьяп екранізує репортажну книжку Хусейна Зайді й розкладає події на два боки: слідчого Ракеша Марію (Кей Кей Менон), який розмотує ланцюжок затримань, і виконавців, що розбігаються країною. Довга піша погоня вулицями трущоб стала візитівкою картини. Прем'єру заблокував Високий суд Бомбея — фільм пролежав до 2007-го, поки не завершився процес у справі."},{"imdb_id":"tt0405094","title":"The Lives of Others","title_uk":"Життя інших","year":2006,"rating":8.4,"votes":446694,"genres":["Drama","Mystery","Thriller"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Тотальне стеження Штазі у Східній Німеччині середини 1980-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Дія відбувається 1984 року в Східному Берліні, і побут Штазі — техніка прослуховування, звітність, практика «розкладання» незручних людей — відтворено з архівною точністю. Капітан Вислер, драматург Драйман і актриса Зіланд вигадані, як і сюжет про офіцера, що почав приховувати доноси. Дебют Флоріана Генкеля фон Доннерсмарка приніс «Оскар» за іншомовний фільм. Реальні тут інституція та методи, а не конкретна справа."},{"imdb_id":"tt4991384","title":"Visaaranai","title_uk":"Допит","year":2015,"rating":8.4,"votes":15868,"genres":["Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл.","theme":"Суд і журналістика","who_what":"Катування чотирьох тамільських заробітчан в поліції Андхра-Прадешу — за автобіографічною книгою «Lock Up» М. Чандракумара.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"М. Чандракумар, рикшар із Тамілнаду, описав у книжці «Lock Up», як поліція в Андхра-Прадеші затримала його з трьома земляками й тижнями вибивала зізнання у крадіжці, до якої вони не мали стосунку. Ветрімааран екранізує це буквально: перша половина — камера й побої, друга йде далі, у корупційні розрахунки, де ті самі люди стають розмінною монетою. Три Національні кінопремії Індії, приз Amnesty International у Венеції та висунення від Індії на «Оскар»."},{"imdb_id":"tt7465992","title":"Mahanati","title_uk":"Маханаті","year":2018,"rating":8.4,"votes":16764,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"телугу, таміл.","theme":"Музика та мистецтво","who_what":"Зірка південноіндійського кіно Савітрі — від слави 1950-х до злиднів і смерті 1981 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1980 рік, Савітрі лежить у комі, і двоє журналістів збирають матеріал про акторку, яка ще недавно була найвищеоплачуванішою зіркою телугу- й таміл-кіно. Наґ Ашвін через цю рамку відмотує життя: дитинство в Андхрі, знімальні майданчики 1950-х, шлюб із одруженим актором Джеміні Ґанесаном, алкоголь, борги. Кіртхі Суреш отримала за роль Національну кінопремію, Ґанесана зіграв Дулкер Салман. Родичі Ґанесана публічно сперечалися з тим, яким його показано."},{"imdb_id":"tt8267604","title":"Capernaum","title_uk":"«Капернаум»","year":2018,"rating":8.4,"votes":126582,"genres":["Drama"],"country":"Ліван","country_main":"Ліван","region":"Близький Схід і Африка","language":"араб.","theme":"Соціальна драма","who_what":"Бейрутські нетрі та становище сирійських і ефіопських мігрантів без документів у Лівані 2010-х.","basis":"реальне тло, вигадані герої","note":"тло сучасне, а не історичне; епоха відтворена репортажно","thriller_flag":false,"decade":"2010-ті","desc":"Надін Лабакі два роки збирала матеріал у трущобах і в'язницях Бейрута, а тоді зняла історію з непрофесіоналами, чиї обставини були близькі до ролей. Дванадцятирічний Зейн подає до суду на батьків за те, що вони його народили, і тікає з дому, де опікується немовлям нелегальної мігрантки. Приз журі в Каннах, номінація на «Оскар». Персонажі й сюжет вигадані, середовище — задокументоване."},{"imdb_id":"tt9477520","title":"Asuran","title_uk":"«Асуран»","year":2019,"rating":8.4,"votes":37717,"genres":["Action","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Соціальна драма","who_what":"Кастове насильство в Тамілнаду 1960–1980-х, з відлунням різанини в Кілвенмані 1968 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ветрімааран екранізує роман Пумані «Веккай» і показує два віки далітської родини: молодість Сівасамі, коли землевласники спалювали хатини, і сучасність, де його син убиває кастового боса. Дхануш зіграв обидва вікові шари й отримав Національну кінопремію Індії. Земельні конфлікти, підпали й безкарність задокументовані істориками. Родина Сівасамі та конкретні вбивства вигадані, хоч і зібрані з реальних епізодів."},{"imdb_id":"tt11580854","title":"Sarpatta Parambarai","title_uk":"«Сарпатта Парамбарай»","year":2021,"rating":8.4,"votes":28990,"genres":["Action","Drama","History","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Спорт","who_what":"Північний Мадрас 1970-х: клубний бокс, кастові кланові змагання і надзвичайний стан 1975–1977 років.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Па Ранджіт відновлює забуту традицію боксерських «парамбарай» — кланових шкіл Північного Мадраса, що змагалися на відкритих рингах, доки владу не запровадила заборони. Кабілан із далітської родини всупереч матері виходить на ринг за клан Сарпатта, поки за надзвичайного стану саджають комуністів і профспілкових активістів. Арія в головній ролі. Бокс і надзвичайний стан реальні, клани й боксери вигадані."},{"imdb_id":"tt31514146","title":"I Swear","title_uk":"Клянуся","year":2025,"rating":8.4,"votes":59111,"genres":["Biography","Drama","History"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Медицина та виживання","who_what":"Шотландець Джон Девідсон, якому в 15 років діагностували синдром Туретта, стає публічним голосом людей із цим розладом.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Джон Девідсон із шотландського Ґалашилса почав неконтрольовано смикатися й вигукувати слова у дванадцять, а після документального фільму BBC «John's Not Mad» (1989) став найвідомішим у Британії голосом людей із синдромом Туретта. Кірк Джонс веде оповідь від 1983 року до 2020-х — через ліки, безробіття, орден Британської імперії та участь у дослідженні глибокої стимуляції мозку. Роберт Арамайо здобув за цю роль BAFTA за найкращу чоловічу роль."},{"imdb_id":"tt0110081","title":"To Live","title_uk":"Жити","year":1994,"rating":8.3,"votes":22652,"genres":["Drama","Romance","War"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"кит.","theme":"Політика та історія","who_what":"Китай від громадянської війни 1940-х через «Великий стрибок» до Культурної революції.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Чжан Їмоу простежує сорок років життя Фуґуя, який програє родинний маєток у кості й саме тому уникає розстрілу як поміщик. Кампанії Мао входять у побут як фон: домна на подвір'ї, хунвейбіни, вигнані з лікарні лікарі. Ґе Йоу отримав приз Канн за чоловічу роль; у Китаї фільм заборонили, а режисерові на два роки закрили виїзд."},{"imdb_id":"tt0112573","title":"Braveheart","title_uk":"Хоробре серце","year":1995,"rating":8.3,"votes":1171181,"genres":["Action","Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Вільям Воллес і шотландське повстання проти англійського короля Едуарда I наприкінці XIII століття.","basis":"натхненний реальними подіями","note":"Один із найчастіше критикованих істориками фільмів: хронологія, костюми, битви й лінія з Ізабеллою Французькою суперечать джерелам.","thriller_flag":false,"decade":"1990-ті","desc":"Воллес розбив англійців біля Стерлінґ-Бриджа 1297 року, програв під Фолкерком 1298-го і був страчений у Лондоні 1305-го. Мел Гібсон поставив фільм і зіграв головну роль; п'ять «Оскарів», зокрема за найкращий фільм і режисуру. Історики нарахували десятки помилок: мосту в битві при Стерлінґ-Бриджі немає взагалі, кілти з'явилися на три століття пізніше, а роман Воллеса з Ізабеллою Французькою неможливий — на час його страти їй було близько десяти років."},{"imdb_id":"tt0312859","title":"Kannathil Muthamittal","title_uk":"Поцілунок у щоку","year":2002,"rating":8.3,"votes":10893,"genres":["Action","Drama","Musical","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл.","theme":"Війна","who_what":"Громадянська війна на Шрі-Ланці і доля тамільських біженців.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Дев'ятирічна Амуда дізнається, що її вдочерили, і батьки везуть її на охоплений війною острів шукати біологічну матір-повстанку. Родина вигадана, але табори біженців, мінування сіл і вербування до Тигрів визволення реальні. Мані Ратнам знімав поблизу зони бойових дій; шість Національних премій Індії. Музику написав А. Р. Рахман, постійний співавтор режисера."},{"imdb_id":"tt1255953","title":"Incendies","title_uk":"Пожежі","year":2010,"rating":8.3,"votes":258474,"genres":["Drama","Mystery","War"],"country":"Канада","country_main":"Канада","region":"Інше","language":"франц., араб.","theme":"Війна","who_what":"Громадянська війна в Лівані 1975–1990 років (країну у фільмі не названо).","basis":"реальне тло, вигадані герої","note":"Країну прямо не названо, хоча тло впізнавано ліванське.","thriller_flag":false,"decade":"2010-ті","desc":"Дені Вільньов екранізує п'єсу Важді Муавада: розстріл автобуса, християнські міліції, табори біженців і в'язниця для політв'язнів — усе впізнавано ліванське, хоча країну не назвали. Наваль Марван, її діти-близнюки й кат Абу Тарек вигадані. Знімали в Йорданії; номінація на «Оскар» і міжнародний прорив Вільньова. Тюрма має прототип у Хіямі, конкретні долі — ні."},{"imdb_id":"tt5074352","title":"Dangal","title_uk":"Дангал","year":2016,"rating":8.3,"votes":247148,"genres":["Action","Biography","Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Борець Махавір Сінгх Пхогат, який виховав із доньок Гіти та Бабіти чемпіонок світу з вільної боротьби.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Махавір Сінгх Пхогат, колишній борець із гар'янського села Балалі, вирішує тренувати доньок так, як тренував би синів, — попри те, що дівчат у боротьбі там просто не існувало. Нітеш Тіварі веде історію від перших ранкових пробіжок до фіналу Ігор Співдружності 2010 року в Делі, де Ґіта здобула золото. Амір Хан набрав близько тридцяти кілограмів, щоб зіграти батька в старшому віці. Тренер-антагоніст — вигадка сценаристів, проти якої публічно заперечував реальний наставник сестер."},{"imdb_id":"tt10280296","title":"Sardar Udham","title_uk":"Сардар Удхам","year":2021,"rating":8.3,"votes":51210,"genres":["Crime","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Удхам Сінгх убиває в Лондоні Майкла О'Двайєра, мстячись за різанину в Джалліанвала-Бах.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"13 березня 1940 року Удхам Сінгх застрелив у лондонському Кекстон-холі Майкла О'Двайєра — губернатора Пенджабу, який схвалив розстріл у Джалліанвала-Баг 1919 року. Шуджіт Сіркар розповідає нелінійно, через допити й спогади, а сама різанина показана аж наприкінці — довгою нічною сценою серед поранених. Вікі Каушал грає Сінгха мовчазним і виснаженим; фільм не висунули від Індії на «Оскар», і в пресі писали, що журі не влаштувала його антибританська різкість."},{"imdb_id":"tt10295212","title":"Shershaah","title_uk":"Шершах","year":2021,"rating":8.3,"votes":137311,"genres":["Action","Biography","Drama","Thriller","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Капітан Вікрам Батра, посмертний кавалер «Парам Вір Чакри», у Каргільській війні 1999 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Каргіл, літо 1999-го: капітан Вікрам Батра бере висоту 5140, передає в ефір «Yeh Dil Maange More» і гине 7 липня при штурмі точки 4875, яку згодом назвуть Batra Top. Вішнувардхан веде лінію від академії в Дехрадуні через стосунки з Дімпл Чімою до останнього бою. Сіддхарт Малхотра грає і Вікрама, і його брата-близнюка Вішала. Родина Батри консультувала зйомки, а сам фільм через пандемію вийшов одразу на стримінгу."},{"imdb_id":"tt11423818","title":"Pawankhind","title_uk":"Паванхінд","year":2022,"rating":8.3,"votes":8354,"genres":["Action","Drama","History","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"маратхі","theme":"Війна","who_what":"Битва при Паван-Хінді 1660 року, де Баджі Прабху Дешпанде із загоном стримував ворога, щоб урятувати Шіваджі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Липень 1660-го: Шіваджі з невеликим загоном вирвався з облоги форту Панхала й пробивається до Вішалґада, а Баджі Прабху Дешпанде з приблизно трьомастами воїнами замикає гірський прохід Ґходкхінд, щоб затримати військо Сідді Джохара. Дігпал Ланджекар знімає майже все як один розтягнутий бій: вузький прохід, дощ, лічені години. Аджай Пуркар грає Баджі Прабху без сучасних психологічних надбудов, у регістрі усного переказу. Після битви ущелину перейменували на Паван-Хінд; фільм став одним із найкасовіших маратхі."},{"imdb_id":"tt9006564","title":"2018","title_uk":"2018","year":2023,"rating":8.3,"votes":17017,"genres":["Action","Adventure","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Катастрофа і виживання","who_what":"Повінь у Кералі 2018 року і рятувальна операція рибалок та волонтерів.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"За кілька серпневих днів 2018-го в Кералі випала злива століття, водосховища довелося відкрити одночасно, і під водою опинилися сотні сіл. Джуд Ентоні Джозеф збирає з десятка вигаданих доль одну картину катастрофи, а головними героями робить рибалок, які пригнали свої човни з узбережжя в затоплені райони. На момент виходу — найкасовіший малаяламський фільм і офіційна заявка Індії на «Оскар». Персонажі збірні, самі рятувальні операції задокументовані."},{"imdb_id":"tt0100234","title":"Close-Up","title_uk":"Крупний план","year":1990,"rating":8.2,"votes":27346,"genres":["Biography","Crime","Drama"],"country":"Іран","country_main":"Іран","region":"Близький Схід і Африка","language":"перс.","theme":"Суд і журналістика","who_what":"Реальна справа Хосейна Сабзіана, який видавав себе за режисера Мохсена Махмальбафа й потрапив під суд за шахрайство.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"1989 року безробітний друкар Хосейн Сабзіан кілька тижнів видавав себе за режисера Мохсена Махмальбафа перед тегеранською родиною Аханхах, обіцяючи зняти їх у кіно; його заарештували за шахрайство. Аббас Кіаростамі зняв справжній судовий процес і попросив усіх учасників — Сабзіана, Аханхахів, журналіста Фаразманда й самого Махмальбафа — переграти події перед камерою. Межа між документом і постановкою зникає остаточно. Фінальна зустріч двох чоловіків на мотоциклі стала класикою іранського кіно."},{"imdb_id":"tt0101985","title":"A Brighter Summer Day","title_uk":"Яскравий літній день","year":1991,"rating":8.2,"votes":15365,"genres":["Crime","Drama","Romance"],"country":"Тайвань","country_main":"Тайвань","region":"Східна Азія","language":"кит. (мандарин, тайв.)","theme":"Кримінал","who_what":"Перше вбивство, скоєне неповнолітнім у повоєнному Тайвані: 1961 року тайбейський школяр зарізав свою однолітку.","basis":"реальна історія","note":"Імена учасників змінені, а більшість персонажів навколо вбивства — художня реконструкція середовища, а не документальні постаті.","thriller_flag":false,"decade":"1990-ті","desc":"У червні 1961 року в Тайбеї підліток зарізав свою однолітку — це стало першим убивством, скоєним неповнолітнім у повоєнному Тайвані. Едвард Ян навчався в тій самій школі й через тридцять років розгорнув справу в майже чотиригодинну фреску про дітей материкових біженців, вуличні банди та задуху воєнного стану Гоміньдану. Дебютна роль чотирнадцятирічного Чан Чженя. Хроніку злочину відтворено близько до справи, але імена й побутові деталі змінені."},{"imdb_id":"tt0112641","title":"Casino","title_uk":"Казино","year":1995,"rating":8.2,"votes":627231,"genres":["Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Френк «Лівша» Розенталь керував лас-веґаським казино в інтересах чиказької мафії у 1970-х, поки все не розсипалося.","basis":"реальна історія","note":"Сцену розправи над братами Спілотро знято за ранньою версією; свідчення на процесі 2007 року показали, що їх убили в підвалі, а вже потім закопали.","thriller_flag":false,"decade":"1990-ті","desc":"Скорсезе екранізував документальну книжку Ніколаса Пілледжі: Сем Ротстін — це Розенталь, який тримав «Stardust», Ніккі Санторо — бойовик Ентоні Спілотро, Джинджер — Джері Макджі. Показано і вибух автомобіля 1982 року, який Розенталь пережив, і те, як чиказька верхівка втратила контроль над касою. Роберт Де Ніро, Джо Пеші, Шерон Стоун із номінацією на «Оскар». Імена змінено, деякі епізоди спресовано."},{"imdb_id":"tt0245929","title":"Devils on the Doorstep","title_uk":"Дияволи на порозі","year":2000,"rating":8.2,"votes":9462,"genres":["Comedy","Drama","War"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"кит. / яп.","theme":"Війна","who_what":"Японська окупація Північного Китаю наприкінці Другої світової війни.","basis":"реальне тло, вигадані герої","note":"У материковому Китаї фільм так і не вийшов у широкий прокат.","thriller_flag":false,"decade":"2000-ті","desc":"Селянинові Ма Дасаню підкидають двох полонених — японського солдата й перекладача — і наказують стерегти до весни. Село й мешканці вигадані, але каральна логіка окупації та фінальна різанина спираються на задокументовані практики. Цзян Вень зняв фільм чорно-білим, вивіз до Канн без дозволу цензури, отримав Гран-прі й п'ять років заборони знімати."},{"imdb_id":"tt0268978","title":"A Beautiful Mind","title_uk":"Ігри розуму","year":2001,"rating":8.2,"votes":1061740,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Математик і нобелівський лауреат Джон Неш, який усе життя боровся з шизофренією.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Основа — біографія Сильвії Насар про Джона Неша, чия робота з теорії ігор принесла Нобелівську премію 1994 року, а параноїдна шизофренія забрала кілька десятиліть життя. Рон Говард будує оповідь так, щоб глядач бачив світ очима Неша й не одразу відрізняв реальність від марення. Чотири «Оскари», зокрема за фільм. Насправді галюцинації Неша були слуховими, а не візуальними, і сценарій обходить його розлучення з Алісією."},{"imdb_id":"tt0319736","title":"The Legend of Bhagat Singh","title_uk":"Легенда про Бгаґата Сінґха","year":2002,"rating":8.2,"votes":18491,"genres":["Biography","Drama","History","Action"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Біографія індійського революціонера Бгагата Сінгха, страченого британцями 1931 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Бгаґат Сінґх у 1928-му застрелив британського поліціянта Джона Сондерса, наступного року разом із Батукешваром Даттом кинув бомбу в Центральних законодавчих зборах у Делі — не щоб убити, а щоб бути почутим, — і 23 березня 1931-го його повісили в Лахорі у двадцять три роки. Раджкумар Сантоші веде оповідь від арешту до шибениці, з наголосом на тюремному голодуванні й судових промовах. Аджай Девґн отримав за роль Національну кінопремію."},{"imdb_id":"tt0363163","title":"Downfall (Der Untergang)","title_uk":"Бункер (Падіння)","year":2004,"rating":8.2,"votes":403187,"genres":["Biography","Drama","History"],"country":"Німеччина/Австрія/Італія","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Війна","who_what":"Останні дні Адольфа Гітлера у берлінському бункері за спогадами секретарки Траудль Юнге.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Квітень 1945-го, бункер під рейхсканцелярією: останні десять днів Гітлера очима його секретарки Траудль Юнґе, чиї спогади разом із книжкою Йоахіма Феста лягли в основу сценарію. Бруно Ґанц вибудував роль на єдиному вцілілому записі приватної мови Гітлера й на симптомах Паркінсона, а Олівер Гіршбіґель уникає будь-яких закадрових пояснень. Після виходу в Німеччині довго сперечалися, чи не робить така докладність диктатора надто людяним."},{"imdb_id":"tt0367110","title":"Swades","title_uk":"Свадес: Ми, народ","year":2004,"rating":8.2,"votes":107057,"genres":["Drama","Musical"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Натхненний історією Аравінди Піллаламаррі й Раві Кучіманчі, які привезли електрику в індійські села.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Інженер NASA Мохан Бгарґава повертається до Індії, щоб забрати в США няню, яка його виростила, і застрягає в селі Чаранпур, де немає сталого електропостачання. Ашутош Ґоварікер відштовхувався від історії активістів Аравінди Піллаламаррі й Раві Кучіманчі, які возили селами педальний генератор. Шах Рукх Кхан грає без звичної для себе екзальтації, музику написав А. Р. Рахман. У прокаті 2004-го фільм провалився, а репутацію найкращої ролі актора здобув уже згодом."},{"imdb_id":"tt0476735","title":"My Father and My Son","title_uk":"Мій батько і мій син","year":2005,"rating":8.2,"votes":102084,"genres":["Drama"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"тур.","theme":"Політика та історія","who_what":"Військовий переворот 12 вересня 1980 року в Туреччині й репресії проти лівих.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Журналіст Садик, скалічений тортурами після перевороту, привозить малого сина до батьківського села, з господарем якого не розмовляв роками. Родина вигадана, натомість арешти сотень тисяч людей, страти й цензура після 1980-го задокументовані. Чаган Ірмак зняв мелодраму, що стала однією з найпопулярніших у турецькому кіно. Дитинство хлопчика в селі подано як противагу політичному терору."},{"imdb_id":"tt0457430","title":"Pan's Labyrinth","title_uk":"Лабіринт Фавна","year":2006,"rating":8.2,"votes":752370,"genres":["Drama","Fantasy","War"],"country":"Мексика / Іспанія","country_main":"Мексика","region":"Латинська Америка","language":"ісп.","theme":"Війна","who_what":"Іспанія 1944 року: франкістські каральні операції проти партизанів-макі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Тло реальне: 1944 рік, залишки республіканських партизанів у горах, продуктові картки, каральні загони. Дівчинка Офелія, її вітчим капітан Відаль і фавн із лабіринту вигадані, а вся казкова лінія — авторська міфологія Гільєрмо дель Торо. Три «Оскари» за операторську роботу, грим і художнє оформлення. Реальні партизанський рух і репресії, вигадані всі персонажі та фантастична частина."},{"imdb_id":"tt0469494","title":"There Will Be Blood","title_uk":"Нафта","year":2007,"rating":8.2,"votes":717991,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Нафтовий бум Південної Каліфорнії 1898–1927 років.","basis":"реальне тло, вигадані герої","note":"Тло — радше історична епоха, ніж окрема подія.","thriller_flag":false,"decade":"2000-ті","desc":"Пол Томас Андерсон докладно реконструює ранню нафтову індустрію: ручне буріння, скуповування ділянок у фермерів, пожежі свердловин, прокладання трубопроводів в обхід монополій, паралельне піднесення проповідників-п'ятдесятників. Старатель Деніел Плейнв'ю і проповідник Ілай Сандей вигадані, як і містечко Літл-Бостон. Даніель Дей-Льюїс отримав «Оскар»; знімали в Марфі, Техас. Реальні економіка й релігійне пробудження доби, вигадані всі персонажі."},{"imdb_id":"tt1305806","title":"The Secret in Their Eyes","title_uk":"Таємниця в їхніх очах","year":2009,"rating":8.2,"votes":245031,"genres":["Drama","Mystery","Romance","Thriller"],"country":"Аргентина / Іспанія","country_main":"Аргентина","region":"Латинська Америка","language":"ісп.","theme":"Суд і журналістика","who_what":"Аргентина 1974–1975 років напередодні диктатури: ескадрони «Тройки А» і безкарність спецслужб.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Хуан Хосе Кампанелья показує судову систему Буенос-Айреса середини 1970-х, коли вбивць беруть на службу до ескадронів смерті, а справи закривають згори. Слідчий Бенхамін Еспосіто, суддя Ірене Менендес-Гастінґс і справа про вбивство Ліліани Колото вигадані. «Оскар» за іншомовний фільм і знаменитий безперервний кадр на стадіоні «Уракан». Реальний політичний клімат, вигадане розслідування."},{"imdb_id":"tt2181831","title":"Shahid","title_uk":"Шахід","year":2012,"rating":8.2,"votes":21692,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Суд і журналістика","who_what":"Правозахисний адвокат Шахід Азмі, який захищав несправедливо звинувачених у тероризмі й був убитий у 2010 році.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Шахід Азмі після бомбейських погромів 1992–93 років підлітком поїхав у табір бойовиків, повернувся й сім років провів у в'язниці Тіхар — вирок згодом скасували, а він вийшов звідти з дипломом юриста. Хансал Мехта простежує обидві половини цього життя аж до 11 лютого 2010-го, коли Азмі застрелили в його ж конторі в Курлі. Раджкуммар Рао грає без героїчного нальоту: сутулий адвокат, який бере справи, від яких відмовляються всі. Обидва отримали Національну кінопремію Індії."},{"imdb_id":"tt1620933","title":"Paan Singh Tomar","title_uk":"Паан Сінгх Томар","year":2012,"rating":8.2,"votes":40424,"genres":["Action","Biography","Crime","Sport","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Чемпіон Індії зі стипль-чезу, який після несправедливості став ватажком бандитів у Чамбалі.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Субедар індійської армії Паан Сінґх Томар сім разів вигравав національну першість зі стипль-чезу й бігав за країну на Азійських іграх 1958-го в Токіо; після відставки земельний конфлікт із ріднею та байдужість поліції зробили з нього ватажка збройної групи в ярах Чамбалу, де його вбили 1981 року. Тіґманшу Дгулія будує фільм як інтерв'ю героя журналістові, перемежоване спогадами. Ірфан Хан отримав Національну кінопремію за головну роль, а сам фільм — за найкращу повнометражну стрічку року."},{"imdb_id":"tt1954470","title":"Gangs of Wasseypur","title_uk":"Банди Вассейпура","year":2012,"rating":8.2,"votes":115387,"genres":["Action","Comedy","Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Війни вугільної мафії у Вассейпурі (Джаркханд) від 1940-х до 2000-х років.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Анураґ Кашьяп простежує три покоління ворожнечі навколо вугільних шахт Дханбада — від 1940-х, коли Шахід Хан грабував потяги, до 2000-х із кланами, що поділили вивіз вугілля, металобрухт і місцеву політику. П'ять із половиною годин, випущені двома частинами; прем'єра відбулася на «Двотижневику режисерів» у Каннах. Манодж Байпаї і Наваззуддін Сіддікі грають батька й сина, гумор і жорстокість тут ідуть упритул. Імена й родини змінено: це радше збірна хроніка мафії вугільного поясу, ніж чиясь біографія."},{"imdb_id":"tt0993846","title":"The Wolf of Wall Street","title_uk":"Вовк з Волл-стріт","year":2013,"rating":8.2,"votes":1818833,"genres":["Biography","Comedy","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Біржовий маклер Джордан Белфорт і махінації його фірми Stratton Oakmont у 1990-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Джордан Белфорт наприкінці 1980-х відкрив брокерську контору Stratton Oakmont, яка качала гроші зі сміттєвих акцій, і врешті сів за шахрайство та відмивання. Скорсезе екранізує його власні мемуари, тому й розповідь ведеться голосом Белфорта: три години торгів, кокаїну й корпоративних оргій, майже без обманутих інвесторів у кадрі. Саме за це фільм і сварили; режисер відповідав, що глядач має відчути принадність, аби зрозуміти, як це працювало."},{"imdb_id":"tt2356180","title":"Bhaag Milkha Bhaag","title_uk":"Біжи, Мілкха, біжи","year":2013,"rating":8.2,"votes":79781,"genres":["Biography","Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Біографія «Летючого сикха» Мілкхи Сінгха — від жахів поділу Індії до Олімпіади в Римі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мілкха Сінґх дитиною вцілів під час поділу 1947-го, коли в Мултані вирізали його родину, а через тринадцять років у Римі був за крок від олімпійської медалі на 400 метрах. Ракеш Омпракаш Мехра монтує три часові пласти — біженський табір, армійські казарми й підготовку до Олімпіади. Фархан Ахтар готувався рік і біг усі дистанції сам. Сам Мілкха продав права на свою історію за одну рупію; тривалість понад три години влаштовує не кожного глядача."},{"imdb_id":"tt3153634","title":"Hope","title_uk":"Надія","year":2013,"rating":8.2,"votes":12393,"genres":["Drama"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Соціальна драма","who_what":"Родина дівчинки, що пережила напад; в основі — справа Наюн (Чо Ду Суна) 2008 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"2008 року в Ансані п'ятдесятисемирічний рецидивіст жорстоко зґвалтував восьмирічну дівчинку; вирок у дванадцять років спричинив у Кореї хвилю обурення й зміни в законодавстві. Лі Джун Ік свідомо знімає не про злочин, а про те, що після: батько (Соль Кьон Гу), якого дитина тепер боїться, вчиться підходити до неї в костюмі мультяшного героя. Насильство лишається за кадром, усе тримається на терпінні й дрібних побутових перемогах. Найкращий фільм на «Блакитному драконі» 2013 року."},{"imdb_id":"tt6316138","title":"Ayla: The Daughter of War","title_uk":"Айла: Донька війни","year":2017,"rating":8.2,"votes":48998,"genres":["Biography","Drama","History","War"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"турецька, корейська","theme":"Війна","who_what":"Турецький сержант рятує корейську дівчинку під час Корейської війни.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Восени 1950 року турецький сержант Сулейман Дільбірлігі знайшов у розбомбленому корейському селищі осиротілу дівчинку й назвав її Айлою — «місячним сяйвом»; вона жила при бригаді, доки та не повернулася додому. Джан Улкай будує фільм на цій розлуці та на зустрічі через шістдесят років, яку 2010-го зафільмувала південнокорейська MBC. Відверто мелодраматичний тон і Четін Текіндор у ролі старого Сулеймана зробили картину однією з найкасовіших турецьких і кандидатом від Туреччини на «Оскар»."},{"imdb_id":"tt7060460","title":"Theeran Adhigaram Ondru","title_uk":"Тіран: Розділ перший","year":2017,"rating":8.2,"votes":19854,"genres":["Action","Crime","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл.","theme":"Кримінал","who_what":"Восьмирічне полювання тамільського поліціянта на банду «баварія», що грабувала й убивала на трасах Північної Індії.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Наприкінці 1990-х банди грабували придорожні будинки й вирізали цілі родини на трасах Північної Індії; розслідування, відоме як операція «Баварія», очолював офіцер С. Р. Джанґід. Х. Вінот перетворює його справу на восьмирічне полювання: картотеки, засідки, поїздки в Раджастхан і Гар'яну без юрисдикції та без підтримки. Карті грає поліціянта буденно, а насильство подано сухо, майже протокольно. Після прокату громади денотифікованих кочових племен звинуватили авторів у стигматизації, і частину сцен із пізніших версій прибрали."},{"imdb_id":"tt6966692","title":"Green Book","title_uk":"Зелена книга","year":2018,"rating":8.2,"votes":700111,"genres":["Biography","Comedy","Drama","Music"],"country":"США","country_main":"США","region":"США","language":"англ., італ., рос.","theme":"Соціальна драма","who_what":"Турне піаніста Дона Ширлі Півднем США 1962 року разом із водієм-охоронцем Тоні Валлелонгою.","basis":"реальна історія","note":"Родина Дона Ширлі публічно заперечила зображену дружбу й називала фільм вигадкою, побудованою на розповідях сім'ї Валлелонги; критики вказували на наратив «білого рятівника».","thriller_flag":false,"decade":"2010-ті","desc":"1962 року бронкський вибивайло Тоні Валлелонга наймається водієм до афроамериканського піаніста Дона Ширлі, який навмисне везе тріо в турне південними штатами; назва — з довідника мотелів і кафе, куди чорношкірим було безпечно заходити. Пітер Фарреллі знімає роуд-муві, де змінюється насамперед водій. Три «Оскари», зокрема за фільм і за роль Магершали Алі. Сценарій писав син Тоні за батьковими розповідями, і родина Ширлі публічно заперечила і саму дружбу, і зображення піаніста."},{"imdb_id":"tt8291224","title":"Uri: The Surgical Strike","title_uk":"Урі: Хірургічний удар","year":2019,"rating":8.2,"votes":85163,"genres":["Action","Drama","History","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Індійська відповідь на теракт в Урі — «хірургічні удари» 2016 року.","basis":"реальна історія","note":"Персонажі вигадані, а перебіг «хірургічних ударів» 2016 року драматизовано; фільм критикували за мілітаристський пропагандистський тон.","thriller_flag":false,"decade":"2010-ті","desc":"У вересні 2016-го напад бойовиків на армійську базу в Урі забрав життя 19 індійських солдатів; за одинадцять днів Індія оголосила про «хірургічні удари» по таборах через Лінію контролю. Адітья Дгар знімає це як військовий трилер, розбитий на глави, з вигаданим майором Віхааном Шерґіллом (Вікі Каушал) у центрі. Пакистан заперечував масштаб ударів, незалежних підтверджень немає, а фільм подає операцію як безсумнівний тріумф; його репліка «How's the josh?» стала політичним слоганом."},{"imdb_id":"tt8579674","title":"1917","title_uk":"«1917»","year":2019,"rating":8.2,"votes":784702,"genres":["Drama","History","War"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Війна","who_what":"Весняний наступ 1917 року на Західному фронті напередодні відходу німців на лінію Гінденбурга.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Квітень 1917-го, британські позиції у Північній Франції — обстановка, техніка й географія відтворені майже документально. Двоє рядових, Скофілд і Блейк, дістають наказ перетнути щойно залишені німцями землі й зупинити приречену атаку на 1600 солдатів. Сем Мендес зняв усе як безперервний кадр разом з Роджером Дікінсом; три «Оскари». Самі герої та їхнє доручення вигадані, натхнені уривчастими розповідями дідуся режисера."},{"imdb_id":"tt15398776","title":"Oppenheimer","title_uk":"Оппенгеймер","year":2023,"rating":8.2,"votes":1088834,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Фізик Дж. Роберт Оппенгеймер керує Мангеттенським проєктом і потім розплачується за створення атомної бомби.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Нолан екранізував біографію «Американський Прометей» Кая Берда і Мартіна Шервіна, склавши фільм із двох переплетених слухань: перегляду допуску Оппенгеймера 1954 року й сенатських слухань щодо Льюїса Штраусса 1959-го, між якими вкладено Лос-Аламос і випробування «Трініті» 16 липня 1945-го. Кольорові сцени тут суб'єктивні, чорно-білі — погляд збоку; вибух знімали без комп'ютерної графіки. Сім «Оскарів», зокрема Кілліану Мерфі й Роберту Дауні-молодшому. Найчастіший докір: Хіросіма й Нагасакі лишаються за кадром."},{"imdb_id":"tt26458038","title":"Manjummel Boys","title_uk":"Хлопці з Манджуммеля","year":2024,"rating":8.2,"votes":34800,"genres":["Adventure","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Катастрофа і виживання","who_what":"Порятунок друга, який 2006 року провалився в «Диявольську яму» печер Гуна в Кодайканалі.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"2006 року компанія друзів із кочинського Манджуммеля поїхала в Кодайканал, і на екскурсії в печерах Ґуна один із них, Субгаш, провалився в розколину, куди не наважувалися спускатися рятувальники. Чідамбарам знімає першу половину як безтурботну подорож, а другу — як задушливий трилер про те, що робити, коли поліція і пожежники розводять руками. Витяг друга не професіонал, а свій же — Сіджу Девід, який пішов униз на мотузці. На момент виходу це найкасовіше малаяламське кіно в історії."},{"imdb_id":"tt33014583","title":"Dhurandhar","title_uk":"Дхурандхар","year":2025,"rating":8.2,"votes":149207,"genres":["Action","Crime","Thriller","Adventure"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Індійський агент під прикриттям у кримінальному підпіллі Карачі — за реальними операціями індійської розвідки.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Карачі, райони Ліярі: індійський агент вростає в місцеве кримінальне підпілля, а поруч діють упізнавані постаті — поліціянт Чаудхрі Аслам Хан і ватажок банди Рехман Дакайт. Адітья Дхар збирає сюжет із кількох операцій індійської розвідки після атак 26/11, не роблячи біографії жодної конкретної людини. У головній ролі Ранвір Сінґх, поруч Р. Мадхаван, Арджун Рампал, Акшай Кханна й Санджай Датт. Родина майора Мохіта Шарми зверталася до Високого суду Делі, вважаючи прототипом його, — режисер цей зв'язок заперечив."},{"imdb_id":"tt36943034","title":"The Voice of Hind Rajab","title_uk":"Голос Хінд Раджаб","year":2025,"rating":8.2,"votes":20708,"genres":["Biography","Drama","History","War"],"country":"Туніс / Франція","country_main":"Туніс","region":"Близький Схід і Африка","language":"араб.","theme":"Війна","who_what":"Диспетчери Червоного Півмісяця в реальному часі слухають дзвінки п'ятирічної палестинки Хінд Раджаб із обстріляного авто в Газі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"29 січня 2024 року диспетчери Палестинського Червоного Півмісяця понад годину тримали на лінії дівчинку, яка сиділа в розстріляному автомобілі в Газі поруч із тілами родичів і чекала на швидку. Кауттер Бен Ганія вмонтувала в фільм справжній запис цих дзвінків, а все довкола — кімнату диспетчерської, узгодження проїзду, безсилля — зіграли актори. Дія майже не виходить за межі одного приміщення й одного дня. Гран-прі журі Венеції, овація на 23 хвилини й висунення на «Оскар» від Тунісу."},{"imdb_id":"tt39139925","title":"Dhurandhar: The Revenge","title_uk":"Дхурандхар: помста","year":2026,"rating":8.2,"votes":70103,"genres":["Action","Crime","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Продовження історії індійської таємної операції в Пакистані.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Друга й фінальна частина дилогії Адітьї Дгара, знята одним блоком із першою: індійський агент під легендою Хамзи Алі Мазарі роками працює всередині кримінальних мереж карачинського району Лярі. Реальні події тут радше тло й мотив — поліцейська операція в Лярі, теракти в Мумбаї 2008 року, індійська політика 2010-х, — тоді як сам герой і його місія вигадані. У головній ролі Ранвір Сінґх, поряд — Арджун Рампал, Санджай Датт і Мадгаван; прем'єра 19 березня 2026 року."},{"imdb_id":"tt0105271","title":"Roja","title_uk":"Роджа","year":1992,"rating":8.1,"votes":14889,"genres":["Action","Drama","Musical","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл.","theme":"Політика та історія","who_what":"Викрадення заручників кашмірськими бойовиками на початку 1990-х.","basis":"реальне тло, вигадані герої","note":"Стрічку звинувачували у спрощеному, проурядовому погляді на кашмірський конфлікт.","thriller_flag":false,"decade":"1990-ті","desc":"Сільську дівчину Роджу привозять до Делі, а її чоловіка-криптографа викрадають у Кашмірі й вимагають звільнити свого командира. Подружжя вигадане, але практика обміну заручників на ув'язнених сепаратистів у ті роки була цілком реальною. Перший фільм «терористичної трилогії» Мані Ратнама; дебютний саундтрек А. Р. Рахмана здобув Національну премію."},{"imdb_id":"tt0107207","title":"In the Name of the Father","title_uk":"В ім'я батька","year":1993,"rating":8.1,"votes":204528,"genres":["Biography","Crime","Drama"],"country":"Ірландія / Велика Британія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Суд і журналістика","who_what":"Справа «ґілдфордської четвірки» — ірландців, засуджених 1975 року за теракт, якого вони не скоювали.","basis":"реальна історія","note":"Батько й син насправді не сиділи в одній камері, а фінальна сцена в суді та роль адвокатки значно змінені.","thriller_flag":false,"decade":"1990-ті","desc":"У жовтні 1974-го вибухи в пабах Ґілдфорда вбили п’ятьох людей; поліція вибила зізнання з Джеррі Конлона та ще трьох ірландців, які просиділи п’ятнадцять років, доки вирок не скасували 1989 року. Джим Шерідан екранізував спогади Конлона «Proved Innocent», зробивши осердям стосунки сина з батьком Джузеппе, що помер за ґратами 1980-го. Сім номінацій на «Оскар», зокрема Деніелу Дей-Льюїсу та Піту Постлтвейту."},{"imdb_id":"tt0106332","title":"Farewell My Concubine","title_uk":"Прощавай, моя наложнице","year":1993,"rating":8.1,"votes":37641,"genres":["Drama","Music","Romance"],"country":"Китай / Гонконг","country_main":"Китай","region":"Східна Азія","language":"кит.","theme":"Музика та мистецтво","who_what":"Півстоліття китайської історії — від республіки 1920-х до Культурної революції.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Двоє акторів Пекінської опери, Дьєї та Сяолоу, проходять крізь японську окупацію, прихід комуністів і публічні сеанси «боротьби», де змушені зраджувати одне одного. Персонажі й трупа вигадані, але цькування оперних артистів у 1960-ті відтворене точно. «Золота пальмова гілка» 1993 року — перша для китайського кіно; Леслі Чун у головній ролі."},{"imdb_id":"tt0112553","title":"Bombay","title_uk":"Бомбей","year":1995,"rating":8.1,"votes":15305,"genres":["Drama","Musical","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл.","theme":"Політика та історія","who_what":"Знесення мечеті Бабрі 1992 року і погроми в Бомбеї 1992—1993 років.","basis":"реальне тло, вигадані герої","note":"Фільм вийшов із цензурними купюрами, і його критикували з обох релігійних боків за розстановку акцентів.","thriller_flag":false,"decade":"1990-ті","desc":"Індуїст Шекхар і мусульманка Шайла-бану тікають із села до Бомбея, а через кілька років їхні діти губляться посеред погромів. Родина вигадана, натомість хронологія заворушень, підпали й безсилля поліції відтворені за подіями. Мані Ратнам знімав під загрозами; музика А. Р. Рахмана стала одним із найпродаваніших альбомів індійського кіно."},{"imdb_id":"tt0167331","title":"Cosy Dens","title_uk":"Затишні гніздечка","year":1999,"rating":8.1,"votes":7075,"genres":["Comedy","Drama"],"country":"Чехія","country_main":"Чехія","region":"Європа","language":"чеськ.","theme":"Політика та історія","who_what":"Прага 1967—1968 років: Празька весна і радянське вторгнення.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Дві родини в одному будинку — комуніста-військового і колишнього фронтовика-антикомуніста — сваряться через дітей, дивани й політику, поки на вулиці не з'являються танки. Персонажі вигадані, натомість реформи Дубчека, серпень 1968-го й еміграція показані без пафосу. Ян Гржебейк зняв одну з найулюбленіших чеських комедій. Сценарій написав Петр Шабах за власними оповіданнями."},{"imdb_id":"tt0169102","title":"Lagaan: Once Upon a Time in India","title_uk":"Лаґаан: Колись давно в Індії","year":2001,"rating":8.1,"votes":130417,"genres":["Adventure","Drama","History","Musical","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Колоніальна Індія 1893 року: посуха і подвійний земельний податок «лаґаан».","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Селяни Чампанера приймають парі британського офіцера: виграють у крикет — податок скасують на три роки, програють — платитимуть утричі більше. Село, матч і всі герої вигадані, але посуха, система лаґаану й расова ієрархія гарнізону історичні. Аамір Хан продюсував і зіграв головну роль; номінація на «Оскар» за іншомовний фільм."},{"imdb_id":"tt0264464","title":"Catch Me If You Can","title_uk":"Спіймай мене, якщо зможеш","year":2002,"rating":8.1,"votes":1260145,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Шахрай Френк Абаґнейл-молодший, який у 1960-х видавав себе за пілота, лікаря і юриста.","basis":"реальна історія","note":"Мемуари Френка Абаґнейла, на яких базується фільм, значною мірою спростовані журналістськими розслідуваннями: більшість афер, приписаних йому, документально не підтверджуються.","thriller_flag":false,"decade":"2000-ті","desc":"Френк Абаґнейл-молодший розповідав, що підлітком підробив чеків на мільйони й видавав себе за пілота Pan Am, лікаря і прокурора, доки його не спіймали у Франції. Спілберг знімає це як легку гонитву втікача (Леонардо Ді Капріо) й агента ФБР Карла Генраті (Том Генкс), прообразом якого був Джозеф Ші. Пізніші журналістські розслідування показали, що більшу частину своїх пригод Абаґнейл вигадав сам — фільм цього, звісно, не знав."},{"imdb_id":"tt0353969","title":"Memories of Murder","title_uk":"Спогади про вбивство","year":2003,"rating":8.1,"votes":273448,"genres":["Crime","Drama","Mystery","Thriller"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Кримінал","who_what":"Розслідування серійних убивств у Хвасоні 1986–1991 років.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Десять жінок убито в повіті Хвасон між 1986 і 1991 роками; тодішнє слідство не дало нічого. Пон Джун-хо, відштовхуючись від п'єси Кім Кван-ріма, знімає не детектив, а портрет країни під військовою диктатурою: провінційний коп вибиває зізнання ногами, столичний слідчий вірить документам, і обидва методи безсилі. Пісня Кан-хо тримає роль на межі фарсу й жаху. Справжнього вбивцю встановили лише 2019 року, через шістнадцять років після прем'єри."},{"imdb_id":"tt0395169","title":"Hotel Rwanda","title_uk":"Готель «Руанда»","year":2004,"rating":8.1,"votes":394284,"genres":["Biography","Drama","History"],"country":"Велика Британія/ПАР/Італія/США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Війна","who_what":"Готельєр Поль Русесабаджіна, який урятував понад тисячу людей під час геноциду в Руанді 1994 року.","basis":"реальна історія","note":"Частина врятованих у готелі та дослідники геноциду заперечують героїчну версію: свідки стверджували, що Русесабаджіна брав із людей гроші; сам він пізніше був засуджений у Руанді у політично вмотивованому процесі.","thriller_flag":false,"decade":"2000-ті","desc":"Навесні 1994-го менеджер готелю Mille Collines у Кігалі Поль Русесабаджіна сховав за його стінами понад тисячу людей, поки за вікном тривало винищення тутсі. Террі Джордж будує фільм на дрібних оборудках — хабарі, віскі, телефонні дзвінки, — а Дон Чідл грає людину, яка щоразу вигадує наступну годину. Номінації на «Оскар» для Чідла, Софі Оконедо і сценарію. Пізніше частина врятованих оскаржувала цю версію подій, а сам Русесабаджіна 2021 року дістав у Руанді тюремний вирок."},{"imdb_id":"tt0405508","title":"Rang De Basanti","title_uk":"Колір шафрану","year":2006,"rating":8.1,"votes":127257,"genres":["Comedy","Crime","Drama","History","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Антиколоніальний рух 1920–30-х і скандал довкола аварій винищувачів МіГ-21 у сучасній Індії.","basis":"реальне тло, вигадані герої","note":"У флешбеках діють реальні історичні особи (Бгаґат Сінґх та інші).","thriller_flag":false,"decade":"2000-ті","desc":"Британська студентка знімає в Делі фільм про Бгаґата Сінґха й Чандрашекхара Азада, і четверо безтурботних студентів грають цих революціонерів. Самі студенти та їхня історія помсти за загиблого пілота вигадані, але тло реальне: і колоніальні страти, і корупція в закупівлях МіГ-21. Ракеш Омпракаш Мехра, музика А. Р. Рахмана, культовий статус у покоління 2000-х. Історичні вставки документальні за суттю, сучасна лінія — ні."},{"imdb_id":"tt0871510","title":"Chak De! India","title_uk":"Вперед, Індіє!","year":2007,"rating":8.1,"votes":92570,"genres":["Drama","Family","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Тренер жіночої збірної з хокею на траві веде команду до перемоги; прообраз — воротар Мір Ранджан Неґі та тріумф 2002 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Кабір Хан (Шах Рух Хан), колишній капітан збірної Індії з хокею на траві, якого після незабитого пенальті звинуватили у зраді, повертається тренувати жіночу команду з шістнадцяти дівчат із різних штатів. Прообразом став воротар Мір Ранджан Неґі, якого цькували після поразки 1:7 від Пакистану 1982 року, а фінал відсилає до перемоги індійок на Іграх Співдружності 2002-го. Шіміт Амін знімає матчі майже без пісенних вставок — рідкість для Боллівуду тих років. Сам турнір у фільмі вигаданий."},{"imdb_id":"tt0978762","title":"Mary and Max","title_uk":"Мері і Макс","year":2009,"rating":8.1,"votes":203000,"genres":["Animation","Comedy","Drama"],"country":"Австралія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ.","theme":"Соціальна драма","who_what":"Двадцятирічне листування дівчинки з Мельбурна і нью-йоркця з синдромом Аспергера — за реальним листуванням режисера.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Адам Елліот двадцять років листувався з нью-йоркцем, з якого зробив Макса Горовіца — сорокачотирирічного єврея з синдромом Аспергера, що випадково отримує лист від восьмирічної Мері Дейзі Дінкл із передмістя Мельбурна. Пластилінова анімація, знята покадрово: сірий Нью-Йорк і бурий Мельбурн, голоси Філіпа Сеймура Гоффмана і Тоні Коллетт. Попри вигляд, це не дитяче кіно — тут самотність, переїдання, алкоголізм і психіатрія. Відкривав «Санденс» 2009 року і взяв головний приз в Ансі."},{"imdb_id":"tt1028532","title":"Hachi: A Dog's Tale","title_uk":"Хатіко: Найвірніший друг","year":2009,"rating":8.1,"votes":347195,"genres":["Biography","Drama","Family"],"country":"США / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Історія пса Хатіко, який роками чекав померлого господаря на вокзалі.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Справжній Хатіко — акіта-іну професора Хідесабуро Уено, який 1925 року помер на роботі; пес приходив на станцію Сібуя зустрічати його ще майже десять років. Лассе Галльстрем переніс історію в містечко в Род-Айленді, зробивши господаря викладачем музики у виконанні Річарда Ґіра. Знято просто, майже без сюжетних ускладнень, чимало сцен подано з собачої перспективи. Це друга екранізація — японський «Хатіко моноґатарі» вийшов 1987 року."},{"imdb_id":"tt1821682","title":"Traffic","title_uk":"Трафік","year":2011,"rating":8.1,"votes":5765,"genres":["Action","Adventure","Mystery"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Медицина та виживання","who_what":"Гонка з часом задля перевезення донорського серця — за реальною естафетою трансплантації в Ченнаї 2008 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Поштовхом став реальний випадок у Ченнаї, коли поліція розчистила дорожній коридор, щоб донорське серце встигли довезти до реципієнта. Раджеш Піллаї розкладає це на кілька ліній — розжалуваний констебль, кардіолог, кінозірка, батько дитини — і зводить їх на стокілометровому відрізку траси, де рахунок іде на хвилини. Малаяламський «Traffic» вважають одним із перших фільмів місцевої нової хвилі; згодом вийшов гінді-ремейк із тією ж назвою."},{"imdb_id":"tt1454029","title":"The Help","title_uk":"Прислуга","year":2011,"rating":8.1,"votes":532594,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Сегрегований Міссісіпі 1963 року і рух за громадянські права.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Тейт Тейлор показує Джексон 1963 року: закони Джима Кроу, окремі вбиральні для чорношкірої прислуги, убивство Медґара Еверса, промови Кеннеді по телевізору. Скітер Фелан, Ейбілін Кларк і Мінні Джексон вигадані, як і книжка, яку вони таємно пишуть. Октавія Спенсер отримала «Оскар» за другопланову роль. Реальні події лишаються тлом; сюжет — із роману Кетрін Стокетт."},{"imdb_id":"tt2024544","title":"12 Years a Slave","title_uk":"12 років рабства","year":2013,"rating":8.1,"votes":793071,"genres":["Biography","Drama","History"],"country":"США, Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Вільний афроамериканець Соломон Нортап був викрадений 1841 року і 12 років провів у рабстві в Луїзіані.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Соломон Нортап, вільний скрипаль із Нью-Йорка, 1841 року поїхав на заробіток до Вашингтона, де його напоїли, викрали й продали на Південь; додому він повернувся аж через дванадцять років і одразу видав книжку спогадів. Стів Макквін екранізує її майже дослівно, довгими нерозрізаними планами — сцена із зашморгом триває так, що глядач починає рахувати секунди. Чіветел Еджіофор у головній ролі, Лупіта Ніонго — «Оскар» за другий план, фільм — за найкращий. Знімали на справжніх луїзіанських плантаціях."},{"imdb_id":"tt1979320","title":"Rush","title_uk":"Гонка","year":2013,"rating":8.1,"votes":565234,"genres":["Biography","Drama","Sport"],"country":"Велика Британія, Німеччина, США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Спорт","who_what":"Суперництво пілотів Формули-1 Джеймса Ганта і Нікі Лауди в сезоні 1976 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Сезон Формули-1 1976 року: британець Джеймс Гант і австрієць Нікі Лауда б'ються за титул, поки Лауда не згорає у «Феррарі» на Нюрбурґрінзі — і через сорок днів повертається за кермо. Рон Говард знімає подвійний портрет: Кріс Гемсворт грає безладного гедоніста, Даніель Брюль — інженера, який рахує ризик у відсотках. Лауда консультував зйомки і схвалив результат. Ворожнечу загострено — поза трасою пілоти приятелювали і якийсь час навіть жили в одній квартирі."},{"imdb_id":"tt2659414","title":"Miracle in Cell No. 7","title_uk":"Диво в камері №7","year":2013,"rating":8.1,"votes":26420,"genres":["Comedy","Drama"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Соціальна драма","who_what":"Батько з інтелектуальною інвалідністю, несправедливо засуджений за вбивство — сюжет натхнений судовою помилкою у справі Чон Вон Сопа (Чхунчхон, 1972).","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Відправна точка — судова помилка 1972 року в Чхунчхоні, де Чон Вон Сопа під тиском змусили зізнатися у вбивстві дівчинки, а виправдали лише через 36 років. Лі Хван Кьон переносить дію в 1997-й і робить із цього сентиментальну трагікомедію: батько з інтелектуальною інвалідністю та шестеро співкамерників, які потайки проносять до камери його маленьку доньку. Фільм зібрав понад 12 мільйонів глядачів у Кореї й породив щонайменше п'ять іноземних рімейків."},{"imdb_id":"tt2991224","title":"Tangerines","title_uk":"Мандарини","year":2013,"rating":8.1,"votes":52021,"genres":["Drama","War"],"country":"Естонія / Грузія","country_main":"Естонія","region":"Інше","language":"естон., рос., груз.","theme":"Війна","who_what":"Війна в Абхазії 1992–1993 років.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Заза Урушадзе показує абхазький конфлікт із боку естонського села, майже спорожнілого після від'їзду громади: чеченський найманець і грузинський боєць виживають у хаті старого столяра Іво. Іво, його сусід Марґус і обидва поранені вигадані. Естонсько-грузинська копродукція, номінації на «Оскар» і «Золотий глобус». Реальні і війна, і естонські поселення Абхазії; вигадана вся ситуація в домі."},{"imdb_id":"tt1895587","title":"Spotlight","title_uk":"У центрі уваги","year":2015,"rating":8.1,"votes":539626,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Розслідування редакції Boston Globe про масові приховані випадки педофілії у Католицькій церкві Бостона (2001–2002).","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"2001 року новий редактор Boston Globe Мартін Барон доручив відділу Spotlight перевірити справу священника Джона Ґеоґана — і за пів року журналісти вийшли на систему, якою архідієцезія десятиліттями переводила педофілів із парафії в парафію. Том Маккарті знімає це без жодних ефектів: телефонні дзвінки, судові архіви, розмови з потерпілими на кухнях. «Оскари» за фільм і сценарій; редакція консультувала знімальну групу, а серія публікацій зрештою розрослася на сотні матеріалів."},{"imdb_id":"tt4934950","title":"Talvar","title_uk":"Лезо","year":2015,"rating":8.1,"votes":43894,"genres":["Crime","Drama","Mystery","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Суд і журналістика","who_what":"Три версії слідства у справі про вбивство Аруші Талвар і Хемраджа 2008 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Ніч на 16 травня 2008 року в Нойді: у своїй кімнаті знаходять мертвою школярку Аруші Талвар, наступного дня на даху — тіло слуги Хемраджа. Меґхна Ґулзар за сценарієм Вішала Бхардваджа вибудовує три несумісні реконструкції — місцевої поліції, першої слідчої групи й другої — і жодну не подає як остаточну. Ірфан Хан грає слідчого, який програє не злочинцям, а бюрократії. Батьків дівчини засудили 2013-го й виправдали 2017 року; справа й досі нерозкрита."},{"imdb_id":"tt2119532","title":"Hacksaw Ridge","title_uk":"Із міркувань совісті","year":2016,"rating":8.1,"votes":693903,"genres":["Biography","Drama","History","War"],"country":"США / Австралія","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Санітар-адвентист Десмонд Досс, який відмовився брати зброю та врятував 75 поранених у битві за Окінаву 1945 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Десмонд Досс, адвентист сьомого дня з Вірджинії, пішов на війну санітаром і відмовився навіть тримати гвинтівку — за що його цькували у власній роті й судили; у травні 1945-го на скелі Маеда під Окінавою він за одну ніч спустив униз десятки поранених. Мел Гібсон ділить фільм навпіл: тиха вірджинська перша година й натуралістична різанина в другій. Ендрю Гарфілд грає впертість без святенництва; два «Оскари» — за монтаж і зведення звуку."},{"imdb_id":"tt1950186","title":"Ford v Ferrari","title_uk":"Ford проти Ferrari","year":2019,"rating":8.1,"votes":583790,"genres":["Action","Biography","Drama","Sport"],"country":"США / Франція","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Керолл Шелбі та Кен Майлз, які збудували Ford GT40 і виграли «24 години Ле-Мана» 1966 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Коли Енцо Феррарі зірвав продаж компанії Генрі Форду II, у Дірборні вирішили побити його на трасі — і покликали колишнього гонщика Керролла Шелбі, а той тягне за собою впертого механіка Кена Майлза. Джеймс Мангольд знімає перегони плівкою, з мінімумом графіки, і половину напруги виносить у кабінети Дірборна, де корпорація заважає власній команді. Метт Деймон і Крістіан Бейл, два «Оскари» — за монтаж і звук. Наказ фінішувати трьома машинами в ряд у Ле-Мані 1966-го реальний."},{"imdb_id":"tt10324144","title":"Article 15","title_uk":"Стаття 15","year":2019,"rating":8.1,"votes":41852,"genres":["Crime","Drama","Mystery","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Розслідування кастового злочину на селі; натхнено справою про зґвалтування й убивство дівчат у Бадауні 2014 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Стаття 15 Конституції Індії забороняє дискримінацію за кастою, релігією чи статтю — назва працює як докір. Молодий офіцер поліції з делійського середовища отримує призначення в село в Уттар-Прадеші, де зникли три дівчинки з далітської родини, і швидко бачить, що підлеглі не вважають це справою. Анубхав Сінха відштовхувався від справи в Бадауні 2014 року й від публічного шмагання далітів в Уні. Аюшманн Кхуррана грає чужинця, чиє незнання власної країни й становить сюжет."},{"imdb_id":"tt9851854","title":"Major","title_uk":"Майор","year":2022,"rating":8.1,"votes":34547,"genres":["Action","Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"телугу","theme":"Війна","who_what":"Майор Сандіп Уннікрішнан, який загинув під час звільнення заручників у Мумбаї 2008 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"26 листопада 2008 року бойовики захопили кілька об'єктів у Мумбаї, і майора Сандіпа Уннікрішнана з групи NSG кинули на звільнення готелю Taj Mahal Palace, де він загинув наступного дня, витягуючи поранену колегу. Саші Кіран Тікка більшу частину хронометражу віддає не штурму, а Бангалору: школі, батькам, коханню, військовій академії. Адіві Сеш зіграв головну роль і написав сценарій, продюсував Махеш Бабу. Знімали одночасно телугу й гінді; посмертно Уннікрішнану присвоїли «Ашока Чакру»."},{"imdb_id":"tt11396310","title":"Viduthalai: Part 1","title_uk":"«Відудалай. Частина 1»","year":2023,"rating":8.1,"votes":12175,"genres":["Action","Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Політика та історія","who_what":"Поліцейські операції проти сепаратистського партизанського руху в лісах на межі Тамілнаду 1980-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Ветрімааран екранізує оповідання Джеямохана й показує спецоперацію проти угруповання «Маккал Падай» очима новобранця. Констебль Кумаресан приставлений водієм до загону, який катує селян і фабрикує справи, і поступово переходить на бік тих, кого має ловити. Сурадж Венджарамуду й Віджай Сетхупаті; дві Національні кінопремії Індії. Тактика зачисток і зникнення людей задокументовані; загін, село й ватажок вигадані."},{"imdb_id":"tt14961016","title":"I'm Still Here","title_uk":"Я досі тут","year":2024,"rating":8.1,"votes":171175,"genres":["Biography","Drama","History"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"порт.","theme":"Політика та історія","who_what":"Еуніс Пайва роками домагається правди про чоловіка-конгресмена, викраденого і вбитого бразильською хунтою 1971 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Ріо, січень 1971-го: люди в цивільному забирають з дому колишнього конгресмена Рубенса Пайву «для свідчень», і він не повертається; його дружину Еуніс і доньку теж тримають під вартою. Волтер Саллес екранізував мемуари сина, Марселу Рубенса Пайви, охопивши понад сорок років — аж до свідоцтва про смерть, виданого 1996-го. Еуніс, яка у сорок вісім стала юристкою й захищала права корінних народів, грає Фернанда Торрес, у пізніх сценах — Фернанда Монтенеґро. Перший «Оскар» в історії бразильського кіно."},{"imdb_id":"tt27118357","title":"Amaran","title_uk":"Амаран","year":2024,"rating":8.1,"votes":24413,"genres":["Action","Adventure","Biography","Drama","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Війна","who_what":"Майор Мукунд Варадараджан, посмертно нагороджений «Ашока Чакра».","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Майор Мукунд Варадараджан загинув 25 квітня 2014 року в бою з бойовиками в Шопіані на півдні Кашміру й посмертно отримав «Ашока Чакру» — найвищу нагороду Індії за мужність поза війною. Раджкумар Періасамі будує фільм навколо його стосунків із дружиною Індгу Ребеккою Варґезе, тож половина хронометражу — це знайомство, весілля й побут військової родини. Сівакартікеян і Саї Паллаві грають подружжя; основа — нарис зі збірки «India's Most Fearless»."},{"imdb_id":"tt0099348","title":"Dances with Wolves","title_uk":"Танцює з вовками","year":1990,"rating":8,"votes":312863,"genres":["Adventure","Drama","Western"],"country":"США","country_main":"США","region":"США","language":"англ. / лакота","theme":"Політика та історія","who_what":"Фронтир США 1863 року і витіснення сіу з Великих рівнин.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Лейтенант Данбар просить призначення на найдальший форпост, оселяється поруч із табором лакота і поступово переходить на їхній бік. Данбар і громада вигадані, але побут лакота, полювання на бізонів і наступ армії показані з етнографічною увагою, а більшість діалогів звучить мовою лакота. Сім «Оскарів» і повернення вестерну в моду."},{"imdb_id":"tt0102138","title":"JFK","title_uk":"Джей-Еф-Кей","year":1991,"rating":8,"votes":183287,"genres":["Drama","History","Thriller"],"country":"США / Франція","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Розслідування прокурора Джима Гаррісона, який єдиний довів до суду справу про змову у вбивстві Джона Кеннеді.","basis":"реальна історія","note":"Версія про змову, яку обстоює фільм, не підтверджена слідством; історики закидають стрічці вибірковість і вигадані сцени.","thriller_flag":true,"decade":"1990-ті","desc":"Окружний прокурор Нового Орлеана Джим Гаррісон у 1967–1969 роках єдиний у США дійшов до суду присяжних у справі про змову навколо вбивства Джона Кеннеді — бізнесмена Клея Шоу виправдали менш ніж за годину. Олівер Стоун змонтував версію Гаррісона з хронікою та плівкою Запрудера й отримав два «Оскари» — за операторську роботу й монтаж. Резонанс від фільму підштовхнув Конгрес ухвалити закон 1992 року про розсекречення матеріалів справи."},{"imdb_id":"tt0111786","title":"In the Heat of the Sun","title_uk":"Під палючим сонцем","year":1994,"rating":8,"votes":6383,"genres":["Drama","Romance"],"country":"Китай / Гонконг","country_main":"Китай","region":"Східна Азія","language":"кит.","theme":"Політика та історія","who_what":"Пекін часів Культурної революції, коли школи закрили, а батьків відправили в кампанії.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Підлітки з військового містечка вештаються напівпорожнім містом, відмикають чужі квартири й вигадують собі перше кохання, поки дорослі роблять революцію. Герої вигадані за повістю Ван Шо, а безлад 1970-х, гасла й армійські родини реальні. Режисерський дебют Цзян Веня; сімнадцятирічний Ся Юй став наймолодшим переможцем венеційського конкурсу за чоловічу роль."},{"imdb_id":"tt0114787","title":"Underground","title_uk":"Андеграунд","year":1995,"rating":8,"votes":64524,"genres":["Comedy","Drama","Fantasy","War"],"country":"Югославія / Франція / Німеччина","country_main":"Югославія","region":"Європа","language":"сербохорв.","theme":"Політика та історія","who_what":"Югославія від бомбардування Белграда 1941 року до воєн розпаду 1990-х.","basis":"реальне тло, вигадані герої","note":"Фільм гостро критикували за нібито просербське трактування розпаду Югославії.","thriller_flag":false,"decade":"1990-ті","desc":"Емір Кустуриця веде двох шахраїв, Марка й Чорного, крізь півстоліття: підвал, де люди двадцять років роблять зброю, не знаючи, що війна скінчилася, стає метафорою країни. Герої й підвал вигадані, хроніка в кадрі справжня. Друга «Золота пальмова гілка» режисера. Три частини оповіді охоплюють війну, соціалізм і розпад країни, а музику написав Ґоран Бреґович."},{"imdb_id":"tt0118751","title":"Border","title_uk":"Кордон","year":1997,"rating":8,"votes":20575,"genres":["Action","Drama","History","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Бій під Лонгевалою в ніч проти 5 грудня 1971 року під час індо-пакистанської війни.","basis":"реальна історія","note":"Масштаб бою і втрати драматизовано, побутові й родинні лінії героїв вигадані.","thriller_flag":false,"decade":"1990-ті","desc":"У ніч проти 5 грудня 1971 року близько ста двадцяти індійських солдатів під командою майора Кулдіпа Сінгха Чандпурі втримали пост Лонгевала в пустелі Тар проти пакистанської танкової колони, доки на світанку не підійшла авіація. Дж. П. Дутта зняв тригодинний епос із Санні Деолом у ролі Чандпурі. У фільмі виведені й інші реальні учасники — Бгайрон Сінгх Ратхор, субедар Ратан Сінгх, льотчик М. С. Бава."},{"imdb_id":"tt0120338","title":"Titanic","title_uk":"Титанік","year":1997,"rating":8,"votes":1410666,"genres":["Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Загибель лайнера «Титанік» у ніч на 15 квітня 1912 року.","basis":"реальне тло, вигадані герої","note":"Показ першого помічника Мердока як убивці пасажирів викликав протести його родини й рідного міста.","thriller_flag":false,"decade":"1990-ті","desc":"Джеймс Кемерон відтворив рейс і загибель «Титаніка» майже з музейною точністю — від інтер'єрів до хронології затоплення. Роман бідного художника Джека і панянки Роуз вигаданий, як і більшість пасажирів у кадрі, хоча капітан Сміт, Ісмей та Ендрюс реальні. Одинадцять «Оскарів» і касовий рекорд 1990-х. Претензії істориків стосуються здебільшого зображення офіцера Мердока."},{"imdb_id":"tt0165546","title":"The Wounds","title_uk":"Рани","year":1998,"rating":8,"votes":12641,"genres":["Comedy","Crime","Drama"],"country":"Югославія (Сербія)","country_main":"Югославія (Сербія)","region":"Європа","language":"сербська","theme":"Кримінал","who_what":"Випадок двох белградських підлітків-кримінальників Мірка Бешевича і Марка Пейковича, що стріляли один в одного.","basis":"натхненний реальними подіями","note":"Герої і сюжет вигадані; реальним є лише випадок, що дав поштовх сценарію.","thriller_flag":false,"decade":"1990-ті","desc":"1994 року белградська телепрограма «Трагач» розповіла про двох друзів із кримінального середовища: один п'ять разів вистрілив в іншого, а після одужання жертви запропонував відстріляти йому у відповідь. Срджан Драгоєвич написав сценарій за тринадцять днів, свідомо не переглядаючи телесюжет. Фільм показує, як санкції, війна і режим Мілошевича перетворювали белградських підлітків на вбивць."},{"imdb_id":"tt0166896","title":"The Straight Story","title_uk":"Проста історія","year":1999,"rating":8,"votes":109612,"genres":["Adventure","Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Сімдесятитрирічний Елвін Стрейт 1994 року проїхав понад триста кілометрів на садовому тракторі, щоб помиритися з братом.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"1994 року 73-річний Елвін Стрейт вирушив із Лоренса в Айові до Маунт-Зайона у Вісконсині на газонокосарці John Deere, бо через зір і ноги не міг вести автомобіль; дорога зайняла близько шести тижнів. Девід Лінч зняв за цим найтихішу свою стрічку, з музикою Анджело Бадаламенті. Річард Фарнсворт у сімдесят дев'ять років став найстаршим номінантом на «Оскар» за головну чоловічу роль."},{"imdb_id":"tt0222012","title":"Hey Ram","title_uk":"Гей, Рам","year":2000,"rating":8,"votes":15291,"genres":["Crime","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"таміл. / гінді","theme":"Політика та історія","who_what":"Поділ Індії 1946—1948 років і вбивство Ґанді.","basis":"реальне тло, вигадані герої","note":"Фільм звинувачували водночас у виправданні індуїстського радикалізму і в наклепі на нього.","thriller_flag":false,"decade":"2000-ті","desc":"Археолог Сакет Рам після загибелі дружини під час калькуттських погромів приєднується до радикалів і погоджується вбити Ґанді. Сакет Рам вигаданий, натомість «День прямої дії», Натурам Ґодзе й останні дні Ґанді реальні. Каміл Хасан написав сценарій, зняв фільм і зіграв головну роль; стрічка викликала протести з обох боків."},{"imdb_id":"tt0270053","title":"Vizontele","title_uk":"Візонтеле","year":2001,"rating":8,"votes":41553,"genres":["Comedy","Drama","History"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"тур.","theme":"Соціальна драма","who_what":"Прихід першого телевізора до містечка в Хаккярі 1974 року — напівавтобіографія Їлмаза Ердогана.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Літо 1974-го, глухе містечко в Хаккярі на південному сході Туреччини: держава надсилає перший телевізор, і селище ділиться на тих, хто чекає дива, і тих, хто бачить загрозу. Їлмаз Ердоган, який там виріс, зіграв міського дивака Еміна й поставив фільм за власними спогадами разом з Омером Фаруком Сораком. Комедія поступово темніє: за кадром іде турецька операція на Кіпрі. Один із найкасовіших турецьких фільмів свого часу."},{"imdb_id":"tt0351817","title":"The Twilight Samurai","title_uk":"Сутінковий самурай","year":2002,"rating":8,"votes":27270,"genres":["Drama","Romance"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"яп.","theme":"Політика та історія","who_what":"Останні роки сьоґунату Токуґава напередодні Реставрації Мейдзі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Дрібний самурай Іґуті Сейбей після смерті дружини сам ростить доньок і латає бюджет підробітками, аж поки клан не наказує йому вбити непокірного васала. Герої вигадані Сюхеєм Фудзісавою, натомість зубожіння нижчого самурайства і крах станової системи показані буденно й точно. Дванадцять премій Японської кіноакадемії та номінація на «Оскар»."},{"imdb_id":"tt0408664","title":"Nobody Knows","title_uk":"Ніхто не знає","year":2004,"rating":8,"votes":35934,"genres":["Drama"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"японська","theme":"Соціальна драма","who_what":"Четверо дітей самі виживають у токійській квартирі; в основі — справа покинутих дітей у Сугамо 1988 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"1988 року в токійському районі Сугамо виявили чотирьох дітей, яких мати покинула в орендованій квартирі. Хірокадзу Корееда розтягує історію на рік, від літа до літа, і дивиться на неї очима дванадцятирічного Акіри, що стає дорослим замість матері: рахує гроші, пере, ходить по продукти. Камера тримається на рівні дітей, дорослі майже не потрапляють у кадр. Юя Яґіра у чотирнадцять став наймолодшим переможцем Канн за чоловічу роль."},{"imdb_id":"tt0424227","title":"Turtles Can Fly","title_uk":"Черепахи вміють літати","year":2004,"rating":8,"votes":22933,"genres":["Drama","War"],"country":"Іран / Ірак","country_main":"Іран","region":"Близький Схід і Африка","language":"курдська","theme":"Війна","who_what":"Іракський Курдистан напередодні вторгнення США 2003 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Діти в таборі біженців на іраксько-турецькому кордоні розміновують поля руками й продають міни, чекаючи війни, яка має скинути Саддама. Герої вигадані, але табори, покалічені діти й супутникові антени заради новин — реальність, зафіксована Бахманом Ґобаді. Усі ролі зіграли непрофесійні актори, багато з них справді без кінцівок."},{"imdb_id":"tt0386064","title":"Tae Guk Gi: The Brotherhood of War","title_uk":"38-ма паралель","year":2004,"rating":8,"votes":42499,"genres":["Action","Drama","War"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Війна","who_what":"Корейська війна 1950—1953 років.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Двох братів із Сеула мобілізують того самого дня, і старший береться за смертельні завдання, щоб виторгувати молодшому звільнення. Брати вигадані, а падіння Сеула, оборона на Нактонгані, висадка в Інчхоні й чистки «неблагонадійних» — реальні епізоди війни. Найдорожчий корейський фільм свого часу; понад одинадцять мільйонів глядачів у прокаті."},{"imdb_id":"tt0352248","title":"Cinderella Man","title_uk":"Нокдаун (Попелюшка)","year":2005,"rating":8,"votes":210606,"genres":["Biography","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Боксер Джеймс Дж. Бреддок, який під час Великої депресії повернувся на ринг і став чемпіоном світу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джеймс Дж. Бреддок втратив кар'єру через переламану руку й у Велику депресію розвантажував судна в доках Нью-Джерсі, а 1935-го несподівано побив чемпіона Макса Бера. Рон Говард знімає передусім сімейну драму: борги, вимкнене опалення, дружина Мей — і аж потім ринг. Рассел Кроу і Пол Джаматті грають дуетом боксера й менеджера Джо Ґулда; родина Бера публічно дорікала фільму за те, що з реального боксера зробили карикатурного вбивцю."},{"imdb_id":"tt0454921","title":"The Pursuit of Happyness","title_uk":"У гонитві за щастям","year":2006,"rating":8,"votes":629054,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Автобіографія","who_what":"Історія Кріса Гарднера — бездомного батька-одинака, який став успішним біржовим брокером.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Сан-Франциско початку 1980-х: Кріс Ґарднер вклав заощадження в апарати для сканування кісткової тканини, які майже не продаються, і водночас іде на неоплачуване стажування в брокерську фірму Dean Witter. Ґабріеле Муччино будує фільм на побуті — черги в притулок, ночівля в туалеті метро, син на руках між дзвінками клієнтам. Вілл Сміт грає в парі з власним сином Джейденом і отримав номінацію на «Оскар». У реальності син Ґарднера був немовлям, а бездомним той пробув близько року."},{"imdb_id":"tt0450259","title":"Blood Diamond","title_uk":"Кривавий діамант","year":2006,"rating":8,"votes":630715,"genres":["Action","Adventure","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Громадянська війна в Сьєрра-Леоне 1990-х і торгівля «кривавими діамантами», що її фінансувала.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Фільм відтворює війну в Сьєрра-Леоне кінця 1990-х: рейди RUF, дітей-солдатів, копальні та схеми легалізації каменів через Ліберію. Родезійський найманець Денні Арчер, рибалка Соломон Ванді й американська журналістка вигадані, як і сама історія пошуку рожевого діаманта. Едвард Цвік знімав у Мозамбіку та ПАР; Ді Капріо і Джимон Гонсу отримали номінації на «Оскар». Кімберлійський процес, згаданий у фіналі, справжній."},{"imdb_id":"tt0758758","title":"Into the Wild","title_uk":"У диких умовах","year":2007,"rating":8,"votes":698732,"genres":["Adventure","Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Подорож і загибель Крістофера Мак-Кендлесса на Алясці за книгою Джона Кракауера.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"1990 року випускник Еморі Крістофер Мак-Кендлесс роздав заощадження, кинув машину й документи і два роки мандрував Штатами під іменем Александр Супербродяга; у серпні 1992-го його знайшли мертвим у покинутому автобусі на Алясці. Шон Пенн екранізував книжку Джона Кракауера, перемежувавши аляскинські місяці зі спогадами про людей, яких Кріс зустрів дорогою. Еміль Гірш схуд на два десятки кілограмів, Гел Голбрук отримав номінацію на «Оскар», музику написав Едді Веддер."},{"imdb_id":"tt0401383","title":"The Diving Bell and the Butterfly","title_uk":"Скафандр і метелик","year":2007,"rating":8,"votes":113157,"genres":["Biography","Drama"],"country":"Франція / США","country_main":"Франція","region":"Європа","language":"фр.","theme":"Медицина та виживання","who_what":"Редактор Elle Жан-Домінік Бобі після інсульту диктує книгу одним оком.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"У грудні 1995-го 43-річний головний редактор французького Elle Жан-Домінік Бобі пережив інсульт стовбура мозку й прокинувся паралізованим, зберігши рух лише лівої повіки. Джуліан Шнабель майже пів фільму тримає камеру Януша Камінського всередині цього ока: розмиті обличчя, кліпання, повільний підбір літер логопедом. Так була продиктована книжка, що вийшла за два дні до смерті Бобі. Каннський приз за режисуру і чотири номінації на «Оскар»."},{"imdb_id":"tt0808417","title":"Persepolis","title_uk":"Персеполіс","year":2007,"rating":8,"votes":106929,"genres":["Animation","Biography","Drama","History","War"],"country":"Франція / США","country_main":"Франція","region":"Європа","language":"фр.","theme":"Автобіографія","who_what":"Автобіографічна графічна повість Маржан Сатрапі про дорослішання під час Ісламської революції в Ірані.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Маржан Сатрапі намалювала автобіографію про Тегеран після 1979 року: страта улюбленого дядька, війна з Іраком, обов'язкова хустка в школі, а далі — самотні підліткові роки у Відні. Разом із Венсаном Паронно вона перенесла графічний роман на екран, зберігши грубу чорно-білу графіку замість мультиплікаційної гладкості. Фільм отримав приз журі Каннського фестивалю, а офіційний Тегеран назвав його антиіранським."},{"imdb_id":"tt0861739","title":"Elite Squad","title_uk":"Елітний загін","year":2007,"rating":8,"votes":120862,"genres":["Action","Crime","Drama","Thriller"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"порт.","theme":"Кримінал","who_what":"Спецпідрозділ BOPE у фавелах Ріо перед візитом Папи Римського 1997 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"1997 рік, Ріо готується до візиту Івана Павла II, і поліція має «зачистити» фавелу поблизу резиденції понтифіка. Жозе Паділья екранізував книжку колишнього офіцера BOPE Родріґу Піментела, написану разом із Луїсом Едуарду Соарешем і Андре Батістою, а розповідь веде вигорілий капітан Насіменту у виконанні Ваґнера Моури. «Золотий ведмідь» Берлінале-2008 і водночас гучна суперечка вдома: частина бразильських критиків побачила у фільмі виправдання катувань."},{"imdb_id":"tt1220719","title":"Ip Man","title_uk":"Іп Ман","year":2008,"rating":8,"votes":244945,"genres":["Action","Biography","Drama","War"],"country":"Гонконг / Китай","country_main":"Гонконг","region":"Східна Азія","language":"кант.","theme":"Спорт","who_what":"Майстер віньчунь Іп Ман у Фошані під час японської окупації Китаю.","basis":"натхненний реальними подіями","note":"Реальний Іп Ман не влаштовував поєдинків із японськими офіцерами і не був народним героєм опору; більшість подій фільму вигадані.","thriller_flag":false,"decade":"2000-ті","desc":"Фошань кінця 1930-х: заможний майстер віньчунь Іп Ман тренується для себе, поки японська окупація не позбавляє його дому. Вілсон Іп ставить класичну гонконзьку драму з боями у постановці Саммо Хуна, а Донні Єн грає стриманого інтелігента, а не крикливого героя. Стрічка перезапустила моду на кунг-фу-байопіки. З біографією збігається небагато: справжній Іп служив у поліції, з японцями не бився і 1949 року виїхав до Гонконгу, де згодом навчав Брюса Лі."},{"imdb_id":"tt1010048","title":"Slumdog Millionaire","title_uk":"Мільйонер із нетрів","year":2008,"rating":8,"votes":914856,"genres":["Crime","Drama","Romance"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ., гінді","theme":"Соціальна драма","who_what":"Мумбаї від індуїстсько-мусульманських погромів 1992–1993 років до буму нульових.","basis":"реальне тло, вигадані герої","note":"Історичні події з'являються фрагментарно, як віхи біографії героя.","thriller_flag":false,"decade":"2000-ті","desc":"Денні Бойл вибудовує біографію хлопця з Дхараві через реальні віхи: погроми після зруйнування мечеті в Айодх'ї, знесення нетрів, будівельний бум і телевікторину «Хто хоче стати мільйонером». Джамаль, Саліма й Латіка вигадані, як і сюжет із поліцейськими допитами. Вісім «Оскарів», зокрема за фільм і музику А. Р. Рахмана. Історичне тло конкретне, але подане епізодами."},{"imdb_id":"tt1171701","title":"The Breath","title_uk":"Подих: хай живе Батьківщина","year":2009,"rating":8,"votes":37147,"genres":["Action","Drama","Thriller"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"турецька","theme":"Війна","who_what":"Турецька застава під облогою РПК; за реальними подіями на південному сході країни.","basis":"натхненний реальними подіями","note":"Турецький воєнний фільм із виразно націоналістичним тоном; конкретна застава й перебіг бою художньо змодельовані, критики оцінювали стрічку як пропагандистську.","thriller_flag":true,"decade":"2000-ті","desc":"Початок 1990-х, ретрансляційна застава в горах на південному сході Туреччини: сорок спецпризначенців чекають нападу, який усі вважають неминучим. Левент Семерджі знімав за оповіданнями Хакана Евренселя, тож конкретної застави за сюжетом немає — є зібраний із багатьох випадків побут: холод, радіоперехоплення, дзвінки додому. Мете Горозоглу грає капітана, для якого чекання виявляється важчим за сам бій. У турецькому прокаті фільм чотири тижні поспіль тримав перше місце."},{"imdb_id":"tt1504320","title":"The King's Speech","title_uk":"Промова короля","year":2010,"rating":8,"votes":736079,"genres":["Biography","Drama","History"],"country":"Велика Британія / США / Австралія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Король Георг VI долає заїкання за допомогою логопеда Лайонела Лога напередодні війни.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Георг VI успадкував трон після зречення брата і 1939 року мусив звернутися по радіо до країни, що вступала у війну, — при тому, що все життя заїкався. Том Гупер будує фільм на сеансах з австралійським логопедом Лайонелом Лоґом (Джеффрі Раш), чиї щоденники знайшов онук; Колін Ферт дістав за роль «Оскар», а фільм — ще три, включно з найкращим. Камера тримається незручно близько, кімнати обдерті. Хронологію стиснуто: насправді Лоґ працював із королем ще з 1926 року."},{"imdb_id":"tt1555149","title":"Elite Squad: The Enemy Within","title_uk":"Елітний загін: Ворог усередині","year":2010,"rating":8,"votes":92968,"genres":["Action","Crime","Drama","Thriller"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"порт.","theme":"Кримінал","who_what":"Зрощення поліцейських «ополчень» і політики в Ріо-де-Жанейро після бунту у в'язниці Бангу-1.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Друга частина Жозе Падільї починається з бунту у в'язниці Бангу-1 і виводить полковника Насіменту (Вагнер Моура) зі штурмової групи БОПЕ в кабінет секретаріату безпеки Ріо, звідки видно головне: фавели переділили не наркоторговці, а поліцейські «ополчення» разом із депутатами. Матеріал зібрано з реальних подій 2000-х — бунт 2002 року, зростання мілісій, парламентські комісії. Найкасовіший бразильський фільм в історії прокату. Персонажі вигадані, але прототипи в Ріо впізнавали без підказок."},{"imdb_id":"tt2070649","title":"Silenced","title_uk":"Тигель","year":2011,"rating":8,"votes":28209,"genres":["Crime","Drama","Thriller"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Суд і журналістика","who_what":"Систематичне насильство над глухими дітьми у школі Інхва в Кванджу та судовий процес 2005–2011 років.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"У школі-інтернаті для глухих дітей Інхва в Кванджу директор і вчителі роками ґвалтували й били учнів, а суд 2005 року роздав винним переважно умовні терміни. Хван Дон-хьок екранізував роман Кон Джі-йон, ведучи розповідь через нового вчителя малювання; Гон Ю сам домігся, щоб фільм зняли. Після прем'єри школу закрили, справу переглянули, а парламент ухвалив «закон Тогані» про суворіші покарання за насильство над дітьми й людьми з інвалідністю."},{"imdb_id":"tt2377938","title":"Special 26","title_uk":"Спецгрупа 26","year":2013,"rating":8,"votes":62870,"genres":["Crime","Drama","History","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Пограбування ювелірного дому Opera House у Бомбеї 1987 року групою, що видавала себе за офіцерів CBI.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"19 березня 1987 року група чоловіків у формі увійшла до ювелірного дому Tribhovandas Bhimji Zaveri біля бомбейської Opera House, оголосила «рейд CBI» і винесла коштовності; виконавців так і не знайшли. Нірадж Пандей відтворює кінець 1980-х із телефонами-автоматами й паперовими ордерами, а поруч із аферистами веде лінію офіцера, що йде по їхньому сліду. Акшай Кумар грає без жодного бойовика: працюють блеф і папірець із печаткою. Розв'язку сценаристи домислили — реальна справа лишилася нерозкритою."},{"imdb_id":"tt2084970","title":"The Imitation Game","title_uk":"Гра в імітацію","year":2014,"rating":8,"votes":883719,"genres":["Biography","Drama","Thriller","War"],"country":"Велика Британія, США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Наука і технології","who_what":"Математик Алан Тюрінг зламав німецький шифр «Енігма» у Блетчлі-Парк і згодом був засуджений за гомосексуальність.","basis":"реальна історія","note":"Численні викривлення: вигадана лінія зі шпигуном Кернкроссом і шантажем, конфлікт із командою та роль Тюрінга в шифруванні подані неточно; історики назвали фільм одним із найменш достовірних байопіків.","thriller_flag":true,"decade":"2010-ті","desc":"Блетчлі-Парк, 1939–1945: Алан Тюрінг будує електромеханічну машину проти «Енігми», а рамкою слугує допит у манчестерському відділку 1951 року, після якого його засудять за «непристойність» і піддадуть гормональній терапії. Мортен Тільдум екранізував біографію Ендрю Годжеса, сценарій Ґрема Мура отримав «Оскар», Камбербетч і Кіра Найтлі — номінації. Історики дорікають фільму за вигадану лінію шантажу з боку радянського агента Джона Кернкросса й за применшення ролі команди та польських криптологів."},{"imdb_id":"tt3390572","title":"Haider","title_uk":"Хайдер","year":2014,"rating":8,"votes":61609,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, урду","theme":"Політика та історія","who_what":"Кашмірський конфлікт 1995 року: зникнення людей, режим AFSPA і проурядові загони «іхван».","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Вішал Бгардвадж переносить «Гамлета» в Кашмір 1995 року: облави, катівні, тисячі зниклих безвісти й «напівудови», що роками шукають чоловіків. Студент Хайдер, його мати Ґазала й дядько Хуррам вигадані; сценарій написано разом із журналістом Башаратом Піром за його документальною книжкою. Головні ролі — Шахід Капур і Табу. Реальні репресії, вигадана родинна драма."},{"imdb_id":"tt1663202","title":"The Revenant","title_uk":"Легенда Г'ю Ґласса","year":2015,"rating":8,"votes":958814,"genres":["Action","Drama","Western"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Траппер Г'ю Ґласс, якого 1823 року розтерзав ведмідь і покинули товариші, вижив і подолав сотні миль заради помсти.","basis":"натхненний реальними подіями","note":"Лінія помсти за вбитого сина вигадана — у реального Г'ю Ґласса не було сина-індіанця, і він, за джерелами, зрештою пробачив тих, хто його покинув.","thriller_flag":false,"decade":"2010-ті","desc":"Серпень 1823-го, верхів'я Міссурі: траппера Г'ю Ґласса шматує ведмедиця, супутники кидають його непохованим, а він повзе й іде сотні кілометрів до форту. Алехандро Ґ. Іньярріту знімав хронологічно, на натурі й лише при денному світлі — камера Емманюеля Любескі майже не відпускає обличчя. Три «Оскари», зокрема перший для Леонардо ДіКапріо. Від справжньої історії лишився кістяк: у Ґласса не було сина-метиса, а кривдника він, знайшовши, не вбив."},{"imdb_id":"tt3449292","title":"Manjhi: The Mountain Man","title_uk":"Манджі: Людина-гора","year":2015,"rating":8,"votes":21415,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Дашратх Манджі з Біхару 22 роки самотужки прорубував прохід у скелі після загибелі дружини.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Дашратх Манджі з села Ґехлаур у Біхарі втратив дружину тому, що через скелястий кряж дорога до лікарні тягнулася десятки кілометрів в обхід. Із 1960 року він двадцять два роки довбав у скелі прохід молотком і зубилом — і зрештою скоротив шлях до кількох кілометрів. Кетан Мехта будує фільм на цій виснажливій повторюваності й на кастовій зневазі довкола; Наваззуддін Сіддікі грає Манджі впертим і трохи схибленим, Радгіка Апте — його дружину Фаґунію."},{"imdb_id":"tt4888834","title":"Ennu Ninte Moideen","title_uk":"Назавжди твій, Мойдін","year":2015,"rating":8,"votes":7680,"genres":["Biography","Drama","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Соціальна драма","who_what":"Правдива історія кохання Мойдіна й Канчанамали, розділених релігією у Кералі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Б. П. Мойдін і Канчанамала виросли в містечку Муккам у Кералі — він із мусульманської родини, вона з індуїстської, і рідні заборонили їм навіть бачитися. Роками вони листувалися через посередників, користуючись власною вигаданою абеткою, і прожили в цій розлуці більшу частину життя. Р. С. Вімал готував фільм майже десять років; Прітхвірадж Сукумаран і Парваті Тіруотху грають пару, яку глядач майже ніколи не бачить в одному кадрі."},{"imdb_id":"tt3741834","title":"Lion","title_uk":"Лев","year":2016,"rating":8,"votes":268480,"genres":["Biography","Drama"],"country":"Австралія / Велика Британія / США","country_main":"Австралія","region":"Австралія і Океанія","language":"англ., гінді, бенгальська","theme":"Соціальна драма","who_what":"Індієць Сару Брайерлі, який п'ятирічним загубився в потязі, виріс в Австралії й через 25 років знайшов рідне село за супутниковими картами.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1986 рік: п'ятирічний Саро засинає в порожньому вагоні на станції під Кхандвою й прокидається за півтори тисячі кілометрів у Калькутті, де не знає ні мови, ні назви свого села. Ґарт Девіс віддає майже всю першу годину дитині — Санні Павар грає без жодної англійської репліки — і лише потім переходить до дорослого Саро (Дев Патель), який роками водить курсором по супутникових знімках. Ніколь Кідман грає прийомну матір, яка свідомо брала чужу дитину, а не заміну власній. Шість номінацій на «Оскар», жодної статуетки."},{"imdb_id":"tt4169250","title":"M.S. Dhoni: The Untold Story","title_uk":"М. С. Дхоні: Нерозказана історія","year":2016,"rating":8,"votes":76996,"genres":["Biography","Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Шлях Махендри Сінгха Дхоні від контролера на залізниці до капітана збірної Індії з крикету.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Нірадж Пандей веде Магендру Сінґха Дгоні від дитинства в Ранчі й роботи квитковим контролером на станції Харагпур до капітанства і фіналу Кубка світу 2011 року. Сушант Сінгх Раджпут довго вчився повторювати техніку Дгоні, зокрема його «гелікоптерний» удар, а у фінальні сцени вмонтовані справжні телетрансляції. Фільм робився за участі самого гравця, тож суперечливі епізоди кар'єри обходить обережно — це радше авторизований портрет, ніж розслідування."},{"imdb_id":"tt6315524","title":"Take Off","title_uk":"Зліт","year":2017,"rating":8,"votes":8242,"genres":["Action","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Катастрофа і виживання","who_what":"Порятунок індійських медсестер, захоплених ІДІЛ у Тікриті 2014 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Коли влітку 2014-го ІДІЛ узяв Тікріт, у місцевому шпиталі опинилися заблокованими десятки індійських медсестер із Керали; вивозили їх через переговори за участі дипломатів. Магеш Нараянан у режисерському дебюті починає не з війни: перша година — про розлучення, борги й те, чому жінки взагалі їдуть працювати в Ірак. Парваті Тіруватху зібрала за головну роль кілька нагород, Фахад Фаасіл грає посадовця в Багдаді. Приватні лінії й імена героїнь вигадані, сама операція — ні."},{"imdb_id":"tt8108268","title":"The Tashkent Files","title_uk":"Ташкентські файли","year":2019,"rating":8,"votes":39480,"genres":["Drama","Mystery","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Розслідування обставин смерті прем'єр-міністра Індії Лала Бахадура Шастрі в Ташкенті 1966 року.","basis":"реальна історія","note":"Розслідування, комісія та всі персонажі вигадані; фільм просуває непідтверджені конспірологічні версії смерті Лала Бахадура Шастрі й був розкритикований як політичне замовлення.","thriller_flag":true,"decade":"2010-ті","desc":"11 січня 1966 року, за кілька годин після підписання Ташкентської декларації з Пакистаном, помер прем'єр-міністр Індії Лал Бахадур Шастрі; розтину не проводили, і це живить теорії донині. Вівек Аґніхотрі будує фільм як засідання комісії: журналістка (Швета Басу Прасад) і десяток експертів (Мітхун Чакраборті, Насіруддін Шах, Панкадж Тріпатхі) годинами сперечаються майже без дії. Відповіді картина не дає. Критика розгромила її за конспірологію та джерела рівня пошукового запиту, хоча дві національні кінопремії стрічка отримала."},{"imdb_id":"tt8633462","title":"Quo Vadis, Aida?","title_uk":"Куди йдеш, Аїдо?","year":2020,"rating":8,"votes":42273,"genres":["Drama","History","War"],"country":"Боснія і Герцеговина","country_main":"Боснія і Герцеговина","region":"Європа","language":"боснійська","theme":"Війна","who_what":"Перекладачка ООН у Сребрениці в липні 1995 року намагається врятувати свою родину напередодні геноциду.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Липень 1995-го, Сребрениця: після входу військ Ратка Младича до міста тисячі людей збігаються на базу нідерландського батальйону ООН у Поточарі, а перекладачка Аїда Селманаґіч намагається внести чоловіка й двох синів до списків персоналу, щоб їх не видали. Ясміла Жбанич веде камеру за нею коридорами й натовпом майже без пауз: героїня знає більше за всіх і не може зарадити нічому. Аїда — збірний персонаж, решта хронології відтворена за матеріалами трибуналу. Європейська кінопремія за найкращий фільм і номінація на «Оскар»."},{"imdb_id":"tt11581174","title":"Karnan","title_uk":"Карнан","year":2021,"rating":8,"votes":25307,"genres":["Action","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Соціальна драма","who_what":"Молодий чоловік очолює опір касовому гнобленню в тамільському селі — за мотивами кастового погрому в Кодіянкуламі 1995 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Марі Селварай відштовхується від погрому 1995 року в тамільському селі Кодіянкулам, де поліція розгромила будинки далітської громади. У фільмі село Подіянкулам не має навіть автобусної зупинки, і молодий Карнан (Данущ) переходить від дрібного бунту до відкритого спротиву. Оповідь насичена міфологічними образами — безголова богиня, спутаний осел, орел — і музикою Сантоша Нараянана. Це радше алегорія кастового насильства, ніж реконструкція конкретних подій."},{"imdb_id":"tt10919240","title":"Malik","title_uk":"Малік","year":2021,"rating":8,"votes":15334,"genres":["Action","Adventure","Biography","Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Політика та історія","who_what":"Піднесення й падіння громадського лідера приморської громади Кералі — за мотивами розстрілу в Бімапаллі 2009 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Махеш Нараянан відштовхується від розстрілу поліцією протестувальників у Бімапаллі (Керала) 2009 року, але вигадує приморське містечко Рамадапаллі та його неформального лідера Алі Іккаку. Фільм починається з арешту п'ятдесятивосьмирічного героя і повертається назад — до контрабанди, будівництва мечеті й політиків, які роками стравлювали мусульманську та християнську громади. Фахад Фаасіл грає одну людину протягом сорока років; знімали у зворотному порядку, від старості до юності. Відкриває стрічку безперервний план на понад десять хвилин."},{"imdb_id":"tt24485052","title":"Sirf Ek Bandaa Kaafi Hai","title_uk":"Досить одного чоловіка","year":2023,"rating":8,"votes":31325,"genres":["Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Суд і журналістика","who_what":"Провінційний адвокат П. Ч. Соланкі веде справу неповнолітньої проти впливового гуру Асарама Бапу.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"2013 року шістнадцятирічна вихованка ашраму звинуватила проповідника Асарама Бапу у зґвалтуванні; справу в Джодхпурі вів адвокат П. Ч. Соланкі — одинак проти зірок індійської адвокатури та мільйонів послідовників гуру. Апурв Сінґх Каркі зняв майже камерний судовий фільм: засідання, свідки, тиск, напади на учасників процесу. Манодж Баджпаї грає Соланкі тихим і впертим. Асарама засудили до довічного 2018 року; стрічка вийшла одразу на ZEE5."},{"imdb_id":"tt24226474","title":"Jigarthanda Double X","title_uk":"«Джиґартханда Дабл Ікс»","year":2023,"rating":8,"votes":12084,"genres":["Action","Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Музика та мистецтво","who_what":"Тамілнаду середини 1970-х: надзвичайний стан Індіри Ґанді, поліцейські «зіткнення» й витіснення лісових племен.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Картік Субарадж змішує вестерн із сатирою: поліція під прикриттям кіноекспедиції відправляє дрібного шахрая знімати «фільм» про бандита Цезаря, щоб підібратися й убити його. Цезар мріє стати актором, як Клінт Іствуд, а зйомки перетворюються на хроніку виселення племені з лісу. Раґхава Лоуренс і С. Дж. Сур'я в головних ролях. Надзвичайний стан, позасудові вбивства й вирубка лісів реальні, персонажі — ні."},{"imdb_id":"tt27540542","title":"Lucky Baskhar","title_uk":"«Щасливчик Баскхар»","year":2024,"rating":8,"votes":43396,"genres":["Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"телугу","theme":"Кримінал","who_what":"Бомбей кінця 1980-х — початку 1990-х і банківські махінації доби фондової афери 1992 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Венкі Атлурі відтворює побут середнього класу перед лібералізацією економіки: черги у відділеннях, паперові депозити, дефіцит і саму схему з підробленими банківськими розписками, на якій трималася афера 1992-го. Касир Баскхар, якого роками обходять підвищенням, знаходить дірку в системі й починає прокручувати чужі гроші. Дульквер Салман у головній ролі. Механіка афери задокументована, Баскхар і його банк вигадані."},{"imdb_id":"tt0106469","title":"Blood In Blood Out","title_uk":"Кров за кров","year":1993,"rating":7.9,"votes":38234,"genres":["Biography","Crime","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Долі трьох родичів-чикано зі Східного Лос-Анджелеса, розведених вуличною війною й тюрмою.","basis":"натхненний реальними подіями","note":"Тюремне братство «Ла Онда» — вигаданий відповідник Мексиканської мафії; персонажі збірні.","thriller_flag":true,"decade":"1990-ті","desc":"Сюжет виріс із біографій трьох двоюрідних братів-чикано зі Східного Лос-Анджелеса й тюремного досвіду поета Джиммі Сантьяго Баки, одного з авторів історії та сценариста. Тейлор Гекфорд простежує, як бійка 1972 року розводить родичів по різні боки: Сан-Квентін, героїн і поліційний значок. Знімали частково в самому Сан-Квентіні, залучивши до масовки ув’язнених."},{"imdb_id":"tt0181875","title":"Almost Famous","title_uk":"Майже знаменитий","year":2000,"rating":7.9,"votes":317034,"genres":["Adventure","Comedy","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Напівавтобіографічна історія Кемерона Кроу, який підлітком їздив у тури з рок-гуртами як journalist Rolling Stone.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Кемерон Кроу справді у п'ятнадцять писав для Rolling Stone і їздив у тури з рок-гуртами — з цього досвіду виріс образ Вільяма Міллера й вигаданого гурту Stillwater. Дія охоплює одне турне 1973 року, побачене очима підлітка, якому редакція наказала не заводити дружби з музикантами. Кроу отримав «Оскар» за сценарій; прототипом Пенні Лейн у виконанні Кейт Гадсон стала Пенні Лейн Трамбулл, реальна учасниця тодішньої фанатської сцени."},{"imdb_id":"tt0283509","title":"No Man's Land","title_uk":"Нічия земля","year":2001,"rating":7.9,"votes":50862,"genres":["Action","Comedy","Drama","History","War"],"country":"Боснія і Герцеговина / Франція / Словенія","country_main":"Боснія і Герцеговина","region":"Європа","language":"боснійська / сербська","theme":"Війна","who_what":"Боснійська війна 1993 року і безпорадність місії ООН.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Боснієць і серб застрягають в одному окопі між лініями, а під тілом третього солдата лежить активована стрибуча міна. Ситуація вигадана, натомість блакитні шоломи без мандата на втручання і телекамери, що женуться за сюжетом, точно передають механіку конфлікту. Дебют Даніса Тановича здобув «Оскар» за іншомовний фільм і приз Канн за сценарій."},{"imdb_id":"tt0296574","title":"Company","title_uk":"Компанія","year":2002,"rating":7.9,"votes":17341,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Заснований на історії мумбайського злочинного синдикату D-Company Давуда Ібрагіма.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Рам Ґопал Варма переносить на екран розкол у мумбайському синдикаті D-Company — конфлікт між босом Маліком і його висуванцем Чанду, за якими прочитуються Давуд Ібрагім і Чхота Раджан. Дія тягнеться від вуличних сутичок у Мумбаї до Гонконгу й Кенії, куди верхівка тікає від поліції. Аджай Девґн і Вівек Оберой грають майже без пафосу, а нахилена камера й рваний монтаж зробили фільм зразком для індійського кримінального кіно 2000-х. Імена змінено, тож прототипів автори прямо не називали."},{"imdb_id":"tt0329393","title":"Mr. and Mrs. Iyer","title_uk":"Містер і місіс Айєр","year":2002,"rating":7.9,"votes":5078,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"англ. / гінді","theme":"Соціальна драма","who_what":"Індуїстсько-мусульманські погроми в Індії початку 2000-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Автобус із випадковими пасажирами зупиняють на гірській дорозі, і брахманка Міна називає свого мусульманського попутника чоловіком, щоб урятувати його від натовпу. Герої вигадані, але сценарій Апарни Сен спирається на хвилю погромів, зокрема гуджаратські події 2002 року. Конкона Сен Шарма отримала Національну премію за головну роль."},{"imdb_id":"tt0411469","title":"Hazaaron Khwaishein Aisi","title_uk":"Тисячі таких бажань","year":2003,"rating":7.9,"votes":5643,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Індія 1969—1977 років: рух наксалітів і надзвичайний стан Індіри Ґанді.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Троє друзів із делійського університету розходяться: один іде в підпілля до наксалітів, другий робить кар'єру в міністерстві, третя намагається допомагати селянам. Герої вигадані, натомість поліційні операції в Біхарі, примусова стерилізація і цензура часів надзвичайного стану задокументовані. Судхір Мішра знімав фільм роками, і той поступово став культовим."},{"imdb_id":"tt0369702","title":"The Sea Inside (Mar adentro)","title_uk":"Море всередині","year":2004,"rating":7.9,"votes":89326,"genres":["Biography","Drama"],"country":"Іспанія/Франція/Італія","country_main":"Іспанія","region":"Європа","language":"ісп.","theme":"Медицина та виживання","who_what":"Іспанець Рамон Сампедро, паралізований на 30 років, який судився за право на евтаназію.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Галісієць Рамон Сампедро зламав шию, пірнувши 1968 року, і майже тридцять років домагався через суди права піти з життя; він помер 1998-го. Алехандро Аменабар звужує все до кімнати з вікном на море й до розмов Рамона з жінками навколо нього — виходить не мітинг, а суперечка, де кожна сторона має аргумент. Хав'єр Бардем грав у гримі, що старив його на чверть століття; «Оскар» за іншомовний фільм і чотирнадцять «Гойя»."},{"imdb_id":"tt1032846","title":"4 Months, 3 Weeks and 2 Days","title_uk":"4 місяці, 3 тижні і 2 дні","year":2007,"rating":7.9,"votes":66469,"genres":["Drama"],"country":"Румунія","country_main":"Румунія","region":"Європа","language":"рум.","theme":"Політика та історія","who_what":"Румунія 1987 року за Чаушеску: заборона абортів за декретом 770.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Крістіан Мунджу відтворює останні роки диктатури: гуртожитки, дефіцит, чорний ринок, декрет 770, що криміналізував аборти й контрацепцію. Студентки Отілія й Ґабіца та підпільний «лікар» Бебе вигадані, історія одного дня в готелі — теж. «Золота пальмова гілка» 2007 року, ключовий фільм румунської нової хвилі. Реальні закон і побут, вигадана конкретна доля."},{"imdb_id":"tt1277737","title":"The Stoning of Soraya M.","title_uk":"Побиття камінням Сорайї М.","year":2008,"rating":7.9,"votes":23330,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"перс., англ.","theme":"Соціальна драма","who_what":"Страта іранки Сорайї Манучехрі 1986 року за неправдивим звинуваченням у зраді.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Село Купайє, 1986 рік: чоловік Сорайї Манучехрі, щоб одружитися вдруге й не платити утримання, зводить на неї наклеп про перелюб, і сільський суд ухвалює побиття камінням. Сайрус Ноурастех екранізував книжку французько-іранського журналіста Фрейдуна Сахебджама, який записав розповідь тітки страченої. Саме від цієї жінки, Захри у виконанні Шохре Аґдашлу, ведеться оповідь — вона зупиняє на дорозі чужинця з диктофоном. Сцену страти показано майже в реальному часі, і витримати її важко."},{"imdb_id":"tt0790636","title":"Dallas Buyers Club","title_uk":"Далласький клуб покупців","year":2013,"rating":7.9,"votes":551758,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Медицина та виживання","who_what":"Техасець Рон Вудруф, хворий на СНІД, у 1985 році організував нелегальне постачання незатверджених ліків для інших пацієнтів.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1985 рік, Даллас: електрику й завсіднику родео Рону Вудруфу діагностують СНІД і дають 30 днів життя. Він знаходить незатверджені FDA препарати в Мексиці та Японії й починає постачати їх іншим хворим через «клуб покупців» із членськими внесками замість продажу. Метью Макконагі й Джаред Лето різко схудли для ролей і отримали «Оскари». Реальний Вудруф, за спогадами близьких, був бісексуалом і не таким гомофобом, як на екрані, а трансгендерна Рейон — вигаданий збірний персонаж."},{"imdb_id":"tt4387040","title":"Airlift","title_uk":"Евакуація","year":2016,"rating":7.9,"votes":61777,"genres":["Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Катастрофа і виживання","who_what":"Евакуація понад 170 тисяч індійців із Кувейту після іракського вторгнення 1990 року, організована бізнесменом Ранджитом Катьялом (прототипи — Матхунні Метьюз і Веду Наяр).","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"2 серпня 1990 року Ірак входить у Кувейт, і 170 тисяч індійців опиняються без держави, яка їх вивезе. Раджа Крішна Менон стягує реальних організаторів — Матхунні Метьюза й Веду Наяра — в одного вигаданого бізнесмена Ранджита Катьяла, якого грає Акшай Кумар. Це найбільша цивільна повітряна евакуація в історії: 488 рейсів Air India через Амман за 59 днів. Індійських дипломатів фільм показує пасивнішими, ніж вони були, — на це нарікали учасники подій."},{"imdb_id":"tt5458088","title":"Kammatti Paadam","title_uk":"«Камматті Паадам»","year":2016,"rating":7.9,"votes":5522,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Соціальна драма","who_what":"Витіснення далітських громад Кочі забудовниками від 1970-х до 2010-х років.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Раджив Раві показує чотири десятиліття перетворення болотистого поселення Камматті Паадам на елітні квартали Кочі. Ганеш і його друзі з громади пулая стають найманими бійцями земельних мафій, які скуповують ділянки в їхніх же родин. Дульквер Салман і Вінаяакан у головних ролях; фільм вважають одним із найкращих малаяламських за десятиліття. Механіка земельних оборудок і зникнення поселень задокументовані, герої вигадані."},{"imdb_id":"tt6878038","title":"A Taxi Driver","title_uk":"Таксист","year":2017,"rating":7.9,"votes":38975,"genres":["Action","Drama","History"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"корейська, англ.","theme":"Політика та історія","who_what":"Сеульський таксист везе німецького журналіста Юрґена Гінцпетера в Кванджу 1980 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Німецький журналіст Юрґен Гінцпетер у травні 1980-го пробрався до заблокованого армією Кванджу і вивіз плівки, які вперше показали світові, як придушували повстання. Чан Хун розповідає це з боку сеульського таксиста (Сон Ган Хо), який погодився на рейс заради грошей і не розумів, куди їде. Перша половина майже комедійна, друга — ні. Реального водія Гінцпетер шукав усе життя і не знайшов; ідентифікували його вже після виходу фільму, а фінальна гонитва — вигадка сценаристів."},{"imdb_id":"tt6293516","title":"Bingo: The King of the Mornings","title_uk":"Бінго: Король ранків","year":2017,"rating":7.9,"votes":7105,"genres":["Biography","Comedy","Drama"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"португ.","theme":"Музика та мистецтво","who_what":"Актор Арліндо Баррето, який у 1980-х став бразильським клоуном Бозо й не мав права розкривати своє обличчя.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"На початку 1980-х безвісний бразильський актор дістає роль клоуна в ранковому дитячому шоу — і стає найпопулярнішою людиною країни, якої без гриму ніхто не впізнає, бо контракт забороняє показувати обличчя. Прототип — Арліндо Баррето, перший бразильський Бозо, але через права героя перейменували на Бінго. Данієл Резенде, монтажер «Міста Бога», знімає це як карнавал, що поступово стає нічним кошмаром: кокаїн, розлучення, син, який бачить батька лише в телевізорі. Бразильська заявка на «Оскар»."},{"imdb_id":"tt1727824","title":"Bohemian Rhapsody","title_uk":"Богемна рапсодія","year":2018,"rating":7.9,"votes":653040,"genres":["Biography","Drama","Music"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Музика та мистецтво","who_what":"Фредді Мерк'юрі й гурт Queen від заснування до виступу на Live Aid 1985 року.","basis":"реальна історія","note":"Хронологію переписано: Мерк'юрі дізнався про ВІЛ не перед Live Aid, гурт не розпадався, а низку конфліктів вигадано; учасники Queen були співпродюсерами фільму.","thriller_flag":false,"decade":"2010-ті","desc":"Від 1970-го, коли Фаррух Балсара приєднується до гурту Smile, до двадцяти хвилин на сцені Вемблі 13 липня 1985 року — виступ на Live Aid відтворено майже покадрово. Рамі Малек отримав «Оскар» за головну роль, усього фільм узяв чотири статуетки. Брайана Сінґера звільнили за кілька тижнів до кінця зйомок, доробляв Декстер Флетчер, але в титрах лишився Сінґер. Хронологію зсунуто свідомо: свій діагноз Мерк'юрі дізнався 1987-го, а розпаду гурту перед Live Aid не було взагалі."},{"imdb_id":"tt5116302","title":"Togo","title_uk":"Того","year":2019,"rating":7.9,"votes":63004,"genres":["Adventure","Biography","Drama","Family","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Каюр Леонард Сеппала і його пес Того, які подолали найдовший відрізок «сироваткової естафети» до Нома 1925 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Січень 1925-го, Аляска: у Номі спалах дифтерії, сироватку везуть естафетою собачих упряжок, і найдовший та найнебезпечніший відрізок — понад 400 кілометрів, зокрема кригу затоки Нортон — долає команда Леонарда Сеппали з дванадцятирічним ватажком Того. Еріксон Кор чергує дорогу з флешбеками про те, як Сеппала спершу хотів позбутися хирлявого цуценяти. Віллем Дефо грає майже без партнерів-людей. Фільм принагідно виправляє давню несправедливість: пам'ятник у Нью-Йорку дістався Балто, який пробіг останній, найкоротший етап."},{"imdb_id":"tt2395469","title":"Gully Boy","title_uk":"Хлопець із нетрів","year":2019,"rating":7.9,"votes":47838,"genres":["Drama","Music","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Музика та мистецтво","who_what":"Репер із мумбайських нетрів; прообрази — вуличні виконавці Divine і Naezy.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мурад живе в мумбайському Дхараві, возить чужу машину і пише реп у зошит — доки не бачить, що це можна виконувати вголос. Зоя Ахтар зібрала героя з біографій вуличних реперів Divine і Naezy, які писали для фільму тексти; Ранвір Сінгх і Алія Бгатт грають майже без боллівудського глянцю. Пісня Apna Time Aayega стала гімном індійської хіп-хоп-сцени. Індія висувала стрічку на «Оскар» 2020 року."},{"imdb_id":"tt7485048","title":"Super 30","title_uk":"Супер 30","year":2019,"rating":7.9,"votes":42748,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Математик Ананд Кумар із Патни, який безкоштовно готує 30 дітей із бідних родин до вступу в IIT.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ананд Кумар із Патни не поїхав вчитися до Кембриджа через брак грошей і згодом почав щороку безкоштовно готувати тридцятьох дітей із найбідніших родин до вступних іспитів в IIT, оселяючи їх у себе вдома. Вікас Бахл будує сюжет на протистоянні Кумара з власником прибуткових комерційних курсів. Грітік Рошан у головній ролі викликав суперечки через затемнений грим, а індійські журналісти паралельно ставили під сумнів офіційну статистику успіхів «Super 30»."},{"imdb_id":"tt2584384","title":"Jojo Rabbit","title_uk":"«Кролик Джоджо»","year":2019,"rating":7.9,"votes":493710,"genres":["Comedy","Drama","War"],"country":"Нова Зеландія / США","country_main":"Нова Зеландія","region":"Австралія і Океанія","language":"англ. / нім.","theme":"Голокост","who_what":"Нацистська Німеччина останнього року війни: Гітлер'юґенд, тотальна мобілізація, полювання на євреїв.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Тайка Вайтіті екранізує роман Крістін Лоненс про хлопчика з провінційного німецького містечка 1944–1945 років. Десятирічний Йоганнес фанатіє від фюрера, вигадує собі уявного Гітлера й знаходить у стіні власного будинку єврейку Ельзу. Скарлетт Йоганссон номінована на «Оскар», сценарій отримав статуетку. Табори, вербування дітей у фольксштурм і страти за переховування реальні; хлопчик, його мати й Ельза — ні."},{"imdb_id":"tt19653180","title":"Leila's Brothers","title_uk":"«Брати Лейли»","year":2022,"rating":7.9,"votes":19438,"genres":["Drama"],"country":"Іран","country_main":"Іран","region":"Близький Схід і Африка","language":"перська","theme":"Соціальна драма","who_what":"Економічний обвал в Ірані після повернення американських санкцій 2018 року: гіперінфляція й девальвація ріала.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Саїд Рустаї показує родину з чотирма безробітними братами на тлі новин про курс долара й закриття заводів; сюжет прямо прив'язаний до подій 2018–2019 років. Лейла намагається змусити братів вкластися в крамницю, поки батько витрачає родинне золото на купівлю титулу старійшини клану. Приз ФІПРЕССІ в Каннах; в Ірані фільм заборонили, а режисера засудили. Санкції та інфляція реальні, родина вигадана."},{"imdb_id":"tt14849194","title":"The Holdovers","title_uk":"«Ті, що залишились»","year":2023,"rating":7.9,"votes":273323,"genres":["Comedy","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Різдво 1970 року в закритій школі Нової Англії, війна у В'єтнамі та студентські відстрочки від призову.","basis":"реальне тло, вигадані герої","note":"історична доба радше тло характерної драми, ніж її предмет","thriller_flag":false,"decade":"2020-ті","desc":"Александр Пейн знімає фільм так, ніби той зроблений у 1970-х, — від логотипів студій до зерна плівки. Викладач античності Пол Ганем застрягає в порожньому кампусі з учнем Ангусом і кухаркою Мері, чий син загинув у В'єтнамі, бо в родини не було грошей на коледж. Да'Він Джой Рендольф отримала «Оскар» за другорядну роль. Система відстрочок і класова нерівність призову реальні; усі троє вигадані."},{"imdb_id":"tt10869778","title":"Maidaan","title_uk":"Майдан","year":2024,"rating":7.9,"votes":23640,"genres":["Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Тренер Саїд Абдул Рахім будує «золоту еру» індійського футболу між 1952 і 1962 роками.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Саїд Абдул Рахім тренував збірну Індії з футболу з 1950 року й привів її до четвертого місця на Олімпіаді 1956-го в Мельбурні та золота Азійських ігор 1962 року в Джакарті — час, який досі називають золотою ерою. Аміт Шарма знімає це і як спортивну драму, і як історію апаратної війни: чиновники федерації, регіональні квоти, туберкульоз тренера. Аджай Девґан грає Рахіма стримано, а матчі зняті довгими планами з реальними футболістами."},{"imdb_id":"tt3562110","title":"Kesari Chapter 2","title_uk":"Кесарі. Розділ 2","year":2025,"rating":7.9,"votes":16186,"genres":["Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Суд і журналістика","who_what":"Юрист Ч. Санкаран Наїр судиться з Британською імперією через різанину в Джалліанвала-Багх 1919 року.","basis":"реальна історія","note":"Реальний процес Ч. Санкарана Наїра відбувався в Лондоні 1924 року і був програний ним; судова драма у фільмі, як і більшість персонажів, вигадана — критики вказували на грубу підміну фактів.","thriller_flag":false,"decade":"2020-ті","desc":"Після розстрілу в Джалліанвала-Багх 13 квітня 1919 року юрист Ч. Санкаран Наїр вийшов із виконавчої ради віцекороля і взявся доводити, що це була не паніка гарнізону, а спланована кара. Каран Сінгх Тьягі екранізував книжку правнука Наїра «Справа, що сколихнула імперію», перетворивши все на судову драму: Акшай Кумар проти Р. Мадгавана в ролі обвинувача корони. Реальний процес відбувся 1924 року в Лондоні за позовом Майкла О'Дваєра, і Наїр його програв — фільм поводиться з цим доволі вільно."},{"imdb_id":"tt26733325","title":"Homebound","title_uk":"Дорога додому","year":2025,"rating":7.9,"votes":14361,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Двоє друзів із північноіндійського села мріють про роботу в поліції — за статтею NYT про мігрантів під час локдауну.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Двоє друзів дитинства з північноіндійського села — Шоаїб із мусульманської родини й Чандан із далітської — готуються до іспиту в поліцію, бо форма для них єдиний спосіб перестати бути людьми другого сорту. Нірадж Ґхайван виходить із репортажу Башарата Піра в The New York Times про робітників-мігрантів, які під час локдауну 2020 року рушили додому пішки. Іщан Кхаттар і Вішал Джетва грають дружбу, яку роз'їдає не сварка, а нерівність шансів. Прем'єра в каннській програмі «Особливий погляд»; виконавчий продюсер — Мартін Скорсезе."},{"imdb_id":"tt0099077","title":"Awakenings","title_uk":"Пробудження","year":1990,"rating":7.8,"votes":178559,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Медицина та виживання","who_what":"Експеримент невролога Олівера Сакса, який 1969 року ненадовго «розбудив» пацієнтів із летаргічним енцефалітом.","basis":"реальна історія","note":"Імена лікаря й хворих у сценарії змінено, а перебіг лікування спрощено й ущільнено.","thriller_flag":false,"decade":"1990-ті","desc":"Улітку 1969 року невролог Олівер Сакс дав експериментальний препарат L-DOPA пацієнтам нью-йоркської лікарні Бет-Ейбрахам, які десятиліттями пробули в кататонії після епідемії летаргічного енцефаліту. Дехто з них ожив на кілька тижнів — і знову згас. Пенні Маршалл екранізувала мемуари Сакса 1973 року: Робін Вільямс грає замкненого лікаря, Роберт Де Ніро — пацієнта Леонарда, за що дістав номінацію на «Оскар»."},{"imdb_id":"tt0105888","title":"And Life Goes On","title_uk":"І життя триває","year":1992,"rating":7.8,"votes":9365,"genres":["Adventure","Drama"],"country":"Іран","country_main":"Іран","region":"Близький Схід і Африка","language":"перс.","theme":"Катастрофа і виживання","who_what":"Поїздка Аббаса Кіаростамі в села, зруйновані землетрусом 1990 року, на пошуки своїх юних акторів.","basis":"реальна історія","note":"Землетрус і люди справжні, але саму поїздку відтворено постановчо: режисера та його сина грають актори.","thriller_flag":false,"decade":"1990-ті","desc":"21 червня 1990 року землетрус у Манджілі й Рудбарі забрав близько сорока тисяч життів на півночі Ірану. Аббас Кіаростамі поїхав у зруйновані села шукати хлопчиків, які знялися в його фільмі «Де дім друга?». Власну подорож він переграв перед камерою, доручивши роль режисера акторові Фархаду Керадманду. Вийшла напрочуд спокійна стрічка про людей, які серед руїн лагодять антену, щоб подивитися чемпіонат світу з футболу."},{"imdb_id":"tt0108358","title":"Tombstone","title_uk":"Тумстоун","year":1993,"rating":7.8,"votes":194926,"genres":["Action","Biography","Drama","History","Western"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Перестрілка біля загону O.K. Corral 1881 року та кривава «вендета Вайатта Ерпа».","basis":"реальна історія","note":"Хронологію подій стиснуто, а низку деталей — як-от червоні пояси «ковбоїв» — додумано.","thriller_flag":false,"decade":"1990-ті","desc":"26 жовтня 1881 року в аризонському Тумстоуні брати Ерпи й Док Голлідей за півхвилини розстріляли ковбоїв Клентонів і Маклорі біля загону O.K. Corral, після чого Вайатт Ерп повів вендету проти їхніх спільників. Джордж Косматос зняв класичний вестерн, у якому Вел Кілмер зіграв сухотного картяра Голлідея — роль, що стала його візитівкою. Курт Рассел виконує роль Вайатта Ерпа."},{"imdb_id":"tt0106489","title":"A Bronx Tale","title_uk":"Бронкська історія","year":1993,"rating":7.8,"votes":189531,"genres":["Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Дитинство Чазза Пальмінтері в Бронксі 1960-х між батьком-водієм і місцевим мафіозі.","basis":"натхненний реальними подіями","note":"Імена та частину подій змінено; автобіографічні тут середовище й ключовий епізод із убивством.","thriller_flag":false,"decade":"1990-ті","desc":"Чазз Пальмінтері виріс на Белмонт-авеню в Бронксі й дев’ятирічним побачив із вікна вбивство, після якого відмовився впізнати стрільця. З цього епізоду він зробив моновиставу, потім сценарій, а в фільмі сам зіграв мафіозі Сонні. Це режисерський дебют Роберта Де Ніро, який узяв собі роль батька — чесного водія автобуса."},{"imdb_id":"tt0107943","title":"The Remains of the Day","title_uk":"Залишок дня","year":1993,"rating":7.8,"votes":94046,"genres":["Drama","Romance"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Британська політика умиротворення Гітлера у 1930-х роках.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Дворецький Стівенс бездоганно обслуговує конференції, на яких його господар лорд Дарлінгтон зближується з нацистською дипломатією, і не дозволяє собі жодного власного судження. Дарлінгтон-Голл і всі персонажі вигадані Кадзуо Ішіґуро, але приватна дипломатія британських аристократів 1930-х цілком реальна. Ентоні Гопкінс і Емма Томпсон; вісім номінацій на «Оскар»."},{"imdb_id":"tt0109707","title":"Ed Wood","title_uk":"Ед Вуд","year":1994,"rating":7.8,"votes":190939,"genres":["Biography","Comedy","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Едвард Д. Вуд-молодший, режисер 1950-х, якого пізніше назвали найгіршим постановником Голлівуду.","basis":"реальна історія","note":"Вуд ніколи не зустрічався з Орсоном Веллсом; цю ключову сцену придумали сценаристи.","thriller_flag":false,"decade":"1990-ті","desc":"Фільм узято з усної біографії Рудольфа Ґрея «Nightmare of Ecstasy» і охоплює 1952–1959 роки: зйомки «Glen or Glenda», «Bride of the Monster» і «Plan 9 from Outer Space», а також дружбу Вуда з немічним Белою Луґоші. Тім Бертон зняв усе чорно-білим, Джонні Депп грає Вуда, а Мартін Ландау отримав «Оскар» за Луґоші; друга статуетка — за грим. Сцена зустрічі Вуда з Орсоном Веллсом вигадана."},{"imdb_id":"tt0111579","title":"Burnt by the Sun","title_uk":"Втомлені сонцем","year":1994,"rating":7.8,"votes":17415,"genres":["Drama","War"],"country":"Росія / Франція","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Політика та історія","who_what":"Великий терор 1936 року в СРСР.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Один літній день на дачі: комдив Котов, герой Громадянської війни, приймає гостей, поки по нього вже їде машина НКВС. Котов, Митя і вся родина вигадані, але механіка арештів і культ Сталіна відтворені впізнавано. «Оскар» за іншомовний фільм і Гран-прі Канн; Микита Михалков зіграв головну роль разом із власною донькою Надією."},{"imdb_id":"tt0110877","title":"Il Postino: The Postman","title_uk":"Листоноша","year":1994,"rating":7.8,"votes":41893,"genres":["Biography","Comedy","Drama","Romance"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Музика та мистецтво","who_what":"Вигнання чилійського поета Пабло Неруди в Італію на початку 1950-х.","basis":"реальне тло, вигадані герої","note":"Неруда — реальна особа, але місце дії й усі інші персонажі вигадані.","thriller_flag":false,"decade":"1990-ті","desc":"Неруда справді жив у Італії після переслідувань удома, і фільм відштовхується від цього факту, але листоноша Маріо та його кохання до Беатріче вигадані романом Антоніо Скарметою. Масімо Троїзі грав, відклавши операцію на серці, і помер наступного дня після зйомок. «Оскар» за музику Луїса Бакалова і ще чотири номінації."},{"imdb_id":"tt0110882","title":"Before the Rain","title_uk":"Перед дощем","year":1994,"rating":7.8,"votes":16805,"genres":["Drama","Romance","War"],"country":"Македонія / Велика Британія / Франція","country_main":"Македонія","region":"Інше","language":"макед. / англ.","theme":"Війна","who_what":"Македонія початку 1990-х і етнічна напруга на тлі розпаду Югославії.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Три історії — молодий чернець ховає албанську дівчину, лондонська редакторка обирає між двома чоловіками, фотограф вертається в рідне село — замикаються в коло, де час не має початку. Герої вигадані, але міжетнічні вбивства й передчуття війни списані з реальної Македонії. «Золотий лев» Венеції для дебютанта Мілчо Манчевського."},{"imdb_id":"tt0140352","title":"The Insider","title_uk":"Інсайдер","year":1999,"rating":7.8,"votes":193153,"genres":["Biography","Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Викривач тютюнової індустрії Джеффрі Віганд і скандал навколо його інтерв'ю для програми «60 хвилин» 1995 року.","basis":"реальна історія","note":"Журналісти CBS, зокрема Майк Воллес, публічно заперечували точність свого зображення у фільмі.","thriller_flag":true,"decade":"1990-ті","desc":"1994 року звільнений віцепрезидент Brown & Williamson Джеффрі Віганд розповів продюсерові CBS Лоуеллу Берґману, що компанія свідомо посилювала звикання до нікотину. Під тиском юристів CBS зняла інтерв'ю з ефіру «60 хвилин» 1995 року. Майкл Манн зняв цю історію як напружену драму з Расселом Кроу і Аль Пачіно; фільм отримав сім номінацій на «Оскар»."},{"imdb_id":"tt0132477","title":"October Sky","title_uk":"Жовтневе небо","year":1999,"rating":7.8,"votes":113000,"genres":["Biography","Drama","Family","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Школяр із шахтарського містечка Гомер Гікем, який після запуску супутника 1957 року почав будувати ракети і став інженером NASA.","basis":"реальна історія","note":"Конфлікт із батьком і роль учительки Райлі помітно драматизовані порівняно зі спогадами.","thriller_flag":false,"decade":"1990-ті","desc":"Після запуску радянського супутника в жовтні 1957 року школяр Гомер Гікем із шахтарського Колвуда у Західній Вірджинії з трьома друзями почав майструвати саморобні ракети, виграв національний науковий ярмарок 1960 року і згодом працював інженером NASA. Джо Джонстон екранізував мемуари Гікема «Rocket Boys» із Джейком Джилленголом у головній ролі. Назва фільму — анаграма назви книжки."},{"imdb_id":"tt0210945","title":"Remember the Titans","title_uk":"Згадати титанів","year":2000,"rating":7.8,"votes":252730,"genres":["Biography","Comedy","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Реальна історія тренера Германа Буна і расово інтегрованої шкільної футбольної команди T.C. Williams у Вірджинії 1971 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Восени 1971-го в Александрії (Вірджинія) три школи злили в одну — T.C. Williams, — і футбольну команду очолив чорношкірий тренер Герман Бун, посунувши популярного Білла Йоста в асистенти. Фільм тримається на дуеті Дензела Вашингтона й Вілла Паттона та на літньому таборі, де підлітки поволі вчаться грати разом. Реальна інтеграція в місті минула спокійніше, ніж на екрані, а команда й до того вважалася сильною: сценарій згустив конфлікт заради драми."},{"imdb_id":"tt0300140","title":"Lilya 4-ever","title_uk":"Лілія назавжди","year":2002,"rating":7.8,"votes":56295,"genres":["Crime","Drama"],"country":"Швеція/Данія","country_main":"Швеція","region":"Європа","language":"рос./швед.","theme":"Соціальна драма","who_what":"Натхненний долею литовської дівчини Дангуоле Расалайте, яку продали в сексуальне рабство у Швецію.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Поштовхом для Лукаса Мудіссона стала смерть шістнадцятирічної литовки Дангуоле Расалайте, яку 2000 року вивезли до Швеції і продали в проституцію. Режисер переносить дію в безіменне пострадянське містечко: мати їде до США, Лілю (Оксана Акіньшина) лишають саму, і єдиний її друг — молодший хлопчик Володя. Знято сухо, без жодної спроби пом'якшити, а фінал відомий уже з перших кадрів. У Швеції сперечалися, чи має західний режисер право на такий погляд на «схід»."},{"imdb_id":"tt0325710","title":"The Last Samurai","title_uk":"Останній самурай","year":2003,"rating":7.8,"votes":508628,"genres":["Action","Drama"],"country":"США/Японія/Нова Зеландія","country_main":"США","region":"США","language":"англ./яп.","theme":"Війна","who_what":"Натхненний Сацумським повстанням 1877 року та історією французького офіцера Жуля Брюне.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Сацумське повстання 1877 року, коли самураї на чолі з Сайґо Такаморі виступили проти армійських реформ Мейдзі, дало канву для вигаданого капітана Нейтана Олґрена; серед його прообразів називають французького офіцера Жуля Брюне. Едвард Цвік ставить у центр американця, який переймає кодекс переможених, — саме за це фільм і дорікали як історію «білого рятівника». Кен Ватанабе за роль Кацумото отримав номінацію на «Оскар»."},{"imdb_id":"tt0373856","title":"Gangaajal","title_uk":"Ґанґааджал","year":2003,"rating":7.8,"votes":19233,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Натхненний «бгаґалпурськими осліпленнями» 1979–80 років, коли поліція Біхара калічила підозрюваних.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Пракаш Джха переносить у вигадане біхарське містечко Тезпур відлуння «бгаґалпурських осліплень» 1979–80 років, коли поліція заливала кислоту в очі затриманим. Аджай Девґан грає нового суперінтенданта, який приїздить наводити лад і бачить, як самосуд подобається і підлеглим, і мешканцям. Це фільм не про розслідування, а про спокусу «швидкої справедливості» — і легкого виходу з неї він не пропонує."},{"imdb_id":"tt0402014","title":"Ab Tak Chhappan","title_uk":"Уже п'ятдесят шість","year":2004,"rating":7.8,"votes":10115,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Портрет мумбайського поліцейського-«ліквідатора», прообразом якого став реальний офіцер Дая Наяк.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Назва — це рахунок: п'ятдесят шість убитих у «зіткненнях». Інспектор Садгу Аґаше з мумбайського відділу боротьби зі злочинністю відстрілює бандитів у під'їздах і на пустирях, поки політика й заздрість колег не обертаються проти нього самого. Прообразом став реальний «енкаунтер-спеціаліст» Дая Наяк, якого згодом самого притягли до відповідальності. Дебют Шиміта Аміна під продюсерством Рама Ґопала Варми знято сухо, майже без музики, а Нана Патекар грає ледь помітною мімікою."},{"imdb_id":"tt0387914","title":"Innocent Voices (Voces inocentes)","title_uk":"Невинні голоси","year":2004,"rating":7.8,"votes":8683,"genres":["Drama","Thriller","War"],"country":"Мексика/США/Пуерто-Рико","country_main":"Мексика","region":"Латинська Америка","language":"ісп.","theme":"Війна","who_what":"Дитинство сценариста Оскара Торреса під час громадянської війни в Сальвадорі 1980-х.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Сценарист Оскар Торрес виріс у передмісті Сан-Сальвадора, де під час громадянської війни армія забирала хлопців до війська просто зі шкільних класів, щойно тим виповнювалося дванадцять. Луїс Мандокі показує рік життя Чави, який рахує місяці до цього дня рівно так само, як інші діти рахують до канікул. Політичних пояснень майже немає — війна тут існує на рівні кухні, подвір'я і бляшаного даху, під яким ховаються від куль."},{"imdb_id":"tt0358273","title":"Walk the Line","title_uk":"Переступити межу","year":2005,"rating":7.8,"votes":282171,"genres":["Biography","Drama","Music"],"country":"США/Німеччина","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя кантрі-музиканта Джонні Кеша та його стосунки з Джун Картер.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джеймс Менголд веде Джонні Кеша від ферми в Арканзасі та смерті старшого брата — через прослуховування в Sun Records 1955-го, гастрольний конвеєр і амфетаміни — до концерту у в'язниці Фолсом 1968 року. Хребет сюжету — багаторічне тяжіння до Джун Картер, яка довго не хотіла мати з ним справи. Хоакін Фенікс і Різ Візерспун співали самі, без підміни голосів; Візерспун отримала «Оскар» за головну роль."},{"imdb_id":"tt0498380","title":"Letters from Iwo Jima","title_uk":"Листи з Іводзіми","year":2006,"rating":7.8,"votes":177937,"genres":["Action","Adventure","Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"яп.","theme":"Війна","who_what":"Битва за острів Іводзіма 1945 року очима японського гарнізону генерала Тадаміті Курібаясі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Клінт Іствуд зняв цю картину одразу після «Прапорів наших батьків» — той самий бій за Іводзіму в лютому-березні 1945-го, але з японських тунелів. Опорою стали генерал Тадаміті Курібаясі (Кен Ватанабе), який відмовився від оборони на пляжі й наказав рити кілометри печер, та його листи додому. Майже все звучить японською, колір із кадру майже вимито. «Оскар» за монтаж звуку і номінація на найкращий фільм; у Японії стрічку прийняли надзвичайно тепло."},{"imdb_id":"tt0851577","title":"The Island","title_uk":"Острів","year":2006,"rating":7.8,"votes":13404,"genres":["Comedy","Drama"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Соціальна драма","who_what":"Радянська Північ: епізод німецької окупації 1942 року і монастирське життя 1976-го.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Фільм починається з війни на Білому морі 1942 року, а далі показує напівлегальний уклад північного монастиря пізнього СРСР — з відрядженнями партійних гостей і чергами прочан. Кочегар отець Анатолій, який тридцять років спокутує зраду, і вся братія вигадані. Павло Лунгін зняв у головній ролі Петра Мамонова; стрічка стала подією російського кіно 2006 року. Реальні тло й уклад, вигадані персонажі та історія гріха."},{"imdb_id":"tt0765429","title":"American Gangster","title_uk":"Американський гангстер","year":2007,"rating":7.8,"votes":492153,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Гарлемський наркобарон Френк Лукас і детектив Річі Робертс, який його викрив.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Наприкінці 1960-х гарлемський водій Френк Лукас перебирає бізнес по смерті боса й починає возити героїн просто з «Золотого трикутника», обходячи мафію-посередників; ловить його ньюаркський детектив Річі Робертс. Рідлі Скотт веде дві лінії паралельно, а Дензел Вашингтон грає ділка, який поводиться як обережний підприємець. Основа — репортаж Марка Джейкобсона в журналі New York. Чимало «фактів» Лукас вигадав сам: агенти DEA судилися через фільм, а історію з трунами так і не підтвердили."},{"imdb_id":"tt0783233","title":"Atonement","title_uk":"Спокута","year":2007,"rating":7.8,"votes":333199,"genres":["Drama","Mystery","Romance"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Війна","who_what":"Евакуація британських військ із Дюнкерка 1940 року і Лондон під час Бліцу.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джо Райт екранізує Ієна Мак'юена: маєток 1935 року, потім хаос на пляжі Дюнкерка й переповнені лондонські шпиталі 1940-го. Брайоні Талліс, Сесилія та Роббі Тернер вигадані, як і хибне звинувачення, що ламає їм життя. П'ятихвилинний безперервний кадр на пляжі знімали в Редкарі; «Оскар» за музику Даріо Маріанеллі. Війна справжня, злочин і покута — вигадка."},{"imdb_id":"tt1190539","title":"The Chaser","title_uk":"Переслідувач","year":2008,"rating":7.8,"votes":82104,"genres":["Action","Crime","Drama"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"корейська","theme":"Кримінал","who_what":"Колишній поліцейський полює на серійного вбивцю; прообраз — Ю Йон Чхоль.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Ю Йон Чхоль убив у Сеулі понад двадцять людей у 2003-2004 роках, і затримали його через дзвінок із телефона жертви. Дебют На Хон Джіна перетворює це на нічну гонитву: колишній поліцейський, що звідникує (Кім Юн Сок), шукає зниклих дівчат, а вбивцю (Ха Джон У) поліція вже тримає в руках і не може втримати. Двигун сюжету — не загадка, а бюрократія, яка втрачає години. Хронологію і деталі справи змінено: від реального випадку лишився радше механізм провалу."},{"imdb_id":"tt1149362","title":"The White Ribbon","title_uk":"Біла стрічка","year":2009,"rating":7.8,"votes":82082,"genres":["Drama","Mystery","Thriller"],"country":"Німеччина / Австрія","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Соціальна драма","who_what":"Північнонімецьке протестантське село напередодні Першої світової, 1913–1914.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Міхаель Ганеке відтворює життя пруського села останнього передвоєнного року: баронський маєток, пастор, лікар, поденники, сувора педагогіка сорому й покарань. Село Айхвальд, його мешканці та серія загадкових нападів вигадані. Чорно-біла зйомка Крістіана Берґера, «Золота пальмова гілка» 2009 року. Фільм читають як гіпотезу про коріння покоління, що виросло в націонал-соціалізм; конкретних подій він не переказує."},{"imdb_id":"tt1285016","title":"The Social Network","title_uk":"Соціальна мережа","year":2010,"rating":7.8,"votes":826924,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Створення Facebook Марком Цукербергом і судові позови навколо нього.","basis":"реальна історія","note":"Ключова мотивація героя (створення Facebook через розрив із дівчиною) вигадана; Марк Цукерберг і низка учасників подій заперечували значну частину зображеного, а сценарист визнавав свідому драматизацію.","thriller_flag":false,"decade":"2010-ті","desc":"Facebook виріс із гарвардського гуртожитку 2003 року, а далі були позови близнюків Вінклвоссів і витісненого співзасновника Едуардо Саверіна. Фінчер і сценарист Аарон Соркін будують фільм як дві паралельні депозиції, з яких складається свідомо суперечлива версія подій. Три «Оскари», зокрема за адаптований сценарій і музику Резнора з Россом; сам Цукерберг заперечував ключовий мотив — розрив із дівчиною, з якого нібито все й почалося."},{"imdb_id":"tt0964517","title":"The Fighter","title_uk":"Боєць","year":2010,"rating":7.8,"votes":410592,"genres":["Action","Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Боксер Міккі Ворд і його зведений брат Діккі Еклунд на шляху до чемпіонського титулу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ловелл, Массачусетс: боксер Міккі Ворд намагається пробитися нагору, поки його тренує зведений брат Діккі Еклунд — колишній суперник Шуґара Рея Леонарда, який осів на креку. Девід О. Расселл знімає радше сімейну драму, ніж спортивну: мати-менеджерка, сім сестер, нова дівчина Шарлін проти всіх. «Оскари» дісталися Крістіану Бейлу й Меліссі Лео, а бої знімали старими телевізійними камерами HBO, щоб вони виглядали як трансляція тих років."},{"imdb_id":"tt1655442","title":"The Artist","title_uk":"Артист","year":2011,"rating":7.8,"votes":256308,"genres":["Comedy","Drama","Romance"],"country":"Франція","country_main":"Франція","region":"Європа","language":"без діалогів","theme":"Музика та мистецтво","who_what":"Перехід Голлівуду від німого кіно до звукового, 1927–1932.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мішель Азанавічус відтворює злам, який пережила індустрія після «Співака джазу»: провал німих зірок, тиск студій, крах 1929 року й Велика депресія. Зірка Джордж Валентин і актриса Пеппі Міллер вигадані, хоча їхні долі зібрані з біографій Джона Гілберта, Дуґласа Фербенкса і Джоан Кроуфорд. П'ять «Оскарів», зокрема за фільм і роль Жана Дюжардена. Історичний процес реальний, персонажі — збірні."},{"imdb_id":"tt2290840","title":"Masquerade","title_uk":"Маскарад","year":2012,"rating":7.8,"votes":8133,"genres":["Drama","History"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"корейс.","theme":"Політика та історія","who_what":"Правління корейського короля Кванхеґуна, 1616 рік.","basis":"реальне тло, вигадані герої","note":"Король Кванхеґун — реальна постать; двійник і фабула вигадані.","thriller_flag":false,"decade":"2010-ті","desc":"Чху Чханмін відштовхується від реального пропуску в «Анналах династії Чосон», де п'ятнадцять днів царювання вилучено з хроніки. Простолюдин-блазень Ха Сон, якого садять на трон замість отруєного короля, вигаданий, як і його реформи та стосунки з королевою. Лі Бьонхон грає обидві ролі; фільм зібрав понад дванадцять мільйонів глядачів і взяв основні нагороди Daejong. Кванхеґун реальний, підміна — вигадка."},{"imdb_id":"tt2013293","title":"The Wind Rises","title_uk":"Вітер міцніє","year":2013,"rating":7.8,"votes":114816,"genres":["Animation","Biography","Drama","History","Romance","War"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"яп.","theme":"Наука і технології","who_what":"Авіаконструктор Дзіро Хорікосі, творець винищувача Mitsubishi A6M «Зеро».","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Дзіро Хорікосі спроєктував для Mitsubishi винищувач A6M «Зеро», на якому Японія воювала до 1945-го. Хаяо Міядзакі змішує його біографію з повістю Тацуо Хорі й власними снами: інженер, який хоче будувати красиві літаки, живе в країні землетрусів, злиднів і мілітаризму. Це остання робота режисера перед оголошенням про відхід із великого метру. В Японії його критикували праві — за пацифізм, ліві — за поетизацію зброї, а в Кореї — за мовчання про підневільну працю."},{"imdb_id":"tt1535109","title":"Captain Phillips","title_uk":"Капітан Філліпс","year":2013,"rating":7.8,"votes":522126,"genres":["Action","Biography","Crime","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Захоплення сомалійськими піратами судна Maersk Alabama 2009 року та порятунок капітана Річарда Філліпса.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Квітень 2009-го: четверо сомалійців на скіфі беруть на абордаж контейнеровоз Maersk Alabama, а згодом опиняються з капітаном у зачиненій рятувальній шлюпці, яку по п'ятах веде есмінець ВМС США. Пол Ґрінґрасс знімає майже без пауз, з рук, і віддає другу половину фільму замкненому простору. Барход Абді, якого знайшли на відкритому кастингу в Міннеаполісі, вивів свого Мусе на номінацію «Оскара». Частина екіпажу згодом публічно оскаржувала версію Філліпса, звинувативши його в нехтуванні попередженнями про піратів."},{"imdb_id":"tt2213054","title":"Kai Po Che","title_uk":"Кай По Че!","year":2013,"rating":7.8,"votes":40258,"genres":["Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Землетрус у Гуджараті 2001 року і погроми 2002-го після пожежі потяга в Ґодхрі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Абгішек Капур екранізує Четана Бгаґата: троє друзів відкривають крикетну академію в Ахмадабаді, а їхні плани перекреслюють землетрус у Бхуджі та міжобщинне насильство 2002 року. Ішан, Омі й Ґовінд вигадані, як і доля хлопчика-мусульманина, якого вони тренують. Одна з ранніх головних ролей Сушанта Сінґха Раджпута. Катастрофа й погроми реальні, герої — ні."},{"imdb_id":"tt3169706","title":"Pride","title_uk":"Гордість","year":2014,"rating":7.8,"votes":65605,"genres":["Biography","Comedy","Drama","History","Romance"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Лондонські ЛГБТ-активісти групи LGSM підтримали валлійських шахтарів під час страйку 1984–1985 років.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Улітку 1984-го, коли Тетчер ламала шахтарський страйк, купка лондонських геїв і лесбійок почала збирати гроші для шахтарського селища в Південному Уельсі — і мусила ще переконати шахтарів ті гроші взяти. Меттью Ворчус знімає комедію про робітничу солідарність, де смішне не скасовує ні поліційних кийків, ні СНІДу, ні смерті засновника групи Марка Ештона у 26 років. В ансамблі Імелда Стонтон, Білл Наї, Домінік Вест, Педді Консідайн. «Квір-пальма» в Каннах."},{"imdb_id":"tt4168188","title":"Chaar Sahibzaade","title_uk":"Чаар Сахібзааде","year":2014,"rating":7.8,"votes":8309,"genres":["Animation","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"панджабі","theme":"Політика та історія","who_what":"Загибель чотирьох синів десятого сикхського гуру Ґобінда Сінгха у війнах із Моголами 1704–1705 років.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Грудень 1704-го: після виходу з обложеного Анандпура старші сини ґуру Ґобінда Сінґха — сімнадцятирічний Аджіт і чотирнадцятирічний Джуджхар — гинуть у бою під Чамкауром, а молодших, дев'ятирічного Зоравара й шестирічного Фатеха, разом із бабусею Матою Ґуджрі схоплюють і за наказом Вазір-хана замуровують живцем у Сірхінді. Гаррі Баведжа зняв це як повнометражну панджабі-анімацію в 3D із закадровим голосом Ома Пурі. За сикхською традицією обличчя ґуру не зображують — його присутність передано світлом."},{"imdb_id":"tt3812366","title":"Ode to My Father","title_uk":"Ода моєму батькові","year":2014,"rating":7.8,"votes":6933,"genres":["Drama","War"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"корейс.","theme":"Політика та історія","who_what":"Корея від евакуації Хиннама 1950 року до телемарафону з возз'єднання родин 1983-го.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Юн Джегюн проводить одну родину крізь віхи корейської історії: евакуація Хиннама на судні «Мередіт Вікторі», робота гірників і медсестер у ФРН, підряди у В'єтнамі, прямий ефір KBS 1983 року. Токсу, його сестра й друг Дальґу вигадані. Понад чотирнадцять мільйонів глядачів у прокаті та суперечки про надто теплий погляд на диктатуру. Усі події реальні, родина — ні."},{"imdb_id":"tt1596363","title":"The Big Short","title_uk":"Гра на пониження","year":2015,"rating":7.8,"votes":546092,"genres":["Biography","Comedy","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Кілька інвесторів (Майкл Беррі, Стів Айсман та ін.) передбачили крах іпотечного ринку США 2007–2008 років і зіграли проти нього.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"За книжкою Майкла Льюїса: лікар-невролог Майкл Беррі, трейдер Deutsche Bank і двоє новачків із гаражного фонду ще у 2005-му розгледіли, що іпотечні облігації набиті поганими кредитами, і купили страховки проти них. Адам Маккей пояснює CDO й дефолтні свопи прямими звертаннями до камери й камео Марґо Роббі та Ентоні Бурдена. Персонаж Стіва Керелла зветься Марком Баумом, але списаний зі Стіва Айсмана. «Оскар» за адаптований сценарій."},{"imdb_id":"tt1398426","title":"Straight Outta Compton","title_uk":"Голос вулиць","year":2015,"rating":7.8,"votes":235657,"genres":["Biography","Drama","History","Music","Musical"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Історія гурту N.W.A з Комптона — Eazy-E, Dr. Dre, Ice Cube — і народження ґанґста-репу наприкінці 1980-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Комптон, 1986–1995: Ізі-І вкладає гроші від вуличної торгівлі в лейбл Ruthless, Dr. Dre зводить біти, Айс К'юб пише тексти — і «Fuck tha Police» приносить гурту лист-попередження від ФБР. Ґері Ґрей доводить оповідь до розпаду складу, судів із менеджером Джеррі Геллером і смерті Ізі-І 1995 року, а Айс К'юба грає його власний син О'Ші Джексон-молодший. Продюсерами були Dre і Cube, і фільм мовчить про задокументовані напади Dr. Dre на жінок."},{"imdb_id":"tt3841424","title":"Land of Mine","title_uk":"Під піском","year":2015,"rating":7.8,"votes":49686,"genres":["Drama","History","War"],"country":"Данія, Німеччина","country_main":"Данія","region":"Європа","language":"дан., нім.","theme":"Війна","who_what":"Німецькі військовополонені-підлітки розміновували узбережжя Данії після капітуляції 1945 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Травень 1945-го, західне узбережжя Данії: близько двох тисяч німецьких полонених, більшість — зовсім юні, повзуть піском і знешкоджують міни голими руками; за оцінками, майже половина загинула або лишилася скаліченою. Мартін Зандвліт стягує це до одного пляжу й одного данського сержанта (Роланд Мьоллер), чия ненависть повільно дає тріщину. Луїс Гофманн грає старшого серед хлопців, який намагається тримати групу вкупі. Номінація на «Оскар» і незручна для Данії розмова про те, що робили переможці."},{"imdb_id":"tt4285496","title":"Embrace of the Serpent","title_uk":"Обійми змія","year":2015,"rating":7.8,"votes":26047,"genres":["Adventure","Biography","Drama"],"country":"Колумбія, Венесуела, Аргентина","country_main":"Колумбія","region":"Латинська Америка","language":"ісп., португ., мови амазонських народів","theme":"Наука і технології","who_what":"Щоденники етнографів Теодора Кох-Ґрюнберґа (1909) та Річарда Еванса Шультеса (1940-і) про подорожі Амазонією у пошуках рослини яакруна.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Сіро Ґерра сплітає два реальні щоденники: німець Теодор Кох-Ґрюнберґ мандрував колумбійською Амазонією 1909 року, американський ботанік Річард Еванс Шультес — у 1940-х. Обох веде той самий шаман Карамакате, спершу молодий, потім старий, у пошуках цілющої рослини яакруна. Знято на чорно-білу плівку, здебільшого мовами корінних народів, з акторами з амазонських громад. Перша колумбійська стрічка, номінована на «Оскар» за іншомовний фільм; Карамакате вигаданий, а каучукові місії та їхні наслідки — ні."},{"imdb_id":"tt4846340","title":"Hidden Figures","title_uk":"Приховані фігури","year":2016,"rating":7.8,"votes":293112,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Афроамериканські математикині NASA Кетрін Джонсон, Дороті Вон і Мері Джексон, які забезпечили орбітальний політ Джона Гленна 1962 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Кетрін Джонсон рахувала траєкторії для орбітального польоту Джона Ґленна 1962 року, Дороті Вон перевчила свій відділ на програмування IBM, Мері Джексон через суд домоглася права ходити на курси в сегрегованій школі й стала інженеркою NASA. Теодор Мелфі стискає три біографії з книжки Марґо Лі Шеттерлі в один робочий рік у Ленглі. Кілька ефектних сцен вигадано — зокрема начальник, який збиває табличку «для кольорових»: реальна Джонсон просто ігнорувала ці правила."},{"imdb_id":"tt5600714","title":"Laal Rang","title_uk":"Червоний колір","year":2016,"rating":7.8,"votes":5477,"genres":["Comedy","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Кримінальний бізнес на краденій донорській крові в штаті Гар'яна; натхненно реальними схемами «кров'яної мафії» довкола Карналу.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Карнал, штат Гар'яна: студент лабораторного коледжу Раджеш прибивається до Шанкара, який заробляє на крові — виманює її в бідняків, підмінює аналізи, постачає лікарням. Сайєд Ахмад Афзал знімав у самому Карналі й спирався на схеми «кров'яної мафії», про які писала регіональна преса. Тон тут чорнокомедійний: життям торгують з інтонацією дрібних дилерів, які вірять у власну шляхетність. У прокаті 2016-го фільм провалився, але з роками зібрав культову аудиторію — насамперед завдяки роботі Рандіпа Гуди."},{"imdb_id":"tt4769824","title":"In This Corner of the World","title_uk":"«У цьому куточку світу»","year":2016,"rating":7.8,"votes":14110,"genres":["Animation","Drama","History","War"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"яп.","theme":"Війна","who_what":"Життя цивільних у Куре й Хіросімі від 1933 року до атомного бомбардування 6 серпня 1945-го.","basis":"реальне тло, вигадані герої","note":"анімаційний повнометражний фільм, не ігровий","thriller_flag":false,"decade":"2010-ті","desc":"Сунао Катабучі кілька років звіряв топографію Куре й Хіросіми за довоєнними фотографіями, тож вулиці, крамниці й розклад авіанальотів точні до дати. Судзу з Хіросіми виходить заміж у місто-порт Куре і вчиться виживати при картковій системі, бомбардуваннях і втраті руки. Приз глядацьких симпатій в Аннесі та головна нагорода Японської кіноакадемії. Судзу та її родина вигадані."},{"imdb_id":"tt3262342","title":"Loving Vincent","title_uk":"З любов'ю, Вінсент","year":2017,"rating":7.8,"votes":68786,"genres":["Animation","Drama","Mystery"],"country":"Польща / Велика Британія","country_main":"Польща","region":"Європа","language":"англ.","theme":"Музика та мистецтво","who_what":"Розслідування обставин смерті Вінсента ван Гога, зняте з живими акторами й перемальоване олією кадр за кадром.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Овер-сюр-Уаз, 1891-й, через рік після пострілу: син листоноші Арман Рулен везе останній лист Вінсента до брата Тео й починає розпитувати всіх, хто бачив художника в останні тижні. Дорота Кобеля й Г'ю Велчмен спершу зняли гру акторів, а тоді 125 живописців перемалювали кожен кадр олією — понад 65 тисяч полотен у манері самого ван Гога. Спогади свідків подано чорно-білою графікою. Номінація на «Оскар» за анімаційний фільм; версію про вбивство фільм припускає, але не стверджує."},{"imdb_id":"tt5013056","title":"Dunkirk","title_uk":"Дюнкерк","year":2017,"rating":7.8,"votes":823804,"genres":["Action","Drama","History","Thriller","War"],"country":"Велика Британія / Нідерланди / Франція / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ., франц., нім.","theme":"Війна","who_what":"Евакуація 338 тисяч союзних солдатів із Дюнкерка у травні–червні 1940 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Понад триста тисяч британських і французьких солдатів наприкінці травня 1940 року опинилися притиснутими до моря під Дюнкерком, і вивозили їх у тому числі цивільними катерами. Крістофер Нолан монтує три відрізки різної тривалості — тиждень на молу, день у морі, годину в повітрі, — які сходяться в одній точці. Діалогів мало, персонажі майже без біографій, знімали на 65-мм плівку та IMAX зі справжніми кораблями і «спітфайрами». Три «Оскари»: монтаж, звук і звуковий мікс."},{"imdb_id":"tt7218518","title":"Pad Man","title_uk":"Людина-прокладка","year":2018,"rating":7.8,"votes":33016,"genres":["Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Наука і технології","who_what":"Арунахалам Муруганантам, який винайшов дешевий верстат для виробництва гігієнічних прокладок у сільській Індії.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Арунахалам Муруганантам із Тамілнаду почав із того, що спробував зробити дешевшу прокладку для дружини, а закінчив верстатом, який тепер збирають жіночі кооперативи по всій Індії; дорогою від нього пішли дружина й мати. Р. Балкі переніс дію в Мадг'я-Прадеш і перейменував героя на Лакшміканта Чаухана, зберігши соромливість теми і впертість винахідника. Акшай Кумар грає без звичного героїзму, з комедійною ніяковістю. Головний ефект не в сюжеті: масове індійське кіно вперше вголос заговорило про менструацію."},{"imdb_id":"tt7362036","title":"Dying to Survive","title_uk":"Я не бог ліків","year":2018,"rating":7.8,"votes":9244,"genres":["Comedy","Drama"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"кит.","theme":"Медицина та виживання","who_what":"Торговець контрабандою дешевих ліків від лейкемії; прообраз — Лу Юн.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Прообраз — Лу Юн, китайський підприємець із хронічним мієлолейкозом, який із середини 2000-х завозив із Індії дешеві дженерики іматинібу для тисяч пацієнтів і потрапив під суд за контрабанду. Вень Мує починає як комедію про дрібного торговця афродизіаками (Сюй Чжен) і поступово переводить її в драму про ціну ліків. Фільм зібрав понад 3 мільярди юанів і підштовхнув публічну дискусію, після якої Китай скасував мита на низку онкопрепаратів."},{"imdb_id":"tt1302006","title":"The Irishman","title_uk":"Ірландець","year":2019,"rating":7.8,"votes":478169,"genres":["Biography","Crime","Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ., італ.","theme":"Кримінал","who_what":"Кілер профспілок Френк Ширан, його зв'язок із Джиммі Гоффою та мафією; за книжкою «I Heard You Paint Houses».","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"За книжкою Чарльза Брандта «I Heard You Paint Houses»: далекобійник Френк Ширан стає виконавцем для родини Буфаліно й водночас довіреною людиною профспілкового лідера Джиммі Гоффи, який зник у липні 1975 року. Скорсезе розтягує оповідь на пів століття й 209 хвилин, застосувавши цифрове омолодження Де Ніро, Пачіно та Пеші. Історики й журналісти здебільшого не вірять передсмертному зізнанню Ширана — фільм подає його версію як факт."},{"imdb_id":"tt1016150","title":"All Quiet on the Western Front","title_uk":"«На Західному фронті без змін»","year":2022,"rating":7.8,"votes":344590,"genres":["Drama","History","War"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Війна","who_what":"Останні місяці Першої світової на Західному фронті та переговори про перемир'я 11 листопада 1918 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Едвард Берґер переносить роман Ремарка у 1917–1918 роки й додає документальну лінію: делегація Матіаса Ерцберґера торгується у вагоні під Комп'єном. Сімнадцятирічний Пауль Боймер із друзями йде добровольцем і за кілька місяців перетворюється на людину без ілюзій. Чотири «Оскари», зокрема за найкращий міжнародний фільм. Боймер вигаданий, перемир'я і його година — ні; фінальна атака за чверть години до тиші дописана сценаристами."},{"imdb_id":"tt8178634","title":"RRR","title_uk":"«RRR»","year":2022,"rating":7.8,"votes":226538,"genres":["Action","Adventure","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"телугу","theme":"Політика та історія","who_what":"Британське колоніальне панування в Індії 1920-х років.","basis":"реальне тло, вигадані герої","note":"реальні імена революціонерів, але сюжет повністю вигаданий","thriller_flag":false,"decade":"2020-ті","desc":"Раджамулі бере двох реальних революціонерів — Комарама Бхіма й Аллурі Сітараму Раджу — і вигадує їм зустріч, якої ніколи не було, у Делі 1920 року. Фільм показує колоніальне свавілля, викрадення дівчинки з племені гонд і повстання проти губернатора Скотта. Пісня «Naatu Naatu» принесла перший індійський «Оскар». Історичні тут лише імена й загальний контекст: уся фабула, дружба й бої — фантазія."},{"imdb_id":"tt16277242","title":"Society of the Snow","title_uk":"Снігове братство","year":2023,"rating":7.8,"votes":176984,"genres":["Adventure","Biography","Drama","History"],"country":"Іспанія","country_main":"Іспанія","region":"Європа","language":"ісп.","theme":"Катастрофа і виживання","who_what":"Уругвайські регбісти виживають 72 дні в Андах після авіакатастрофи рейсу 571 у 1972 році.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"13 жовтня 1972-го літак уругвайських ВПС із командою регбістів на борту врізався в андійський льодовик; шістнадцятеро з сорока п'яти протрималися 72 дні, поки двоє не перейшли гори пішки. Х. А. Байона зняв це за книжкою Пабло В'єрсі, іспанською, з переважно недосвідченими уругвайськими та аргентинськими акторами, і віддав закадровий голос одному з тих, хто не вижив. Частину зйомок провели просто в Долині сліз. Дві номінації на «Оскар» — за іншомовний фільм і грим."},{"imdb_id":"tt13238346","title":"Past Lives","title_uk":"Минулі життя","year":2023,"rating":7.8,"votes":177018,"genres":["Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ., кор.","theme":"Автобіографія","who_what":"Двоє друзів дитинства з Сеула зустрічаються через 24 роки в Нью-Йорку — за особистою історією режисерки Селін Сон.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Селін Сон переписала власну історію: дитиною вона виїхала з Сеула до Канади, а через роки її шкільний друг і чоловік-американець зустрілися за одним столом у Нью-Йорку. Фільм ділиться на три зустрічі з проміжками у 12 і 24 роки: дитинство, розмови по Skype, кілька днів у місті. Ґрета Лі, Тео Ю і Джон Маґаро грають майже без пояснень; ключове поняття — корейське «інйон», зв'язок, що тягнеться крізь життя. Дебют із номінаціями на «Оскар» за фільм і сценарій."},{"imdb_id":"tt14570440","title":"Radical","title_uk":"Радикал","year":2023,"rating":7.8,"votes":7926,"genres":["Drama"],"country":"Мексика","country_main":"Мексика","region":"Латинська Америка","language":"ісп.","theme":"Соціальна драма","who_what":"Учитель Серхіо Хуарес Корреа в занедбаній школі Матамороса змінює життя учнів нестандартною методикою навчання.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Школа імені Хосе Урбіни Лопеса в прикордонному Матаморосі мала одні з найгірших результатів у Мексиці, доки вчитель Серхіо Хуарес Корреа не відклав підручники й не почав вести уроки через запитання самих дітей; його учениця Палома Нойола згодом показала найкращий бал з математики в країні. Крістофер Залла екранізував репортаж Джошуа Девіса для Wired. Еухеніо Дербес, відомий як комік, грає без жодного комедійного прийому; фільм отримав глядацький приз Санденсу."},{"imdb_id":"tt27470893","title":"Chandu Champion","title_uk":"Чанду-чемпіон","year":2024,"rating":7.8,"votes":36726,"genres":["Action","Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Мурлікант Петкар, поранений на війні 1965 року, стає першим індійським золотим медалістом Паралімпіади 1972 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Мурліканта Петкара з махараштрійського містечка посікло кулями під час індійсько-пакистанської війни 1965 року; після років реабілітації він сів у басейн і 1972-го на Паралімпіаді в Гейдельберзі виграв 50 метрів вільним стилем зі світовим рекордом — перше золото Індії на Паралімпіадах. Кабір Хан веде розповідь від літнього Петкара, який прийшов до поліції зі скаргою на власну державу. Картік Ар'ян перебудував тіло під боксера й плавця одночасно."},{"imdb_id":"tt26658272","title":"Amar Singh Chamkila","title_uk":"Амар Сінгх Чамкіла","year":2024,"rating":7.8,"votes":17901,"genres":["Biography","Drama","Music"],"country":"Індія","country_main":"Індія","region":"Індія","language":"панджабі","theme":"Музика та мистецтво","who_what":"Панджабський співак Чамкіла, застрелений разом із дружиною 1988 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Дхані Рам із далітської родини під Лудхіяною став Амаром Сінгхом Чамкілою — найбільш продаваним панджабським співаком 1980-х, чиї відверті пісні слухали всі й публічно засуджували теж усі. 8 березня 1988 року його разом із дружиною й сценічною партнеркою Амарджот та двома музикантами розстріляли біля Джаландхара; убивць так і не знайшли. Імтіяз Алі перемішує ігрові сцени з анімацією, архівом і піснями А. Р. Рахмана, а розповідь ведуть ті, хто лишився. Ділджіт Досандж співає сам."},{"imdb_id":"tt30970235","title":"Article 370","title_uk":"Стаття 370","year":2024,"rating":7.8,"votes":28891,"genres":["Action","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Скасування особливого статусу Джамму і Кашміру у серпні 2019 року.","basis":"натхненний реальними подіями","note":"Односторонній політичний наратив, схвально поданий владою; агентка NIA та більшість сюжетних подій вигадані, критики називали фільм передвиборчою агітацією.","thriller_flag":true,"decade":"2020-ті","desc":"5 серпня 2019 року індійський уряд скасував статтю 370 Конституції, яка давала Джамму і Кашміру особливий статус. Адітья Джамбхале показує підготовку до цього кроку як шпигунський трилер: вигадана офіцерка Національного агентства розслідувань у Срінагарі й чиновниця з канцелярії прем'єра в Делі ведуть паралельні лінії — оперативну та юридично-парламентську. Ямі Ґаутам у головній ролі, темп щільний. Фільм вийшов за кілька тижнів до виборів 2024-го, і чимало критиків назвали його прямою агітацією."},{"imdb_id":"tt35301431","title":"Latin Blood – The Ballad of Ney Matogrosso","title_uk":"Латинська кров: Балада про Нея Матогроссо","year":2025,"rating":7.8,"votes":6237,"genres":["Biography","Drama","History","Music"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"порт.","theme":"Музика та мистецтво","who_what":"Життя бразильського співака Нея Матогроссо, який кинув виклик диктатурі й гендерним нормам 1970-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Ней Матогроссо злетів у 1970-х із гуртом Secos & Molhados — у гримі, пір'ї та з пластикою, яку військова диктатура читала як виклик. Есмір Філю екранізує біографію Жуліу Марії: дитинство в родині військового, важкі стосунки з батьком, слава і особисте життя, якого співак не приховував. Жезуїта Барбоза грає його від юності до зрілості, роблячи ставку на пластику й сценічну подачу. Оригінальна назва — «Homem com H», за однойменною піснею з репертуару Матогроссо."},{"imdb_id":"tt0104797","title":"Malcolm X","title_uk":"Малкольм Ікс","year":1992,"rating":7.7,"votes":112365,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Життя афроамериканського проповідника й політичного лідера Малкольма Ікса, убитого 1965 року.","basis":"реальна історія","note":"Ранні роки подано за автобіографією, точність якої дослідники частково заперечують.","thriller_flag":false,"decade":"1990-ті","desc":"Малкольм Літл (1925–1965) пройшов шлях від гарлемського шахрая до головного речника «Нації ісламу», порвав з Іллаєм Мухаммадом, здійснив хадж і 21 лютого 1965 року був застрелений у нью-йоркському Одюбон-Болрумі. Спайк Лі екранізував автобіографію, записану Алексом Гейлі, у тригодинну фреску; Дензел Вашингтон здобув за роль номінацію на «Оскар». Фінальний епізод знімали в Соуето за участі Нельсона Мандели."},{"imdb_id":"tt0107818","title":"Philadelphia","title_uk":"Філадельфія","year":1993,"rating":7.7,"votes":276533,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Позов юриста, звільненого через ВІЛ-статус, — сюжет виріс зі справжніх справ кінця 1980-х.","basis":"натхненний реальними подіями","note":"Герої вигадані; родина Джеффрі Бауерса судилася зі студією за запозичення деталей його справи й уклала мирову.","thriller_flag":false,"decade":"1990-ті","desc":"Сценарій Рона Наєвського спирався на реальні позови кінця 1980-х, насамперед справу нью-йоркського юриста Джеффрі Бауерса, якого фірма звільнила після того, як на його обличчі проступила саркома Капоші. Джонатан Деммі зробив із цього першу голлівудську студійну драму про СНІД: Том Генкс схуд приблизно на дванадцять кілограмів і отримав «Оскар», ще один дістався пісні Брюса Спрінгстіна."},{"imdb_id":"tt0112384","title":"Apollo 13","title_uk":"Аполлон-13","year":1995,"rating":7.7,"votes":342307,"genres":["Adventure","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Аварія кисневого бака на кораблі «Аполлон-13» у квітні 1970 року і порятунок трьох астронавтів.","basis":"реальна історія","note":"Фразу «Failure is not an option» Кранц ніколи не казав — її написали сценаристи; справжній радіообмін звучав «Houston, we've had a problem».","thriller_flag":false,"decade":"1990-ті","desc":"13 квітня 1970 року, за двісті тисяч миль від Землі, на «Аполлоні-13» вибухнув кисневий бак; Джим Ловелл, Джек Свайґерт і Фред Гейз повернулися живими 17 квітня, використавши місячний модуль як рятувальну шлюпку. Рон Говард знімав за книжкою Ловелла «Lost Moon», у невагомості на літаку KC-135. Том Генкс, Кевін Бейкон, Білл Пекстон і Ед Гарріс у ролі Джина Кранца; два «Оскари»."},{"imdb_id":"tt0117214","title":"Nun va Goldoon","title_uk":"Мить невинності","year":1996,"rating":7.7,"votes":5290,"genres":["Comedy","Drama"],"country":"Іран / Франція","country_main":"Іран","region":"Близький Схід і Африка","language":"перс.","theme":"Автобіографія","who_what":"Мохсен Махмальбаф і поліцейський, якого він поранив ножем 1974 року, разом переграють ту саму подію на камеру.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"1974 року сімнадцятирічний Мохсен Махмальбаф спробував роззброїти поліцейського під час акції проти шаха, поранив його ножем, дістав кулю і сидів у в'язниці до революції 1979 року. Через двадцять років той самий поліцейський Мірхаді Тайебі прийшов до режисера на кастинг. Вони зняли фільм, у якому кожен ставить сцену зі своїм молодим двійником і сперечається за версію минулого. Фінальний стоп-кадр пропонує інший, ненасильницький результат тієї зустрічі."},{"imdb_id":"tt0116790","title":"Kolya","title_uk":"Коля","year":1996,"rating":7.7,"votes":17085,"genres":["Comedy","Drama","Music"],"country":"Чехія","country_main":"Чехія","region":"Європа","language":"чеськ. / рос.","theme":"Політика та історія","who_what":"Чехословаччина 1988 року напередодні Оксамитової революції.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Празький віолончеліст Лоука за гроші укладає фіктивний шлюб із росіянкою, а на руках у нього залишається її п'ятирічний син Коля. Герої вигадані, але тиск держбезпеки, черги за візами й листопадові демонстрації 1989-го на тлі реальні. «Оскар» за іншомовний фільм; сценарій написав Зденєк Свєрак для сина-режисера."},{"imdb_id":"tt0119008","title":"Donnie Brasco","title_uk":"Донні Браско","year":1997,"rating":7.7,"votes":360257,"genres":["Biography","Crime","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Агент ФБР Джозеф Пістоне шість років працював під прикриттям у нью-йоркській мафіозній родині Боннанно.","basis":"реальна історія","note":"Події шести років стиснуто, частину другорядних персонажів і сцен вигадано.","thriller_flag":true,"decade":"1990-ті","desc":"З 1976 по 1981 рік агент ФБР Джозеф Пістоне під іменем Донні Браско жив серед бійців родини Боннанно і зібрав матеріал більш ніж на сотню мафіозі. Майк Ньюелл зосередився на його дружбі з рядовим виконавцем Бенджаміном «Лефті» Рудджеро, якого зіграв Аль Пачіно, а Пістоне грає Джонні Депп. Сценарій Пола Аттанасіо номінували на «Оскар». Хронологію і низку епізодів у фільмі ущільнено."},{"imdb_id":"tt0169145","title":"Cabaret Balkan","title_uk":"Балканське кабаре","year":1998,"rating":7.7,"votes":6079,"genres":["Comedy","Drama","Thriller"],"country":"Югославія / Франція / Греція","country_main":"Югославія","region":"Європа","language":"сербська","theme":"Політика та історія","who_what":"Белград середини 1990-х під санкціями і владою Мілошевича.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"1990-ті","desc":"Одна ніч у місті: десяток незнайомців сходяться в ланцюжку сутичок, де кожна дрібна образа закінчується кров'ю. Персонажі вигадані за п'єсою Деяна Дуковського, але агресія, безробіття й повернення ветеранів із фронту передають реальну атмосферу Сербії під санкціями. Ґоран Паскалевич отримав приз ФІПРЕССІ у Венеції. Стрічка вийшла за рік до бомбардувань НАТО і сприймалася як передчуття."},{"imdb_id":"tt0260991","title":"Joint Security Area","title_uk":"Спільна зона безпеки","year":2000,"rating":7.7,"votes":39459,"genres":["Action","Drama","Mystery","Thriller"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Війна","who_what":"Демілітаризована зона між Кореями і режим спільної охорони в Пханмунджомі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Після нічної стрілянини на прикордонному посту нейтральна слідча з'ясовує, що солдати двох армій потайки дружили. Інцидент і персонажі вигадані, натомість топографія ДМЗ, «міст без вороття» і протокол спільної зони відтворені точно. Пак Чхан-ук зробив фільм найкасовішим у Кореї на той момент; у головних ролях Сон Кан-хо і Лі Бьон-хон."},{"imdb_id":"tt0249462","title":"Billy Elliot","title_uk":"Біллі Елліот","year":2000,"rating":7.7,"votes":153554,"genres":["Comedy","Drama","Music"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Страйк британських шахтарів 1984—1985 років.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Син шахтаря з Даремського вугільного басейну ходить на балет замість боксу, поки батько й брат стоять у пікетах проти поліції. Родина Елліотів вигадана, а перебіг страйку — сутички, штрейкбрехери, поразка профспілки — реальний. Дебют у кіно Стівена Долдрі; три номінації на «Оскар», а згодом мюзикл із музикою Елтона Джона."},{"imdb_id":"tt0265086","title":"Black Hawk Down","title_uk":"Падіння «Чорного яструба»","year":2001,"rating":7.7,"votes":458438,"genres":["Action","Drama","History","War"],"country":"США/Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Битва в Могадішо 3–4 жовтня 1993 року під час операції США в Сомалі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"3 жовтня 1993 року рейнджери й «Дельта» мали за годину захопити двох помічників сомалійського генерала Айдіда — після того, як бойовики збили два гелікоптери, бій розтягнувся на добу. Рідлі Скотт екранізує репортажну книжку Марка Боудена майже без передісторії: весь фільм — вуличний хаос Могадішо очима десятків солдатів. Дві премії «Оскар», за монтаж і звук. Сомалійська сторона лишається безликою масою, хоча втрат там було в десятки разів більше, ніж 18 загиблих американців."},{"imdb_id":"tt0250258","title":"Das Experiment","title_uk":"Експеримент","year":2001,"rating":7.7,"votes":99134,"genres":["Drama","Thriller"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Наука і технології","who_what":"Натхненний Стенфордським тюремним експериментом Філіпа Зімбардо 1971 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Двадцятеро добровольців за чотири тисячі марок погоджуються два тижні грати в'язнів і наглядачів у фальшивій тюрмі, і ролі швидко перестають бути грою. Основа — Стенфордський експеримент Філіпа Зімбардо 1971 року, але Гіршбіґель екранізує роман Маріо Джордано «Чорна скринька» й доводить сюжет до вбивств і захоплення заручників, чого в Стенфорді не було. Моріц Бляйбтрой грає журналіста, який іде в експеримент по матеріал. Дивитися варто як трилер про механіку влади, а не як реконструкцію."},{"imdb_id":"tt0318411","title":"The Magdalene Sisters","title_uk":"Сестри Магдалини","year":2002,"rating":7.7,"votes":30191,"genres":["Drama"],"country":"Ірландія/Велика Британія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Ірландські «притулки Магдалини», де церква десятиліттями утримувала жінок на примусовій праці.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Пітер Маллан зводить долі трьох ірландок, яких 1964 року родини здають до дублінської пральні Магдалини: одну — бо завагітніла поза шлюбом, другу — бо її зґвалтував родич, третю — бо надто заглядалася на хлопців. Камера майже не виходить за мури: праця, побої, вивчена покора. «Золотий лев» Венеції та лють ватиканської преси; останню таку пральню в Ірландії закрили 1996 року, офіційне вибачення держави прозвучало 2013-го."},{"imdb_id":"tt0308476","title":"The Cuckoo","title_uk":"Зозуля","year":2002,"rating":7.7,"votes":8271,"genres":["Comedy","Drama","Romance","War"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос. / фін. / саамська","theme":"Війна","who_what":"Вихід Фінляндії з війни у вересні 1944 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Фінський снайпер, прикутий до скелі, і заарештований радянський капітан опиняються на хуторі саамки Анні й розмовляють трьома мовами, не розуміючи одне одного. Герої вигадані, натомість Лапландська війна, снайпери-«зозулі» й СМЕРШ реальні. Олександр Рогожкін отримав приз Московського кінофестивалю за режисуру. Кожен герой говорить своєю мовою, і жоден діалог у фільмі не перекладається."},{"imdb_id":"tt0338309","title":"Evil (Ondskan)","title_uk":"Зло","year":2003,"rating":7.7,"votes":45010,"genres":["Drama"],"country":"Швеція/Данія","country_main":"Швеція","region":"Європа","language":"швед.","theme":"Автобіографія","who_what":"За автобіографічним романом Яна Ґійу про насильство в шведській школі-інтернаті 1950-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Швеція кінця 1950-х: підлітка Еріка Понті, якого вітчим б'є вдома, віддають до елітного інтернату, де старшокласники мають офіційне право карати молодших. Мікаель Гофстрем екранізує напівавтобіографічний роман Яна Ґійу, котрий сам пройшов через школу Солбакка. Андреас Вілсон грає хлопця, який вирішує не відповідати ударом — і саме цим доводить систему до сказу. Номінація на «Оскар» за найкращий іншомовний фільм."},{"imdb_id":"tt0301357","title":"Good Bye Lenin!","title_uk":"Гуд бай, Ленін!","year":2003,"rating":7.7,"votes":160770,"genres":["Comedy","Drama","Romance"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Падіння Берлінського муру і зникнення НДР у 1989—1990 роках.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Мати Алекса, переконана соціалістка, впадає в кому напередодні падіння муру, і син відтворює для неї НДР у межах однієї квартири — зі старими банками огірків і фальшивими випусками новин. Родина вигадана, хроніка й побутові деталі справжні. Даніель Брюль став зіркою; дев'ять премій Німецької кіноакадемії та «Сезар»."},{"imdb_id":"tt0350258","title":"Ray","title_uk":"Рей","year":2004,"rating":7.7,"votes":166955,"genres":["Biography","Drama","Music"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя сліпого музиканта Рея Чарльза.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Рей Чарльз осліп у сім років, виріс у злиднях у Флориді й зліпив із госпелу, блюзу та кантрі звучання, якого до нього не існувало. Тейлор Гекфорд бере два десятиліття — від перших записів до героїнової залежності та відмови грати перед сегрегованою залою в Джорджії — і постійно перебиває їх спогадами про дитинство. Джеймі Фокс отримав за роль «Оскар»; сам Чарльз брав участь у підготовці, але до прем'єри не дожив."},{"imdb_id":"tt0318462","title":"The Motorcycle Diaries","title_uk":"Щоденники мотоцикліста","year":2004,"rating":7.7,"votes":109703,"genres":["Adventure","Biography","Drama"],"country":"Аргентина/США/Чилі/Перу/Велика Британія","country_main":"Аргентина","region":"Латинська Америка","language":"ісп.","theme":"Автобіографія","who_what":"Подорож молодого Ернесто Че Ґевари й Альберто Ґранадо Південною Америкою 1952 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"1952 року 23-річний студент-медик Ернесто Ґевара і біохімік Альберто Ґранадо вирушили з Буенос-Айреса на розхитаному «Нортоні» через Чилі, Перу й Колумбію до Венесуели. Вальтер Саллес знімає це як дорожній фільм, де політика лишається на периферії: мідні копальні, руїни Мачу-Пікчу, лепрозорій у Сан-Пабло на Амазонці. Ґаель Ґарсія Берналь грає ще не «Че», а юнака з астмою, який поволі починає бачити нерівність довкола."},{"imdb_id":"tt0378284","title":"Machuca","title_uk":"Мачука","year":2004,"rating":7.7,"votes":13276,"genres":["Biography","Drama","History"],"country":"Чилі/Іспанія/Велика Британія/Франція","country_main":"Чилі","region":"Латинська Америка","language":"ісп.","theme":"Політика та історія","who_what":"Чилі 1973 року напередодні й під час перевороту Піночета, побачене очима двох школярів.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Сантьяго, 1973-й: священник-директор приватної школи бере на навчання дітей із сусіднього нетрища, і хлопчик із заможної родини Ґонсало заводить дружбу з Педро Мачукою. Андрес Вуд спирався на власний шкільний досвід — прототипом отця Макенро став отець Ґерардо Вілан із коледжу Сент-Джордж, який справді проводив такий експеримент. Переворот 11 вересня входить у кадр не через хроніку, а через те, що з класу зникають однокласники. Усе знято з висоти дитячого зросту, і від цього різкіше."},{"imdb_id":"tt0240200","title":"Water","title_uk":"Вода","year":2005,"rating":7.7,"votes":15857,"genres":["Drama","Romance"],"country":"Канада / Індія","country_main":"Канада","region":"Інше","language":"гінді","theme":"Соціальна драма","who_what":"Становище індуїстських удів у колоніальній Індії 1938 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Восьмирічну Чую після смерті чоловіка віддають до ашраму вдів у Варанасі, де жінки живуть із милостині, а молодших змушують до проституції. Героїні вигадані, але самі ашрами, закон про повторні шлюби і поява Ґанді на тлі реальні. Зйомки в Індії зірвали релігійні активісти, тож Діпа Мехта переїхала до Шрі-Ланки; номінація на «Оскар»."},{"imdb_id":"tt0480025","title":"This Is England","title_uk":"Це — Англія","year":2006,"rating":7.7,"votes":135923,"genres":["Crime","Drama"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Напівавтобіографічна історія Шейна Медовза про хлопця в середовищі скінхедів Англії 1983 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Літо 1983-го, англійське приморське містечко: дванадцятирічний Шон, чий батько загинув на Фолклендах, прибивається до компанії скінхедів — спершу цілком мирної й багатонаціональної, поки з тюрми не повертається Комбо з гаслами Національного фронту. Шейн Медоуз писав це з власного підліткового досвіду й брав непрофесіоналів: Томас Тьорґуз до того не грав ніде. Стівен Ґрем робить із Комбо не карикатурного расиста, а зламану людину. Премія BAFTA за найкращий британський фільм."},{"imdb_id":"tt0389557","title":"Black Book","title_uk":"Чорна книга","year":2006,"rating":7.7,"votes":84302,"genres":["Drama","Thriller","War"],"country":"Нідерланди / Німеччина / Велика Британія / Бельгія","country_main":"Нідерланди","region":"Європа","language":"нід., нім.","theme":"Війна","who_what":"Єврейська співачка в нідерландському Опорі 1944 року; сюжет зібрано з реальних історій.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"1944 рік, окупована Голландія: єврейка, що втратила родину, під чужим ім'ям входить до підпілля й влаштовується до штабу СД у Гаазі. Пауль Верговен зі співавтором Герардом Сутеманом збирали матеріал два десятиліття й зліпили героїню з кількох задокументованих випадків. Карісе ван Гаутен грає без ореолу мучениці, а фільм навмисно розмиває межу між Опором і колаборацією — за що вдома його і хвалили, і лаяли."},{"imdb_id":"tt0499375","title":"Guru","title_uk":"Гуру","year":2007,"rating":7.7,"votes":26414,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Історія злету промислового магната, прототипом якого став Дхірубхай Амбані.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Мані Ратнам простежує, як сільський хлопець Ґурукант Десаї їде торгувати спеціями до Туреччини, повертається до Бомбея й будує текстильну імперію, обходячи ліцензійні правила. Прототип очевидний — Дхірубгай Амбані, засновник Reliance, хоча імена й деталі змінені. Абгішек Баччан грає його без осуду: фільм захоплюється зухвалістю героя і водночас рахує ціну, яку платять близькі, а фінальна промова перед комісією ставить питання про межу між підприємливістю й шахрайством."},{"imdb_id":"tt0443706","title":"Zodiac","title_uk":"Зодіак","year":2007,"rating":7.7,"votes":685159,"genres":["Crime","Drama","Mystery","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Полювання поліції та журналістів Сан-Франциско на серійного вбивцю Зодіака.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Наприкінці 1960-х убивця, що називав себе Зодіаком, застрелив і зарізав кількох людей у районі затоки Сан-Франциско й надсилав до газет шифри та листи. Девід Фінчер екранізує книжки карикатуриста Роберта Ґрейсміта (Джейк Джилленгол) і знімає не трилер, а хроніку виснаження: детектив Тоші (Марк Руффало), репортер Ейвері (Роберт Дауні-молодший) і сам Ґрейсміт роками перебирають папери. Кожну дату звіряли з архівами. Справа й досі офіційно не розкрита, а версія фільму щодо головного підозрюваного лишається спірною."},{"imdb_id":"tt0824747","title":"Changeling","title_uk":"Підміна","year":2008,"rating":7.7,"votes":276255,"genres":["Biography","Crime","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Крістін Коллінз шукає зниклого сина в Лос-Анджелесі 1928 року і розкриває вбивства у Вайнвіллі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"У березні 1928-го в Лос-Анджелесі зник дев'ятирічний Волтер Коллінз; за кілька місяців поліція привезла його матері Крістін іншого хлопчика й вимагала визнати сином. Іствуд веде дві лінії: тиск на жінку, яку за впертість запроторили до психіатричної лікарні, і паралельне розкриття вбивств хлопчиків на фермі у Вайнвіллі. Сценарій Дж. Майкла Стражинські виріс із міських архівів і газетних підшивок, а Анджеліна Джолі здобула за роль номінацію на «Оскар»."},{"imdb_id":"tt0914798","title":"The Boy in the Striped Pajamas","title_uk":"Хлопчик у смугастій піжамі","year":2008,"rating":7.7,"votes":277781,"genres":["Drama","History","War"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Голокост","who_what":"Голокост: німецький табір смерті очима родини коменданта, 1942 рік.","basis":"реальне тло, вигадані герої","note":"Історики критикують фільм за фактичну недостовірність табірного побуту.","thriller_flag":false,"decade":"2000-ті","desc":"Марк Герман екранізує роман Джона Бойна: побут родини есесівця біля табору, димарі крематоріїв, пропагандистські фільми про «переселення» євреїв. Восьмирічний Бруно, його батько-комендант і в'язень Шмуль вигадані; саму можливість такої дружби через дріт історики жорстко критикували. Знімали в Будапешті, з Асою Баттерфілдом у головній ролі. Голокост реальний, сюжет — притча, а не свідчення."},{"imdb_id":"tt1124052","title":"City of Life and Death","title_uk":"Місто життя і смерті","year":2009,"rating":7.7,"votes":12567,"genres":["Drama","History","War"],"country":"Китай / Гонконг","country_main":"Китай","region":"Східна Азія","language":"кит., яп.","theme":"Війна","who_what":"Нанкінська різанина 1937 року після захоплення міста японською армією.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Грудень 1937-го: японська армія бере Нанкін, і далі — шість тижнів масових убивств та зґвалтувань. Лу Чуань знімає в чорно-білому й веде кілька ліній: китайський солдат, учителька з міжнародної зони безпеки, німець Йон Рабе з китайським секретарем і японський рядовий Кадокава. Саме остання лінія викликала в Китаї гострі суперечки — режисера звинувачували в тому, що він дав загарбникові співчутливий погляд."},{"imdb_id":"tt1024648","title":"Argo","title_uk":"Арґо","year":2012,"rating":7.7,"votes":671646,"genres":["Biography","Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Операція ЦРУ «Канадський капер» — вивезення шести американських дипломатів з Тегерана 1980 року під виглядом знімальної групи.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Після захоплення посольства США в Тегерані в листопаді 1979-го шестеро дипломатів устигли вислизнути й сховалися в резиденціях канадських колег. Бен Аффлек екранізує операцію ЦРУ, у якій оперативник Тоні Мендес вивіз їх у січні 1980-го під легендою знімальної групи фантастичного фільму «Арґо». Голлівудська лінія з Джоном Ґудменом і Аланом Аркіном дає комічний контрапункт тегеранській напрузі. «Оскар» за найкращий фільм — і докори за применшення ролі Канади та вигадану погоню в аеропорту."},{"imdb_id":"tt3404140","title":"The Attorney","title_uk":"Адвокат","year":2013,"rating":7.7,"votes":8573,"genres":["Crime","Drama","History"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Суд і журналістика","who_what":"Молодий Но Му Хьон (майбутній президент Кореї) захищає студентів у політичній справі «Бурім» 1981 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Пусан, початок 1980-х: успішний податковий адвокат без престижного диплома береться за справу студентів, яких поліція під тортурами змусила зізнатися в прокомуністичній змові — так званий випадок «Бурім» 1981 року. Прототип героя — Но Му Хьон, який через двадцять років став президентом Південної Кореї, хоч у фільмі його названо інакше. Сон Кан Хо веде роль від самовдоволеного ділка до людини, що кричить у залі суду. Понад одинадцять мільйонів глядачів у прокаті; реальних підсудних Верховний суд виправдав лише 2014 року."},{"imdb_id":"tt2980516","title":"The Theory of Everything","title_uk":"Всесвіт Стівена Гокінга","year":2014,"rating":7.7,"votes":510093,"genres":["Biography","Drama","Romance"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Наука і технології","who_what":"Фізик Стівен Гокінг, його наукова праця та шлюб із Джейн Вайлд на тлі бічного аміотрофічного склерозу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Кембридж 1963-го: аспірант Стівен Гокінг знайомиться з філологинею Джейн Вайлд і невдовзі чує, що жити йому лишилося близько двох років. Джеймс Марш екранізує саме її мемуари «Подорож до нескінченності», тож центр історії — не чорні діри, а тридцять років шлюбу, догляду, трьох дітей і поступового віддалення. Едді Редмейн отримав «Оскар» за роль, у якій фізичний розпад показано без пауз на пафос. Наукову частину фільм спрощує, а найгостріші кути в стосунках згладжує."},{"imdb_id":"tt5121000","title":"Aligarh","title_uk":"Алігарх","year":2015,"rating":7.7,"votes":8779,"genres":["Biography","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, англ.","theme":"Соціальна драма","who_what":"Професора Рамчандру Сіраса звільняють з університету через його гомосексуальність.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"У лютому 2010-го професора маратхі Рамчандру Сіраса зняли прихованою камерою вдома з чоловіком і звільнили з Аліґархського мусульманського університету «за аморальність». Хансал Мехта знімає стримано, майже без риторики: Манодж Баджпаї грає самотнього 64-річного чоловіка, який не хоче зватися активістом і не любить слова «гей», а Раджкуммар Рао — журналіста, що веде його справу. Суд поновив Сіраса на посаді; за кілька днів його знайшли мертвим у квартирі."},{"imdb_id":"tt1365050","title":"Beasts of No Nation","title_uk":"Безрідні звірі","year":2015,"rating":7.7,"votes":92155,"genres":["Drama","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Громадянська війна в неназваній західноафриканській країні та вербування дітей-солдатів.","basis":"реальне тло, вигадані герої","note":"Країна й конфлікт узагальнені, без прив'язки до однієї держави.","thriller_flag":false,"decade":"2010-ті","desc":"Кері Фукунаґа екранізує роман Узодінми Ібуеле: буферні зони, безпорадні «миротворці», загони, що вербують дітей, наркотики й ритуали посвяти. Хлопчик Агу і Комендант вигадані, країну не названо, хоча знімали в Гані й відтворено впізнавані ліберійські та сьєрра-леонські практики. Ідріс Ельба в головній ролі; перший ігровий фільм Netflix у широкому релізі. Явище реальне, конкретна війна — ні."},{"imdb_id":"tt6493286","title":"1987: When the Day Comes","title_uk":"1987: Коли настане день","year":2017,"rating":7.7,"votes":8115,"genres":["Drama","History","Thriller"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"корейська","theme":"Політика та історія","who_what":"Смерть студента Пак Чон-чхоля під тортурами й Червневе демократичне повстання в Кореї 1987 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"14 січня 1987-го в поліцейській катівні Сеула загинув студент Пак Чон-чхоль; влада хотіла швидко спалити тіло, але прокурор наполіг на розтині — і офіційна версія посипалася. Чан Джун-хван веде розповідь естафетою: камера щокілька хвилин переходить до наступної людини в ланцюжку — прокурора, лікаря, наглядача, репортера, студентки, — і разом вони складають Червневе повстання, що змусило режим погодитися на прямі вибори. Ансамбль на чолі з Кім Юн-соком; фінал змонтовано з реальною хронікою."},{"imdb_id":"tt4065552","title":"The Unknown Soldier","title_uk":"«Невідомий солдат»","year":2017,"rating":7.7,"votes":14932,"genres":["Drama","War"],"country":"Фінляндія","country_main":"Фінляндія","region":"Європа","language":"фін.","theme":"Війна","who_what":"Фінська війна-продовження 1941–1944 років проти СРСР.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Аку Лоугіміес екранізує роман Вяйньо Лінни й проводить кулеметну роту через усі три роки війни-продовження — від ейфорії наступу на Карелію до відступу 1944-го. Ротні Коскела, Рокка й Хієтанен вигадані, але їхні маршрути збігаються з реальними позиціями фінської армії. Найдорожчий фільм в історії країни; його подивився кожен п'ятий фін. Лінна сам воював на цьому фронті, тож побут і мова солдатів узяті з першоджерела."},{"imdb_id":"tt5311542","title":"Never Look Away","title_uk":"Робота без автора","year":2018,"rating":7.7,"votes":28462,"genres":["Biography","Drama","Romance","Thriller","War"],"country":"Німеччина / Італія","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Музика та мистецтво","who_what":"Доля художника, списана з Ґерхарда Ріхтера, і його тесть — нацистський лікар програми евтаназії.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Флоріан Генкель фон Доннерсмарк простежує три епохи Німеччини очима художника Курта Барнерта: нацистська програма «евтаназії», під яку потрапила його тітка, соцреалізм у НДР, Дюссельдорфська академія 1960-х і народження фотореалістичних полотен. Біографія Барнерта майже дослівно повторює життя Ґерхарда Ріхтера, включно з тим, що тесть героя був причетний до вбивств пацієнток. Ріхтер публічно дистанціювався від фільму; дві номінації на «Оскар», зокрема за операторську роботу Калеба Дешанеля."},{"imdb_id":"tt7098658","title":"Raazi","title_uk":"Раазі","year":2018,"rating":7.7,"votes":37708,"genres":["Action","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, урду","theme":"Війна","who_what":"Індійська студентка виходить заміж за пакистанського офіцера й шпигує напередодні війни 1971 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Сехмат Хан, донька кашмірця, який роками працював на індійську розвідку, у 1971 році вийшла заміж за офіцера пакистанської армії, щоб передавати відомості напередодні війни. Мегна Ґульзар екранізувала роман Гаріндера Сікки «Calling Sehmat», записаний зі слів очевидців, — документального підтвердження цієї історії немає. Алія Бгатт грає двадцятирічну студентку, яка щодня вчиться брехати; фільм цікавить радше ціна цієї роботи, ніж шпигунські трюки."},{"imdb_id":"tt8649186","title":"Corpus Christi","title_uk":"Боже тіло","year":2019,"rating":7.7,"votes":24357,"genres":["Drama"],"country":"Польща / Франція","country_main":"Польща","region":"Європа","language":"польська","theme":"Соціальна драма","who_what":"Юнак із виправної колонії видає себе за священника в польському містечку; натхнено реальними випадками самозванців-ксьондзів.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Двадцятирічний Даніель переживає в колонії для неповнолітніх релігійне навернення, але з судимістю до семінарії не беруть; випадково опинившись у містечку на іншому кінці Польщі, він видає себе за священника. Ян Комаса відштовхується від реальних випадків самозванців у сутані й додає громаду, яка не оговталася після смертельної аварії. Бартош Бєленя грає з такою напругою в очах, що проповіді самозванця звучать переконливіше за офіційні. Номінація на «Оскар» за найкращий міжнародний фільм."},{"imdb_id":"tt8941440","title":"Virus","title_uk":"Вірус","year":2019,"rating":7.7,"votes":5957,"genres":["Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Медицина та виживання","who_what":"Спалах вірусу Ніпа в Кожікоде (Керала) 2018 року і робота медиків.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Кожікоде, травень 2018-го: у лікарню привозять пацієнта з невідомою гарячкою, і за кілька тижнів вірус Ніпа вбиває сімнадцятьох із вісімнадцяти заражених. Ашік Абу будує мозаїку без головного героя — медсестри, епідеміологи, водій швидкої, чиновниця охорони здоров'я, родини на карантині, — а паралельно веде майже детективну лінію пошуку нульового пацієнта. У великому керальському ансамблі Парваті, Реваті й Товіно Томас. Знято невдовзі після подій, з консультаціями учасників."},{"imdb_id":"tt7581552","title":"Unda","title_uk":"Унда","year":2019,"rating":7.7,"votes":5087,"genres":["Action","Comedy","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Політика та історія","who_what":"Загін поліції з Керали, відправлений охороняти вибори у маоїстському районі Чхаттісгарха майже без набоїв.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"2014 рік: загін поліції з Керали відправляють на вибори до маоїстського району Чхаттісгарха — без спорядження, без спільної мови з місцевими й із жменею набоїв, від якої після першої ж стрілянини лишається вісім. Халід Рахман зняв це за газетним репортажем Malayala Manorama як чорну комедію, де смішне й принизливе не відділити одне від одного. Мамутті грає субінспектора, який замість подвигів рахує патрони й пише рапорти. Під комедією — розмова про кастову зневагу й державу, що відправила людей у поле й забула."},{"imdb_id":"tt9581076","title":"So Long, My Son","title_uk":"«Прощавай, мій сину»","year":2019,"rating":7.7,"votes":6186,"genres":["Drama"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"кит.","theme":"Соціальна драма","who_what":"Політика «одна сім'я — одна дитина», масові звільнення з держпідприємств у 1990-х і три десятиліття китайських реформ.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ван Сяошуай простежує тридцять років двох робітничих родин із північного заводського міста — від примусового аборту за квотою до приватизації й переїзду на південь. Яоцзюнь і Ліюнь втрачають сина, а потім і роботу, і мовчки несуть провину, яка насправді належить чужій родині. Ван Цзінчунь і Юн Мей отримали обидва акторські «Срібні ведмеді» Берлінале. Політика й реформи реальні, родини вигадані."},{"imdb_id":"tt1070874","title":"The Trial of the Chicago 7","title_uk":"Суд над чиказькою сімкою","year":2020,"rating":7.7,"votes":206810,"genres":["Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Судовий процес 1969 року над організаторами антивоєнних протестів під час з'їзду Демократичної партії в Чикаго.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Розгін антивоєнних протестів під час з'їзду Демократичної партії в Чикаго 1968 року обернувся для організаторів — від Тома Гейдена до Еббі Гоффмана — федеральним звинуваченням у змові. Аарон Соркін тримає майже все в залі суду, де суддя Джуліус Гоффман веде процес відверто упереджено, а Боббі Сіла в якийсь момент прив'язують до стільця з кляпом. В ансамблі Саша Барон Коен, Едді Редмейн і Френк Ланджелла. Хронологію процесу стиснуто, а фінальний жест у залі — винахід сценариста."},{"imdb_id":"tt20561198","title":"The Promised Land","title_uk":"Земля обітована","year":2023,"rating":7.7,"votes":41825,"genres":["Action","Drama","History"],"country":"Данія","country_main":"Данія","region":"Європа","language":"дан.","theme":"Політика та історія","who_what":"Капітан Людвіг фон Кален у XVIII столітті намагається освоїти безплідні ютландські пустища всупереч місцевому феодалу.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"1755 рік: відставний капітан Людвіг фон Кален із королівського дозволу вирушає освоювати ютландські пустища, де до нього ніхто не втримався. Кален — реальна постать, яка справді намагалася виростити врожай на вересових пустирях за Фредеріка V, але Ніколай Арсель екранізував роман Іди Єссен «Капітан і Анн Барбара», тож феодал Фредерік де Шинкель і майже всі людські стосунки тут вигадані. Мадс Міккельсен грає упертість, що межує з байдужістю до себе. Конкурс Венеції й данське висування на «Оскар»."},{"imdb_id":"tt10786774","title":"Sam Bahadur","title_uk":"Сем Бахадур","year":2023,"rating":7.7,"votes":22036,"genres":["Biography","Drama","History","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Життя фельдмаршала Сема Манекшоу, переможця війни 1971 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Сем Манекшоу пройшов шлях від бірманського фронту 1942-го, де його прошило кулеметною чергою, до посади начальника штабу армії, який 1971 року відмовив Індірі Ґанді у весняному наступі й дочекався сухого сезону — та війна тривала тринадцять днів. Меґхна Ґулзар охоплює майже сорок років служби, тримаючись радше епізодів і анекдотів, ніж однієї драматичної лінії. Вікі Каушал відтворює характерну манеру говорити й тримати спину. Індіру Ґанді грає Фатіма Сана Шейх."},{"imdb_id":"tt21800162","title":"There's Still Tomorrow","title_uk":"«Ще є завтра»","year":2023,"rating":7.7,"votes":18791,"genres":["Comedy","Drama","History"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Політика та історія","who_what":"Рим 1946 року напередодні референдуму, на якому італійки вперше отримали право голосу.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Паола Кортеллезі знімає чорно-білий режисерський дебют у стилістиці неореалізму: американська окупаційна зона, продуктові картки, побутове насильство як норма. Делія терпить чоловіка й свекра та збирає гроші доньці на посаг, а лист, який глядач приймає за любовний, виявляється повідомленням про виборчу дільницю. Найкасовіший італійський фільм 2023 року й шість «Давидів ді Донателло». Референдум 2 червня 1946-го реальний, родина вигадана."},{"imdb_id":"tt14753612","title":"Swatantrya Veer Savarkar","title_uk":"Сватантр'я Вір Саваркар","year":2024,"rating":7.7,"votes":18312,"genres":["Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Життя індійського націоналіста Вінаяка Дамодара Саваркара — від навчання в Лондоні до ув'язнення на Андаманах.","basis":"реальна історія","note":"Відверта агіографія: фільм приписує Саваркару вплив на Бгагата Сінгха й Субхаса Чандру Бозе та обходить його прохання про помилування перед британцями.","thriller_flag":false,"decade":"2020-ті","desc":"Вінаяк Дамодар Саваркар навчався права в Лондоні, писав про повстання 1857-го як про війну за незалежність, а 1911 року отримав два довічні терміни й потрапив до Целюлярної в'язниці на Андаманах. Рандіп Гуда, для якого це режисерський дебют, зіграв головну роль сам і схуд на понад двадцять кілограмів. Фільм відкрито полемізує з канонічною версією історії Індії: применшує роль Ґанді й приписує Саваркару вплив на кілька поколінь революціонерів. Історики розкритикували цю оптику, зокрема через те, як подано його прохання про помилування."},{"imdb_id":"tt28007064","title":"Superboys of Malegaon","title_uk":"Супербої з Малегаона","year":2024,"rating":7.7,"votes":8945,"genres":["Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Музика та мистецтво","who_what":"Насір Шейх і друзі знімають саморобні пародії на болівудські хіти в текстильному містечку Малегаон.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Малеґаон, текстильне містечко в Махараштрі, 1997 рік: власник відеозалу Насір Шейх бере напрокат камеру й знімає з друзями «Малеґаон ке Шолай» — пародійний ремейк класики місцевою говіркою, за копійки. Ріма Каґті й сценарист Варун Ґровер відштовхнулися від документальної стрічки Файзи Ахмад Хан «Supermen of Malegaon» і довели історію до зйомок саморобного «Супермена». Адарш Ґаурав грає Насіра, Вініт Кумар Сінґх — ображеного сценариста Фароґа, чия лінія й рухає другу половину. Прем'єра відбулася в Торонто 2024-го."},{"imdb_id":"tt23782140","title":"Vaazhai","title_uk":"Ваажай","year":2024,"rating":7.7,"votes":5701,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Соціальна драма","who_what":"Реальний випадок із дитинства режисера Марі Сельвараджа: діти-наймити на бананових плантаціях Тамілнаду й загибель його шкільного друга.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Марі Сельварадж повернувся у власне дитинство на півдні Тамілнаду 1990-х: школярі по вихідних тягають на спині зрізані банани до вантажівок, бо без цих грошей родина не витягне. Фільм тримається на буденності — уроці, поході в кіно, першій закоханості, — і саме тому рахунок, який зрештою виставляє плантація, б'є так сильно. Режисер знімав це як борг перед шкільним другом, чия загибель лишилася в нього перед очима; головні ролі зіграли непрофесійні діти."},{"imdb_id":"tt0104691","title":"The Last of the Mohicans","title_uk":"Останній з могікан","year":1992,"rating":7.6,"votes":209456,"genres":["Action","Adventure","Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Війна з французами й індіанцями: облога форту Вільям-Генрі 1757 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Майкл Манн екранізував Купера: облога форту, капітуляція під гарантії Монкальма і різанина колони, що відходила, справді відбулися. Соколине Око, Ункас і сестри Манро — літературні герої, а полковник Манро й Монкальм історичні. Деніел Дей-Льюїс місяцями вчився жити в лісі; «Оскар» за звук і фінал без жодного слова."},{"imdb_id":"tt0105185","title":"Psy","title_uk":"Пси","year":1992,"rating":7.6,"votes":6168,"genres":["Action","Crime","Drama","Thriller"],"country":"Польща","country_main":"Польща","region":"Європа","language":"пол.","theme":"Кримінал","who_what":"Люстрація співробітників польської держбезпеки після падіння комунізму 1990 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"1990-ті","desc":"Офіцер СБ Франц Маурер проходить перевірку, залишається в новій поліції, а його колишній напарник іде в мафію. Герої вигадані, але сама верифікація 1990 року, коли тисячі есбістів переатестовували в поліцію, реальна. Владислав Пасіковський зняв культовий бойовик, а репліки Богуслава Лінди розійшлися на приказки. Фільм започаткував популярну польську серію про Маурера."},{"imdb_id":"tt0107007","title":"Gettysburg","title_uk":"Ґеттісберг","year":1993,"rating":7.6,"votes":32554,"genres":["Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Три дні битви під Ґеттісберґом 1863 року — переломного бою Громадянської війни в США.","basis":"реальна історія","note":"Діалоги здебільшого вигадані романістом, а трактування генерала Лонгстріта відображає позицію книжки.","thriller_flag":false,"decade":"1990-ті","desc":"Битва під Ґеттісберґом 1–3 липня 1863 року — оборона висоти Літл-Раунд-Топ полком Джошуа Лоуренса Чемберлена й самогубна атака Пікетта — переказана за романом Майкла Шаари «Убивчі янголи». Рональд Максвелл знімав на справжньому полі бою за участі тисяч реконструкторів; чотиригодинна стрічка задумувалася для телебачення, але вийшла в прокат. Джефф Деніелз грає Чемберлена, Мартін Шин — генерала Лі."},{"imdb_id":"tt0114863","title":"Ulysses' Gaze","title_uk":"Погляд Улісса","year":1995,"rating":7.6,"votes":8179,"genres":["Drama","History","War"],"country":"Греція / Франція / Італія","country_main":"Греція","region":"Європа","language":"грец.","theme":"Музика та мистецтво","who_what":"Балканські війни 1990-х і облога Сараєва як фінал «століття кіно».","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Режисер, названий лише літерою А., їде з Греції через Скоп'є, Белград і Дунай до обложеного Сараєва, шукаючи непроявлені плівки братів Манакі. Сам А. вигаданий, брати Манакі й війна довкола — реальні. Тео Ангелопулос зняв фільм довгими планами; Гран-прі Канн 1995 року, у головній ролі Гарві Кейтель."},{"imdb_id":"tt0117631","title":"Shine","title_uk":"Блиск","year":1996,"rating":7.6,"votes":59307,"genres":["Biography","Drama","Music"],"country":"Австралія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ.","theme":"Музика та мистецтво","who_what":"Австралійський піаніст Девід Гельфготт, його психічний зрив і повернення на сцену через багато років.","basis":"реальна історія","note":"Родина Гельфготта, зокрема сестра Маргарет, заперечувала зображення батька Пітера й наполягала, що фільм спотворив його роль.","thriller_flag":false,"decade":"1990-ті","desc":"Гельфготт, син уцілілого в Голокості батька, поїхав учитися до лондонського Королівського коледжу музики, зіграв Третій концерт Рахманінова і зламався; далі були роки в психіатричних закладах і повільне повернення до фортепіано у 1980-х. Скотт Гікс будує фільм на розривах пам'яті, Джеффрі Раш отримав «Оскар» за головну роль. Сестра піаніста Маргарет публічно заперечила екранний образ батька як домашнього тирана."},{"imdb_id":"tt0124207","title":"The Thief","title_uk":"Злодій","year":1997,"rating":7.6,"votes":6013,"genres":["Crime","Drama"],"country":"Росія / Франція","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Політика та історія","who_what":"Повоєнний СРСР 1952 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Мати з шестирічним сином знайомиться в потязі з красенем-офіцером, який виявляється злодієм і використовує їх для квартирних крадіжок. Родина вигадана, а комуналки, татуювання зі Сталіним і безбатьківщина повоєнного покоління — впізнаваний фон. Володимир Машков у головній ролі; номінація на «Оскар» за іншомовний фільм. Павло Чухрай — син фронтового кінорежисера Григорія Чухрая."},{"imdb_id":"tt0150433","title":"Earth","title_uk":"Земля","year":1998,"rating":7.6,"votes":8451,"genres":["Drama","History","Romance","War"],"country":"Індія / Канада","country_main":"Індія","region":"Індія","language":"гінді, урду, англ.","theme":"Політика та історія","who_what":"Поділ Британської Індії в серпні 1947 року й міжрелігійна різанина в Лахорі, побачені очима дитини.","basis":"натхненний реальними подіями","note":"Родина й персонажі вигадані; поділ, потяги з убитими та хвиля насильства в Пенджабі відтворені за історичними свідченнями.","thriller_flag":false,"decade":"1990-ті","desc":"Серпень 1947 року, Лахор: поділ Британської Індії розрізає Пенджаб, і сусіди — парси, індуси, сикхи та мусульмани, які ще вчора сиділи в одному парку, — опиняються по різні боки різанини. Діпа Мехта екранізувала напівавтобіографічний роман Бапсі Сідхви «Cracking India», зберігши погляд восьмирічної парсійки Ленні. Амір Хан у нетиповій для себе ролі продавця морозива, Нандіта Дас — няня Шанта. Друга частина трилогії Мехти «Вогонь — Земля — Вода»."},{"imdb_id":"tt0120863","title":"The Thin Red Line","title_uk":"Тонка червона лінія","year":1998,"rating":7.6,"votes":213678,"genres":["Drama","History","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Битва за Ґуадалканал 1942—1943 років на Тихому океані.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Терренс Малік екранізував роман Джеймса Джонса про штурм пагорба на Ґуадалканалі, зберігши хід кампанії, але вигадавши роту й усіх її солдатів. Рядовий Вітт, сержант Велш і підполковник Толл — літературні постаті, крізь чиї внутрішні монологи війна постає як зіткнення з природою. Фільм повернув Маліка в кіно після двадцятирічної паузи; сім номінацій на «Оскар»."},{"imdb_id":"tt0120125","title":"The Barber of Siberia","title_uk":"Сибірський цирульник","year":1998,"rating":7.6,"votes":13448,"genres":["Comedy","Drama","History","Romance"],"country":"Росія / Франція / Італія","country_main":"Росія","region":"Східна Європа","language":"рос. / англ.","theme":"Політика та історія","who_what":"Росія Олександра III у 1885 році: юнкерські училища й імперський побут.","basis":"реальне тло, вигадані герої","note":"Історичні деталі підпорядковані відверто міфологізованому образу імперії.","thriller_flag":false,"decade":"1990-ті","desc":"Американка Джейн приїздить до Москви заради концесії на машину для вирубки тайги, а юнкер Толстой закохується в неї і потрапляє на каторгу. Герої вигадані, натомість Олександр III, масляна на Красній площі та юнкерська муштра відтворені з розмахом. Один із найдорожчих російських фільмів 1990-х; Микита Михалков зіграв імператора сам."},{"imdb_id":"tt0170705","title":"Train of Life","title_uk":"Потяг життя","year":1998,"rating":7.6,"votes":9974,"genres":["Comedy","Drama","War"],"country":"Франція / Бельгія / Румунія","country_main":"Франція","region":"Європа","language":"фр.","theme":"Голокост","who_what":"Депортація євреїв Східної Європи 1941 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Мешканці штетла вирішують самі спорядити фальшивий депортаційний потяг із «німецькою» охороною з-поміж своїх і доїхати ним до Палестини. Село й задум вигадані, але приреченість штетлів і механіка депортацій — ні. Раду Міхайляну зняв притчу, яку часто порівнюють із «Життя прекрасне»; фінал перевертає весь фільм. Раду Міхайляну — румунський режисер, що емігрував до Франції."},{"imdb_id":"tt0174856","title":"The Hurricane","title_uk":"Ураган","year":1999,"rating":7.6,"votes":108968,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Боксер Рубін «Ураган» Картер, засуджений 1967 року за потрійне вбивство і виправданий 1985-го.","basis":"реальна історія","note":"Бій із Джої Джарделлою, збірний образ детектива Делла Пески та роль канадців суперечать документованим фактам.","thriller_flag":false,"decade":"1990-ті","desc":"1966 року в барі міста Патерсон, штат Нью-Джерсі, застрелили трьох людей; боксера Рубіна Картера і Джона Артіса засудили до довічного, і Картер провів за ґратами майже двадцять років, доки федеральний суддя не скасував вирок 1985 року. Норман Джуїсон зосередився на дружбі Картера з підлітком Лезрою Мартіном і канадськими активістами. Дензел Вашингтон отримав за роль «Золотий глобус»."},{"imdb_id":"tt0247613","title":"Peppermint Candy","title_uk":"М'ятний льодяник","year":1999,"rating":7.6,"votes":12823,"genres":["Drama"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Політика та історія","who_what":"Двадцять років Південної Кореї — від придушення повстання в Кванджу 1980 року до кризи 1997-го.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Історія Йон-хо розгортається назад у часі: від самогубства на колії до дня, коли переляканий солдат випадково вбиває дівчину в оточеному Кванджу. Герой вигаданий, але хронологія — бійня 1980-го, катування в поліції, банкрутства після азійської кризи — реальна. Другий фільм Лі Чхан-дона, який згодом став міністром культури."},{"imdb_id":"tt0188030","title":"Butterfly","title_uk":"Язик метелика","year":1999,"rating":7.6,"votes":10742,"genres":["Drama","War"],"country":"Іспанія","country_main":"Іспанія","region":"Європа","language":"ісп.","theme":"Політика та історія","who_what":"Останні місяці Другої Іспанської Республіки перед заколотом 1936 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Хлопчик Монтчо прив'язується до старого вчителя-республіканця дона Ґреґоріо, який учить його дивитися на метеликів і не боятися. Коли до галісійського містечка приходять франкісти, родина рятується єдиним способом — вигукнувши прокляття вслід арештованому. Герої вигадані за оповіданнями Мануеля Ріваса; «Ґойя» за сценарій, у головній ролі Фернандо Фернан Ґомес."},{"imdb_id":"tt0234288","title":"Divided We Fall","title_uk":"Мусимо допомагати одне одному","year":2000,"rating":7.6,"votes":5576,"genres":["Comedy","Drama","War"],"country":"Чехія","country_main":"Чехія","region":"Європа","language":"чеськ.","theme":"Голокост","who_what":"Нацистська окупація Чехії та переслідування євреїв, 1943—1945 роки.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Бездітне подружжя ховає в комірчині втікача з табору, а щоб відвести підозри, чоловік іде працювати до колаборанта і вдає, що дружина завагітніла від нього. Персонажі вигадані, натомість система доносів, протекторатна адміністрація і хаос перших днів після звільнення відтворені точно. Номінація на «Оскар» за іншомовний фільм."},{"imdb_id":"tt0280491","title":"Bloody Sunday","title_uk":"Кривава неділя","year":2002,"rating":7.6,"votes":26843,"genres":["Drama","History","War"],"country":"Велика Британія/Ірландія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Розстріл британськими десантниками мирної демонстрації в Деррі 30 січня 1972 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"30 січня 1972 року в Деррі британські десантники відкрили вогонь по учасниках маршу за громадянські права: тринадцятеро загинули на місці, ще один помер згодом. Пол Ґрінґрасс веде хроніку одного дня одразу з чотирьох боків — від депутата Івана Купера (Джеймс Несбітт) до командирів парашутного полку, ручною камерою і майже без музики. «Золотий ведмідь» Берлінале 2002 року, поділений із «Віднесеними привидами». Фільм вийшов задовго до звіту Севілла, який 2010-го визнав ті постріли невиправданими."},{"imdb_id":"tt0298845","title":"In America","title_uk":"В Америці","year":2002,"rating":7.6,"votes":44485,"genres":["Drama"],"country":"Ірландія/Велика Британія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Автобіографія","who_what":"Напівавтобіографічна історія Джима Шерідана про переїзд ірландської родини до Нью-Йорка після смерті сина.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джим Шерідан написав сценарій разом із доньками Наомі та Кірстен, переклавши на екран власний переїзд до Нью-Йорка й смерть молодшого брата Френкі. Ірландська сім'я нелегально селиться в облупленому будинку в Пекельній кухні, і майже все ми бачимо очима старшої доньки з відеокамерою. Саманта Мортон, Педді Консідайн і Джимон Гонсу грають без натиску на сльозу; три номінації на «Оскар». Реальний Френкі був братом режисера — у фільмі він став сином."},{"imdb_id":"tt0293007","title":"Carandiru","title_uk":"Карандіру","year":2003,"rating":7.6,"votes":25112,"genres":["Crime","Drama"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"португ.","theme":"Кримінал","who_what":"Різанина у в'язниці Карандіру в Сан-Паулу 1992 року, коли поліція вбила 111 в'язнів; за книгою лікаря Драузіу Варелли.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"2 жовтня 1992 року військова поліція штурмувала переповнену в'язницю Карандіру в Сан-Паулу: загинуло 111 ув'язнених, серед поліціянтів жертв не було. Ектор Бабенко екранізував спогади лікаря Драузіу Варелли, який роками лікував там хворих на СНІД, тож більшу частину екранного часу займає не бійня, а окремі камери та історії, розказані самими в'язнями. Штурм показано наприкінці — як розв'язку до зібраної галереї портретів."},{"imdb_id":"tt0308644","title":"Finding Neverland","title_uk":"У пошуках Неверленду","year":2004,"rating":7.6,"votes":217975,"genres":["Biography","Drama","Family"],"country":"Велика Британія/США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Музика та мистецтво","who_what":"Драматург Дж. М. Баррі і родина Ллуелін-Дейвіс, які надихнули «Пітера Пена».","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Лондон 1903 року: драматург Дж. М. Баррі знайомиться в Кенсінгтонських садах із удовою Сільвією Ллуелін-Дейвіс та її синами, і з ігор із хлопцями виростає «Пітер Пен». Марк Форстер знімає історію про те, звідки береться вигадка, підмішуючи до побуту фантазійні вставки. Джонні Депп грає майже без ексцентрики, поруч Кейт Вінслет і Дастін Гоффман; «Оскар» дістався музиці Яна Качмарека. Насправді синів було п'ятеро, а їхній батько був живий, коли Баррі увійшов у родину."},{"imdb_id":"tt0386651","title":"Mountain Patrol (Kekexili)","title_uk":"Кекексілі: Гірський патруль","year":2004,"rating":7.6,"votes":5775,"genres":["Action","Drama"],"country":"Китай/Гонконг","country_main":"Китай","region":"Східна Азія","language":"кит./тибет.","theme":"Соціальна драма","who_what":"Добровольчий патруль, який у 1990-х захищав тибетських антилоп від браконьєрів на плато Кекексілі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"На плато Хох-Сіл у Цінхаї добровольчий загін тибетців у 1990-х без зарплат і повноважень ганявся за браконьєрами, які вибивали антилоп чиру заради вовни шахтуш. Лу Чуань веде глядача туди разом із пекінським журналістом — і сюжет швидко перестає ділити людей на героїв та лиходіїв. Знімали на висоті понад чотири тисячі метрів, майже документально, з непрофесійними акторами. Гран-прі Токійського фестивалю і кілька «Золотих коней»."},{"imdb_id":"tt0442286","title":"The Hidden Blade","title_uk":"Прихований клинок","year":2004,"rating":7.6,"votes":7663,"genres":["Drama","History","Romance"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"яп.","theme":"Політика та історія","who_what":"Реставрація Мейдзі: перехід японської армії від мечів до вогнепальної зброї.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Самурай Катаґірі Мунедзо вчиться стріляти з гармати під наглядом інструктора-західника, поки клан змушує його вбити давнього товариша-бунтівника. Герої вигадані, але муштра за європейським зразком, станові заборони на шлюб і поява артилерії — реальні прикмети 1860-х. Другий фільм самурайської трилогії Йодзі Ямади. В основі — оповідання Сюхея Фудзісави, як і в попередній частині."},{"imdb_id":"tt0344510","title":"A Very Long Engagement","title_uk":"Дуже довгі заручини","year":2004,"rating":7.6,"votes":78245,"genres":["Drama","Mystery","Romance","War"],"country":"Франція / США","country_main":"Франція","region":"Європа","language":"фр.","theme":"Війна","who_what":"Перша світова війна: покарання солдатів-самокалічників на Соммі 1917 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Матільда відмовляється вірити, що наречений загинув, і роками розшукує свідків того, як п'ятьох засуджених виштовхнули в нейтральну смугу. Герої вигадані Себастьяном Жапрізо, але військові трибунали, самострільники й показові розстріли справді були. Жан-П'єр Жене й Одрі Тоту після «Амелі»; дві номінації на «Оскар» і п'ять «Сезарів»."},{"imdb_id":"tt0426578","title":"Sophie Scholl - Die letzten Tage","title_uk":"Софі Шолль: Останні дні","year":2005,"rating":7.6,"votes":29980,"genres":["Biography","Crime","Drama"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Війна","who_what":"Останні шість днів життя Софі Шолль, учасниці антинацистської «Білої троянди», страченої 1943 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"18 лютого 1943 року Софі Шолль із братом Гансом розкидали листівки «Білої троянди» в атріумі Мюнхенського університету — через чотири дні їх стратили. Марк Ротемунд відтворює ці шість днів майже дослівно за протоколами допитів гестапо, які знайшли в архівах НДР після 1990 року. Головне тут — камерні поєдинки Софі зі слідчим Робертом Морем, де вона поступово перестає рятувати себе; Юлія Єнч за цю роль здобула «Срібного ведмедя» в Берліні."},{"imdb_id":"tt0424205","title":"Joyeux Noel","title_uk":"Щасливого Різдва","year":2005,"rating":7.6,"votes":34466,"genres":["Drama","History","Music"],"country":"Франція/Німеччина/Велика Британія/Бельгія/Румунія","country_main":"Франція","region":"Європа","language":"франц./нім./англ.","theme":"Війна","who_what":"Різдвяне перемир'я 1914 року, коли французькі, шотландські й німецькі солдати вийшли з окопів.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Різдво 1914-го на ділянці фронту, де окопи французів, шотландців і німців розділяє кількадесят метрів: спів з одного боку, волинка з другого — і солдати виходять на нічийну землю ховати вбитих та обмінюватися дрібницями. Крістіан Каріон зшив в один епізод кілька задокументованих перемир'їв і додав вигаданих героїв — німецького тенора та його партнерку-сопрано (Діана Крюґер). Далі йде реакція командування, яке такого братання не пробачило. Номінація на «Оскар» від Франції."},{"imdb_id":"tt0399295","title":"Lord of War","title_uk":"Збройний барон","year":2005,"rating":7.6,"votes":362065,"genres":["Crime","Drama"],"country":"США/Франція","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Збірний образ міжнародних торговців зброєю, зокрема Віктора Бута.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Юрій Орлов, торговець зброєю з української родини в Брайтон-Біч, — персонаж вигаданий, зліплений Ендрю Ніколом із біографій кількох реальних дилерів, серед них Віктор Бут. Розповідь іде від першої особи, з холодною іронією проводячи глядача крізь розпад СРСР, африканські війни й схеми з підробленими сертифікатами кінцевого користувача. Відкриття фільму — «життєвий шлях» патрона від конвеєра до пострілу, знятий одним планом."},{"imdb_id":"tt0420901","title":"Shooting Dogs","title_uk":"Стріляти в собак (За воротами)","year":2005,"rating":7.6,"votes":12459,"genres":["Drama","History","War"],"country":"Велика Британія/Німеччина","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Війна","who_what":"Різанина в технічній школі Кігалі під час геноциду в Руанді 1994 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"У квітні 1994-го в технічній школі Кігалі під захистом бельгійських миротворців ООН зібралися понад дві тисячі тутсі; щойно контингент вивели, майже всіх убили за кілька годин. Майкл Кейтон-Джонс знімав саме там, із людьми, які пережили геноцид, і веде розповідь через католицького священника (Джон Герт) і молодого британського вчителя. Головне питання фільму — не про вбивць, а про тих, хто мав право поїхати. Закид критиків звичний для теми: у центрі кадру знову європейці."},{"imdb_id":"tt0475783","title":"Welcome to Dongmakgol","title_uk":"Ласкаво просимо в Донмакколь","year":2005,"rating":7.6,"votes":7948,"genres":["Comedy","Drama","War"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Війна","who_what":"Корейська війна 1950 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Солдати Півночі, Півдня і збитий американський пілот опиняються в гірському селі, яке досі не знає, що триває війна. Село Донмакколь вигадане, а бомбардування, наступ сил ООН і паніка втікачів — ні. Фільм виріс із популярної п'єси, музику написав Дзьо Хісаїсі, і в прокаті 2005 року стрічка стала однією з найкасовіших у Кореї."},{"imdb_id":"tt0455590","title":"The Last King of Scotland","title_uk":"Останній король Шотландії","year":2006,"rating":7.6,"votes":206922,"genres":["Biography","Drama","History"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Диктатура Іді Аміна в Уганді 1970-х очима його молодого особистого лікаря.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Іді Амін захопив владу в Уганді 1971 року, і за вісім років його правління загинули сотні тисяч людей. Кевін Макдональд дивиться на диктатуру очима вигаданого шотландського лікаря Ніколаса Ґарріґана, який випадково стає особистим медиком президента, — персонаж придуманий Джайлзом Фоденом у романі, хоча західні наближені в Аміна справді були. Форест Вітакер отримав «Оскар» за роль, у якій обаяння і жах не відокремлені одне від одного."},{"imdb_id":"tt0475276","title":"United 93","title_uk":"Рейс 93","year":2006,"rating":7.6,"votes":116029,"genres":["Action","Crime","Drama","History","Thriller"],"country":"США / Велика Британія / Франція","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Реальний час захоплення рейсу United 93 та спротиву пасажирів 11 вересня 2001 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Пол Ґрінґрасс відтворює ранок 11 вересня 2001 року майже в реальному часі, паралельно монтуючи салон рейсу United 93, диспетчерські центри й командний пункт NEADS. Частину ролей грають самі учасники подій — зокрема керівник оперативного центру FAA Бен Слайні. Відомих облич у салоні немає, музики майже немає, камера ручна. Що саме сталося в кабіні в останні хвилини, достеменно невідомо: режисер спирався на бортовий самописець і телефонні дзвінки пасажирів."},{"imdb_id":"tt0421082","title":"Control","title_uk":"Контроль","year":2007,"rating":7.6,"votes":72092,"genres":["Biography","Drama","Music"],"country":"Велика Британія / США / Японія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя і самогубство Іена Кертіса, вокаліста гурту Joy Division.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Іен Кертіс повісився в Макклсфілді у травні 1980 року, за кілька днів до першого туру Joy Division Америкою; йому було двадцять три. Антон Корбейн, який колись фотографував гурт, зняв дебютний фільм за спогадами вдови Дебори Кертіс — тут переважає побут: ранній шлюб, епілепсія, робота в бюро працевлаштування. Чорно-біла картинка й Сем Райлі, який сам співає в кадрі, повертають рок-міфу масштаб дуже буденного життя."},{"imdb_id":"tt0463998","title":"Freedom Writers","title_uk":"Письменники свободи","year":2007,"rating":7.6,"votes":93475,"genres":["Biography","Crime","Drama"],"country":"США / Німеччина","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Вчителька Ерін Ґрувелл і щоденники її учнів у Лонг-Біч після заворушень у Лос-Анджелесі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Ерін Ґрувелл прийшла 1994 року в школу Вілсона в Лонг-Біч — місто ще не відійшло від заворушень 1992-го, а її клас поділений на етнічні угруповання, які між собою не розмовляють. Вона роздає учням чисті зошити й просить писати про власне життя щодня; з тих записів згодом вийшла книжка «Щоденник письменників свободи». Гіларі Свонк грає без учительського пафосу, хоча сама схема «натхненний педагог рятує клас» звучить упізнавано. Реальний клас читав щоденник Анни Франк і приймав у себе Міп Гіс."},{"imdb_id":"tt0870111","title":"Frost/Nixon","title_uk":"Фрост проти Ніксона","year":2008,"rating":7.6,"votes":116301,"genres":["Biography","Drama","History"],"country":"США / Велика Британія / Франція","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Телеінтерв'ю Девіда Фроста з Річардом Ніксоном 1977 року про Вотергейт.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"1977 рік: британський телеведучий Девід Фрост, якого в США мали за легковаговика, викупає в Річарда Ніксона право на серію інтерв'ю й ставить на кін власні гроші. Рон Говард екранізує п'єсу Пітера Морґана як поєдинок двох людей, що обом потрібна реабілітація, — з підготовкою, розвідкою й останнім раундом про Вотергейт. Френк Ланджелла і Майкл Шин перенесли ролі просто зі сцени. Нічний п'яний дзвінок Ніксона до Фроста драматурги вигадали."},{"imdb_id":"tt1266583","title":"Mumbai Meri Jaan","title_uk":"Мумбаї, любов моя","year":2008,"rating":7.6,"votes":6790,"genres":["Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"П'ять доль після серії вибухів у приміських потягах Мумбаї 11 липня 2006 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"11 липня 2006 року сім вибухів у приміських потягах Мумбаї забрали майже дві сотні життів. Нішікант Камат будує фільм не навколо теракту, а навколо п'ятьох людей після нього: тележурналістки, вуличного торговця кавою, офісного клерка, охопленого підозрою до сусідів-мусульман, безробітного й поліціянта напередодні пенсії. Пареш Равал, Кей Кей Менон, Ірфан Хан і Мадгаван грають без героїзму — про страх, упередження й повернення до звичного життя."},{"imdb_id":"tt1063669","title":"The Wave","title_uk":"Хвиля","year":2008,"rating":7.6,"votes":122644,"genres":["Drama","Thriller"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Соціальна драма","who_what":"Шкільний експеримент про автократію за мотивами реального «Третьої хвилі» Рона Джонса 1967 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Рон Джонс 1967 року за п'ять днів показав каліфорнійським старшокласникам, як працює автократія, — німецький фільм переносить цей експеримент у сучасну гімназію, де вчитель Райнер Венґер веде тижневий факультатив. Спільна форма, вітання, назва «Хвиля» — і клас, який щойно позіхав, за кілька днів починає ділити світ на своїх і чужих. Юрґен Фоґель грає педагога, що надто пізно помічає, куди все зайшло. Розв'язка в Денніса Ґанзеля куди різкіша за те, чим завершився справжній експеримент."},{"imdb_id":"tt0976051","title":"The Reader","title_uk":"Читець","year":2008,"rating":7.6,"votes":275406,"genres":["Drama","Mystery","Romance"],"country":"США / Німеччина","country_main":"США","region":"США","language":"англ.","theme":"Голокост","who_what":"Повоєнна Німеччина і процеси над наглядачками концтаборів у 1960-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Стівен Долдрі показує ФРН 1958-го, а потім судові процеси проти жінок-наглядачок і покоління студентів, яке дізнається про провину батьків. Ганна Шміц, юрист Міхаель Берг і епізод із замкненою церквою вигадані, хоча спираються на реальну практику франкфуртських процесів. Кейт Вінслет отримала «Оскар» за головну роль; за романом Бернгарда Шлінка. Реальна юридична й моральна ситуація, вигадана конкретна справа."},{"imdb_id":"tt0878804","title":"The Blind Side","title_uk":"Невидима сторона","year":2009,"rating":7.6,"votes":390775,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Майкл Оер — безпритульний підліток, який завдяки прийомній родині став зіркою NFL.","basis":"реальна історія","note":"Майкл Оер публічно заперечив зображене (зокрема сцени, де він не розуміє футболу) і 2023 року оскаржив опіку родини Туї; фільм критикують за наратив «білого рятівника».","thriller_flag":false,"decade":"2000-ті","desc":"Мемфіс, середина 2000-х: підлітка Майкла Оера, що ночує де прийдеться, забирає до себе заможна родина Туї, і за кілька років він іде в першому раунді драфту NFL. Джон Лі Генкок екранізував книжку Майкла Льюїса, змістивши акцент із футболу на Лі Енн Туї — Сандра Буллок отримала за роль «Оскар». Сам Оер згодом заперечив образ мовчазного й недалекого хлопця, а 2023 року заявив у суді, що Туї оформили не всиновлення, а опіку над його справами."},{"imdb_id":"tt1210166","title":"Moneyball","title_uk":"Людина, яка змінила все","year":2011,"rating":7.6,"votes":515559,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Генеральний менеджер бейсбольного клубу «Окленд Атлетікс» Біллі Бін у сезоні 2002 року перебудував команду за статистичним методом сейберметрики.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Сезон 2002-го: генеральний менеджер «Окленд Атлетікс» Біллі Бін втрачає трьох зіркових гравців, грошей на заміну не має і збирає команду за статистикою на кшталт відсотка виходу на базу. Беннетт Міллер за сценарієм Стівена Заяна і Аарона Соркіна робить фільм про телефонні дзвінки, торги й таблиці, а не про матчі. Аналітик Пітер Бренд — вигадане ім'я: реальний Пол Деподеста не дозволив використати своє. «Атлетікс» тоді виграли 20 матчів поспіль, але не Світову серію."},{"imdb_id":"tt1306980","title":"50/50","title_uk":"50/50","year":2011,"rating":7.6,"votes":355981,"genres":["Comedy","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Медицина та виживання","who_what":"Автобіографічна історія сценариста Вілла Райзера, який у 25 років дізнався про рідкісний рак хребта.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Сценарист Вілл Райзер у 25 років почув діагноз — рідкісна пухлина вздовж хребта, шанси приблизно рівні. Через кілька років він написав про це комедію, а роль друга, який тягне його по хіміотерапіях і невдало жартує, зіграв Сет Роґен — той самий, що був поруч насправді. Джозеф Ґордон-Левітт грає Адама тихо, майже без емоційних вибухів, і найсильніші сцени тут не про хворобу, а про те, як реагують інші. Тон коливається між лікарняним чорним гумором і панікою, ніде не зісковзуючи в сентимент."},{"imdb_id":"tt2431286","title":"Philomena","title_uk":"Філомена","year":2013,"rating":7.6,"votes":107643,"genres":["Biography","Comedy","Drama"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Суд і журналістика","who_what":"Ірландка Філомена Лі разом із журналістом Мартіном Сікссмітом 50 років шукала сина, якого монастир віддав на усиновлення.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1952 року вагітну незаміжню ірландку Філомену Лі віддали в монастир Шон-Росс у Роскрі, а її трирічного сина черниці передали американським усиновлювачам, не спитавши матері. Через півстоліття вона разом із безробітним журналістом Мартіном Сікссмітом береться його шукати — стара віряка проти саркастичного атеїста, і фільм тримає комедійний тон там, де легко було б збитися на памфлет. Джуді Денч номінована на «Оскар», сценарій Стіва Куґана і Джеффа Поупа взяв призи Венеції та BAFTA."},{"imdb_id":"tt2608224","title":"The Butterfly's Dream","title_uk":"Сон метелика","year":2013,"rating":7.6,"votes":26340,"genres":["Biography","Drama","History","Romance"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"тур.","theme":"Музика та мистецтво","who_what":"Хворі на туберкульоз турецькі поети Музаффер Таййіп Услу та Рюшту Онур у шахтарському Зонгулдаку часів Другої світової.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Зонгулдак початку 1940-х, вугільне містечко на Чорному морі: двоє молодих поетів, Рюшту Онур і Музаффер Тайїп Услу, хворі на туберкульоз, пишуть вірші, працюють у шахтарській конторі й закохуються в одну дівчину. Йилмаз Ердоган зняв це в теплій, майже казковій манері й сам зіграв поета Бехчета Неджатіґіля, який їм допомагає; головні ролі — у Ківанча Татлитуга і Мерта Фирата. Туреччина висувала фільм на «Оскар» за найкращий іншомовний."},{"imdb_id":"tt2855648","title":"Madras Cafe","title_uk":"Кафе «Мадрас»","year":2013,"rating":7.6,"votes":26785,"genres":["Action","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Індійський агент на Шрі-Ланці напередодні вбивства Раджіва Ганді 1991 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Індійський розвідник Вікрам Сінгх їде на Шрі-Ланку наприкінці 1980-х, коли індійський контингент грузне у війні з тамільськими сепаратистами, і поступово натрапляє на слід змови проти колишнього прем'єра. Шуджіт Сіркар знімає це як сухий політичний трилер із брифінгами, явками й радіоперехопленням — без пісень і майже без романтики. Назви організацій змінено, хоча першоджерело впізнається одразу: 21 травня 1991-го Раджіва Ганді підірвала смертниця в Шріперумбудурі. У Тамілнаду прокат фільму фактично зірвали протести."},{"imdb_id":"tt3745620","title":"Gods","title_uk":"Боги","year":2014,"rating":7.6,"votes":8360,"genres":["Biography","Drama"],"country":"Польща","country_main":"Польща","region":"Європа","language":"пол.","theme":"Медицина та виживання","who_what":"Кардіохірург Збігнєв Реліга і перша успішна пересадка серця в Польщі (1985).","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Збіґнєв Реліга в середині 1980-х пробиває стіну: колеги вважають пересадку серця марнуванням ресурсів, міністерство не дає грошей, перші пацієнти помирають. Лукаш Палковський зосереджується на кількох роках до 5 листопада 1985-го, коли команда в Забжу зробила першу в Польщі вдалу трансплантацію. Томаш Кот грає хірурга грубим, самовпевненим і незручним для всіх довкола, а фінальний кадр відтворює знамените фото Джеймса Станфілда з виснаженим лікарем біля монітора. Головні призи фестивалю в Ґдині."},{"imdb_id":"tt2713180","title":"Fury","title_uk":"Лють","year":2014,"rating":7.6,"votes":617699,"genres":["Action","Drama","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Останній місяць війни в Німеччині, квітень 1945 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Девід Еєр показує квітень 1945-го: нерівні бої «Шерманів» проти «Тигрів», фольксштурм із підлітками, повішених дезертирів, зачистки німецьких містечок. Екіпаж Дона «Вордеді» Кольєра і сам танк Fury вигадані. Знімали із єдиним у світі ходовим «Тигром» 131 із танкового музею в Бовінгтоні. Техніка й тактика відтворені точно, історія екіпажу — вигадана."},{"imdb_id":"tt2802154","title":"Leviathan","title_uk":"Левіафан","year":2014,"rating":7.6,"votes":60540,"genres":["Crime","Drama"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Політика та історія","who_what":"Сучасна Росія: зрощення муніципальної влади, суду й церкви.","basis":"реальне тло, вигадані герої","note":"Тло — сучасний політичний режим, а не окрема історична подія.","thriller_flag":false,"decade":"2010-ті","desc":"Андрій Звягінцев знімає в Териберці на Баренцовому морі історію про вилучення приватної землі під потреби мера. Автомеханік Коля, його дружина Ліля й адвокат Дмитро вигадані, хоча поштовхом став випадок американця Марвіна Гіммаєра. Приз Канн за сценарій, номінація на «Оскар» і гучний скандал удома. Тло тут — не завершена подія минулого, а чинний режим і його практики."},{"imdb_id":"tt3682448","title":"Bridge of Spies","title_uk":"Шпигунський міст","year":2015,"rating":7.6,"votes":346748,"genres":["Drama","History","Thriller","War"],"country":"США, Німеччина","country_main":"США","region":"США","language":"англ., нім., рос.","theme":"Політика та історія","who_what":"Адвокат Джеймс Донован організував обмін радянського розвідника Рудольфа Абеля на пілота U-2 Френсіса Ґері Пауерса (1962).","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"1957 року нью-йоркському страховому адвокату Джеймсу Доновану доручають захищати радянського розвідника Рудольфа Абеля; через п'ять років він же їде в розділений Берлін вимінювати Абеля на збитого пілота U-2 Френсіса Ґері Пауерса. Спілберг знімає розмовний трилер: діалоги переписували брати Коени, і половина напруги — в переговорних кімнатах, а не на мосту. Марк Райленс отримав «Оскар» за роль Абеля, зіграну майже пошепки. Обмін 10 лютого 1962-го справді включав ще й студента Фредеріка Прайора."},{"imdb_id":"tt5286444","title":"Neerja","title_uk":"Нірджа","year":2016,"rating":7.6,"votes":25315,"genres":["Biography","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, англ.","theme":"Катастрофа і виживання","who_what":"Старша бортпровідниця Нірджа Бганот, яка загинула, рятуючи пасажирів захопленого рейсу Pan Am 73 у Карачі 1986 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"5 вересня 1986 року в Карачі четверо озброєних чоловіків захопили літак Pan Am 73; старша бортпровідниця Нірджа Бганот встигла попередити кабіну, ховала паспорти американців і загинула, прикриваючи трьох дітей, — за два дні до свого двадцятитриріччя. Рам Мадхвані тримає майже весь фільм у салоні, у ритмі сімнадцятигодинного захоплення, і паралельно показує домашнє життя героїні. Сонам Капур у головній ролі, Шабана Азмі — мати. Бганот посмертно отримала «Ашока Чакру», найвищу цивільну нагороду Індії за мужність."},{"imdb_id":"tt3721954","title":"Maudie","title_uk":"Моді","year":2016,"rating":7.6,"votes":25984,"genres":["Biography","Drama","Romance"],"country":"Канада/Ірландія","country_main":"Канада","region":"Інше","language":"англ.","theme":"Музика та мистецтво","who_what":"Канадська художниця-примітивістка Мод Льюїс, яка попри тяжкий артрит усе життя малювала в крихітному будиночку в Новій Шотландії.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мод Льюїс усе життя прожила в Новій Шотландії з артритом, що скрутив їй руки, а від 1938 року — в халупі три на чотири метри разом із рибним торговцем Евереттом, до якого найнялася хатньою робітницею. Ейслінг Волш знімає їхній шлюб як довге шорстке звикання двох незручних людей, а не як романс. Саллі Гокінс та Ітан Гоук грають майже без слів — поставою й руками. Розмальований Мод будиночок сьогодні стоїть у Художній галереї Нової Шотландії."},{"imdb_id":"tt3829920","title":"Only the Brave","title_uk":"Тільки хоробрі","year":2017,"rating":7.6,"votes":93414,"genres":["Action","Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Загін пожежників-«гранітних гірників» із Прескотта, 19 з яких загинули на пожежі Ярнелл-Гілл 2013 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Загін Granite Mountain Hotshots із Прескотта в Аризоні під керівництвом Еріка Марша став першою муніципальною бригадою, атестованою на найвищий рівень гасіння лісових пожеж; 30 червня 2013-го на пожежі Ярнелл-Гілл загинули 19 із 20 його бійців. Джозеф Косінскі більшу частину фільму віддає рутині — вирубуванню просік, контрольованим підпалам, сімейним сваркам у міжсезоння. Джош Бролін грає Марша, Майлз Теллер — новачка Брендана Макдонафа, єдиного, хто вижив."},{"imdb_id":"tt6788942","title":"Bad Genius","title_uk":"Погані генії","year":2017,"rating":7.6,"votes":25748,"genres":["Comedy","Crime","Drama","Thriller"],"country":"Таїланд","country_main":"Таїланд","region":"Східна Азія","language":"тайська, англ.","theme":"Соціальна драма","who_what":"Школярі організовують міжнародну схему списування на іспитах; в основі — скандал зі SAT 2014 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Лінн, відмінниця на стипендії в дорогій бангкокській школі, спершу підказує подрузі, а далі будує бізнес: код пальцями на іспиті, потім переліт до Сіднея, щоб через різницю часових поясів передати відповіді назад у Таїланд. В основі — скандал 2014 року, коли College Board анулював результати SAT в Азії саме через таку схему. Наттавут Пунпірія знімає списування як пограбування банку: секундоміри, паралельний монтаж, ударні на саундтреку. Головну роль зіграла дебютантка Чутімон Чуенгчароенсукін."},{"imdb_id":"tt7048622","title":"The Insult","title_uk":"«Образа»","year":2017,"rating":7.6,"votes":19224,"genres":["Crime","Drama","Thriller"],"country":"Ліван / Франція","country_main":"Ліван","region":"Близький Схід і Африка","language":"араб.","theme":"Суд і журналістика","who_what":"Незагоєні травми ліванської громадянської війни 1975–1990 років, зокрема різанина в Дамурі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Зіад Дуейрі виводить побутову сварку через тріснуту ринву на рівень національного судового процесу, який паралізує Бейрут. Ліванський християнин Тоні й палестинський біженець Ясер доходять до найвищої інстанції, де з'ясовується, що обидва пережили масові вбивства з різних боків. Каміль Салама отримав кубок Вольпі у Венеції, фільм номінований на «Оскар». Дамур і Тель-аз-Заатар реальні, справа вигадана."},{"imdb_id":"tt6484982","title":"Newton","title_uk":"«Ньютон»","year":2017,"rating":7.6,"votes":22579,"genres":["Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Загальні вибори в охоплених наксалітським повстанням лісах Чхаттісґарха.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Амір Масурі знімає майже абсурдистську комедію про день голосування в селі, куди виборчу комісію ведуть під охороною спецпризначенців. Молодий клерк, що назвався Ньютоном, вимагає провести вибори за буквою закону там, де немає ані виборців, ані бажання держави. Індійська заявка на «Оскар» і приз секції Panorama Берлінале. Конфлікт держави з маоїстами й фіктивна явка задокументовані; Ньютон та його дільниця вигадані."},{"imdb_id":"tt6155172","title":"Roma","title_uk":"Рома","year":2018,"rating":7.6,"votes":179463,"genres":["Drama"],"country":"Мексика","country_main":"Мексика","region":"Латинська Америка","language":"ісп., міштекська","theme":"Автобіографія","who_what":"Спогади Альфонсо Куарона про няню Лібо та рік у мексиканському районі Рома-Норте на тлі «різанини Корпус-Крісті» 1971 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Альфонсо Куарон відтворює рік із власного дитинства в районі Рома-Норте: 1970–1971-й, коли від родини пішов батько, а дім тримала няня-міштечка Клео, списана з Лібо Родріґес, якій фільм і присвячено. Камеру Куарон вів сам — чорно-біле 65-міліметрове зображення, довгі панорами, майже жодного крупного плану. Історія вривається в побут 10 червня 1971 року, коли воєнізовані «яструби» розстрілювали студентів на вулицях: різанина Корпус-Крісті. Три «Оскари», зокрема за режисуру й операторську роботу."},{"imdb_id":"tt6452574","title":"Sanju","title_uk":"Санджу","year":2018,"rating":7.6,"votes":68085,"genres":["Biography","Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Музика та мистецтво","who_what":"Життя болівудського актора Санджая Датта — наркозалежність, тюремні терміни та звинувачення у зв'язках із теракти 1993 року.","basis":"реальна історія","note":"Фільм знято за участі самого Санджая Датта і критикували як спробу відбілювання: провину за наркотики та зброю перекладено на пресу й оточення.","thriller_flag":false,"decade":"2010-ті","desc":"Раджкумар Хірані будує байопік Санджая Датта як сповідь письменникові: наркозалежність кінця 1980-х, смерть матері Наргіс, арешт 1993 року за незаконне зберігання АК-56, отриманого від людей, причетних до бомбейських вибухів, і роки судів аж до вироку 2013-го. Ранбір Капур відтворює пластику й голос актора майже покадрово. Критики закидали фільмові вибілювання: він наполегливо подає Датта жертвою поганого оточення і преси, а незручні епізоди обминає."},{"imdb_id":"tt7832124","title":"Muslum","title_uk":"Мюслюм","year":2018,"rating":7.6,"votes":21931,"genres":["Biography","Drama","Music","Romance"],"country":"Туреччина","country_main":"Туреччина","region":"Близький Схід і Африка","language":"турецька","theme":"Музика та мистецтво","who_what":"Життя турецького співака арабеск Мюслюма Гюрсеса — від сирітства до всенародної слави.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мюслюм Ґюрсес виріс у злиднях на півдні Туреччини, рано втратив матір, терпів жорстокого батька — і став голосом арабеску, на чиїх концертах слухачі різали себе лезами від надміру почуттів. Кетче і Джан Улькай ведуть біографію через десятиліття й через шлюб із Мухтерем, яка лишалася поруч до кінця. Тимучин Есен майже не грає зовнішньої подібності, тримаючись на голосі й поставі. У турецькому прокаті 2018-го фільм зібрав найбільше глядачів з-поміж усіх."},{"imdb_id":"tt5461944","title":"Hotel Mumbai","title_uk":"Готель «Мумбаї»","year":2018,"rating":7.6,"votes":80205,"genres":["Action","Drama","History","Thriller"],"country":"Австралія / США / Індія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ., гінді","theme":"Катастрофа і виживання","who_what":"Терористична атака на готель «Тадж-Махал» у Мумбаї 26 листопада 2008 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"26 листопада 2008 року десятеро бойовиків атакували Мумбаї одразу в кількох точках; облога готелю «Тадж-Магал Палас» тривала майже три доби. Ентоні Марас не виходить за стіни будівлі й веде історію переважно очима персоналу, який залишився з гостями, зокрема шеф-кухаря Геманта Обероя. Дев Патель грає офіціанта, зібраного з кількох реальних працівників, а головна пружина напруги теж документальна: спецпризначенці летіли з Делі й прибули лише через багато годин."},{"imdb_id":"tt6826438","title":"Parmanu: The Story of Pokhran","title_uk":"Пармана: Історія Похрана","year":2018,"rating":7.6,"votes":26832,"genres":["Drama","History","Thriller","Action"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Наука і технології","who_what":"Таємна підготовка індійських ядерних випробувань у Похрані 1998 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Травень 1998-го: Індія за кілька днів провела п'ять підземних ядерних вибухів у пустелі під Похраном — так, щоб американські супутники нічого не помітили заздалегідь. Абхішек Шарма робить із цього шпигунський трилер: чиновник Ашвата Рейна (Джон Абрахам) збирає групу з п'яти фахівців, які возять обладнання ночами й видають себе за військових. Напруга будується на розкладі прольотів супутників. Головний герой вигаданий, а реальні керівники програми, Абдул Калам і Р. Чідамбарам, у кадрі майже відсутні."},{"imdb_id":"tt8404614","title":"The Two Popes","title_uk":"Два Папи","year":2019,"rating":7.6,"votes":147754,"genres":["Biography","Drama"],"country":"Велика Британія / Італія / Аргентина","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ., ісп., італ.","theme":"Політика та історія","who_what":"Діалоги Бенедикта XVI та кардинала Берґольйо напередодні зречення 2013 року.","basis":"натхненний реальними подіями","note":"Розмови Бенедикта XVI й Берґольйо повністю вигадані сценаристом; зустрічі в такому форматі не відбувалися, а політичні погляди обох понтифіків спрощено.","thriller_flag":false,"decade":"2010-ті","desc":"У 2013 році Бенедикт XVI став першим за майже шістсот років папою, який зрікся престолу, а конклав обрав аргентинця Хорхе Берґольйо. Фернандо Мейреллеш і сценарист Ентоні Маккартен вигадують серію приватних розмов між ними у Кастель-Гандольфо й Сикстинській капелі — таких зустрічей насправді не було. Ентоні Гопкінс і Джонатан Прайс перетворюють це на діалог двох способів бути церквою; окремою лінією йде минуле Берґольйо за часів аргентинської хунти."},{"imdb_id":"tt4916630","title":"Just Mercy","title_uk":"Просто помилуй","year":2019,"rating":7.6,"votes":85698,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Адвокат Браян Стівенсон, який домігся виправдання безпідставно засудженого до страти Волтера Макміллана.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Монровілль, штат Алабама — містечко, де виросла Гарпер Лі, — 1988 року засудило до страти Волтера Макміллана за вбивство, попри десятки свідків, які бачили його в іншому місці. Дестін Деніел Креттон екранізував мемуари адвоката Браяна Стівенсона, засновника Equal Justice Initiative, який домігся скасування вироку 1993-го. Майкл Б. Джордан і Джеймі Фокс грають стримано, без промов на публіку. Окремо тримається лінія Герберта Річардсона, ветерана В'єтнаму з сусідньої камери, у виконанні Роба Морґана."},{"imdb_id":"tt7533152","title":"The Boy Who Harnessed the Wind","title_uk":"Хлопчик, який приборкав вітер","year":2019,"rating":7.6,"votes":53333,"genres":["Biography","Drama","History"],"country":"Велика Британія / Малаві","country_main":"Велика Британія","region":"Британія та Ірландія","language":"чичева, англ.","theme":"Наука і технології","who_what":"Малавійський підліток Вільям Камквамба, який під час голоду 2001 року побудував вітряк із брухту.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Село Вімбе, Малаві, 2001 рік: посуха й голод, родині нічим платити за школу, і чотирнадцятирічний Вільям Камквамба потай пробирається до шкільної бібліотеки, де знаходить підручник про використання енергії. З велосипедного динамо, пластикових труб і брухту з покинутого трактора він збирає вітряк, що качає воду на поле. Чіветел Еджіофор дебютував тут як режисер і сам зіграв батька, знімали в Малаві мовою чичева. Максвелл Сімба в головній ролі — теж дебютант."},{"imdb_id":"tt9071322","title":"Dark Waters","title_uk":"Темні води","year":2019,"rating":7.6,"votes":123064,"genres":["Biography","Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Адвокат Роб Білотт, який два десятиліття судився з DuPont через отруєння води хімікатом PFOA.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"1998 року фермер Вілбур Теннант із Паркерсбурга у Західній Вірджинії привіз корпоративному юристові Робу Білотту касети з мертвою худобою — і той відкрив справу проти компанії з кола власних клієнтів, DuPont, через скид PFOA у воду. Тодд Гейнс знімає похмуро й буденно: коробки з паперами, аналізи крові десятків тисяч мешканців, роки очікування. Марк Руффало грає без героїчних жестів. Позови тривають досі, а PFOA виявляють у крові майже всіх американців."},{"imdb_id":"tt9179230","title":"Held for Ransom (Ser du manen, Daniel)","title_uk":"Ти бачиш місяць, Даніелю?","year":2019,"rating":7.6,"votes":5692,"genres":["Biography","Drama","Thriller","War"],"country":"Данія / Норвегія / Швеція","country_main":"Данія","region":"Європа","language":"дан., англ., араб.","theme":"Катастрофа і виживання","who_what":"Данський фотограф Даніель Рюе, який 398 днів пробув у полоні ІДІЛ у Сирії.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Данського фотографа Даніеля Рюе викрали в Сирії 2013 року; він провів у полоні «Ісламської держави» 398 днів, сидів в одній камері з американським журналістом Джеймсом Фолі й вийшов на волю після виплати викупу. Нільс Арден Оплев і Андерс В. Бертельсен ведуть дві лінії паралельно — камеру в Сирії та перемовника, який працює з родиною в Данії. Знято за книжкою журналістки Пук Дамсґорд; екшену тут майже немає, головна дія — телефонні переговори й очікування."},{"imdb_id":"tt15301048","title":"Argentina, 1985","title_uk":"Аргентина, 1985","year":2022,"rating":7.6,"votes":36824,"genres":["Biography","Crime","Drama","History"],"country":"Аргентина","country_main":"Аргентина","region":"Латинська Америка","language":"ісп.","theme":"Суд і журналістика","who_what":"Прокурори Хуліо Страссера і Луїс Морено Окампо судять військову хунту за злочини «брудної війни».","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"1985 року, всього через два роки після падіння диктатури, цивільний суд у Буенос-Айресі судив дев'ятьох членів військових хунт за викрадення, тортури й убивства. Прокурор Хуліо Страссера (Рікардо Дарін) і його заступник Луїс Морено Окампо (Петер Ланцані) зібрали команду з молодих юристів, бо досвідчені боялися, і за кілька місяців вислухали сотні свідків. Сантьяґо Мітре чергує рутинну процедурну роботу з погрозами, що надходили щодня. «Золотий глобус» за іншомовний фільм і номінація на «Оскар»."},{"imdb_id":"tt11813216","title":"The Banshees of Inisherin","title_uk":"«Банші Інішеріна»","year":2022,"rating":7.6,"votes":299712,"genres":["Comedy","Drama"],"country":"Ірландія / Велика Британія / США","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Громадянська війна в Ірландії 1923 року, звуки якої долинають із материка на острів.","basis":"реальне тло, вигадані герої","note":"війна присутня як алегоричне тло, а не як предмет фільму","thriller_flag":false,"decade":"2020-ті","desc":"Мартін Мак-Дона ставить притчу про безпричинну ворожнечу: Колм раптом припиняє дружити з Падрайком і погрожує відрізати собі пальці, якщо той бодай заговорить. За протокою гримлять вибухи громадянської війни, і жоден із героїв не знає до пуття, хто там із ким воює. Дев'ять номінацій на «Оскар» і чотири «Золоті глобуси». Війна 1922–1923 років реальна, острів і всі мешканці вигадані."},{"imdb_id":"tt7599146","title":"Sound of Freedom","title_uk":"Звук свободи","year":2023,"rating":7.6,"votes":139084,"genres":["Action","Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Колишній агент Тім Балларад залишає службу, щоб рятувати дітей із мереж секс-торгівлі в Латинській Америці.","basis":"натхненний реальними подіями","note":"Твердження Тіма Балларда та його організації OUR ставили під сумнів журналістські розслідування, а самого Балларда звинуватили у зловживаннях; фільм критикують за поширення міфів про торгівлю дітьми.","thriller_flag":false,"decade":"2020-ті","desc":"Тім Баллард пішов із Міністерства внутрішньої безпеки США і заснував Operation Underground Railroad — організацію, що проводить рейди проти торгівлі дітьми в Латинській Америці. Алехандро Монтеверде знімає це як бойовик-порятунок із Джимом Кевізелом у головній ролі; фільм пролежав на полиці п'ять років і завдяки краудфандинговому прокату зібрав понад 180 мільйонів доларів. Журналісти й фахівці з протидії торгівлі людьми оскаржували і наведену статистику, і центральну операцію в Колумбії, а самого Балларда згодом змусили піти з організації."},{"imdb_id":"tt25274786","title":"Kannur Squad","title_uk":"Загін Каннур","year":2023,"rating":7.6,"votes":12600,"genres":["Action","Crime","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"малаялам","theme":"Кримінал","who_what":"Робота реального спецзагону поліції Керали, що ловить злочинців по всій Індії.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Реальний загін поліції Керали з округу Каннур — дев'ятеро офіцерів, які їздять по всій країні за фігурантами місцевих справ — став основою для дебюту Робі Варґезе Раджа. У фільмі команда ASI Джорджа Мартіна розкручує пограбування й убивство підприємця-емігранта в Касарґоді, і слід тягне їх через кілька штатів аж до непальського кордону. Сценаристи говорили зі справжніми членами загону. Мамутті грає буденно, без героїчних виходів: тут більше нічних переїздів і чекання, ніж пострілів."},{"imdb_id":"tt28479262","title":"Sing Sing","title_uk":"Сінг-Сінг","year":2023,"rating":7.6,"votes":30543,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Театральна програма для ув'язнених у тюрмі Сінг-Сінг; більшість ролей грають реальні її випускники.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"У Сінг-Сінгу з 1990-х працює театральна програма RTA, і саме її випускники грають тут майже всі ролі — Кларенс Маклін, який сам відсидів у цій тюрмі, зіграв себе. Ґреґ Кведар відштовхується від статті в Esquire та реальної постановки Брента Б'юелла, де змішалися Шекспір, гладіатори, ковбої та єгипетська мумія. Колман Домінго веде роль Джона «Дівайна Джі» Вітфілда, який доводить свою невинуватість і водночас утримує трупу вкупі. Актори й знімальна група працювали за однакову ставку з часткою від прибутку."},{"imdb_id":"tt14225838","title":"Io Capitano","title_uk":"Я — капітан","year":2023,"rating":7.6,"votes":18279,"genres":["Adventure","Drama"],"country":"Італія/Бельгія","country_main":"Італія","region":"Європа","language":"вольоф/франц./італ.","theme":"Соціальна драма","who_what":"Двоє сенегальських підлітків долають Сахару, лівійські катівні й Середземне море дорогою до Європи; в основі — свідчення реальних мігрантів Мамаду Куассі та Фофани Амари.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Шістнадцятирічні Сейду й Мусса вирушають із Дакара до Європи через Нігер, Сахару й лівійські катівні контрабандистів — маршрут складено зі свідчень реальних мігрантів, зокрема Мамаду Куассі та Фофани Амари, які працювали консультантами. Маттео Ґарроне знімає це майже як казкову подорож, із насиченим кольором замість документальної сірості, і саму Європу не показує зовсім. Сейду Сарр отримав у Венеції приз Марчелло Мастроянні, Ґарроне — «Срібного лева» за режисуру."},{"imdb_id":"tt27367464","title":"Kneecap","title_uk":"Kneecap","year":2024,"rating":7.6,"votes":25792,"genres":["Comedy","Drama","Music"],"country":"Ірландія / Велика Британія","country_main":"Ірландія","region":"Британія та Ірландія","language":"ірл., англ.","theme":"Музика та мистецтво","who_what":"Белфастське іншомовне реп-тріо Kneecap грає саме себе в історії власного становлення.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Троє з Белфаста — Моґлаї Бап, Мо Хара і вчитель музики, що виступає в балаклаві під іменем DJ Próvaí, — грають самих себе в напіввигаданій версії того, як почали читати реп ірландською. Річ Пеппіат знімає це швидко й нахабно: наркотики, поліція, сектантські розбірки й кампанія за офіційний статус ірландської мови в Північній Ірландії. Перша повнометражна ірландськомовна стрічка в конкурсі «Санденсу», де вона взяла приз глядацьких симпатій. Майкл Фассбендер грає батька-республіканця, який переховується."},{"imdb_id":"tt32916440","title":"Marty Supreme","title_uk":"Марті Суприм","year":2025,"rating":7.6,"votes":213684,"genres":["Comedy","Drama","Sport","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Пінг-понгіст Нью-Йорка 1950-х женеться за славою — за мотивами життя реального чемпіона Марті Райсмана.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Марті Райсман на прізвисько «Голка» у 1940–50-х вигравав турніри й обігравав людей на гроші в нью-йоркських пінг-понгових залах, коли цей спорт у США не давав ані грошей, ані поваги. Джош Сафді не робить біографії: його героя звати Марті Маузер, і живе він за логікою Райсманових мемуарів, а не за хронологією його життя. Тімоті Шаламе грає одержимість без жодної паузи, у звичному для Сафді ритмі нервової гонитви."},{"imdb_id":"tt15097358","title":"Bison Kaalamaadan","title_uk":"Бізон","year":2025,"rating":7.6,"votes":7946,"genres":["Action","Biography","Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"тамільська","theme":"Спорт","who_what":"Кабадді-гравець Манаті Ганесан пробивається до національної збірної попри кастове насильство в рідному районі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Кабадді-гравець Манаті Ганесан виріс у сільському Тамілнаду, де сутички між сусідніми селами на кастовому ґрунті були частиною побуту, і все ж пробився до національної збірної. Марі Сельварадж називає героя Кіттаном і показує спорт як єдиний спосіб вийти з насильства, у яке того втягують від народження. Дгрув Вікрам грає майже без слів, здебільшого тілом; знімали в Діндіґулі та Раджапалаямі, і фільм мав сильний прокат."},{"imdb_id":"tt0099776","title":"Europa Europa","title_uk":"Європа, Європа","year":1990,"rating":7.5,"votes":18765,"genres":["Drama","History","War"],"country":"Німеччина / Франція / Польща","country_main":"Німеччина","region":"Європа","language":"нім., рос., польськ.","theme":"Голокост","who_what":"Історія Соломона Переля — німецького єврея, який пережив війну, видаючи себе за арійця в гітлер'юґенді.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Соломон Перель, німецький єврей 1925 року народження, після втечі з Польщі вижив, видавши себе за етнічного німця Йозефа Петерса: служив перекладачем у вермахті й потрапив до елітної школи гітлер'юґенду в Брауншвейзі. Агнєшка Голланд екранізувала його мемуари, тримаючи інтонацію гіркої іронії — герой щодня боїться викриття в роздягальні. Фільм здобув «Золотий глобус», але Німеччина не висунула його на «Оскар», що спричинило гучний скандал. Справжній Перель з'являється у фіналі."},{"imdb_id":"tt0103110","title":"Tous les matins du monde","title_uk":"Усі ранки світу","year":1991,"rating":7.5,"votes":8523,"genres":["Biography","Drama","History","Music","Romance"],"country":"Франція","country_main":"Франція","region":"Європа","language":"франц.","theme":"Музика та мистецтво","who_what":"Французькі віольні композитори XVII століття — самітник Сент-Коломб і його учень Марен Маре, майбутній музикант Людовіка XIV.","basis":"натхненний реальними подіями","note":"Про життя Сент-Коломба збереглося майже нічого; фабула великою мірою вигадана Паскалем Кіньяром у повісті-першоджерелі.","thriller_flag":false,"decade":"1990-ті","desc":"Наприкінці XVII століття віольний майстер Сент-Коломб замикається в жалобі за померлою дружиною, а до нього в учні напрошується честолюбний Марен Маре (1656–1728), майбутній придворний музикант Людовіка XIV. Ален Корно зняв стриманий фільм про ціну, яку мистецтво бере з людини, майже без музичного пафосу. Музику виконує ансамбль Жорді Саваля, у ролях — Жан-П'єр Марієль, Жерар Депардьє та його син Гійом. Сім премій «Сезар», зокрема за найкращий фільм."},{"imdb_id":"tt0103939","title":"Chaplin","title_uk":"Чаплін","year":1992,"rating":7.5,"votes":66070,"genres":["Biography","Comedy","Drama"],"country":"Велика Британія / США / Франція / Італія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Музика та мистецтво","who_what":"Біографія Чарлі Чапліна — від лондонських нетрів до вигнання зі США й почесного «Оскара».","basis":"реальна історія","note":"Рамкова оповідь із редактором-біографом вигадана, а стосунки й хронологію подій помітно ущільнено.","thriller_flag":false,"decade":"1990-ті","desc":"Річард Аттенборо простежує вісім десятиліть життя Чарлі Чапліна (1889–1977): мюзик-хол, студія Кістоуна, слава Бродяги, полювання ФБР, від’їзд із США 1952 року й почесний «Оскар» 1972-го. Роберт Дауні-молодший вивчив пантоміму та гру на скрипці лівою рукою і дістав номінацію на «Оскар», а Джералдін Чаплін зіграла власну бабусю Ханну. Сценарій спирається на автобіографію Чапліна та біографію Девіда Робінсона."},{"imdb_id":"tt0108002","title":"Rudy","title_uk":"Руді","year":1993,"rating":7.5,"votes":75519,"genres":["Biography","Drama","History","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Деніел «Руді» Рюттіґер, який усупереч усьому пробився у футбольну команду Нотр-Дама 1975 року.","basis":"реальна історія","note":"Тренер Ден Дівайн насправді сам запропонував випустити Рюттіґера — його опір у фільмі вигаданий.","thriller_flag":false,"decade":"1990-ті","desc":"Деніел «Руді» Рюттіґер із робітничої родини в Джольєті мріяв грати за «Нотр-Дам»: із дислексією, зростом 165 сантиметрів і слабкими оцінками він два роки провчився в сусідньому коледжі, перш ніж вступити й потрапити до тренувального складу. 8 листопада 1975 року його випустили на поле в останніх секундах сезону, він збив квотербека, і одноклубники винесли його на руках. Девід Анспо знімав у самому кампусі Нотр-Дама, головну роль зіграв Шон Естін."},{"imdb_id":"tt0108211","title":"Stalingrad","title_uk":"Сталінград","year":1993,"rating":7.5,"votes":39596,"genres":["Drama","History","War"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Війна","who_what":"Сталінградська битва 1942—1943 років очима німецьких солдатів.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Йозеф Фільсмаєр веде взвод лейтенанта Вітцланда від італійського курорту до котла на Волзі, де від дисципліни не лишається нічого. Солдати вигадані, а хронологія оточення, голод і розстріли за дезертирство спираються на щоденники учасників. Один із найдорожчих німецьких фільмів свого часу; знімали в Чехії та Фінляндії."},{"imdb_id":"tt0110932","title":"Quiz Show","title_uk":"Телевікторина","year":1994,"rating":7.5,"votes":78346,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Скандал 1958 року навколо телевікторини «Twenty-One», де продюсери наперед давали учасникам відповіді.","basis":"реальна історія","note":"Хронологію ущільнено, а слідчий Річард Ґудвін у фільмі має більшу вагу, ніж мав насправді.","thriller_flag":false,"decade":"1990-ті","desc":"У 1958 році телеканал NBC змусив чемпіона Герба Стемпеля програти Чарльзу Ван Дорену, викладачеві Колумбійського університету з відомої літературної родини; підказки давали обом. Слідчий Конгресу Річард Ґудвін розкрутив справу до слухань 1959 року, де Ван Дорен зізнався. Роберт Редфорд зняв це як історію про спокусу респектабельністю; Рейф Файнс, Джон Туртурро і Пол Скофілд у головних ролях, чотири номінації на «Оскар». Роль Ґудвіна у фільмі помітно збільшена."},{"imdb_id":"tt0109206","title":"Bandit Queen","title_uk":"Королева бандитів","year":1994,"rating":7.5,"votes":5921,"genres":["Action","Biography","Crime","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Життя Пхулан Деві — жінки з низької касти, що стала ватажкою банди дакойтів, а згодом депутаткою парламенту Індії.","basis":"реальна історія","note":"Сама Пхулан Деві заперечувала достовірність низки епізодів і судилася з творцями; в Індії фільм тимчасово забороняли.","thriller_flag":false,"decade":"1990-ті","desc":"Пхулан Деві (1963–2001) — жінка з низької касти маллах з Уттар-Прадешу, яку дитиною видали заміж, зґвалтували й вигнали з села; вона очолила банду дакойтів і стала головною підозрюваною в убивстві 22 тхакурів у Бехмаї 1981 року, здалася владі 1983-го, а згодом була обрана до парламенту. Шекхар Капур зняв демонстративно жорсткий фільм за книжкою Мали Сен. Сіма Бісвас у головній ролі; прем'єра в Каннах спричинила міжнародний резонанс."},{"imdb_id":"tt0110322","title":"Legends of the Fall","title_uk":"Легенди осені","year":1994,"rating":7.5,"votes":201850,"genres":["Drama","Romance","War","Western"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Монтана початку XX століття, Перша світова війна і сухий закон.","basis":"реальне тло, вигадані герої","note":"Історичний фон радше декоративний — це передусім родинна сага.","thriller_flag":false,"decade":"1990-ті","desc":"Троє синів полковника Ладлоу йдуть добровольцями на фронт, і загибель молодшого руйнує родину на десятиліття. Ладлоу вигадані, натомість окопи 1914 року, бутлегерство і корупція часів «сухого закону» — реальне тло. Бред Пітт у ролі Трістана; «Оскар» Джона Толла за операторську роботу. Основа сценарію — повість Джима Гаррісона."},{"imdb_id":"tt0112818","title":"Dead Man Walking","title_uk":"Мертвець іде","year":1995,"rating":7.5,"votes":109286,"genres":["Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Черниця Гелен Прежан супроводжує засудженого до страти в'язня в Луїзіані наприкінці 1980-х.","basis":"реальна історія","note":"Засуджений Понселе — вигаданий композит двох реальних смертників; сестра Прежан і її досвід показані документально.","thriller_flag":false,"decade":"1990-ті","desc":"Фільм за мемуарами сестри Прежан 1993 року: черниця стає духовною радницею вбивці, не виправдовуючи його і не відвертаючись від родин загиблих підлітків. Тім Роббінс поставив картину так, щоб глядач бачив і злочин, і ін'єкцію. Сьюзен Сарандон отримала «Оскар», Шон Пенн — номінацію. Метью Понселе — збірний персонаж, зліплений із двох реальних в'язнів, яким Прежан допомагала: Елмо Патріка Соньє і Роберта Лі Віллі."},{"imdb_id":"tt0114671","title":"Land and Freedom","title_uk":"Земля і воля","year":1995,"rating":7.5,"votes":12969,"genres":["Drama","History","War"],"country":"Велика Британія / Іспанія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ. / ісп.","theme":"Війна","who_what":"Громадянська війна в Іспанії 1936—1937 років і розгром ПОУМ.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Безробітний ліверпулець Девід їде воювати в Іспанію, потрапляє до міліції ПОУМ і бачить, як комуністи розганяють власних союзників. Герої вигадані, натомість колективізація села, барселонські бої травня 1937-го і розпуск ополчення показані за документами. Кен Лоуч знімав із непрофесійними акторами, а довгу сцену сільських зборів фактично імпровізували."},{"imdb_id":"tt0117665","title":"Sleepers","title_uk":"Сплячі","year":1996,"rating":7.5,"votes":257275,"genres":["Crime","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Четверо хлопців із нью-йоркської Пекельної кухні пройшли через знущання у виправному закладі й через роки поквиталися з наглядачем.","basis":"натхненний реальними подіями","note":"Достовірність книжки Каркатерри публічно спростовували: жодних записів про описане вбивство і суд не виявлено, автор наполягає на своїй версії.","thriller_flag":true,"decade":"1990-ті","desc":"За книжкою Лоренцо Каркатерри 1995 року, яку автор подав як спогади: 1967-го чотирьох підлітків відправляють до колонії Вілкінсон, де наглядачі їх ґвалтують, а за тринадцять років двоє з них убивають одного з мучителів, і прокурор, їхній давній друг, свідомо валить власну справу. Баррі Левінсон зібрав Де Ніро, Гоффмана, Пітта й Бейкона. Журналісти й влада Нью-Йорка не знайшли слідів ані вбивства, ані процесу."},{"imdb_id":"tt0164538","title":"Dil Se..","title_uk":"Від щирого серця","year":1998,"rating":7.5,"votes":33716,"genres":["Drama","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Політика та історія","who_what":"Повстанські рухи на північному сході Індії напередодні 50-річчя незалежності.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Радіожурналіст Амар закохується в мовчазну Меґну, не знаючи, що вона готується до теракту на параді в Делі. Герої вигадані, натомість насильство в Ассамі, армійські операції й державний культ ювілею незалежності 1997 року — реальний контекст. Шахрух Хан і Маніша Коїрала; пісня «Chaiyya Chaiyya», знята на даху потяга, стала візитівкою індійського кіно."},{"imdb_id":"tt0171804","title":"Boys Don't Cry","title_uk":"Хлопці не плачуть","year":1999,"rating":7.5,"votes":108204,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Убивство трансгендерного юнака Брендона Тіни в Небрасці 31 грудня 1993 року.","basis":"реальна історія","note":"Третю жертву, Філіпа Девайна, з фільму прибрано, а хронологію останніх тижнів стиснуто.","thriller_flag":false,"decade":"1990-ті","desc":"Двадцятиоднорічний Брендон Тіна жив у містечку Фоллз-Сіті, штат Небраска, як хлопець; після викриття його зґвалтували, а 31 грудня 1993 року Джон Лоттер і Том Ніссен застрелили його разом із Ліза Ламберт і Філіпом Девайном. Кімберлі Пірс дебютувала цим фільмом у повному метрі. Гіларі Свонк отримала «Оскар» за головну роль, Хлоя Севіньї — номінацію за другорядну."},{"imdb_id":"tt0195685","title":"Erin Brockovich","title_uk":"Ерін Брокович","year":2000,"rating":7.5,"votes":249057,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Реальна Ерін Брокович, яка довела забруднення води хромом компанією PG&E у Гінклі, Каліфорнія.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Гінклі, Каліфорнія, початок 1990-х: незаможна мати трьох дітей без юридичної освіти працює клеркою в конторі Еда Мазрі й натрапляє на медичні картки, що пов'язують хвороби мешканців із шестивалентним хромом зі свердловин PG&E. Содерберг тримає фокус не на засіданнях суду, а на польовій роботі — розмовах на кухнях і збиранні підписів. Джулія Робертс отримала за цю роль «Оскар». Компанія залагодила справу 1996 року виплатою 333 мільйонів доларів, хоча масштаб доведеної шкоди для здоров'я досі оскаржують."},{"imdb_id":"tt0238891","title":"I cento passi (One Hundred Steps)","title_uk":"Сто кроків","year":2000,"rating":7.5,"votes":7235,"genres":["Biography","Crime","Drama"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Кримінал","who_what":"Сицилійський активіст Пеппіно Імпастато, який висміював мафію на піратському радіо і був убитий 1978 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Пеппіно Імпастато виріс у сицилійському Чінізі за сто кроків від дому боса Тано Бадаламенті — і з кінця 1960-х висміював мафію в ефірі власного Radio Aut. Марко Тулліо Джордана веде розповідь від дитинства до 9 травня 1978-го, коли Пеппіно вбили, а слідство спершу подало це як самогубство терориста. Луїджі Ло Кашо грає його на межі жарту й люті; сценарій отримав приз Венеції, а Бадаламенті засудили лише 2002 року."},{"imdb_id":"tt0215750","title":"Enemy at the Gates","title_uk":"Ворог біля воріт","year":2001,"rating":7.5,"votes":295333,"genres":["Drama","History","War"],"country":"США/Німеччина/Велика Британія/Ірландія","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Радянський снайпер Василь Зайцев у Сталінградській битві 1942 року.","basis":"натхненний реальними подіями","note":"Дуель Зайцева з «майором Кьоніґом» — радянська пропагандистська легенда без підтверджень; зображення штрафних загонів і боїв у Сталінграді теж істотно спотворене.","thriller_flag":false,"decade":"2000-ті","desc":"Жан-Жак Анно бере реального снайпера Василя Зайцева, який восени 1942-го воював у руїнах Сталінграда, і будує навколо нього дуель із німецьким стрільцем (Ед Гарріс). Джуд Лоу грає пастуха з Уралу, що стає обличчям пропаганди, Джозеф Файнз — політрука, який цей образ виготовляє. Дуель із «майором Кеніґом» документально не підтверджена: німецьких слідів такого офіцера немає, тож епізод вважають радянською легендою."},{"imdb_id":"tt0221027","title":"Blow","title_uk":"Кокаїн","year":2001,"rating":7.5,"votes":288752,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Наркоторговець Джордж Юнг, який разом із Медельїнським картелем налагодив постачання кокаїну до США.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джордж Юнг починав із марихуани в Каліфорнії кінця 1960-х, а вже у в'язниці познайомився з людиною, яка вивела його на Медельїнський картель Пабло Ескобара — і через нього в США пішли тонни кокаїну. Тед Демме веде оповідь від першої особи Юнга: від пляжів до федеральної тюрми, де той провів решту життя. Джонні Депп грає без іронії, майже сентиментально, і фільм не приховує, що дивиться на героя його ж очима."},{"imdb_id":"tt0161860","title":"Nowhere in Africa","title_uk":"Ніде в Африці","year":2001,"rating":7.5,"votes":14858,"genres":["Biography","Drama","History"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім./англ.","theme":"Голокост","who_what":"Німецько-єврейська родина Редліхів, яка втекла від нацизму на ферму в Кенії (автобіографічна книга Стефані Цвейг).","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"За автобіографічним романом Стефані Цвейг: наприкінці 1930-х єврейська родина Редліхів тікає з Німеччини на орендовану ферму в Кенії. Кароліне Лінк веде розповідь передусім очима матері Єттель і дівчинки Регіни, для якої вигнання стає домівкою, тоді як батько-юрист тужить за втраченою професією. Стримана сімейна хроніка на тлі британських таборів для «ворожих іноземців» здобула «Оскар» за найкращий іншомовний фільм 2003 року."},{"imdb_id":"tt0217505","title":"Gangs of New York","title_uk":"Банди Нью-Йорка","year":2002,"rating":7.5,"votes":509575,"genres":["Crime","Drama"],"country":"США/Італія","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Війни банд у нью-йоркському кварталі Файв-Пойнтс і призовні бунти 1863 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Скорсезе відштовхується від книжки Герберта Есбері 1927 року про кримінальний квартал Файв-Пойнтс і доводить дію до призовних бунтів у Нью-Йорку в липні 1863-го. Лінія помсти Амстердама Валлона Біллу «Різнику» вигадана, зате павільйонний Мангеттен Данте Ферретті й гра Деніела Дея-Льюїса зробили фільм подією: десять номінацій на «Оскар» і жодної статуетки. Прототип Білла, боксер Вільям Пул, насправді загинув ще 1855 року."},{"imdb_id":"tt0309047","title":"War","title_uk":"Війна","year":2002,"rating":7.5,"votes":6208,"genres":["Action","Drama","War"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос. / англ.","theme":"Війна","who_what":"Друга чеченська війна на початку 2000-х.","basis":"реальне тло, вигадані герої","note":"Стрічка тенденційна в зображенні чеченців; її неодноразово звинувачували в пропаганді.","thriller_flag":false,"decade":"2000-ті","desc":"Британець Джон повертається в Чечню, щоб викупити наречену, і бере в провідники звільненого з полону сибіряка Івана. Персонажі вигадані, а работоргівля, викупи заручників і зачистки в горах — реальні прикмети тієї війни. Олексій Балабанов зняв жорсткий і відверто заангажований фільм, який досі викликає суперечки. Івана грає Олексій Чадов, для якого ця роль стала першою великою."},{"imdb_id":"tt0339707","title":"Song for a Raggy Boy","title_uk":"Пісня для обірваного хлопця","year":2003,"rating":7.5,"votes":5290,"genres":["Drama","History"],"country":"Ірландія/Велика Британія/Данія/Іспанія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"За мемуарами Патріка Ґалвіна про жорстокість в ірландській католицькій виправній школі 1939 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Ірландський поет Патрік Ґалвін описав у мемуарах 1991 року рік, проведений у католицькій виправній школі, — Ейслінґ Волш перенесла це на екран як історію 1939-го. Новий світський учитель Вільям Франклін (Ейдан Квінн), який щойно повернувся з громадянської війни в Іспанії, стикається з режимом побиття, що його тримають брати-християни. Насильство показано без пом'якшень і без катарсису наприкінці. Стрічка вийшла в розпал ірландських розслідувань про систему притулків та виправних шкіл."},{"imdb_id":"tt0378897","title":"A Touch of Spice","title_uk":"Політики кузина (Дрібка спецій)","year":2003,"rating":7.5,"votes":15644,"genres":["Drama"],"country":"Греція/Туреччина","country_main":"Греція","region":"Європа","language":"грец./тур.","theme":"Соціальна драма","who_what":"Вигнання грецької громади зі Стамбула 1964 року; автобіографічні мотиви режисера Тассоса Булметіса.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Восени 1964-го Туреччина висилає зі Стамбула тисячі греків із грецьким громадянством — серед них хлопчика Фаніса, онука торговця прянощами. Тассос Булметіс, якого дитиною вивезли так само, розповідає це через кухню: спеції в нього працюють як мірки характеру й пам'яті, а дорослий Фаніс через десятиліття повертається до міста, звідки його забрали. Фільм став одним із найкасовіших у грецькому прокаті й повернув у розмову тему, яку довго обходили мовчанням."},{"imdb_id":"tt0311113","title":"Master and Commander: The Far Side of the World","title_uk":"Господар морів: На краю Землі","year":2003,"rating":7.5,"votes":259057,"genres":["Action","Adventure","Drama","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Наполеонівські війни на морі, 1805 рік.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Фрегат «Несамовитий» під командою Джека Обрі переслідує французький капер від берегів Бразилії до Галапагосів. Обрі, лікар Метьюрін і сам корабель вигадані Патріком О'Браяном, натомість побут вітрильного флоту, корабельна хірургія й навігація відтворені майже етнографічно. Пітер Вір зняв фільм на справжньому корпусі; два «Оскари» — за зображення і звук."},{"imdb_id":"tt0338751","title":"The Aviator","title_uk":"Авіатор","year":2004,"rating":7.5,"votes":412101,"genres":["Biography","Drama"],"country":"США/Німеччина","country_main":"США","region":"США","language":"англ.","theme":"Наука і технології","who_what":"Авіаційний магнат і кінопродюсер Говард Г'юз у 1927–1947 роках.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Мартін Скорсезе бере двадцять років Говарда Г'юза — від зйомок «Янголів пекла», що розоряли його студію, до сенатських слухань 1947-го й одного-єдиного польоту дерев'яної «Ялинової гуски». Леонардо Ді Капріо грає людину, у якої манія контролю поступово переростає в нав'язливий страх бруду. Зображення імітує двоколірний, а потім триколірний «Техніколор» відповідно до епохи. П'ять «Оскарів», зокрема Кейт Бланшетт за роль Кетрін Гепберн."},{"imdb_id":"tt0349825","title":"Miracle","title_uk":"Диво","year":2004,"rating":7.5,"votes":64284,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Тренер Герб Брукс і «Диво на льоду» — перемога збірної США з хокею на Олімпіаді 1980 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Герб Брукс зібрав збірну США зі студентів і за півроку виснажливих зборів підготував її до Олімпіади в Лейк-Плесіді. Ґевін О'Коннор знімає передусім тренерську роботу — відбір, тактику проти радянської машини, приниження заради згуртованості, — а Курт Рассел грає Брукса сухим і незручним. Матч із СРСР 22 лютого 1980-го, який американці виграли 4:3, був грою медального раунду, а не фіналом: золото здобули за два дні у грі з Фінляндією."},{"imdb_id":"tt0408306","title":"Munich","title_uk":"Мюнхен","year":2005,"rating":7.5,"votes":255234,"genres":["Drama","History","Thriller"],"country":"США/Канада/Франція","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Ізраїльська операція «Гнів Божий» після вбивства спортсменів на Олімпіаді в Мюнхені 1972 року.","basis":"реальна історія","note":"Фільм спирається на книгу «Помста» Джорджа Джонаса, достовірність якої заперечують і Мосад, і численні журналісти; головне джерело — Ювал Авів — не підтвердив свого статусу учасника операції.","thriller_flag":true,"decade":"2000-ті","desc":"Після вбивства одинадцяти ізраїльських спортсменів на Олімпіаді 1972 року Моссад починає операцію «Гнів Божий». Спілберг зі сценаристами Тоні Кушнером та Еріком Ротом веде історію очима командира групи Авнера: що довший список, то менше він розуміє, кого й навіщо вбиває. Знято сухо, без героїчної інтонації, з довгими сценами очікування. Джерело — книжка Джорджа Джонаса «Помста», побудована на свідченнях одного колишнього агента, які й досі оспорюють."},{"imdb_id":"tt0460989","title":"The Wind That Shakes the Barley","title_uk":"Вітер, що гойдає верес","year":2006,"rating":7.5,"votes":59586,"genres":["Drama","War"],"country":"Ірландія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Війна","who_what":"Ірландська війна за незалежність 1919–1921 і громадянська війна після англо-ірландського договору.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Кен Лоуч показує графство Корк 1920 року: рейди «чорно-брунатних», летючі загони ІРА, а потім розкол через договір із Лондоном. Брати Демієн і Тедді О'Донованни та їхній загін вигадані, хоча тактика й репресії відтворені за свідченнями учасників. «Золота пальмова гілка» Канн-2006. Реальні події та закони, вигадані люди; фільм спричинив гостру полеміку в британській пресі."},{"imdb_id":"tt0450188","title":"La Vie en Rose","title_uk":"Життя в рожевому кольорі","year":2007,"rating":7.5,"votes":94520,"genres":["Biography","Drama","Music","Romance"],"country":"Франція / Велика Британія / Чехія","country_main":"Франція","region":"Європа","language":"фр.","theme":"Музика та мистецтво","who_what":"Життя французької співачки Едіт Піаф від вулиць Бельвіля до світової слави.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Едіт Піаф народилася 1915 року в паризькому Бельвілі, співала на вулицях і виросла в найбільший голос Франції, а померла у сорок сім, зруйнована морфієм і артритом. Олів'є Дан монтує її життя не по порядку: дитинство в борделі, Марсель Сердан і останні концерти йдуть упереміш. Маріон Котіяр отримала за цю роль «Оскар», зігравши Піаф на всьому проміжку від юності до смерті. Роки німецької окупації, найспірніший епізод біографії співачки, фільм фактично оминає."},{"imdb_id":"tt0443680","title":"The Assassination of Jesse James by the Coward Robert Ford","title_uk":"Вбивство Джессі Джеймса боягузом Робертом Фордом","year":2007,"rating":7.5,"votes":205910,"genres":["Biography","Crime","Drama","History","Western"],"country":"США / Канада / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Останні місяці життя розбійника Джессі Джеймса і його вбивство Робертом Фордом у 1882 році.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Від пограбування потяга біля Блу-Кат у вересні 1881-го до пострілу в потилицю в Сент-Джозефі 3 квітня 1882-го — Ендрю Домінік екранізує роман Рона Гансена і майже не показує самих нальотів. Головний тут дев'ятнадцятирічний Роберт Форд, який виріс на дешевих книжечках про Джессі Джеймса й раптом опинився поруч із живим ідолом. Кейсі Аффлек номінувався за цю роль на «Оскар», Роджер Дікінз — за операторську роботу, музику написали Нік Кейв і Воррен Елліс."},{"imdb_id":"tt0427309","title":"The Great Debaters","title_uk":"Великі дебатери","year":2007,"rating":7.5,"votes":66785,"genres":["Biography","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Команда дебатерів чорношкірого коледжу Вайлі під керівництвом Мелвіна Толсона у 1935 році.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Техас 1935 року: у чорношкірому коледжі Вайлі поет і профспілковий організатор Мелвін Толсон збирає команду дебатерів, яка починає обігравати білі університети — у штаті, де за вікном лінчують. Дензел Вашингтон як режисер тримає баланс між спортивною драмою і хронікою сегрегації; серед учнів Толсона — юний Джеймс Фармер, майбутній засновник Конгресу расової рівності. Реальний фінал 1935-го Вайлі виграв у команди Університету Південної Каліфорнії — у фільмі суперника замінили на Гарвард."},{"imdb_id":"tt0813547","title":"The Counterfeiters","title_uk":"Фальшивомонетники","year":2007,"rating":7.5,"votes":48759,"genres":["Crime","Drama","History","War"],"country":"Австрія / Німеччина","country_main":"Австрія","region":"Європа","language":"нім.","theme":"Голокост","who_what":"Нацистська операція «Бернгард» у Заксенгаузені очима фальшивомонетника Соломона Смолянова.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Операція «Бернгард»: у окремому бараку Заксенгаузена нацисти зібрали друкарів, граверів і банківських службовців, щоб підробляти фунти стерлінгів і долари та підірвати економіку союзників. Штефан Рузовицький екранізує спогади учасника Адольфа Бурґера й ставить питання руба — робота за пайку й ліжко проти саботажу, який коштуватиме життя всій групі. Карл Марковіч грає Соломона Соровича, професійного фальшивомонетника, для якого якість підробки важить майже стільки ж, як виживання. «Оскар» за найкращий іншомовний фільм."},{"imdb_id":"tt0419887","title":"The Kite Runner","title_uk":"Ловець повітряних зміїв","year":2007,"rating":7.5,"votes":85537,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ., дарі","theme":"Політика та історія","who_what":"Афганістан від радянського вторгнення 1979 року до влади талібів наприкінці 1990-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Стрічка охоплює Кабул 1970-х, вторгнення СРСР, еміграцію до Каліфорнії та повернення в талібський Афганістан із публічними стратами на стадіоні. Амір, Гассан і Ассеф вигадані, як і сюжет про зраду й пізнє спокутування. Марк Форстер знімав у Кашгарі; юних акторів після прем'єри довелося вивозити з Афганістану. Історична канва точна, персонажі — з роману Халеда Госсейні."},{"imdb_id":"tt0808357","title":"Lust, Caution","title_uk":"Хіть, обережність","year":2007,"rating":7.5,"votes":48298,"genres":["Action","Drama","History","Romance","Thriller"],"country":"Тайвань / Китай","country_main":"Тайвань","region":"Східна Азія","language":"мандарин","theme":"Війна","who_what":"Японська окупація Шанхаю і колабораціоністський режим Ван Цзінвея на початку 1940-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Енг Лі відтворює Гонконг 1938-го й окупований Шанхай 1942 року: студентські патріотичні гуртки, таємну поліцію режиму Ван Цзінвея, комендантські години, чорний ринок. Студентка Ван Цзячжі, яка під виглядом заміжньої пані спокушає начальника контррозвідки пана І, вигадана, як і вся операція. За новелою Чжан Айлін; «Золотий лев» Венеції та рейтинг NC-17 у США. Реальний режим, вигадана змова."},{"imdb_id":"tt0488478","title":"12","title_uk":"12","year":2007,"rating":7.5,"votes":16037,"genres":["Crime","Drama","Mystery","Thriller"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Суд і журналістика","who_what":"Чеченські війни та їхній слід у московському суді присяжних 2000-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Микита Михалков переносить «Дванадцять розгніваних чоловіків» у Росію: присяжні в шкільному спортзалі вирішують долю чеченського підлітка, звинуваченого у вбивстві прийомного батька-офіцера. Хлопець, присяжні та сама справа вигадані, але флешбеки про зачистки й руїни Грозного відсилають до реальної війни. Спеціальний приз Венеції та номінація на «Оскар». Війна справжня, процес — ні."},{"imdb_id":"tt1013753","title":"Milk","title_uk":"Мілк","year":2008,"rating":7.5,"votes":186799,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Гарві Мілк — перший відкритий гей, обраний на виборну посаду в США, і його вбивство 1978 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Ґас Ван Сент починає з сорокаліття Гарві Мілка в нью-йоркському метро й веде до 27 листопада 1978-го, коли колишній міський наглядач Ден Вайт застрелив його та мера Джорджа Москоне. Між цим — крамничка на Кастро, чотири виборчі кампанії поспіль і боротьба проти Пропозиції 6, яка мала заборонити геям учителювати. Хроніку тих років вмонтовано просто в дію. Шон Пенн отримав «Оскар» за роль, Дастін Ленс Блек — за сценарій."},{"imdb_id":"tt1068646","title":"The Class","title_uk":"Клас","year":2008,"rating":7.5,"votes":37610,"genres":["Drama"],"country":"Франція","country_main":"Франція","region":"Європа","language":"фр.","theme":"Соціальна драма","who_what":"Рік із життя вчителя Франсуа Беґодо та його класу в паризькому передмісті — за його автобіографічною книгою.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Франсуа Беґодо викладав французьку в колежі паризького 20-го округу й написав про це книжку — у фільмі він грає самого себе. Лоран Канте рік працював зі справжніми учнями, які імпровізували в кадрі, тож більшість сцен — це суперечки в класі, де граматика раптом стає полем боротьби за гідність. «Золота пальмова гілка» 2008 року; камери постійно тримаються на рівні очей підлітків, а не вчителя."},{"imdb_id":"tt0449994","title":"Jodhaa Akbar","title_uk":"Джодха і Акбар","year":2008,"rating":7.5,"votes":36811,"genres":["Action","Drama","History","Romance","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, урду","theme":"Політика та історія","who_what":"Політичний шлюб могольського імператора Акбара та раджпутської принцеси Джодхи у XVI столітті.","basis":"натхненний реальними подіями","note":"Історичність самої «Джодхи» сумнівна — ім'я не фігурує в моголських хроніках; романтична лінія й політичні сцени вигадані, фільм викликав протести істориків і раджпутських громад.","thriller_flag":false,"decade":"2000-ті","desc":"Ашутош Ґоварікер бере XVI століття: третій могольський падишах Акбар одружується з раджпутською принцесою, щоб замирити Амбер, і поступово будує державу, де індуїсти не платять податку за віру. Грітік Рошан і Айшварія Рай грають шлюб, що починався як угода між дворами. Понад три години батальних сцен, костюмів і музики А. Р. Рахмана. Історики заперечують саме ім'я «Джодха» — джерела називають дружину Акбара інакше, — і через це прокат фільму супроводжували протести в Раджастхані."},{"imdb_id":"tt0961066","title":"Everlasting Moments","title_uk":"Вічні миті Марії Ларссон","year":2008,"rating":7.5,"votes":6211,"genres":["Drama","History"],"country":"Швеція / Данія / Норвегія / Фінляндія / Німеччина","country_main":"Швеція","region":"Європа","language":"швед.","theme":"Музика та мистецтво","who_what":"Робітниця Марія Ларссон на початку XX століття відкриває для себе фотографію.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Мальме, початок XX століття: Марія Ларссон виграє в лотерею фотокамеру Contessa, спершу хоче її продати, а натомість починає знімати сусідів, дітей і — на замовлення — покійників. Ян Труелль зняв історію родини, яку його дружина й співсценаристка Аґнета Ульфсетер-Труелль зібрала зі спогадів нащадків Ларссон. Марія Гейскянен грає жінку, чий чоловік-докер п'є й розпускає руки, а камера стає єдиним простором, що належить тільки їй. Зображення навмисне зернисте, ніби знято на плівку тих років."},{"imdb_id":"tt0986233","title":"Hunger","title_uk":"Голод","year":2008,"rating":7.5,"votes":76843,"genres":["Biography","Crime","Drama"],"country":"Велика Британія / Ірландія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Голодування Боббі Сендса та ірландських республіканців у в'язниці Мейз 1981 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Стів Макквін дебютував у повному метрі історією протестів у в'язниці Мейз під Белфастом: «брудний протест», побиття наглядачами і зрештою голодування 1981 року, під час якого Боббі Сендс помер на 66-й день. Фільм майже безсловесний, а в його середині — сімнадцятихвилинна розмова Сендса зі священником, знята одним нерухомим планом. Майкл Фассбендер різко схуд для ролі; у Каннах стрічка отримала «Золоту камеру»."},{"imdb_id":"tt1259014","title":"Mesrine: Killer Instinct","title_uk":"Ворог держави №1","year":2008,"rating":7.5,"votes":36816,"genres":["Action","Biography","Crime","Drama","Thriller"],"country":"Франція / Канада / Італія","country_main":"Франція","region":"Європа","language":"фр.","theme":"Кримінал","who_what":"Перша половина кримінальної кар'єри французького гангстера Жака Мезріна.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Жак Мезрін пройшов Алжирську війну, паризький кримінал і канадські в'язниці, аж поки французька преса не назвала його ворогом держави номер один. Перша з двох частин Жана-Франсуа Ріше доводить його до зухвалої втечі з тюрми суворого режиму в Квебеку й спроби повернутися туди зі зброєю. Венсан Кассель, який набирав і скидав вагу між блоками зйомок, отримав «Сезар»; за основу взято автобіографію самого Мезріна, а той себе відверто прикрашав."},{"imdb_id":"tt0887912","title":"The Hurt Locker","title_uk":"Володар бурі","year":2008,"rating":7.5,"votes":499509,"genres":["Drama","Thriller","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Війна в Іраку 2004 року: робота американських саперів у Багдаді.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Кетрін Бігелоу відтворює будні групи знешкодження вибухівки: саморобні фугаси, костюми EOD, натовп, у якому неможливо вирізнити спостерігача з телефоном. Сержант Вільям Джеймс і його команда вигадані, хоча сценарій Марка Боула виріс із його репортерського відрядження до Іраку. Шість «Оскарів», зокрема за фільм і режисуру — перша жінка з таким призом. Ветерани сперечалися про достовірність процедур."},{"imdb_id":"tt1326972","title":"Red Cliff II","title_uk":"Битва біля Червоної скелі 2","year":2009,"rating":7.5,"votes":26628,"genres":["Action","Adventure","Drama","History","War"],"country":"Китай / Гонконг / Тайвань / Японія / Південна Корея","country_main":"Китай","region":"Східна Азія","language":"мандарин","theme":"Війна","who_what":"Завершення битви при Чібі 208 року — вирішальної для епохи Трьох царств.","basis":"натхненний реальними подіями","note":"Фільм слідує не історичним хронікам, а роману «Трицарство» XIV століття: епізоди на кшталт «позичання стріл» і викликаного східного вітру — легенди, а не задокументовані факти.","thriller_flag":false,"decade":"2000-ті","desc":"Битва при Чібі на Янцзи 208 року, де союз Сунь Цюаня і Лю Бея спалив величезний флот Цао Цао, започаткувала поділ Китаю на Три царства. Джон Ву знімає другу половину кампанії — від хитрощів зі стрілами до вогняної атаки. Матеріал він бере радше з роману «Трицарство», ніж із хронік, тому дуель стратегів тут ефектніша за будь-який літопис; за масштабом масовки це був найдорожчий азійський фільм свого часу."},{"imdb_id":"tt1226271","title":"The Damned United","title_uk":"Проклятий Юнайтед","year":2009,"rating":7.5,"votes":48763,"genres":["Biography","Drama","Sport"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Спорт","who_what":"44 дні Браяна Клафа на посаді головного тренера «Лідс Юнайтед» у 1974 році.","basis":"реальна історія","note":"Екранізація свідомо белетризованого роману Девіда Піса; родина Браяна Клафа та Джонні Джайлз оскаржували зображення подій, останній отримав компенсацію за наклеп.","thriller_flag":false,"decade":"2000-ті","desc":"Влітку 1974-го Браян Клаф очолив «Лідс Юнайтед» — команду Дона Реві, яку роками публічно зневажав, — і протримався 44 дні. Том Гупер за сценарієм Пітера Моргана монтує ці тижні з ретроспекціями про роботу Клафа в «Дербі Каунті» та про розрив із помічником Пітером Тейлором. Майкл Шин грає марнославство й уразливість одночасно. Родина Клафа й гравці «Лідса», зокрема Джонні Джайлз, заперечували чимало епізодів роману Девіда Піса, покладеного в основу."},{"imdb_id":"tt1320082","title":"The Concert","title_uk":"Концерт","year":2009,"rating":7.5,"votes":19228,"genres":["Comedy","Drama","Music","Musical"],"country":"Франція","country_main":"Франція","region":"Європа","language":"франц., рос.","theme":"Музика та мистецтво","who_what":"Брежнєвський СРСР: чистка Большого театру 1980 року й вигнання музикантів-євреїв.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Раду Міхайляну відштовхується від реальної практики пізнього СРСР — чисток оркестрів за «п'ятою графою» і покарань диригентів, які захищали колег. Андрій Філіпов, викинутий із професії й нині прибиральник у тому ж театрі, та його авантюра з підробленими гастролями в Парижі вигадані. Комедія з Олексієм Гуськовим і Меланні Лоран; «Сезар» за музику. Тло реальне, історія — фарс."},{"imdb_id":"tt1542344","title":"127 Hours","title_uk":"127 годин","year":2010,"rating":7.5,"votes":427216,"genres":["Biography","Drama"],"country":"США / Велика Британія / Франція","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Альпініст Арон Ралстон, затиснутий каменем у каньйоні Юти, ампутує собі руку.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Квітень 2003-го, каньйон Блуджон в Юті: 27-річний Арон Ралстон нікому не сказав, куди йде, і п'ять днів простояв із правою рукою, притиснутою зірваним валуном. Денні Бойл вирішує майже нерухомий сюжет через відеощоденник героя, спогади й галюцинації, знімаючи кількома камерами в тісній щілині. Джеймс Франко тримає весь фільм сам; шість номінацій на «Оскар», зокрема за музику А. Р. Рахмана. Сценарій написано за спогадами самого Ралстона."},{"imdb_id":"tt1386932","title":"Ip Man 2","title_uk":"Іп Ман 2","year":2010,"rating":7.5,"votes":117631,"genres":["Action","Biography","Drama","History"],"country":"Гонконг / Китай","country_main":"Гонконг","region":"Східна Азія","language":"кант.","theme":"Спорт","who_what":"Іп Ман відкриває школу віньчунь у повоєнному Гонконгу.","basis":"натхненний реальними подіями","note":"Бій із британським боксером «Твістером» та конфлікт із колоніальною владою вигадані; від біографії Іп Мана залишився лише факт відкриття школи в Гонконзі.","thriller_flag":false,"decade":"2010-ті","desc":"Іп Ман із родиною тікає до Гонконгу після 1949 року й відкриває школу віньчунь на даху — без учнів, без грошей і без згоди місцевих майстрів, які тримають ринок. Друга половина — вигаданий двобій із британським боксером Твістером, придуманий заради фінального ефекту: історичний Іп Ман нічого подібного не робив. Бої, зокрема поєдинок на круглому столі, ставив Семмо Хун, який тут-таки й грає. У фіналі з'являється хлопчик, що назветься Брюсом Лі."},{"imdb_id":"tt1288376","title":"When We Leave","title_uk":"Чужа","year":2010,"rating":7.5,"votes":5730,"genres":["Drama"],"country":"Німеччина / Туреччина / Франція","country_main":"Німеччина","region":"Європа","language":"нім., тур.","theme":"Соціальна драма","who_what":"Турецько-німецька жінка тікає від насильства в шлюбі й стає жертвою «вбивства честі».","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Умай тікає зі Стамбула від чоловіка, який її б'є, і повертається з малим сином до батьків у Берлін — де сама її поява руйнує репутацію родини. Фео Аладаґ відштовхувалася від «убивств честі» в німецько-турецькому середовищі, передусім від справи Хатун Сюрюджю, застреленої в Берліні 2005 року. Сібель Кекіллі грає без надриву, і фільм тримає точку зору жінки, не перетворюючи її рідних на монстрів. Німецька кінопремія за головну роль і висування від Німеччини на «Оскар»."},{"imdb_id":"tt1668200","title":"Sarah's Key","title_uk":"Ключ Сари","year":2010,"rating":7.5,"votes":18782,"genres":["Drama","War"],"country":"Франція","country_main":"Франція","region":"Європа","language":"франц.","theme":"Голокост","who_what":"Облава «Вель д'Ів» у Парижі 16–17 липня 1942 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Жиль Паке-Бреннер відтворює облаву, яку проводила французька, а не німецька поліція: зимовий велодром без води, табір у Бон-ла-Роланд, розлучення дітей з матерями. Дівчинка Сара Старжинська, яка замкнула брата в стінній шафі, і сучасна журналістка Джулія Джармонд вигадані. Головну роль зіграла Крістін Скотт Томас; за романом Тетяни де Росне. Облава й цифри реальні, обидві родинні лінії — ні."},{"imdb_id":"tt1393746","title":"Aftershock","title_uk":"Афтершок","year":2010,"rating":7.5,"votes":10309,"genres":["Drama","History"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"мандарин","theme":"Катастрофа і виживання","who_what":"Таншанський землетрус 28 липня 1976 року і землетрус у Веньчуані 2008-го.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Фен Сяоґан відтворює 23 секунди, що зрівняли Таншань із землею, і наступні тридцять років — від наметових таборів і армійських рятувальників до Веньчуаня 2008 року, де зустрічаються розлучені родичі. Мати Лі Юаньні, змушена вибрати, кого з двійні рятувати з-під плити, та її діти вигадані. Один із найкасовіших китайських фільмів свого часу. Катастрофи й статистика реальні, родина — ні."},{"imdb_id":"tt1436045","title":"13 Assassins","title_uk":"13 убивць","year":2010,"rating":7.5,"votes":72162,"genres":["Action","Adventure","Drama"],"country":"Японія","country_main":"Японія","region":"Східна Азія","language":"япон.","theme":"Війна","who_what":"Занепад сьоґунату Токуґава, 1844 рік.","basis":"реальне тло, вигадані герої","note":"Спирається на інцидент, задокументований лише почасти; фабула вигадана.","thriller_flag":false,"decade":"2010-ті","desc":"Такаші Мііке відтворює Японію пізнього Едо: васальний кодекс, ритуальні самогубства, безкарність зведеного брата сьоґуна, застій самурайського стану напередодні реставрації Мейдзі. Загін із тринадцяти вбивць і пастка в містечку Очіай вигадані, а лорд Наріцуґу — вільна варіація на реальну постать. Ремейк фільму 1963 року з сорокахвилинною фінальною битвою. Історична доба точна, змова — літературна."},{"imdb_id":"tt2007993","title":"Warriors of the Rainbow: Seediq Bale I","title_uk":"Воїни веселки: Сідік Бале","year":2011,"rating":7.5,"votes":7666,"genres":["Action","Drama","History"],"country":"Тайвань","country_main":"Тайвань","region":"Східна Азія","language":"сідік, яп.","theme":"Війна","who_what":"Повстання племені седік проти японської колоніальної влади — інцидент у Вуше 1930 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"27 жовтня 1930 року на шкільному спортивному святі в гірському селищі Ушe воїни седік убили близько 134 японців — так почалося останнє велике повстання корінного народу проти колоніальної адміністрації Тайваню. Вей Те-шен показує й тридцять років до того: вирубку лісів, примусову працю, заборону татуювань і полювання на голови. Вождя Мона Рудао зіграв непрофесійний актор Лін Чін-тай, пресвітеріанський пастор, більшість інших ролей — теж представники корінних народів. Найдорожча тайванська постановка свого часу, спродюсована Джоном Ву."},{"imdb_id":"tt1410063","title":"The Flowers of War","title_uk":"Квіти війни","year":2011,"rating":7.5,"votes":58701,"genres":["Drama","History","Romance","War"],"country":"Китай","country_main":"Китай","region":"Східна Азія","language":"мандарин, англ.","theme":"Війна","who_what":"Нанкінська різанина, грудень 1937 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Чжан Їмоу показує захоплення Нанкіна японською армією: розстріли полонених, полювання на жінок, порятунок у зоні безпеки при католицькому соборі. Американський трунар Джон Міллер, дівчата з монастирської школи й повії з кварталу Цінхуай вигадані. Головну роль зіграв Крістіан Бейл; на той час найдорожчий китайський фільм. Різанина реальна, історія в соборі — ні."},{"imdb_id":"tt1276419","title":"A Royal Affair","title_uk":"Королівський роман","year":2012,"rating":7.5,"votes":54385,"genres":["Biography","Drama","History","Romance"],"country":"Данія","country_main":"Данія","region":"Європа","language":"дан.","theme":"Політика та історія","who_what":"Роман королеви Кароліни Матильди з лікарем Йоганном Фрідріхом Струензе при дворі божевільного данського короля Кристіана VII у 1770-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Данія 1769–1772: німецький лікар Йоганн Фрідріх Струензе стає особистим медиком психічно хворого Кристіана VII, здобуває вплив при дворі й за півтора року видає сотні указів у дусі Просвітництва — від скасування цензури до заборони тортур. Паралельно триває його роман із королевою Кароліною Матильдою, яку видали заміж п'ятнадцятирічною. Ніколай Арсель тримає рівновагу між політикою і спальнею; Міккель Бое Фьольсґор за роль короля отримав «Срібного ведмедя», сценарій — ще одного. Фінал відомий: переворот 1772 року й ешафот."},{"imdb_id":"tt2258281","title":"Beyond the Hills","title_uk":"За пагорбами","year":2012,"rating":7.5,"votes":13992,"genres":["Drama"],"country":"Румунія","country_main":"Румунія","region":"Європа","language":"рум.","theme":"Соціальна драма","who_what":"Смерть послушниці Іріни Корнічі під час екзорцизму в монастирі Танаку (2005) — справа, що сколихнула Румунію.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"У червні 2005-го в монастирі Танаку на сході Румунії померла молода послушниця Іріна Корнічі: священник і четверо черниць кілька днів тримали її прив'язаною, «виганяючи біса». Крістіан Мунджу взяв за основу документальні книжки Тетяни Ніколеску-Бран і зосередився на двох дівчатах з одного дитбудинку — одна пішла в монастир, друга приїхала її забрати. Знято довгими планами, без музики і без злодіїв: усі діють із найкращих намірів. Канни-2012: приз за сценарій і поділена нагорода двом актрисам."},{"imdb_id":"tt1649419","title":"The Impossible","title_uk":"Неможливе","year":2012,"rating":7.5,"votes":266519,"genres":["Drama","History","Thriller"],"country":"Іспанія","country_main":"Іспанія","region":"Європа","language":"англ.","theme":"Катастрофа і виживання","who_what":"Іспанська родина Марії Белон вижила під час цунамі в Індійському океані 26 грудня 2004 року в Таїланді.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"26 грудня 2004 року цунамі накрило готель у таїландському Кхао-Лаку, де відпочивала іспанська родина Марії Белон із трьома синами. Хуан Антоніо Байона знімає перші хвилини хвилі майже без цифрових ефектів — величезним резервуаром, мініатюрами й каскадерами, — а далі це історія пошуку одне одного по лікарнях. Наомі Воттс отримала номінацію на «Оскар», Том Голланд тут дебютував. Заміна іспанської родини на британську викликала докори у «вибілюванні» історії."},{"imdb_id":"tt2140373","title":"Saving Mr. Banks","title_uk":"Рятуючи містера Бенкса","year":2013,"rating":7.5,"votes":176456,"genres":["Biography","Comedy","Drama"],"country":"США, Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Переговори Волта Діснея з письменницею Памелою Треверс про екранізацію «Мері Поппінс» у 1961 році.","basis":"реальна історія","note":"Фільм створено студією Disney про саму студію: реальна Памела Треверс ненавиділа екранізацію «Мері Поппінс» і плакала на прем'єрі від обурення, що у фільмі подано як зворушення.","thriller_flag":false,"decade":"2010-ті","desc":"Волт Дісней двадцять років домагався в Памели Треверс прав на «Мері Поппінс», і 1961 року вона нарешті приїхала до Лос-Анджелеса на два тижні переговорів. Джон Лі Генкок перемежовує ці зустрічі — з диктофонними записами, які письменниця вимагала вести, — спогадами про її дитинство в Австралії й батька-алкоголіка. Емма Томпсон грає Треверс в'їдливою, але фільм студії Disney про студію Disney помітно пом'якшує розв'язку: реальна авторка екранізацію зненавиділа."},{"imdb_id":"tt2334649","title":"Fruitvale Station","title_uk":"Станція «Фрутвейл»","year":2013,"rating":7.5,"votes":92891,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Останній день життя 22-річного Оскара Гранта, застреленого поліцейським BART у Окленді 1 січня 2009 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Фільм відтворює 31 грудня 2008-го — останню добу 22-річного Оскара Гранта, який під ранок 1 січня загинув від пострілу поліцейського BART на платформі станції «Фрутвейл» в Окленді. Раян Куглер у дебюті свідомо знімає буденність: робота, донька, мати, спроби зав'язати. Відкриває картину справжнє аматорське відео з телефона свідка. Гран-прі й приз глядацьких симпатій «Санденсу», нагорода «Особливого погляду» в Каннах; у головних ролях Майкл Б. Джордан і Октавія Спенсер."},{"imdb_id":"tt1091191","title":"Lone Survivor","title_uk":"Уцілілий","year":2013,"rating":7.5,"votes":326019,"genres":["Action","Biography","Drama","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Операція «Червоні крила» 2005 року в Афганістані та порятунок єдиного вцілілого «морського котика» Маркуса Латтрелла.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Червень 2005-го, провінція Кунар: чотирьох «морських котиків», закинутих у гори по польового командира Ахмад Шаха, випадково виявляють пастухи, і групі доводиться вирішувати, що з ними робити. Пітер Берґ екранізував спогади Маркуса Латтрелла, доводячи бій на схилі до майже фізіологічної подробиці, а другу половину віддає селу Сабрай і Ґулабу, який сховав пораненого за законом пуштунвалі. Кількість бойовиків, названу в книжці Латтрелла — від 80 до 200, — офіційні оцінки не підтверджують: ішлося радше про десяток."},{"imdb_id":"tt0453562","title":"42","title_uk":"42","year":2013,"rating":7.5,"votes":109639,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Джекі Робінсон — перший темношкірий гравець Вищої бейсбольної ліги США (1947).","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"15 квітня 1947 року Джекі Робінсон вийшов на поле за «Бруклін Доджерс» і зламав неписану сегрегацію Вищої бейсбольної ліги. Браян Гелґеленд обмежується двома сезонами — від підписання контракту до першого повного року в лізі — і майже стільки ж уваги віддає менеджеру Бренчу Рікі (Гаррісон Форд), який цю авантюру задумав. Чедвік Боузман грає Робінсона підкреслено стриманим: за домовленістю той не мав права відповідати на образи."},{"imdb_id":"tt0816442","title":"The Book Thief","title_uk":"Крадійка книжок","year":2013,"rating":7.5,"votes":148373,"genres":["Drama","War"],"country":"США / Німеччина","country_main":"США","region":"США","language":"англ., нім.","theme":"Голокост","who_what":"Нацистська Німеччина 1938–1945: спалення книжок, «Кришталева ніч», бомбардування міст.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Браян Персівал екранізує роман Маркуса Зузака: провінційне баварське містечко, гітлер'юґенд, публічні спалення книжок, єврей, схований у підвалі, і нічні нальоти авіації союзників. Лізель Мемінґер, її прийомні батьки Губерманни й Макс Ванденбурґ вигадані. Музику написав Джон Вільямс, отримавши номінацію на «Оскар». Реальні хроніка й атмосфера, вигадана родина з Небесної вулиці."},{"imdb_id":"tt2852406","title":"Omar","title_uk":"Омар","year":2013,"rating":7.5,"votes":16349,"genres":["Crime","Drama","Romance","Thriller"],"country":"Палестина","country_main":"Палестина","region":"Близький Схід і Африка","language":"араб.","theme":"Політика та історія","who_what":"Ізраїльська окупація Західного берега і вербування інформаторів службою безпеки.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Гані Абу-Ассад знімає в Назареті й Наблусі, показуючи розділювальну стіну, блокпости й техніку вербування: затримання, підкинуті докази, шантаж родиною. Пекар Омар, його друзі Тарек і Амджад та агент Рамі вигадані, як і історія вбивства солдата. Номінація на «Оскар» і спецприз секції «Особливий погляд» у Каннах. Реальні практики служби безпеки, вигадана конкретна справа."},{"imdb_id":"tt1020072","title":"Selma","title_uk":"Сельма","year":2014,"rating":7.5,"votes":99590,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Марші Мартіна Лютера Кінга з Сельми до Монтгомері 1965 року за виборчі права афроамериканців.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"На початку 1965 року чорні мешканці Алабами практично не могли зареєструватися для голосування; три марші з Сельми до Монтгомері, перший із яких розігнали кийками на мосту Едмунда Петтуса, привели до ухвалення Акта про виборчі права. Ава Дюверней бере лише ці кілька місяців і показує Кінга (Девід Ойелоуо) як тактика, що зважує кожен крок, а не як монумент. Пісня Glory отримала «Оскар». Найгостріша претензія істориків — надто впертий Ліндон Джонсон, який насправді підтримував закон активніше."},{"imdb_id":"tt3671542","title":"Holding the Man","title_uk":"Тримаючи чоловіка","year":2015,"rating":7.5,"votes":14329,"genres":["Biography","Drama","History","Romance"],"country":"Австралія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ.","theme":"Соціальна драма","who_what":"15-річна любовна історія австралійців Тімоті Конігрейва і Джона Кейлі та епідемія СНІДу 1980-х.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Мельбурн, 1976-й: у католицькому Xavier College старшокласник Тімоті Коніґрейв закохується в капітана шкільної футбольної команди Джона Кейлі, і цей зв'язок триває п'ятнадцять років. Ніл Армфілд екранізував мемуари Коніґрейва, дописані за десять днів до його смерті 1994-го — Джон помер двома роками раніше. Раян Корр і Крейґ Стотт ведуть пару від шкільної форми до лікарняних палат кінця 1980-х, батьків грають Ґай Пірс і Ентоні ЛаПалья. Інтонація навмисне легка там, де легкості вже не лишається."},{"imdb_id":"tt2381111","title":"Brooklyn","title_uk":"Бруклін","year":2015,"rating":7.5,"votes":159458,"genres":["Drama","History","Romance"],"country":"Ірландія / Велика Британія","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Соціальна драма","who_what":"Хвиля ірландської еміграції до США на початку 1950-х.","basis":"реальне тло, вигадані герої","note":"Тло — радше історичне явище, ніж окрема подія.","thriller_flag":false,"decade":"2010-ті","desc":"Джон Кровлі показує провінційну Ірландію 1951 року й Бруклін тих самих літ: церковних спонсорів переїзду, пансіони для дівчат, роботу в універмагу, вечірні курси бухгалтерії, італійські квартали. Ейліш Лейсі, її сестра Роуз і двоє наречених вигадані. Сірша Ронан отримала номінацію на «Оскар»; сценарій Ніка Горнбі за романом Колма Тойбіна. Міграційний уклад реальний, доля — вигадана."},{"imdb_id":"tt3704050","title":"Remember","title_uk":"Пам'ятай","year":2015,"rating":7.5,"votes":30076,"genres":["Drama","Mystery","Thriller"],"country":"Канада / Німеччина","country_main":"Канада","region":"Інше","language":"англ., нім.","theme":"Голокост","who_what":"Пам'ять про Аушвіц і невикриті нацистські злочинці в повоєнній Північній Америці.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Атом Еґоян знімає трилер про наслідки Голокосту: списки виживанців, розшук колишніх блокфюрерів, фальшиві біографії втікачів у США й Канаді. Зев Ґутман із деменцією, який вирушає мститися, і його наставник Макс вигадані, як і всі імена в списку. Головну роль зіграв Крістофер Пламмер. Реальні і втеча воєнних злочинців, і повоєнна безкарність; історія помсти — ні."},{"imdb_id":"tt6068960","title":"Hatred (Wolyn)","title_uk":"Волинь","year":2016,"rating":7.5,"votes":7684,"genres":["Drama","War"],"country":"Польща","country_main":"Польща","region":"Європа","language":"польська, українська","theme":"Війна","who_what":"Волинська трагедія 1943 року — етнічні вбивства польського населення на Волині — очима молодої польки Зосі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Улітку 1943 року на Волині українські повстанці вбивали польське цивільне населення; кількість жертв досі лишається предметом суперечок істориків обох країн. Войцех Смажовський дивиться на це очима сільської дівчини Зосі (Міхаліна Лабач), яку віддали заміж за старшого поляка, і веде глядача через кілька років розпаду сусідського життя. Насильство знято демонстративно докладно, майже без пауз. В Україні фільм у прокат не виходив, а українські й частина польських істориків закидали йому однобокість — зустрічні вбивства майже не показані."},{"imdb_id":"tt4451458","title":"Endless Poetry","title_uk":"Нескінченна поезія","year":2016,"rating":7.5,"votes":7082,"genres":["Biography","Drama","Fantasy"],"country":"Чилі/Франція/Японія","country_main":"Чилі","region":"Латинська Америка","language":"ісп.","theme":"Автобіографія","who_what":"Алехандро Ходоровскі згадує свою юність у Сантьяго 1940–50-х років і становлення як поета — друга частина його автобіографічної дилогії після «Танцю реальності».","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Друга частина автобіографічної дилогії Алехандро Ходоровські після «Танцю реальності»: юність у Сантьяго 1940–50-х, розрив із батьком-крамарем і входження в богемне коло поетів разом із Енріке Ліном та Стеллою Діас Варін. Себе молодого грає рідний син режисера Адан, батька — інший син, Бронтіс, а сам Ходоровські з'являється як коментатор власних спогадів. Оператор Крістофер Дойл знімає це як барвистий карнавал, де реальність постійно зривається в театр."},{"imdb_id":"tt5029608","title":"Frantz","title_uk":"«Франц»","year":2016,"rating":7.5,"votes":18927,"genres":["Drama","History","Romance"],"country":"Німеччина / Франція","country_main":"Німеччина","region":"Європа","language":"нім. / фр.","theme":"Війна","who_what":"Перші повоєнні роки після Першої світової — взаємна ненависть німців і французів у 1919-му.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Франсуа Озон знімає майже цілком чорно-білу драму за п'єсою Моріса Ростана; дія відбувається у Кведлінбурзі й Парижі 1919 року. Анна оплакує нареченого, що загинув на фронті, аж поки на його могилу приходить француз Адрієн із власною версією їхнього знайомства. Паула Беєр отримала приз Венеції як найкраща молода акторка. Реваншистські настрої, «Марсельєза» в барах і бойкот усього німецького задокументовані; персонажі вигадані."},{"imdb_id":"tt5580036","title":"I, Tonya","title_uk":"Я, Тоня","year":2017,"rating":7.5,"votes":263362,"genres":["Biography","Comedy","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Фігуристка Тоня Гардінг і скандал з нападом на Ненсі Керріган перед Олімпіадою 1994 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"У січні 1994-го на Ненсі Керріган напали з палицею перед олімпійським відбором, і слід повів до оточення її суперниці Тоні Гардінг; та все одно поїхала до Ліллегаммера, а згодом отримала довічну заборону. Крейг Джилліспі будує фільм на суперечливих інтерв'ю учасників: усі брешуть, тож ключові сцени існують у кількох несумісних версіях. Марго Роббі грає Гардінг без пом'якшення, а Еллісон Дженні отримала «Оскар» за роль її матері."},{"imdb_id":"tt1485796","title":"The Greatest Showman","title_uk":"Найвеличніший шоумен","year":2017,"rating":7.5,"votes":352302,"genres":["Biography","Drama","Musical","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Ф. Т. Барнум і створення першого американського цирку-шоу в Нью-Йорку XIX століття.","basis":"натхненний реальними подіями","note":"Мюзикл суттєво відбілює Ф. Т. Барнума: замовчано експлуатацію артистів і рабині Джойс Гет; романтична лінія з Дженні Лінд та більшість персонажів вигадані.","thriller_flag":false,"decade":"2010-ті","desc":"Ф. Т. Барнум у 1840-х відкриває в Нью-Йорку музей курйозів, збирає трупу з людей, яких місто воліло не бачити, і вирушає в турне зі шведською співачкою Дженні Лінд. Майкл Ґрейсі знімає це як сучасний мюзикл із поп-номерами Пасека і Пола — «This Is Me» здобула «Золотий глобус». Історичного Барнума фільм переписує майже повністю: обходить, як той виставляв напоказ поневолену Джойс Гет, і перетворює комерційну експлуатацію артистів на історію про прийняття."},{"imdb_id":"tt5462602","title":"The Big Sick","title_uk":"Любов — хвороба","year":2017,"rating":7.5,"votes":151365,"genres":["Comedy","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ., урду","theme":"Автобіографія","who_what":"Реальна історія знайомства коміка Кумейла Нанджіані та Емілі В. Гордон, які й написали сценарій про кому Емілі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Кумейл Нанджіані і Емілі В. Ґордон написали сценарій про власне знайомство: пакистанський комік із Чикаго сходиться з американкою, ховає її від батьків, які підшукують йому дружину-мусульманку, а потім її через рідкісну хворобу вводять у штучну кому. Нанджіані грає себе, Емілі — Зої Казан, а найкраще тут — дні з її батьками (Голлі Гантер і Рей Романо) в лікарняному коридорі. Номінація на «Оскар» за оригінальний сценарій. Хронологію стиснуто, діагноз і кома були справжні."},{"imdb_id":"tt7691572","title":"Cyborgs: Heroes Never Die","title_uk":"Кіборги. Герої не вмирають","year":2017,"rating":7.5,"votes":8173,"genres":["Action","Drama","War"],"country":"Україна","country_main":"Україна","region":"Східна Європа","language":"українська, російська","theme":"Війна","who_what":"Оборона Донецького аеропорту українськими військовими у 2014–2015 роках.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ахтем Сеїтаблаєв зняв фільм про оборону нового терміналу Донецького аеропорту взимку 2014–2015 років — 242 дні, за які захисників почали називати «кіборгами». Прізвищ у героїв немає, лише позивні: Мажор, Серпень, Псих, Субота — збірні образи добровольців і кадрових військових. Замість батальних епізодів більшість екранного часу займають розмови в бетонних руїнах: про мову, історію, віру й про те, за що саме вони тут стоять."},{"imdb_id":"tt6299040","title":"The Ghazi Attack","title_uk":"Атака «Газі»","year":2017,"rating":7.5,"votes":16162,"genres":["Action","Drama","Thriller","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді, телугу","theme":"Війна","who_what":"Загибель пакистанського підводного човна PNS Ghazi біля Вішакхапатнама напередодні війни 1971 року.","basis":"натхненний реальними подіями","note":"Причини загибелі PNS Ghazi досі непевні (ймовірно, вибух власних мін); підводна дуель у фільмі — вигадка, а офіційні індійська й пакистанська версії суперечать одна одній.","thriller_flag":true,"decade":"2010-ті","desc":"На початку грудня 1971 року пакистанський підводний човен PNS Ghazi затонув біля Вішакхапатнама разом з усім екіпажем: Індія приписує це глибинним бомбам есмінця INS Rajput, Пакистан — вибуху власних мін. Санкальп Редді бере індійську версію і робить із неї камерний трилер, майже цілком замкнений у відсіках субмарини. Це перший індійський підводний воєнний фільм; його знімали одночасно телугу й гінді, у головних ролях Рана Даггубаті та Кей Кей Менон."},{"imdb_id":"tt5083738","title":"The Favourite","title_uk":"Фаворитка","year":2018,"rating":7.5,"votes":260776,"genres":["Biography","Comedy","Drama","History"],"country":"Ірландія / Велика Британія / США","country_main":"Ірландія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Суперництво Сари Черчилль і Ебігейл Мешем за прихильність королеви Анни на початку XVIII століття.","basis":"натхненний реальними подіями","note":"Свідомо вільна інтерпретація: історики заперечують показані сексуальні стосунки королеви Анни з фрейлінами, епізод з отруєнням і низку інших подій.","thriller_flag":false,"decade":"2010-ті","desc":"Початок XVIII століття, Англія воює з Францією, а хвора на подагру королева Анна майже не встає — країною керує її подруга Сара Черчилль, поки при дворі не з'являється збідніла родичка Ебігейл Гілл. Йоргос Лантімос знімає це надширококутними об'єктивами при свічках, вкладає в уста героїнь сучасну лайку і перетворює двірцеву інтригу на змагання трьох жінок. Олівія Колман отримала «Оскар», Емма Стоун і Рейчел Вайс — номінації. Любовний трикутник спирається радше на памфлети ображеної Сари, ніж на доведені факти."},{"imdb_id":"tt6543652","title":"Cold War","title_uk":"Холодна війна","year":2018,"rating":7.5,"votes":65923,"genres":["Drama","Music","Romance"],"country":"Польща / Франція / Велика Британія","country_main":"Польща","region":"Європа","language":"польська, франц.","theme":"Музика та мистецтво","who_what":"Історія кохання, натхнена долею батьків Павела Павліковського, на тлі післявоєнної Польщі та ансамблю «Мазовше».","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Павел Павліковський назвав героїв іменами своїх батьків — Зула і Віктор — і розтягнув їхню історію на п'ятнадцять років: Польща 1949-го, фольклорний ансамбль, який держава швидко перетворює на пропаганду, потім Берлін, Париж, Югославія, повернення. Кадр квадратний, плівка чорно-біла, епізоди обриваються різко, лишаючи цілі роки за монтажним стиком. Йоанна Куліг співає «Dwa serduszka» в кількох аранжуваннях — від села до паризького джазу. Приз за режисуру в Каннах і три номінації на «Оскар»."},{"imdb_id":"tt6588966","title":"Hichki","title_uk":"Гикавка","year":2018,"rating":7.5,"votes":15582,"genres":["Comedy","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Учителька із синдромом Туретта, що працює з важким класом; екранізація автобіографії Бреда Коена «Front of the Class».","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Наїна Матхур (Рані Мукерджі) хоче викладати, але синдром Туретта змушує її мимоволі скрикувати — школи відмовляють, доки одна не віддає їй клас підлітків зі знесеного нетрища. Основа — автобіографія американця Бреда Коена «Front of the Class» про вчителя з тим самим діагнозом. Сіддхартх Мальхотра переносить сюжет у кастово й майново розшароване індійське місто, де головний конфлікт не в діагнозі, а в тому, кого школа взагалі вважає своїм. Тон світлий, розв'язки передбачувані."},{"imdb_id":"tt6792282","title":"A Twelve-Year Night","title_uk":"Дванадцятирічна ніч","year":2018,"rating":7.5,"votes":11811,"genres":["Adventure","Biography","Crime","Drama","History"],"country":"Уругвай / Аргентина / Іспанія","country_main":"Уругвай","region":"Латинська Америка","language":"ісп.","theme":"Політика та історія","who_what":"Дванадцять років одиночного ув'язнення трьох тупамарос, зокрема майбутнього президента Хосе Мухіки, за уругвайської диктатури.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"У вересні 1973-го уругвайська хунта вивезла з в'язниці дев'ятьох тупамарос як «заручників»: серед них Хосе Мухіка, Маурісіо Розенкоф і Елеутеріо Фернандес Уїдобро провели дванадцять років в одиночках і ямах, з обмеженням води й забороною говорити. Альваро Бречнер знімає тісно й темно, майже не випускаючи камеру назовні. Мухіка згодом став президентом Уругваю, Розенкоф — драматургом, Фернандес Уїдобро — міністром оборони; двоє з них консультували фільм."},{"imdb_id":"tt7349662","title":"BlacKkKlansman","title_uk":"Чорний куклукскланівець","year":2018,"rating":7.5,"votes":317005,"genres":["Biography","Comedy","Crime","Drama","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Чорношкірий детектив Рон Сталворт, який у 1970-х впровадився до Ку-клукс-клану в Колорадо-Спрінгс.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Рон Сталворт, перший чорношкірий поліціянт Колорадо-Спрінгс, наприкінці 1970-х зателефонував за газетним оголошенням Ку-клукс-клану, отримав членський квиток на власне ім'я, а на зустрічі замість нього ходив білий колега-єврей. Спайк Лі екранізує його мемуари з Джоном Девідом Вашинґтоном і Адамом Драйвером, тримає комедійну інтонацію — і завершує кадрами з Шарлоттсвілля 2017 року. «Оскар» за адаптований сценарій; режисер Бутс Райлі публічно дорікав фільму надто прихильним портретом поліції."},{"imdb_id":"tt7125774","title":"Balloon","title_uk":"Повітряна куля","year":2018,"rating":7.5,"votes":15117,"genres":["Drama","History","Thriller"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Втеча родин Штрельциків і Ветцелів із НДР на саморобній повітряній кулі у вересні 1979 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"Дві родини з тюрінзького Пессенека два роки шили з підкладкової тканини повітряну кулю, щоб перелетіти прикордонну смугу НДР; перша спроба в липні 1979-го провалилася, і Штазі почала шукати власників за клаптями, знайденими в лісі. Міхаель «Буллі» Гербіг зняв натягнутий трилер про гонку: хто швидше — вони дошиють другу кулю чи їх вирахують. Політ у ніч на 16 вересня 1979-го закінчився в баварській Найлі. Ту саму історію 1982 року вже екранізував Disney."},{"imdb_id":"tt6386748","title":"Birds of Passage","title_uk":"«Перелітні птахи»","year":2018,"rating":7.5,"votes":14002,"genres":["Crime","Drama"],"country":"Колумбія","country_main":"Колумбія","region":"Латинська Америка","language":"вайюнаїкі / ісп.","theme":"Кримінал","who_what":"«Марихуанова бонанса» на колумбійському півострові Гуахіра в 1960–1980-х роках.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Сіро Ґерра й Крістіна Ґальєґо показують, як торгівля марихуаною з американськими покупцями зруйнувала клановий устрій індіанців вайю. Рапаїт Раяпу заробляє на викуп нареченої, а через двадцять років його родина втягується у міжкланову війну, що нищить її зсередини. Знімали з непрофесійними акторами вайю мовою вайюнаїкі; колумбійська заявка на «Оскар». Бонанса, роль Корпусу миру й наступний перехід до кокаїну реальні, родини вигадані."},{"imdb_id":"tt3513548","title":"Richard Jewell","title_uk":"Справа Річарда Джуелла","year":2019,"rating":7.5,"votes":108130,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Охоронець Річард Джуелл, який виявив бомбу на Олімпіаді 1996 року в Атланті, а потім став головним підозрюваним.","basis":"реальна історія","note":"Сцена, де журналістка Кеті Скраґґс здобуває інформацію в обмін на секс, вигадана; газета Atlanta Journal-Constitution офіційно вимагала спростування.","thriller_flag":false,"decade":"2010-ті","desc":"27 липня 1996-го охоронець Річард Джуелл помітив рюкзак у Столітньому олімпійському парку Атланти й почав виводити людей; після вибуху його три місяці цькували як головного підозрюваного, поки ФБР не зняло звинувачення. Клінт Іствуд екранізував статтю Марі Бреннер у Vanity Fair — про те, як слідство й газети разом ліплять «профіль» винного. Пол Волтер Гаузер, Сем Роквелл і номінована на «Оскар» Кеті Бейтс. Найгостріша претензія — вигаданий епізод із журналісткою, яка дістає злив в обмін на секс."},{"imdb_id":"tt8291806","title":"Pain and Glory","title_uk":"Біль і слава","year":2019,"rating":7.5,"votes":67623,"genres":["Drama"],"country":"Іспанія","country_main":"Іспанія","region":"Європа","language":"ісп.","theme":"Автобіографія","who_what":"Автофікційна сповідь Педро Альмодовара про старіння, хворобу й повернення до кіно.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Педро Альмодовар знімає майже про себе: режисер Сальвадор Малло — Антоніо Бандерас у перуці й одязі самого Альмодовара — не працює через хронічний біль, мириться з актором після тридцяти років мовчання і згадує дитинство в побілених печерних оселях, де мати (Пенелопа Крус) прала білизну в річці. Бандерас отримав за цю роль приз Каннів. Сам режисер називає фільм автофікцією й наполягає, що вигадав більше, ніж здається."},{"imdb_id":"tt8108206","title":"Saand Ki Aankh","title_uk":"Бичаче око","year":2019,"rating":7.5,"votes":6009,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Чандро і Пракаші Томар — сільські бабусі з Уттар-Прадеша, які після 60 років стали чемпіонками зі стрільби з пістолета.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Чандро і Пракаші Томар із села Джохарі в Уттар-Прадеші вперше взяли пістолет після шістдесяти — супроводжуючи онучок у тир — і за наступні роки зібрали сотні медалей, ставши найстаршими стрільчинями Індії. Тушар Хіранандані знімає це як комедію про двох невісток у патріархальному домі, які тренуються потайки від чоловіків. Бгумі Педнекар і Тапсі Панну грають героїнь від шістдесяти й далі — і саме за цей кастинг фільм критикували найгостріше: ролі не віддали літнім акторкам."},{"imdb_id":"tt8637428","title":"The Farewell","title_uk":"Прощання","year":2019,"rating":7.5,"votes":76037,"genres":["Comedy","Drama"],"country":"США/Китай","country_main":"США","region":"США","language":"англ./кит.","theme":"Автобіографія","who_what":"Режисерка Лулу Ван відтворює історію власної родини, яка приховала від бабусі Най-Най смертельний діагноз і влаштувала фіктивне весілля, щоб усі змогли попрощатися з нею.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Родина Лулу Ван дізналася, що бабусі лишилося кілька місяців, і за китайським звичаєм вирішила їй нічого не казати, а зібрати всіх у Чанчуні під приводом поспішного весілля двоюрідного брата. Спершу режисерка розповіла це в радіопрограмі This American Life, потім зняла фільм, який відкривається титром «засновано на справжній брехні». Аквафіна грає Біллі, американку китайського походження, для якої мовчання виглядає зрадою, а не турботою. Реальна Най-Най на момент прем'єри була жива й діагноз пережила."},{"imdb_id":"tt8108274","title":"Tanhaji: The Unsung Warrior","title_uk":"Танхаджі: Неоспіваний воїн","year":2020,"rating":7.5,"votes":38909,"genres":["Action","Biography","Drama","History"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Маратхський полководець Танаджі Малусаре і штурм форту Сінхагад 1670 року.","basis":"натхненний реальними подіями","note":"Значні історичні викривлення: Удайбхан Ратход та більшість сцен вигадані, конфлікт подано в релігійних категоріях, чого не було в реальній битві за Сінхагад 1670 року.","thriller_flag":false,"decade":"2020-ті","desc":"Лютий 1670 року: маратхський воєначальник Танаджі Малусаре штурмує гірський форт Кондхана, який Шіваджі за договором віддав Моголам, — і гине в бою, здобувши фортецю, згодом перейменовану на Сінхагад. Ом Раут знімає стилізований 3D-бойовик із уповільненнями й густою графікою: Аджай Девґн у ролі Танаджі, Саїф Алі Хан — коменданта Удайбхана. Найкасовіший гінді-фільм 2020 року. Історики закидали стрічці вільне поводження з фактами й підганяння битви XVII століття під сучасну риторику."},{"imdb_id":"tt9620288","title":"King Richard","title_uk":"Король Річард","year":2021,"rating":7.5,"votes":193215,"genres":["Biography","Drama","History","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Річард Вільямс виховує і тренує доньок Вінус і Серену, перетворюючи їх на тенісних чемпіонок світу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Річард Вільямс написав план на 78 сторінок ще до народження доньок, а потім роками тягав Вінус і Серену на розбиті корти Комптона, воюючи з бандами, тренерами й тенісною індустрією. Рейнальдо Маркус Грін обриває історію на професійному дебюті Вінус 1994 року: це фільм не про чемпіонок, а про батька, який тримався свого розрахунку всупереч усім. Вілл Сміт отримав «Оскар», Онджаню Елліс — номінацію. Продюсерками були самі сестри, і шорсткого в характері батька сюди увійшло небагато."},{"imdb_id":"tt8721424","title":"tick, tick... BOOM!","title_uk":"Тік-так... БУМ!","year":2021,"rating":7.5,"votes":129877,"genres":["Biography","Comedy","Drama","Music","Musical"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Композитор Джонатан Ларсон напередодні свого 30-річчя намагається пробитися на Бродвей у Нью-Йорку 1990 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Нью-Йорк 1990-го: Джонатан Ларсон працює офіціантом у забігайлівці Moondance, дописує футуристичний мюзикл Superbia і панікує, що йому от-от 30, а на сцену нічого не вийшло. Лін-Мануель Міранда дебютував як режисер, розгорнувши автобіографічне моношоу Ларсона у подвійну структуру — концерт і флешбеки. Ендрю Ґарфілд навчився співати спеціально для ролі. Ларсон помер від розшарування аорти 1996 року, напередодні першого показу «Богеми», яка згодом отримала Пулітцера."},{"imdb_id":"tt7518786","title":"83","title_uk":"83","year":2021,"rating":7.5,"votes":43324,"genres":["Drama","History","Sport","Biography"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Перемога збірної Індії Капіла Дева на Кубку світу з крикету 1983 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"25 червня 1983 року збірна Індії, яку букмекери оцінювали як безнадійного аутсайдера, обіграла на «Лордзі» двократних чемпіонів світу з Вест-Індії. Кабір Хан веде відлік від вильоту команди до Англії й майже покадрово відтворює ключові матчі — зокрема 175 очок Капіла Дева проти Зімбабве, телезапис яких не зберігся. Ранвір Сінгх ставив удари з самим Капілом Девом, а гравці тієї збірної консультували знімальну групу."},{"imdb_id":"tt4761112","title":"The Mauritanian","title_uk":"Мавританець","year":2021,"rating":7.5,"votes":72611,"genres":["Biography","Drama","Thriller"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Суд і журналістика","who_what":"Мохамеду Ульд Слахі понад 14 років утримують у Гуантанамо без звинувачень; адвокатка домагається його звільнення.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Мохамеду Ульд Слахі затримали 2001 року в Мавританії, і наступні чотирнадцять років він провів у Гуантанамо без жодного пред'явленого звинувачення. Кевін Макдональд знімає за його книжкою «Щоденник Гуантанамо», написаною в камері й виданою з чорними цензурними плямами, і ставить поруч дві юридичні лінії — адвокатки Ненсі Голландер і військового прокурора, який зрештою відмовився вести справу. Тахар Рахім грає без жертовної пози, з гумором, що дратує співрозмовників. Джоді Фостер отримала «Золотий глобус» за роль другого плану."},{"imdb_id":"tt14775784","title":"Great Freedom","title_uk":"«Велика свобода»","year":2021,"rating":7.5,"votes":8941,"genres":["Crime","Drama","Romance"],"country":"Австрія / Німеччина","country_main":"Австрія","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Параграф 175 кримінального кодексу ФРН, за яким чоловіків саджали за гомосексуальність до 1969 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Себастьян Майзе показує західнонімецьку в'язницю в 1945, 1957 і 1968 роках — три епохи одного закону, який нацисти посилили, а Бонн зберіг майже без змін. Ганс Гоффманн потрапляє за ґрати просто з концтабору й проводить у камерах два десятиліття поруч із засудженим за вбивство Віктором. Приз журі каннського «Особливого погляду». Практика повторних вироків реальна, Ганс вигаданий."},{"imdb_id":"tt14208870","title":"The Fabelmans","title_uk":"Фабельмани","year":2022,"rating":7.5,"votes":136706,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Автобіографія","who_what":"Напівавтобіографічна історія юності Стівена Спілберга та розпаду його родини, з якої народилася любов до кіно.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Стівен Спілберґ уперше зняв про себе: Семмі Фабельман (Ґабріель ЛаБелль) знімає на 8-мм камеру війни й вестерни з друзями, поки родина переїжджає з Нью-Джерсі в Аризону, а потім у Каліфорнію, — доки монтаж домашньої плівки не показує йому те, чого він бачити не хотів. Мішель Вільямс грає матір-піаністку, Пол Дано — батька-інженера. Імена й деталі змінено, розлучення батьків і роль камери в ньому — ні. Приз глядацьких симпатій у Торонто і сім номінацій на «Оскар»."},{"imdb_id":"tt15006566","title":"The Beasts","title_uk":"Звірі","year":2022,"rating":7.5,"votes":26319,"genres":["Drama","Thriller"],"country":"Іспанія/Франція","country_main":"Іспанія","region":"Європа","language":"ісп./франц./галісійська","theme":"Кримінал","who_what":"Французьке подружжя оселяється в галісійському селі й потрапляє у смертельний конфлікт із сусідами; натхненно вбивством нідерландця Мартіна Верфондерна в Сантоальї 2010 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"1997 року нідерландець Мартін Верфондерн оселився в майже покинутому галісійському селі Сантоалья; після років ворожнечі з сусідами він зник у січні 2010-го, а рештки знайшли лише через чотири роки. Родріго Сорогоєн переніс цю основу на французьке подружжя, що відроджує старий будинок і голосує проти вітрової електростанції, позбавляючи сусідів-братів шансу на гроші. Напруга росте з дрібниць — погляду в барі, отруєної води. Дев'ять «Гойя», зокрема за фільм, режисуру й обидві чоловічі акторські категорії."},{"imdb_id":"tt5537002","title":"Killers of the Flower Moon","title_uk":"Вбивці квіткової повні","year":2023,"rating":7.5,"votes":312203,"genres":["Crime","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Серія вбивств індіанців осейджів заради нафтових прав в Оклахомі 1920-х і перше велике розслідування ФБР.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"У 1920-х осейджі в Оклахомі були серед найбагатших людей США: нафта під резервацією належала їм за правом «хедрайтів» — і саме тому їх почали методично вбивати. Скорсезе за книжкою Девіда Ґранна дивиться не з боку слідства, а зсередини родини: Ернест Беркхарт одружується з Моллі Кайл, поки його дядько Вільям Гейл (Роберт Де Ніро) вибудовує схему спадкування. Ліллі Ґледстоун грає майже мовчки, і на ній тримається моральна вага трьох з половиною годин. Федеральні агенти з'являються аж в останній третині."},{"imdb_id":"tt21064584","title":"The Iron Claw","title_uk":"Залізний кіготь","year":2023,"rating":7.5,"votes":121363,"genres":["Biography","Drama","History","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Династія реслерів фон Еріхів у Техасі 1980-х і низка трагедій, що переслідували братів.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Фріц фон Еріх виховав синів професійними реслерами й тримав техаську промоцію World Class, а протягом 1980-х один за одним померли Девід, Майк і Керрі. Шон Даркін дивиться на це очима Кевіна, єдиного, хто залишився, і знімає радше драму про батьківський тиск, ніж спортивний фільм. Зак Ефрон радикально перебудував тіло під роль; брата Кріса зі сценарію прибрали — режисер пояснював, що стільки смертей в одній родині глядач просто не сприйняв би."},{"imdb_id":"tt13097932","title":"One Life","title_uk":"Одне життя","year":2023,"rating":7.5,"votes":41233,"genres":["Biography","Drama","History"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Голокост","who_what":"Британський брокер Ніколас Вінтон 1939 року вивозить із Чехословаччини 669 єврейських дітей.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Наприкінці 1938-го лондонський біржовий маклер Ніколас Вінтон поїхав до Праги й за кілька місяців організував вісім потягів, якими до британських родин вивезли 669 переважно єврейських дітей; дев'ятий, 1 вересня 1939 року, кордону вже не перетнув. Джеймс Гоуз чергує ту зиму з 1980-ми, коли літній Вінтон (Ентоні Гопкінс) розбирає стару валізу зі списками. Кульмінація відтворює реальний випуск телепрограми That's Life! 1988 року."},{"imdb_id":"tt22507524","title":"12.12: The Day","title_uk":"12.12: День","year":2023,"rating":7.5,"votes":5147,"genres":["Action","Crime","Drama","History","Thriller","War"],"country":"Південна Корея","country_main":"Південна Корея","region":"Східна Азія","language":"кор.","theme":"Політика та історія","who_what":"Військовий переворот Чон Ду Хвана в Сеулі 12 грудня 1979 року, година за годиною.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"12 грудня 1979 року, через два місяці після вбивства Пак Чон Хі, група генералів за одну ніч перебирає на себе армію, а з нею й країну. Кім Сон Су розписує ці дев'ять годин майже похвилинно: телефонні лінії, ворота штабу, колони, що входять у Сеул, і мінлива лояльність тих, кому доводиться вирішувати за секунди. Імена змінено, але прототипи прозорі — Хван Джон Мін і Чон У Сон грають два полюси однієї касти. Понад тринадцять мільйонів глядачів у корейському прокаті."},{"imdb_id":"tt14260836","title":"Better Man","title_uk":"Кращий","year":2024,"rating":7.5,"votes":47208,"genres":["Biography","Drama","Fantasy","Music","Musical"],"country":"Австралія / Велика Британія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя британського поп-зірки Роббі Вільямса, зображеного в кадрі як CGI-шимпанзе.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Роббі Вільямс пройшов шлях від підлітка в Take That до сольної суперзірки, панічних атак і залежностей — і сам розповідає це закадровим голосом. Майкл Ґрейсі зняв біографію, у якій співака від початку до кінця грає CGI-шимпанзе (пластику й міміку віддав Джонно Девіс), а решта світу лишається звичайною і ніхто цього не помічає. Музичні номери поставлено як великі одноплановки, зокрема сцена на Ріджент-стріт. Номінація на «Оскар» за візуальні ефекти при провальних касових зборах."},{"imdb_id":"tt5177114","title":"Young Woman and the Sea","title_uk":"Дівчина і море","year":2024,"rating":7.5,"votes":20608,"genres":["Biography","Drama","History","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Труді Едерле 1926 року стає першою жінкою, яка перепливла Ла-Манш.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"6 серпня 1926 року двадцятирічна американка Труді Едерле перепливла Ла-Манш за 14 годин 34 хвилини — майже на дві години швидше за чоловічий рекорд, і це після зірваної спроби роком раніше. Йоахім Роннінг веде класичну спортивну біографію: Нью-Йорк 1910-х, де дівчат не вчили плавати, Олімпіада в Парижі, конфлікт із федерацією і тренером. Дейзі Рідлі провела в холодній воді більшу частину зйомок. Удома Едерле зустрічали парадом із конфеті — одним із найбільших в історії Нью-Йорка."},{"imdb_id":"tt10236164","title":"The Girl with the Needle","title_uk":"Дівчина з голкою","year":2024,"rating":7.5,"votes":20832,"genres":["Crime","Drama","History"],"country":"Данія","country_main":"Данія","region":"Європа","language":"дан.","theme":"Кримінал","who_what":"Копенгаген після Першої світової і справа Дагмар Овербю, яка вбивала довірених їй немовлят.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Копенгаген 1919 року: швачка Кароліна, вагітна й без опори після війни, знаходить жінку, яка обіцяє прилаштувати немовля в добру родину. Ця жінка — Даґмар Овербю, реальна вбивця, засуджена 1921-го за смерть щонайменше дев'яти дітей. Маґнус фон Горн знімає в різкому чорно-білому, з експресіоністичними обличчями й майже беззвучним жахом; Кароліна вигадана — її очима подано історичну справу. Данська номінація на «Оскар» за найкращий міжнародний фільм."},{"imdb_id":"tt23782584","title":"Nr. 24","title_uk":"Номер 24","year":2024,"rating":7.5,"votes":20867,"genres":["Biography","Drama","War"],"country":"Норвегія","country_main":"Норвегія","region":"Європа","language":"норв./нім.","theme":"Війна","who_what":"Ґуннар Сьонстебю — найрезультативніший боєць норвезького руху опору, який під номером 24 роками саботував нацистську окупаційну машину.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Ґуннар Сьонстебю під номером 24 очолював «Ослоську банду» — групу диверсантів, яка під час нацистської окупації підривала архіви призову, склади й заводи; він став найнагороджуванішим норвежцем Другої світової. Джон Андреас Андерсен обрамляє історію лекцією літнього Сьонстебю перед школярами: він розповідає, а фільм показує операції та ціну, яку платили спіймані. Молодого героя грає Сьюр Ватне Бреан, старшого — Ерік Хів'ю. Після виходу на Netflix 2025 року стрічка стала найпопулярнішим норвезьким фільмом сервісу."},{"imdb_id":"tt32178949","title":"The Seed of the Sacred Fig","title_uk":"«Зерно священної смокви»","year":2024,"rating":7.5,"votes":21068,"genres":["Crime","Drama","Thriller"],"country":"Іран / Німеччина / Франція","country_main":"Іран","region":"Близький Схід і Африка","language":"перська","theme":"Політика та історія","who_what":"Протести «Жінка, життя, свобода» в Ірані після смерті Махси Аміні у вересні 2022 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2020-ті","desc":"Мохаммад Расулоф знімав таємно, дістав вирок і втік з Ірану напередодні прем'єри в Каннах; у фільм вмонтовані справжні відео з телефонів учасників протестів. Слідчий революційного суду Іман отримує підвищення й службовий пістолет, який зникає з дому, і починає допитувати власних дружину та доньок. Спецприз журі Канн, номінація на «Оскар». Протести документальні, родина Імана вигадана."},{"imdb_id":"tt29271622","title":"Palestine 36","title_uk":"Палестина 36","year":2025,"rating":7.5,"votes":7722,"genres":["Drama","History","War"],"country":"Палестина","country_main":"Палестина","region":"Близький Схід і Африка","language":"араб.","theme":"Політика та історія","who_what":"Арабське повстання 1936–1939 років проти британського мандату в Палестині.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"1936 рік: загальний страйк переростає у збройне повстання проти британського мандату, яке триватиме три роки й закінчиться поразкою. Аннемарі Джасір веде оповідь через Юсуфа, молодого чоловіка, що курсує між рідним селом і Єрусалимом, а поруч виводить реальних постатей мандату — верховного комісара Артура Вокопа (Джеремі Айронс), поліційного радника Чарльза Теґарта (Ліам Каннінгем) і Орда Вінґейта (Роберт Арамайо). Режисерка збирала матеріал понад десять років. Прем'єра в Торонто, головний приз у Токіо та висування Палестини на «Оскар»."},{"imdb_id":"tt29768334","title":"Train Dreams","title_uk":"«Сни про потяги»","year":2025,"rating":7.5,"votes":114835,"genres":["Drama","Western"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Освоєння американського Північного Заходу початку XX століття: залізниці, лісоповал і Великі пожежі 1910 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Клінт Бентлі екранізує повість Деніса Джонсона про поденника Роберта Ґрейн'єра, який усе життя валить ліс і зводить мости в Айдахо між 1900-ми й 1960-ми. Він втрачає дружину й доньку в лісовій пожежі та доживає віку самотньо в хатині серед вирубок. Джоел Едґертон у головній ролі, номінації на «Оскар» за сценарій і операторську роботу. Пожежі, артілі й насильство над китайськими робітниками реальні; Ґрейн'єр вигаданий."},{"imdb_id":"tt0099040","title":"An Angel at My Table","title_uk":"Янгол за моїм столом","year":1990,"rating":7.4,"votes":9517,"genres":["Biography","Drama","History"],"country":"Нова Зеландія / Австралія / Велика Британія","country_main":"Нова Зеландія","region":"Австралія і Океанія","language":"англ.","theme":"Автобіографія","who_what":"Життя новозеландської письменниці Джанет Фрейм, якій помилково діагностували шизофренію.","basis":"реальна історія","note":"Знято спершу як тричастинну телепостановку, яку згодом змонтували у прокатний повнометражний фільм.","thriller_flag":false,"decade":"1990-ті","desc":"Новозеландська письменниця Джанет Фрейм (1924–2004) вісім років пробула в психіатричних лікарнях із помилковим діагнозом «шизофренія» і пережила понад двісті сеансів електрошоку; лоботомію скасували напередодні операції, коли її збірка оповідань здобула літературну премію. Джейн Кемпіон екранізувала три автобіографічні книги Фрейм, довіривши головну роль Керрі Фокс. «Срібний лев» Венеційського фестивалю."},{"imdb_id":"tt0102426","title":"Mediterraneo","title_uk":"Середземне море","year":1991,"rating":7.4,"votes":17959,"genres":["Comedy","Drama","Romance","War"],"country":"Італія","country_main":"Італія","region":"Європа","language":"італ.","theme":"Війна","who_what":"Італійська окупація грецького острова під час Другої світової війни, 1941—1944.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Восьмеро італійських солдатів висаджуються на забутому острові Егейського моря, втрачають радіо й корабель — і просто залишаються там жити. Загін і острів вигадані, але доля італійських гарнізонів, покинутих після капітуляції 1943 року, реальна. Ґабріеле Сальваторес отримав «Оскар» за найкращий іншомовний фільм 1992 року. Знімали на грецькому острові Кастелорізо, майже без декорацій."},{"imdb_id":"tt0104694","title":"A League of Their Own","title_uk":"Їхня власна ліга","year":1992,"rating":7.4,"votes":132256,"genres":["Comedy","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Всеамериканська жіноча професійна бейсбольна ліга, заснована 1943 року, поки чоловіки воювали.","basis":"натхненний реальними подіями","note":"Головні героїні вигадані й зібрані з біографій кількох гравчинь; ліга та її обставини реальні.","thriller_flag":false,"decade":"1990-ті","desc":"Поки чоловіків забирала війна, власник «Чикаго Кабс» Філіп Ріглі 1943 року заснував Всеамериканську жіночу професійну бейсбольну лігу, що протрималася до 1954-го. Пенні Маршалл зняла історію двох сестер у команді «Рокфорд Пічез» під орудою спитого тренера, якого грає Том Генкс. Джина Девіс і Мадонна очолюють ансамбль, а у фіналі на полі з’являються справжні ветеранки ліги."},{"imdb_id":"tt0108551","title":"What's Love Got to Do with It","title_uk":"На що здатне кохання","year":1993,"rating":7.4,"votes":25912,"genres":["Biography","Drama","History","Music"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Тіна Тернер — її шлюб із Айком Тернером, домашнє насильство й повернення на сцену.","basis":"реальна історія","note":"Айк Тернер публічно заперечував частину показаних епізодів; хронологію подій у фільмі ущільнено.","thriller_flag":false,"decade":"1990-ті","desc":"Анна Мей Буллок із містечка Натбуш у Теннессі стала Тіною Тернер поруч із Айком Тернером, який роками бив і контролював її, доки 1976 року вона не втекла з далласького готелю з кількома монетами в кишені. Браян Ґібсон екранізував її мемуари «I, Tina»; Анджела Бассетт і Лоуренс Фішберн дістали номінації на «Оскар», а вокал для фонограми перезаписала сама Тернер."},{"imdb_id":"tt0106966","title":"Strawberry and Chocolate","title_uk":"Полуниця й шоколад","year":1993,"rating":7.4,"votes":6391,"genres":["Comedy","Drama","Romance"],"country":"Куба / Мексика / Іспанія","country_main":"Куба","region":"Інше","language":"ісп.","theme":"Політика та історія","who_what":"Куба 1979 року і державне переслідування гомосексуалів.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Студент-комсомолець Давід знайомиться з естетом Дієґо, щоб донести на нього, а натомість стає його другом. Обидва герої вигадані за оповіданням Сенеля Паса, але табори УМАП, чистки в культурі й еміграція через Маріель — реальне тло. Єдиний кубинський фільм, номінований на «Оскар»; Томас Ґутьєррес Алеа знімав його вже тяжко хворим."},{"imdb_id":"tt0110116","title":"Immortal Beloved","title_uk":"Безсмертна кохана","year":1994,"rating":7.4,"votes":27752,"genres":["Biography","Drama","Music","Romance"],"country":"США / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Людвіг ван Бетговен і загадка адресатки його ненадісланого листа до «Безсмертної коханої», написаного 1812 року.","basis":"реальна історія","note":"Розгадка таємниці «Безсмертної коханої» у фільмі не має підтвердження в джерелах і суперечить панівній науковій версії.","thriller_flag":false,"decade":"1990-ті","desc":"Після смерті Бетговена в березні 1827 року його секретар Антон Шиндлер шукає жінку, до якої композитор звертався в листі з Теплиць. Через її пошуки Бернард Роуз перебирає життя Бетговена — глухоту, судову війну за небожа Карла, прем'єру Дев'ятої симфонії. Ґері Олдмен грає композитора різко й нерівно. Відповідь фільму — що коханою була Йоганна, дружина брата, — вигадка режисера: музикознавці схиляються до Антонії Брентано."},{"imdb_id":"tt0110963","title":"Queen Margot","title_uk":"Королева Марго","year":1994,"rating":7.4,"votes":20513,"genres":["Biography","Drama","History","Romance"],"country":"Франція","country_main":"Франція","region":"Європа","language":"фр.","theme":"Політика та історія","who_what":"Варфоломіївська ніч 24 серпня 1572 року і релігійні війни у Франції.","basis":"реальне тло, вигадані герої","note":"Головні постаті історичні, однак інтрига, отруєння й романтична лінія — вигадка Дюма.","thriller_flag":false,"decade":"1990-ті","desc":"Патріс Шеро екранізував роман Дюма: різанина гугенотів у Луврі показана як тілесний хаос майже без політичних пояснень. Марґарита де Валуа, Карл IX і Катерина Медічі реальні, але отруєння, інтрига і роман королеви з Ла Молем належать Дюма. Ізабель Аджані й Віржині Ледуайєн; приз журі Канн і п'ять «Сезарів»."},{"imdb_id":"tt0116209","title":"The English Patient","title_uk":"Англійський пацієнт","year":1996,"rating":7.4,"votes":215137,"genres":["Drama","Romance","War"],"country":"США / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Північноафриканська та італійська кампанії 1942—1945 років.","basis":"реальне тло, вигадані герої","note":"Реальний Ласло Алмаші не мав описаного роману; його біографія суттєво переписана.","thriller_flag":false,"decade":"1990-ті","desc":"Обгорілий пацієнт у покинутому монастирі згадує довоєнні експедиції в Лівійській пустелі й роман із заміжньою англійкою. Ласло Алмаші справді існував і картографував Сахару, але його кохання, зрада і смерть вигадані Майклом Ондаатже. Дев'ять «Оскарів», зокрема за фільм і режисуру Ентоні Мінґелли. Роман Майкла Ондаатже здобув Букерівську премію 1992 року."},{"imdb_id":"tt0119815","title":"O Que É Isso, Companheiro?","title_uk":"Чотири дні у вересні","year":1997,"rating":7.4,"votes":6470,"genres":["Action","Drama","History","Thriller"],"country":"Бразилія","country_main":"Бразилія","region":"Латинська Америка","language":"португ., англ.","theme":"Політика та історія","who_what":"Викрадення посла США Чарлза Елбрика бразильськими підпільниками у вересні 1969 року.","basis":"реальна історія","note":"Частина колишніх учасників підпілля публічно критикувала фільм за пом'якшений портрет викрадачів і вільне поводження з деталями.","thriller_flag":true,"decade":"1990-ті","desc":"У вересні 1969 року бійці підпільних груп MR-8 і ALN викрали в Ріо-де-Жанейро посла США Чарлза Берка Елбрика й обміняли його на 15 політв'язнів військової диктатури. Бруну Барету екранізував спогади учасника операції Фернанду Ґабейри, який згодом став депутатом. Це було перше викрадення дипломата в Латинській Америці й перший випадок, коли режим погодився на обмін. Алан Аркін грає посла; номінація на «Оскар» за іншомовний фільм."},{"imdb_id":"tt0127536","title":"Elizabeth","title_uk":"Єлизавета","year":1998,"rating":7.4,"votes":110916,"genres":["Biography","Drama","History"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Перші роки правління англійської королеви Єлизавети I, що зійшла на трон 1558 року.","basis":"реальна історія","note":"Змову Рідольфі, роль Волсінгема і стосунки з Робертом Дадлі істотно перероблено заради драматургії.","thriller_flag":false,"decade":"1990-ті","desc":"Стрічка охоплює відрізок від ув'язнення принцеси в Тауері за Марії Тюдор і коронації 1558 року до змов герцога Норфолка та іспанського посла і рішення королеви залишитися незаміжньою. Шекхар Капур зняв історію як політичний трилер із Кейт Бланшетт, яка отримала за роль «Золотий глобус»; фільм здобув «Оскар» за грим. Хронологію подій суттєво стиснуто."},{"imdb_id":"tt0120669","title":"Fear and Loathing in Las Vegas","title_uk":"Страх і ненависть у Лас-Вегасі","year":1998,"rating":7.4,"votes":321438,"genres":["Adventure","Comedy","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Автобіографія","who_what":"Поїздки журналіста Хантера С. Томпсона й адвоката Оскара Зети Акости до Лас-Вегаса 1971 року.","basis":"натхненний реальними подіями","note":"Першоджерело — свідомо перебільшений автобіографічний текст; більшість діалогів і епізодів вигадані.","thriller_flag":false,"decade":"1990-ті","desc":"1971 року Хантер С. Томпсон двічі їздив до Лас-Вегаса — писати про мотоперегони «Мінт-400» і про з'їзд окружних прокурорів; супроводжував його адвокат-чикано Оскар Зета Акоста. Свою версію тих днів Томпсон виклав у ґонзо-повісті, де сам виступає під іменем Рауля Дюка. Террі Гілліам зняв екранізацію з Джонні Деппом і Беніціо дель Торо, а сам Томпсон з'являється в епізоді."},{"imdb_id":"tt0119683","title":"Les Misérables","title_uk":"Знедолені","year":1998,"rating":7.4,"votes":44731,"genres":["Crime","Drama","History","Romance"],"country":"США / Німеччина / Велика Британія","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Франція від Реставрації до Червневого повстання 1832 року в Парижі.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Колишній каторжник Жан Вальжан ховається від інспектора Жавера, ростить чужу доньку й опиняється на барикадах студентського повстання. Герої належать Віктору Гюґо, а от барикади червня 1832-го, тулонська каторга й паризька бідність історичні. Ліам Нісон, Джеффрі Раш і Ума Турман; постановка данця Білле Аугуста. Сценарій звів роман до однієї лінії — гонитви Жавера за Вальжаном."},{"imdb_id":"tt0125664","title":"Man on the Moon","title_uk":"Людина на Місяці","year":1999,"rating":7.4,"votes":144163,"genres":["Biography","Comedy","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя американського комедіанта і перформера Енді Кауфмана (1949–1984).","basis":"реальна історія","note":"Хронологію виступів переставлено, кілька розіграшів об'єднано в один епізод.","thriller_flag":false,"decade":"1990-ті","desc":"Енді Кауфман став відомим завдяки серіалу «Таксі» 1978 року, боровся з жінками в рестлінгу, виступав під маскою хамовитого співака Тоні Кліфтона і помер від раку легень у тридцять п'ять років у травні 1984 року. Мілош Форман зняв фільм за участі реального співавтора Кауфмана Боба Змуди; Джим Керрі отримав «Золотий глобус». Назва взята з пісні R.E.M., написаної про Кауфмана."},{"imdb_id":"tt0181530","title":"East/West","title_uk":"Схід — Захід","year":1999,"rating":7.4,"votes":5392,"genres":["Adventure","Drama","History","Romance"],"country":"Франція / Росія","country_main":"Франція","region":"Європа","language":"фр. / рос.","theme":"Політика та історія","who_what":"Повернення російських емігрантів до СРСР 1946 року на заклик Сталіна.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Лікар Голованов із дружиною-француженкою припливає до Одеси разом із тисячами репатріантів і майже одразу опиняється в комунальній пастці, з якої Марі роками шукає вихід. Родина вигадана, але кампанія повернення, арешти просто в порту й доля тих, хто повірив у амністію, задокументовані. Сандрін Боннер, Олег Меньшиков і Катрін Деньов; номінація на «Оскар»."},{"imdb_id":"tt0145503","title":"Sunshine","title_uk":"Смак сонячного світла","year":1999,"rating":7.4,"votes":15317,"genres":["Drama","History","Romance","War"],"country":"Угорщина / Німеччина / Канада / Австрія","country_main":"Угорщина","region":"Європа","language":"англ.","theme":"Політика та історія","who_what":"Століття угорської історії: Австро-Угорщина, Голокост, повстання 1956 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"1990-ті","desc":"Три покоління єврейської родини Зонненшайн змінюють прізвище на Шорш, служать імперії, потрапляють до трудового табору й до комуністичної держбезпеки. Родина та її лікер «Сонячне сяйво» вигадані, історичні злами — реальні. Іштван Сабо зняв фільм англійською, а Рейф Файнз грає одразу трьох чоловіків із роду. Стрічка триває понад три години і завершується придушенням повстання 1956 року."},{"imdb_id":"tt0213847","title":"Malena","title_uk":"Малена","year":2000,"rating":7.4,"votes":126139,"genres":["Drama","Romance","War"],"country":"Італія / США","country_main":"Італія","region":"Європа","language":"італ.","theme":"Війна","who_what":"Сицилія 1940—1945 років: вступ Італії у війну, висадка союзників, розправи над «колаборантками».","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Підліток Ренато спостерігає, як містечко цькує вродливу Малену Скордію, чоловік якої зник на фронті, а фінальне побиття на площі повторює справжню практику публічних розправ 1944 року. Малена й Ренато вигадані Джузеппе Торнаторе, хроніка війни — ні. Музику написав Енніо Морріконе; дві номінації на «Оскар». Моніка Беллуччі грає майже без реплік, а історію ведуть очі підлітка."},{"imdb_id":"tt0255094","title":"The Circle","title_uk":"Коло","year":2000,"rating":7.4,"votes":7508,"genres":["Drama"],"country":"Іран","country_main":"Іран","region":"Близький Схід і Африка","language":"перс.","theme":"Соціальна драма","who_what":"Правове становище жінок в Ісламській Республіці Іран наприкінці 1990-х.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Ланцюжок історій: жінки, що вийшли з в'язниці, не можуть купити квиток без дозволу родича, а породілля ховається, бо народила дівчинку. Героїні вигадані, але кожен епізод спирається на реальні обмеження — від заборони курити на людях до документів на подорож. «Золотий лев» Венеції 2000 року; в Ірані фільм заборонили, а Джафара Панагі згодом позбавили права знімати."},{"imdb_id":"tt0252444","title":"Rabbit-Proof Fence","title_uk":"Паркан від кролів","year":2002,"rating":7.4,"votes":31797,"genres":["Adventure","Biography","Drama"],"country":"Австралія","country_main":"Австралія","region":"Австралія і Океанія","language":"англ.","theme":"Соціальна драма","who_what":"Втеча трьох аборигенних дівчат із табору для «вкраденого покоління» через усю Австралію 1931 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"1931 року трьох дівчат-аборигенок — Моллі, Дейзі й Ґрейсі — забрали від матерів до табору Мур-Рівер у Західній Австралії. Вони втекли й пройшли пішки близько двох тисяч кілометрів додому в Джиґалонг, орієнтуючись на протикролячий паркан, що перетинав континент. Філліп Нойс екранізував книжку Доріс Пілкінгтон Ґарімари, доньки Моллі; Кеннет Брана грає чиновника О. Невілла, який особисто керував політикою «вкрадених поколінь»."},{"imdb_id":"tt0305206","title":"American Splendor","title_uk":"Американське пишноття","year":2003,"rating":7.4,"votes":54989,"genres":["Biography","Comedy","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Автобіографія","who_what":"Життя коміксиста-аутсайдера Гарві Пікара, автора автобіографічної серії American Splendor.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Гарві Пікар працював клерком у шпиталі для ветеранів у Клівленді й паралельно писав комікси про власне буденне життя — черги, сварки, роботу, хворобу. Шері Спрінґер Берман і Роберт Пульчіні змішують ігрові сцени з Полом Джаматті, мальовану анімацію і зйомки справжнього Пікара, який тут-таки коментує, наскільки актор на нього схожий. Гран-прі журі «Санденсу» 2003-го й номінація на «Оскар» за сценарій. Тон уїдливий і зовсім не зворушливий."},{"imdb_id":"tt0371280","title":"Crimson Gold","title_uk":"Багряне золото","year":2003,"rating":7.4,"votes":6158,"genres":["Crime","Drama","Thriller"],"country":"Іран","country_main":"Іран","region":"Близький Схід і Африка","language":"перс.","theme":"Соціальна драма","who_what":"За реальним газетним випадком: рознощик піци пограбував ювелірну крамницю в Тегерані.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Газетна замітка про рознощика піци, який спробував пограбувати ювелірну крамницю, стала для Аббаса Кіаростамі основою сценарію, а зняв його Джафар Панагі. Фільм починається з розв'язки й далі відмотує назад буденні приниження героя — ветерана ірано-іракської війни, що розвозить замовлення в багаті квартали Тегерана. Головну роль зіграв непрофесійний актор Хоссейн Емадеддін, який справді працював рознощиком. Приз журі програми «Особливий погляд» у Каннах; в Ірані картину заборонили."},{"imdb_id":"tt0362227","title":"The Terminal","title_uk":"Термінал","year":2004,"rating":7.4,"votes":540676,"genres":["Comedy","Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Натхненний історією Мехрана Карімі Нассері, який роками жив у паризькому аеропорту Шарль-де-Ґолль.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Іранець Мехран Карімі Нассері прожив у першому терміналі аеропорту Шарль-де-Ґолль з 1988-го до 2006 року, застрягши між загубленими документами й бюрократією. Стівен Спілберґ бере з цього лише вихідну ситуацію: його Віктор Наворський (Том Генкс) — громадянин вигаданої Кракожії, чия країна зникла під час перельоту, а термінал збудували в павільйоні як справжній. Від документальної основи лишилося небагато: замість багаторічної безвиході — комедія про доброзичливого чужинця. Нассері отримав від студії гонорар за права."},{"imdb_id":"tt0390221","title":"Maria Full of Grace","title_uk":"Марія, сповнена благодаті","year":2004,"rating":7.4,"votes":37731,"genres":["Crime","Drama"],"country":"Колумбія/США/Еквадор","country_main":"Колумбія","region":"Латинська Америка","language":"ісп.","theme":"Кримінал","who_what":"Заснований на реальних свідченнях колумбійських дівчат-наркокур'єрок, що ковтали капсули з кокаїном.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Джошуа Марстон писав сценарій за розповідями колумбійок, які возили наркотики в шлунку, і не пом'якшив жодної деталі процедури — від тренування ковтати виноградини до перельоту в Нью-Йорк. Сімнадцятирічна Марія кидає роботу на плантації троянд під Боготою й погоджується на один рейс. Каталіна Сандіно Морено, для якої це був перший фільм, отримала «Срібного ведмедя» Берлінале й номінацію на «Оскар». Усе тримається на буденності: жодного гангстерського шику, лише економічний розрахунок."},{"imdb_id":"tt0384369","title":"Before the Fall","title_uk":"Напола: Еліта фюрера","year":2004,"rating":7.4,"votes":19868,"genres":["Drama","Sport","Thriller"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Нацистські школи НАПОЛА для виховання партійної еліти, 1942 рік.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Боксера Фрідріха беруть до елітної школи в Східній Пруссії, де хлопців тренують до фанатизму, а полювання на втікачів-полонених видають за навчання. Школа й курсанти вигадані, самі ж НАПОЛА, їхня програма та відбір існували насправді. Макс Рімельт і Том Шиллінґ; фільм отримав Баварську кінопремію. Денніс Ґанзель зробив школу-інтернат моделлю всієї нацистської системи."},{"imdb_id":"tt0433383","title":"Good Night, and Good Luck.","title_uk":"На добраніч і хай щастить","year":2005,"rating":7.4,"votes":105643,"genres":["Biography","Drama","History"],"country":"США/Велика Британія/Франція/Японія","country_main":"США","region":"США","language":"англ.","theme":"Суд і журналістика","who_what":"Тележурналіст Едвард Р. Марроу, який 1954 року публічно кинув виклик сенатору Маккарті.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Осінь 1953-го — весна 1954-го, редакція CBS: Едвард Р. Марроу з продюсером Фредом Френдлі готують випуски See It Now про звільненого з ВПС лейтенанта Мило Радуловича, а тоді б'ють по самому Джозефу Маккарті. Джордж Клуні зняв усе чорно-білим і в павільйоні, а Маккарті тут «грає» сам себе — це справжня хроніка слухань. Девід Стретерн веде роль стримано, майже без жестів. Шість номінацій на «Оскар», зокрема за режисуру й сценарій."},{"imdb_id":"tt0388980","title":"The Greatest Game Ever Played","title_uk":"Найкраща гра в історії","year":2005,"rating":7.4,"votes":36381,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Аматор Френсіс Уїмет, який 1913 року переміг Гаррі Вардона на US Open з гольфу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Брукляйн, штат Массачусетс, вересень 1913-го: двадцятирічний колишній кедді Френсіс Уїмет виходить у плей-оф US Open проти британських зірок Гаррі Вардона й Теда Рея — і виграє, маючи за помічника десятирічного Едді Лоурі. Білл Пекстон як режисер веде дві лінії паралельно: юнак із робітничої родини навпроти Вардона, якого класовий бар'єр тиснув усе життя. Це екранізація книжки Марка Фроста, знята з підкресленими цифровими ефектами на кожному ударі — прийом, який подобається не всім."},{"imdb_id":"tt0445620","title":"Paradise Now","title_uk":"Рай тепер","year":2005,"rating":7.4,"votes":24960,"genres":["Crime","Drama","Thriller"],"country":"Палестина / Нідерланди / Німеччина / Франція","country_main":"Палестина","region":"Близький Схід і Африка","language":"араб.","theme":"Політика та історія","who_what":"Друга інтифада: підготовка смертників у Наблусі.","basis":"реальне тло, вигадані герої","note":"Фільм звинувачували водночас у романтизації смертників і в їх засудженні — залежно від табору критиків.","thriller_flag":true,"decade":"2000-ті","desc":"Двоє автомеханіків отримують завдання підірвати себе в Тель-Авіві, і день перед операцією перетворюється на суперечку про сенс такого вибору. Герої й організація вигадані, натомість блокпости, зруйновані будинки й вербування — реальні прикмети інтифади. Хані Абу-Асад отримав «Золотий глобус» і номінацію на «Оскар». Частину зйомок провели в самому Наблусі, у розпал бойових дій."},{"imdb_id":"tt0454776","title":"Amazing Grace","title_uk":"Дивовижна благодать","year":2006,"rating":7.4,"votes":26660,"genres":["Biography","Drama","History","Romance"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Кампанія британського парламентаря Вільяма Вілберфорса за скасування работоргівлі.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Майкл Аптед відтворює двадцятирічну парламентську кампанію Вільяма Вілберфорса, що завершилася британським законом про скасування работоргівлі 1807 року. Йоан Ґріффад грає його в роки хвороби й сумнівів, Альберт Фінні — колишнього работоргівця Джона Ньютона, автора гімну Amazing Grace. Фільм вийшов до 200-річчя закону й тримається на палатних дебатах і закулісних торгах. Роль темношкірих аболіціоністів тут звужена: Олауда Еквіано у виконанні Юсу Н'Дура з'являється лише епізодично."},{"imdb_id":"tt0446755","title":"The Painted Veil","title_uk":"Розмальована вуаль","year":2006,"rating":7.4,"votes":100582,"genres":["Drama","Romance"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Медицина та виживання","who_what":"Спалах холери в китайській глибинці 1925 року на тлі антиіноземних заворушень.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Екранізація Моема переносить глядача в Китай 1925 року: епідемія холери, монастирська місія, страйки та антибританські виступи «Руху 30 травня». Бактеріолог Волтер Фейн і його дружина Кітті вигадані, як і їхній шлюб-покарання в зачумленому містечку. Знімали в Гуансі; Едвард Нортон і Наомі Воттс також були продюсерами. Епідемії та політичне бродіння реальні, історія подружжя — ні."},{"imdb_id":"tt0844457","title":"North Face","title_uk":"Північна стіна","year":2008,"rating":7.4,"votes":17206,"genres":["Adventure","Biography","Drama","History","Sport"],"country":"Німеччина / Австрія / Швейцарія","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Катастрофа і виживання","who_what":"Трагічна спроба Тоні Курца й Андреаса Гінтерштойссера підкорити північну стіну Айгера 1936 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2000-ті","desc":"Липень 1936-го, за кілька тижнів до берлінської Олімпіади: двоє баварських солдатів, Тоні Курц і Андреас Гінтерштойссер, лізуть на північну стіну Айгера, яку нацистська преса призначила ділянкою національної слави. Філіпп Штьольцль монтує кригу й туман стіни з теплим готелем унизу, звідки за альпіністами стежать у підзорні труби. Знімали переважно на натурі й у холоді, без пафосу — розв'язка відома з підручників історії альпінізму. Журналістка, через яку подано «нижню» лінію, вигадана."},{"imdb_id":"tt0411272","title":"Mesrine: Public Enemy No. 1","title_uk":"Ворог держави №1: Легенда","year":2008,"rating":7.4,"votes":32583,"genres":["Action","Biography","Crime","Drama","Thriller"],"country":"Франція / Канада","country_main":"Франція","region":"Європа","language":"фр.","theme":"Кримінал","who_what":"Останні роки Жака Мезріна — «ворога держави номер один» — до його загибелі 1979 року.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2000-ті","desc":"Друга частина дилогії Жан-Франсуа Ріше охоплює 1970-ті: втечі з в'язниць, викрадення мільйонера Анрі Лельєвра, інтерв'ю Paris Match із бравадою про «ворога держави номер один» — і засідку біля Порт-де-Кліньянкур 2 листопада 1979-го. Венсан Кассель набрав для ролі понад двадцять кілограмів і отримав «Сезар», Ріше — «Сезар» за режисуру. Фільм великою мірою спирається на автобіографію самого Мезріна, написану у в'язниці, тож частину епізодів варто читати як його власну легенду про себе."},{"imdb_id":"tt1343703","title":"Fortress of War","title_uk":"Брестська фортеця","year":2010,"rating":7.4,"votes":11294,"genres":["Action","Drama","War"],"country":"Білорусь / Росія","country_main":"Білорусь","region":"Інше","language":"рос.","theme":"Війна","who_what":"Оборона Брестської фортеці в перші дні німецького нападу 22 червня 1941 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"22 червня 1941-го, перші дні облоги: гарнізон Брестської фортеці тримається у відрізаних казематах без води й зв'язку. Олександр Котт веде оповідь очима хлопця з музичного взводу, чиїм прототипом був Петро Клипа, і виводить реальних командирів — полкового комісара Юхима Фоміна, майора Петра Гаврилова, лейтенанта Андрія Кижеватова. Знімали на місці подій, з великою масовкою й важкою піротехнікою. Фільм створено коштом «Союзної держави» Росії та Білорусі, і його героїчна радянська оптика повністю відповідає замовникові."},{"imdb_id":"tt1422032","title":"Even the Rain","title_uk":"І дощ теж","year":2010,"rating":7.4,"votes":15585,"genres":["Drama","History"],"country":"Іспанія / Франція / Мексика","country_main":"Іспанія","region":"Європа","language":"ісп.","theme":"Соціальна драма","who_what":"Знімальна група в Болівії потрапляє у «війну за воду» в Кочабамбі 2000 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"У квітні 2000 року мешканці болівійської Кочабамби вийшли проти приватизації водопостачання, і протести переросли у вуличні бої з армією. Ісіар Больяїн і сценарист Пол Лаверті вигадали іспанську знімальну групу, що приїхала знімати кіно про Колумба: дешева масовка з місцевих індіанців виявляється тими самими людьми, які воюють за воду. Ґаель Ґарсія Берналь і Луїс Тосар грають режисера й продюсера, чиї переконання не витримують зіткнення з бюджетом."},{"imdb_id":"tt0790663","title":"The First Grader","title_uk":"Першокласник","year":2010,"rating":7.4,"votes":5078,"genres":["Biography","Drama","Romance"],"country":"Велика Британія / Кенія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ., суахілі","theme":"Соціальна драма","who_what":"84-річний кенієць Кімані Маруге, колишній повстанець мау-мау, іде в перший клас.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"2003 року Кенія скасувала плату за початкову освіту, і наступного року до сільської школи під Елдоретом прийшов 84-річний Кімані Маруге — колишній боєць мау-мау, який хотів навчитися читати. Джастін Чедвік чергує клас із флешбеками про британські табори 1950-х, показуючи, чому поява старого злить сусідів і чиновників. Олівер Літондо грає Маруге, Наомі Гарріс — учительку, яка його відстоює; знімали в справжній школі з місцевими дітьми. Маруге потрапив до Книги рекордів Гіннесса."},{"imdb_id":"tt2059255","title":"No","title_uk":"Ні","year":2012,"rating":7.4,"votes":27274,"genres":["Drama","History"],"country":"Чилі","country_main":"Чилі","region":"Латинська Америка","language":"ісп.","theme":"Політика та історія","who_what":"Рекламна кампанія «Ні» на чилійському плебісциті 1988 року, що поклала край диктатурі Аугусто Піночета.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"На плебісциті 5 жовтня 1988 року чилійці мали відповісти, чи залишиться Піночет при владі ще на вісім років; опозиції виділили п'ятнадцять хвилин нічного ефіру щодня. Пабло Ларраїн показує роботу рекламника Рене Сааведри, який замість переліку злочинів хунти пропонує райдугу і слоган про радість. Усе знято на відеокамеру U-matic 1983 року, тож архів і постановку не відрізнити. Критики закидали фільму, що перемогу він приписує рекламі, а не десятиліттям вуличного опору."},{"imdb_id":"tt1790885","title":"Zero Dark Thirty","title_uk":"Ціль номер один","year":2012,"rating":7.4,"votes":343699,"genres":["Drama","History","Thriller"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Війна","who_what":"Десятирічне полювання ЦРУ на Усаму бен Ладена та рейд у Абботтабаді 2011 року.","basis":"реальна історія","note":"Зображення тортур як ключа до знаходження бен Ладена суперечить висновкам сенатського комітету США; сенатори публічно назвали цю сюжетну лінію недостовірною.","thriller_flag":true,"decade":"2010-ті","desc":"Від чорних тюрем ЦРУ 2003 року до нічного рейду «морських котиків» у Абботтабаді 2 травня 2011-го — усе показано через одну аналітикиню, збірного персонажа на ім'я Мая. Кетрін Бігелоу і сценарист Марк Боал спиралися на розмови з учасниками пошуку; фінальні сорок хвилин зняті майже в реальному часі, крізь прилади нічного бачення. Головна претензія до фільму: він подає тортури як те, що дало ключову зачіпку, — з чим сперечався сенатський комітет з розвідки."},{"imdb_id":"tt2301592","title":"The Dance of Reality","title_uk":"Танець реальності","year":2013,"rating":7.4,"votes":10038,"genres":["Biography","Drama","Fantasy"],"country":"Чилі, Франція","country_main":"Чилі","region":"Латинська Америка","language":"ісп.","theme":"Автобіографія","who_what":"Дитинство режисера Алехандро Ходоровського в чилійському містечку Токопілья 1930-х років.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ходоровський повернувся до режисури через 23 роки, щоб екранізувати власне дитинство в портовій Токопільї 1930-х: батько-комуніст із крамницею білизни, мати, яка вірить, що син — реінкарнація її батька, і хлопчик, якого б'ють однолітки. Автобіографія тут не документ, а обряд: батька грає рідний син режисера Бронтіс, мати співає всі репліки оперним голосом, а сам 84-річний Ходоровський входить у кадр, щоб обійняти себе малого. Прем'єра — «Двотижневик режисерів» у Каннах."},{"imdb_id":"tt2182001","title":"Legend No. 17","title_uk":"Легенда №17","year":2013,"rating":7.4,"votes":6750,"genres":["Biography","Drama","Sport"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Спорт","who_what":"Хокеїст Валерій Харламов і Суперсерія СРСР — Канада 1972 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Валерій Харламов, син іспанки-емігрантки, пройшов шлях від заслання в чебаркульську команду до першої гри Суперсерії СРСР — Канада 2 вересня 1972 року, яку радянці виграли в Монреалі. Микола Лебедєв зводить біографію до двох вузлів: стосунки з тренером Анатолієм Тарасовим у виконанні Олега Меньшикова і підготовка до того матчу. Фільм знято за державної підтримки, і це відчутно — біографію помітно підчищено, а спорт подано як національний тріумф."},{"imdb_id":"tt2718492","title":"Ida","title_uk":"Іда","year":2013,"rating":7.4,"votes":63526,"genres":["Drama"],"country":"Польща","country_main":"Польща","region":"Європа","language":"польс.","theme":"Голокост","who_what":"Польща 1962 року: пам'ять про вбивство євреїв сусідами та спадок сталінського правосуддя.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Павел Павліковський знімає чорно-білу Польщу початку 1960-х: монастир, розбиті провінційні дороги, джазові клуби й тітку-суддю з минулим прокурорки сталінських трибуналів. Послушниця Анна-Іда та Ванда Ґруз вигадані, як і пошук батьківської могили в лісі. «Оскар» за іншомовний фільм 2015 року, квадратний кадр і мінімум музики. Реальні і сільські вбивства євреїв, і суддівські біографії; конкретна історія — ні."},{"imdb_id":"tt2042568","title":"Inside Llewyn Davis","title_uk":"Усередині Льюїна Девіса","year":2013,"rating":7.4,"votes":173098,"genres":["Drama","Music"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Фолк-сцена нью-йоркського Ґрінвіч-Вілліджу взимку 1961 року.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Брати Коени відтворюють кав'ярні Ґрінвіч-Вілліджу перед приходом Ділана: клуб Gaslight, студійні сесії за фіксовану плату без роялті, менеджерів-шахраїв, чиказький Gate of Horn. Льюїн Девіс вигаданий, хоча його біографію частково списано з Дейва Ван Ронка, а обкладинка платівки повторює його альбом. Гран-прі Канн; музику продюсував Т-Боун Барнетт. Сцена реальна, музикант — ні."},{"imdb_id":"tt2224317","title":"Lootera","title_uk":"Грабіжник","year":2013,"rating":7.4,"votes":18400,"genres":["Drama","Romance"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Індія 1953 року: скасування системи заміндарі й розорення старої земельної аристократії.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Вікрамадітья Мотване переносить оповідання О. Генрі в Бенгалію 1953-го, коли закон про скасування заміндарі відібрав у поміщиків землю, доходи й статус. Заміндар Роя Чоудхурі, його донька Пакхі та шахрай, що видає себе за археолога, вигадані. Оператор Магендра Шетті зняв стрічку в приглушених осінніх тонах; музика Аміта Тріведі. Земельна реформа реальна, історія кохання й пограбування — ні."},{"imdb_id":"tt0903657","title":"Love & Mercy","title_uk":"Любов і милосердя","year":2014,"rating":7.4,"votes":45972,"genres":["Biography","Drama","Music"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Брайан Вілсон із The Beach Boys: запис альбому Pet Sounds і його психічна криза під опікою лікаря Юджина Ленді.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Білл Полад розповідає про Брайана Вілсона двома шарами, що чергуються: 1960-ті, де Пол Дано записує Pet Sounds і Good Vibrations, чуючи в голові дедалі більше голосів, і 1980-ті, де Джон К'юсак живе під цілодобовим наглядом психотерапевта Юджина Ленді. Елізабет Бенкс грає Мелінду Ледбеттер, продавчиню автосалону, яка допомогла Вілсону вирватися; Ленді згодом позбавили ліцензії. Студійні сцени відтворені за реальними сесійними плівками."},{"imdb_id":"tt2192016","title":"The Dark Horse","title_uk":"Темний кінь","year":2014,"rating":7.4,"votes":6886,"genres":["Biography","Drama"],"country":"Нова Зеландія","country_main":"Нова Зеландія","region":"Австралія і Океанія","language":"англ.","theme":"Спорт","who_what":"Маорійський шахіст Дженесіс Потіні, який попри біполярний розлад навчав шахів дітей із бідних районів.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Дженесіс Потіні, шахіст-маорі з новозеландського Ґізборна, жив із біполярним розладом і водночас тренував дітей із бідних родин у клубі Eastern Knights, вивозячи їх на національні турніри. Джеймс Нейпір Робертсон бере кілька місяців після чергової госпіталізації Потіні, коли той береться зібрати команду й одночасно витягнути племінника з байкерського угруповання. Кліфф Кертіс набрав для ролі понад тридцять кілограмів і здобув за неї головні акторські нагороди Нової Зеландії."},{"imdb_id":"tt3203606","title":"Trumbo","title_uk":"Трамбо","year":2015,"rating":7.4,"votes":87943,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Сценарист Далтон Трамбо, внесений до «чорного списку Голлівуду» за часів маккартизму, писав під псевдонімами.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1947 року Далтон Трамбо, найдорожчий сценарист Голлівуду, відмовився відповідати Комісії з розслідування антиамериканської діяльності, відсидів одинадцять місяців і потрапив до «чорного списку» — далі писав під псевдонімами й чужими іменами, зокрема «Римські канікули». Джей Роуч знімає це як гірку виробничу комедію, де Браян Кренстон друкує сценарії просто у ванні, а Гелен Міррен грає колумністку Гедду Гоппер. Блокаду зламали 1960-го Отто Премінджер і Кірк Дуґлас, поставивши ім'я Трамбо в титри. Частина другорядних героїв — збірні постаті."},{"imdb_id":"tt2097298","title":"McFarland, USA","title_uk":"Макфарленд, США","year":2015,"rating":7.4,"votes":46954,"genres":["Biography","Drama","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Тренер Джим Вайт створив із дітей мексиканських наймитів команду з кросу, яка 1987 року виграла чемпіонат Каліфорнії.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1987 рік, містечко Макфарленд у каліфорнійській Центральній долині: звільнений з попередньої школи тренер Джим Вайт помічає, що його учні-латиноамериканці, які до уроків збирають городину, бігають швидше за всіх. Нікі Каро знімає диснеївську спортивну драму, але не оминає ані спекотних борозен, ані того, що стипендія в коледжі для цих родин — єдиний вихід. Кевін Костнер грає без харизматичних промов. Макфарленд справді виграв перший чемпіонат штату з кросу 1987 року, а потім ще вісім разів."},{"imdb_id":"tt3808342","title":"Son of Saul","title_uk":"Син Савла","year":2015,"rating":7.4,"votes":54793,"genres":["Drama","War"],"country":"Угорщина","country_main":"Угорщина","region":"Європа","language":"угор., нім., ідиш","theme":"Голокост","who_what":"Повстання зондеркоманди в Аушвіц-Біркенау в жовтні 1944 року очима в'язня-єврея.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Жовтень 1944-го, Аушвіц-Біркенау: в'язні зондеркоманди, яких змушували обслуговувати крематорії, готують повстання — і саме тоді Савл (Ґеза Рьоріґ) вирішує будь-що поховати одного хлопчика за єврейським обрядом. Ласло Немеш тримає камеру впритул до потилиці героя, у форматі 4:3 і на короткому фокусі: жахи табору лишаються розмитими за спиною і в звуці. Гран-прі Канн і «Оскар» за іншомовний фільм — за дебютний повний метр. В основі — свідчення та «Сувої Аушвіцу», записані самими членами зондеркоманди."},{"imdb_id":"tt3263904","title":"Sully","title_uk":"Диво на Гудзоні","year":2016,"rating":7.4,"votes":325380,"genres":["Biography","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Катастрофа і виживання","who_what":"Пілот Чеслі «Саллі» Салленбергер, який 2009 року посадив аварійний лайнер US Airways на річку Гудзон, урятувавши 155 людей.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"15 січня 2009 року рейс US Airways 1549 через дві хвилини після зльоту з Ла-Гуардії втратив обидва двигуни, зіткнувшись зі зграєю казарок, і Чеслі Салленберґер посадив лайнер на Гудзон — усі 155 людей вижили. Іствуд віддає самій посадці кілька хвилин, а фільм будує навколо слухань NTSB, які ставлять під сумнів рішення пілота. Том Генкс грає людину, що не почувається героєм. Реальні слідчі заперечували проти такого зображення, і на прохання Салленберґера їхні прізвища змінили."},{"imdb_id":"tt5936692","title":"The Last Family","title_uk":"Остання родина","year":2016,"rating":7.4,"votes":5250,"genres":["Biography","Drama"],"country":"Польща","country_main":"Польща","region":"Європа","language":"польська","theme":"Музика та мистецтво","who_what":"Двадцять вісім років життя родини художника Здзіслава Бексінського — від переїзду до варшавської багатоповерхівки до трагічного фіналу.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Здзіслав Бексінський усе життя знімав себе й рідних на камеру — з цього домашнього архіву Ян П. Матушинський і зібрав фільм про двадцять вісім років у варшавському блоці. Художник малює жахіття й лишається спокійним; його син Томаш, радіоведучий і перекладач фільмів, живе в постійній кризі; мати й бабуся тримають побут. Анджей Северин отримав акторський приз Локарно. Фінал родини відомий заздалегідь, і картина не робить із нього таємниці."},{"imdb_id":"tt4341582","title":"Queen of Katwe","title_uk":"Королева Катве","year":2016,"rating":7.4,"votes":20239,"genres":["Biography","Drama","Sport"],"country":"США / ПАР","country_main":"США","region":"США","language":"англ., луганда","theme":"Спорт","who_what":"Дівчинка з угандійських нетрів Фіона Мутесі, яка стала шаховою чемпіонкою й майстринею ФІДЕ.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Фіона Мутесі торгувала кукурудзою в кампальських нетрях Катве, коли тренер Роберт Катенде привів її до шахового гуртка при місіонерській програмі; за кілька років вона грала на шаховій олімпіаді й отримала звання майстрині ФІДЕ. Міра Наїр знімала в самому Катве, з місцевими дітьми в кадрі. Лупіта Ніонго грає матір Фіони, Девід Ойелоуо — тренера; фільм уникає спортивної патетики й радше рахує, скільки коштує родині один переїзд."},{"imdb_id":"tt4555426","title":"Darkest Hour","title_uk":"Темні часи","year":2017,"rating":7.4,"votes":245293,"genres":["Biography","Drama","History","War"],"country":"Велика Британія / США","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ.","theme":"Політика та історія","who_what":"Перші тижні Вінстона Черчилля на посаді прем'єра у травні 1940 року та рішення не йти на переговори з Гітлером.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Травень 1940-го: Черчилль отримує прем'єрство, коли вермахт котиться Францією, а у власному кабінеті лорд Галіфакс тисне почати мирні переговори через Муссоліні. Джо Райт стискає дію до кількох тижнів і майже до інтер'єрів — коридори, бункер, палата громад — і завершує промовою «ми битимемося на пляжах». Гері Олдмен під протезним гримом Кадзухіро Цудзі отримав «Оскар», гример — свій. Епізод, у якому Черчилль спускається в метро радитися з пасажирами, історики називають вигадкою сценариста."},{"imdb_id":"tt4209788","title":"Molly's Game","title_uk":"Велика гра","year":2017,"rating":7.4,"votes":205511,"genres":["Biography","Crime","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Кримінал","who_what":"Колишня гірськолижниця Моллі Блум, яка організувала підпільні покерні ігри для еліти й потрапила під слідство ФБР.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Моллі Блум ішла на Олімпіаду в могулі, зламалася на кваліфікації, а за кілька років уже вела найдорожчі підпільні покерні столи Лос-Анджелеса, згодом Нью-Йорка — з голлівудськими зірками, фінансистами й, як з'ясувалося, російськими грошима. Аарон Соркін у режисерському дебюті монтує розмови з адвокатом і флешбеки в одному темпі скоромовки; Джессіка Честейн тримає цей текст без задишки. Ключовий конфлікт — відмова Блум називати імена гравців навіть під загрозою вироку. Номінація на «Оскар» за адаптований сценарій."},{"imdb_id":"tt6135348","title":"120 BPM (Beats Per Minute)","title_uk":"120 ударів на хвилину","year":2017,"rating":7.4,"votes":17776,"genres":["Drama"],"country":"Франція","country_main":"Франція","region":"Європа","language":"франц.","theme":"Соціальна драма","who_what":"Паризький осередок ACT UP на початку 1990-х і боротьба ВІЛ-активістів за доступ до ліків.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Париж початку 1990-х: щотижневі збори осередку ACT UP, суперечки про тактику, акції з фальшивою кров'ю проти фармкомпаній, лекції про презервативи в школах. Робен Кампійо, який сам був в ACT UP, чергує ці засідання з любовною лінією Наталя й Шона у виконанні Арно Валуа й Наюеля Переса Біск'ярта. Персонажі вигадані, а от механіка зборів відтворена майже документально. Гран-прі Каннського фестивалю 2017 року і шість «Сезарів»."},{"imdb_id":"tt2396589","title":"Mudbound","title_uk":"«Мадбаунд»","year":2017,"rating":7.4,"votes":58025,"genres":["Drama","War"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Соціальна драма","who_what":"Расова сегрегація в дельті Міссісіпі та повернення чорношкірих ветеранів Другої світової додому в 1946-му.","basis":"реальне тло, вигадані герої","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Ді Різ екранізує роман Хіларі Джордан про дві родини на одній фермі — білих Макаленів і чорношкірих орендарів Джексонів. Двоє чоловіків повертаються з фронту: один із Європи, другий — танкіст із 761-го батальйону, і вдома їх зустрічає Ку-клукс-клан. Чотири номінації на «Оскар», зокрема Мері Дж. Блайдж і Рейчел Морісон — перша жінка-оператор у цій категорії. Оренда землі й лінчування реальні, родини — вигадані."},{"imdb_id":"tt6576556","title":"The Silent Revolution","title_uk":"Мовчазна революція","year":2018,"rating":7.4,"votes":6576,"genres":["Drama","History"],"country":"Німеччина","country_main":"Німеччина","region":"Європа","language":"нім.","theme":"Політика та історія","who_what":"Клас східнонімецької школи, який 1956 року вшанував хвилиною мовчання жертв Угорського повстання й поплатився атестатами.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"1956 року випускний клас школи в Шторкові почув із західного радіо про придушення повстання в Угорщині і на уроці вшанував загиблих хвилиною мовчання. Ларс Краум екранізує книжку одного з тих учнів, Дітріха Ґарстки: далі приїзд міністра освіти НДР, вимога назвати призвідника і вибір між атестатом і однокласниками. Майже весь фільм — розмови в класах і на кухнях, тиск м'який і невідворотний. Учні зрештою опинилися на Заході й складали випускні іспити вже там."},{"imdb_id":"tt1226837","title":"Beautiful Boy","title_uk":"Прекрасний хлопчик","year":2018,"rating":7.4,"votes":131948,"genres":["Biography","Drama"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Медицина та виживання","who_what":"Журналіст Девід Шефф і його син Нік, який роками боровся з метамфетаміновою залежністю; за двома мемуарами.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Журналіст Девід Шефф і його син Нік видали дві книжки про одні й ті самі роки: батько — «Beautiful Boy», син — «Tweak». Фелікс ван Ґроенінген зводить їх в одну історію, яка навмисне ходить по колу: зрив, ремісія, обіцянка, знову лікарня. Стів Карелл і Тімоті Шаламе грають без надриву, часова структура рвана. Ні переможного одужання, ні моралі тут немає — залежність показано як хронічний стан цілої родини."},{"imdb_id":"tt7363076","title":"Raid","title_uk":"Рейд","year":2018,"rating":7.4,"votes":24069,"genres":["Crime","Drama","Thriller"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Кримінал","who_what":"Податковий інспектор проводить рекордний обшук у політика; за реальним рейдом 1981 року.","basis":"натхненний реальними подіями","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"1981 рік, Лакхнау: команда податкової служби заходить у маєток впливового депутата й не виходить звідти кілька діб, простукуючи стіни й розбираючи підлогу. Радж Кумар Ґупта відштовхувався від реального обшуку, що його провів офіцер Індійської податкової служби, і тримається загальної канви — подробиці тієї справи оприлюднювали скупо. Аджай Девґн грає інспектора, який не підвищує голосу, а Саурабх Шукла в ролі «Тауджі» перетягує на себе половину сцен. Кульмінація — без бійок: папери, ваги й натовп під ворітьми."},{"imdb_id":"tt5827916","title":"A Hidden Life","title_uk":"Таємне життя","year":2019,"rating":7.4,"votes":32630,"genres":["Biography","Drama","Romance","War"],"country":"США / Німеччина","country_main":"США","region":"США","language":"англ., нім.","theme":"Війна","who_what":"Австрійський селянин Франц Єггерштеттер, страчений 1943 року за відмову присягнути Гітлеру.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Селянин Франц Єґерштеттер із гірського села Санкт-Радеґунд відмовився присягати Гітлеру, був заарештований 1943 року і страчений у Бранденбурзі; 2007-го його беатифікували. Терренс Малік розтягує майже три години на роботу в полі, листи між Францом і дружиною Франціскою та тихий тиск односельців. Діалогів мало, натомість Альпи, коси й дощ; каркасом сценарію стало реальне листування подружжя, опубліковане після війни."},{"imdb_id":"tt8655470","title":"The Specials","title_uk":"Особливі","year":2019,"rating":7.4,"votes":12529,"genres":["Comedy","Drama"],"country":"Франція","country_main":"Франція","region":"Європа","language":"франц.","theme":"Соціальна драма","who_what":"Стефан Бенамю й Дауд Тату та їхні паризькі асоціації, що опікуються підлітками з важким аутизмом.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2010-ті","desc":"Стефан Бенаму й Дауд Тату тримають у Парижі дві асоціації: одна бере до себе підлітків із важким аутизмом, яких відмовляються тримати лікарні, друга вчить хлопців із передмість за ними доглядати. Олів'є Накаш і Ерік Толедано, автори «1+1», знали обох задовго до власної кар'єри в кіно й зняли фільм про цю роботу — і про перевірку, яка може її закрити, бо потрібних дозволів немає. Венсан Кассель і Реда Катеб грають засновників; частину підопічних зіграли люди з реальним досвідом аутизму."},{"imdb_id":"tt6264938","title":"Kesari","title_uk":"Кесарі","year":2019,"rating":7.4,"votes":26546,"genres":["Action","Drama","History","Thriller","War"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Війна","who_what":"Битва при Сарагархі 1897 року: 21 сикхський солдат проти тисяч афганців.","basis":"реальна історія","note":null,"thriller_flag":true,"decade":"2010-ті","desc":"12 вересня 1897 року сигнальний пост Сарагархі на хребті Самана обороняв двадцять один солдат 36-го сикхського полку проти кількох тисяч афридіїв і оракзаїв — усі загинули, передаючи геліографом повідомлення сусіднім фортам до останнього. Анураг Сінгх розтягує один день бою майже на весь фільм, а перед тим ставить конфлікт гавільдара Ішара Сінгха (Акшай Кумар) із британським командуванням. Батальна частина знята розмашисто й патетично, з уповільненнями та хоровим саундтреком. Дружина героя й частина його біографії — сценарний додаток."},{"imdb_id":"tt10796286","title":"Dear Comrades!","title_uk":"Дорогі товариші!","year":2020,"rating":7.4,"votes":6540,"genres":["Drama","History"],"country":"Росія","country_main":"Росія","region":"Східна Європа","language":"рос.","theme":"Політика та історія","who_what":"Розстріл робітничої демонстрації в Новочеркаську 1962 року очима відданої партійної активістки, яка шукає зниклу доньку.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Червень 1962-го, Новочеркаськ: робітники електровозобудівного заводу вийшли проти підвищення цін і зниження розцінок — по демонстрації відкрили вогонь, загиблих ховали таємно, справу засекретили на десятиліття. Андрій Кончаловський дивиться на це очима переконаної партійної працівниці (Юлія Висоцька), яка вимагає покарати «зачинщиків», а потім шукає доньку серед зниклих. Знято чорно-білим у кадрі 4:3, музика звучить тільки з радіо. Спеціальний приз журі Венеції 2020 року."},{"imdb_id":"tt10633456","title":"Minari","title_uk":"Мінарі","year":2020,"rating":7.4,"votes":127121,"genres":["Drama"],"country":"США","country_main":"США","region":"США","language":"англ., кор.","theme":"Автобіографія","who_what":"Родина корейських іммігрантів облаштовує ферму в Арканзасі 1980-х — напівавтобіографічна історія дитинства режисера Лі Айзека Чуна.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Лі Айзек Чун виріс на фермі в Арканзасі, куди його батьки-корейці переїхали в 1980-х вирощувати овочі для корейських громад США, — з цих спогадів і зроблено фільм. Дія охоплює перший рік родини Ї на новій землі: трейлер посеред поля, зміни на птахофабриці, приїзд бабусі з Кореї. Стівен Юн грає батька, який уперто вкладає в землю останні гроші, а Юн Йо-джон отримала «Оскар» за роль бабусі Сунджі."},{"imdb_id":"tt9738784","title":"Persian Lessons","title_uk":"Уроки перської","year":2020,"rating":7.4,"votes":15883,"genres":["Drama","War"],"country":"Німеччина/Росія/Білорусь","country_main":"Німеччина","region":"Європа","language":"нім./франц.","theme":"Голокост","who_what":"Бельгійський єврей у нацистському концтаборі рятується від розстрілу, вигадуючи неіснуючу «перську» мову й навчаючи їй офіцера СС.","basis":"натхненний реальними подіями","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Франція, 1942-й: щоб не бути розстріляним, бельгійський єврей Жиль видає себе за перса й потрапляє кухарем-репетитором до гауптштурмфюрера, який мріє після війни відкрити ресторан у Тегерані. Мову він вигадує щовечора — з імен в'язнів у таборових списках, які сам же переписує. Вадим Перельман екранізував оповідання Вольфґанґа Кольхаазе; що такий випадок стався насправді, історики не підтверджують. Наюель Перес Біскаярт і Ларс Айдінґер тримають двогодинну дуель майже вдвох."},{"imdb_id":"tt9784798","title":"Judas and the Black Messiah","title_uk":"Юда і чорний месія","year":2021,"rating":7.4,"votes":116021,"genres":["Biography","Crime","Drama","History"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Політика та історія","who_what":"Інформатор ФБР Вільям О'Ніл зраджує лідера чиказьких «Чорних пантер» Фреда Гемптона, убитого поліцією 1969 року.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Чиказький автовикрадач Вільям О'Ніл трапляється ФБР і дістає вибір: строк або робота інформатором усередині місцевого відділення «Чорних пантер». Шака Кінґ веде дві лінії паралельно — двадцятиоднорічного Фреда Гемптона, який будує «Веселкову коаліцію» з бідних білих і латиноамериканців, і людину, що щодня приносить кураторові план його квартири. Розв'язка — поліційний рейд 4 грудня 1969 року. Деніел Калуя отримав «Оскар» за роль другого плану, а фільм відкривається справжнім телеінтерв'ю О'Ніла, знятим наприкінці 1980-х."},{"imdb_id":"tt8745676","title":"The Swimmers","title_uk":"Плавчині","year":2022,"rating":7.4,"votes":40924,"genres":["Biography","Drama","History","Sport"],"country":"Велика Британія","country_main":"Велика Британія","region":"Британія та Ірландія","language":"англ., араб.","theme":"Спорт","who_what":"Сестри Юсра і Сара Мардіні тікають із Сирії через Егейське море, і Юсра доходить до Олімпіади в Ріо.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Дарайя під Дамаском, 2015-й: плавчині Юсра й Сара Мардіні вирушають через Туреччину до Європи, і коли мотор перевантаженого човна глухне дорогою на Лесбос, вони по черзі тягнуть його у воді кілька годин. Саллі Ель Госейні знімає першу половину як історію двох підлітків, другу — як шлях через Балкани до збірної біженців на Олімпіаді в Ріо. Юсру й Сару зіграли рідні сестри Наталі й Манал Ісса. Про переслідування Сари в Греції сказано лише в титрах."},{"imdb_id":"tt8983228","title":"Jhund","title_uk":"Джхунд","year":2022,"rating":7.4,"votes":26264,"genres":["Biography","Drama","Sport"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Спорт","who_what":"Учитель Віджай Барсе створює футбольну команду з підлітків нагпурських нетрів і засновує організацію Slum Soccer.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Віджай Барсе, викладач фізкультури в Наґпурі, побачив, як підлітки з нетрів під дощем ганяють пластикове відро замість м'яча, і почав збирати з них команди — так виросла організація Slum Soccer. Наґрадж Манджуле віддає першу половину фільму не грі, а тому, як цих дітей не пускають ані на поле, ані в державні реєстри: у багатьох немає навіть документів. Амітабх Баччан грає Барсе підкреслено непомітним, майже фоновим персонажем."},{"imdb_id":"tt16419074","title":"Air","title_uk":"Air: Велика гра","year":2023,"rating":7.4,"votes":198098,"genres":["Drama","History","Sport"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Спорт","who_what":"Як Nike 1984 року уклала контракт із новачком Майклом Джорданом і створила бренд Air Jordan.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"1984 року баскетбольний напрям Nike програвав Converse і Adidas, і скаут Сонні Ваккаро (Метт Деймон) поставив увесь річний бюджет на одного новачка — Майкла Джордана, який Nike навіть не розглядав. Бен Аффлек зняв фільм і зіграв Філа Найта, а переговори веде не спортсмен, а його мати Делоріс (Віола Девіс), яка вимагає відсоток із продажів. Джордана в кадрі майже не показують — тільки зі спини. Усе тримається на розмовах у кабінетах, хоч результат відомий наперед."},{"imdb_id":"tt23790740","title":"Srikanth","title_uk":"Шріканта","year":2024,"rating":7.4,"votes":14751,"genres":["Biography","Drama"],"country":"Індія","country_main":"Індія","region":"Індія","language":"гінді","theme":"Соціальна драма","who_what":"Незрячий підприємець Шрікант Болла, засновник Bollant Industries.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Шрікант Болла народився незрячим у бідній родині в Андхра-Прадеші, через суд домігся права складати іспити з природничих наук, став першим незрячим іноземним студентом MIT і повернувся в Індію засновувати Bollant Industries — виробництво екопакування, де працюють люди з інвалідністю. Тушар Гіранандані веде фільм від шкільних років до перших великих контрактів. Раджкуммар Рао грає без надриву, а сценарій не приховує ані впертості свого героя, ані його марнославства."},{"imdb_id":"tt11378946","title":"Michael","title_uk":"Майкл","year":2026,"rating":7.4,"votes":165882,"genres":["Biography","Drama","History","Music"],"country":"США","country_main":"США","region":"США","language":"англ.","theme":"Музика та мистецтво","who_what":"Життя Майкла Джексона — від дитинства в Jackson 5 до світового турне Bad.","basis":"реальна історія","note":null,"thriller_flag":false,"decade":"2020-ті","desc":"Байопік охоплює шлях від репетицій братів Джексонів у Ґері в Індіані до світового турне Bad наприкінці 1980-х. Майкла грає його рідний племінник Джаафар Джексон, який співає й танцює сам; режисер — Антуан Фукуа, сценарист — Джон Логан, у ролі Джо Джексона Колман Домінго. Прем'єру кілька разів переносили, а преса писала про перезйомки, пов'язані з тим, як показувати звинувачення 1990-х. Фільм зроблено за участі спадкоємців співака."}]};
